window.addEventListener('unhandledrejection', function(e) {
    var msg = (e.reason && e.reason.message) ? e.reason.message : String(e.reason || '');
    if (msg.toLowerCase().includes('failed to fetch') || msg.toLowerCase().includes('networkerror')) {
        console.warn('[Offline]', msg); return;
    }
    if (msg.toLowerCase().includes('play()') || msg.toLowerCase().includes('abortederror') ||
        msg.toLowerCase().includes('notallowederror') || msg.toLowerCase().includes('interrupted')) {
        console.warn('[MediaPlay suppressed]', msg); e.preventDefault(); return;
    }
    console.error('[UnhandledRejection]', e.reason);
    e.preventDefault();
});
window.addEventListener('error', function(e) {
    if (e.target && e.target !== window) return;
    console.error('[GlobalError]', e.message);
});

