function isSleepModeActive() {
    var toggle = document.getElementById('sleepModeToggle');
    if (!toggle || !toggle.classList.contains('active')) return false;
    var bedtime  = document.querySelector('#sleepModeOptions input[type="time"]:first-of-type');
    var waketime = document.querySelector('#sleepModeOptions input[type="time"]:last-of-type');
    if (!bedtime || !waketime) return false;
    var now = new Date();
    var nowMins = now.getHours() * 60 + now.getMinutes();
    var parts = function(v) { var p = v.split(':'); return parseInt(p[0]) * 60 + parseInt(p[1]); };
    var bed  = parts(bedtime.value  || '22:00');
    var wake = parts(waketime.value || '07:00');
    if (bed > wake) return nowMins >= bed || nowMins < wake;  // overnight
    return nowMins >= bed && nowMins < wake;
}

function showToast(message, duration = 3000) {
    // Strip emojis/symbols from toasts for a clean, professional look (no caller changes needed)
    try {
        message = String(message)
            .replace(/[\p{Extended_Pictographic}\p{Regional_Indicator}️‍←-⇿⌀-➿⬀-⯿]/gu, '')
            .replace(/\s{2,}/g, ' ')
            .trim();
    } catch (e) {}
    const existing = document.getElementById('toastNotif');
    if (existing) existing.remove();

    const toast = document.createElement('div');
    toast.id = 'toastNotif';
    toast.style.cssText = `
        position:fixed; bottom:100px; left:50%; transform:translateX(-50%);
        background:rgba(0,0,0,0.85); backdrop-filter:blur(20px);
        color:white; padding:12px 24px; border-radius:30px;
        font-size:14px; font-weight:600; z-index:99999;
        animation:fadeInUp 0.3s ease;
        max-width:90%; text-align:center;
        border:1px solid rgba(255,255,255,0.1);
    `;
    toast.textContent = message;
    document.body.appendChild(toast);

    setTimeout(() => {
        toast.style.animation = 'fadeOut 0.3s ease forwards';
        setTimeout(() => toast.remove(), 300);
    }, duration);
}

