function isTrustClipPost(post) {
    if (!post) return false;
    var type = String(post.post_type || post.content_type || post.kind || '').toLowerCase();
    return type === 'trustclip' || type === 'trust_clip' || post.is_trustclip === true || !!post.trustclip_id;
}

async function toggleFeedFollow(btn) {
    if (!canPerformAction('follow a user')) return;
    var postCard = btn.closest('[data-post-id]') || btn.closest('[data-user-id]');
    var userId = btn.getAttribute('data-user-id') || (postCard ? postCard.getAttribute('data-author-id') : null);
    if (!userId) {
        console.warn('[toggleFeedFollow] No user ID on button. Follow will not persist.');
        btn.classList.toggle('following');
        btn.textContent = btn.classList.contains('following') ? 'Following' : 'Follow';
        triggerHaptic(20);
        return;
    }
    // Optimistic
    var wasFollowing = btn.classList.contains('following');
    btn.classList.toggle('following');
    btn.textContent = btn.classList.contains('following') ? 'Following' : 'Follow';
    btn.disabled = true;
    triggerHaptic(20);
    try {
        if (wasFollowing) {
            var { error } = await window._sb.from('follows')
                .delete()
                .eq('follower_id', currentUser.id)
                .eq('following_id', userId);
            if (error) throw error;
        } else {
            var { error } = await window._sb.from('follows')
                .insert({ follower_id: currentUser.id, following_id: userId, created_at: new Date().toISOString() });
            if (error) throw error;
        }
    } catch(e) {
        // Rollback
        btn.classList.toggle('following');
        btn.textContent = btn.classList.contains('following') ? 'Following' : 'Follow';
        showToast('Could not update follow. Try again.');
    } finally {
        btn.disabled = false;
    }
}

