function nextAuthStep(stepId) {
    document.querySelectorAll('.auth-step').forEach(s => s.classList.remove('active'));
    var step = document.getElementById(stepId);
    if (!step) { console.error('[Auth] Step not found:', stepId); return; }
    step.classList.add('active');
    history.pushState({ authStep: stepId }, '', '');
}

window.addEventListener('popstate', function(e) {
    var authWrapper = document.getElementById('auth-wrapper');
    if (!authWrapper || authWrapper.style.display === 'none') return;
    var stepId = (e.state && e.state.authStep) ? e.state.authStep : 'step-splash';
    document.querySelectorAll('.auth-step').forEach(s => s.classList.remove('active'));
    var step = document.getElementById(stepId);
    if (step) step.classList.add('active');
});

function selectAccountType(type) {
    var birthDate = (document.getElementById('reg-birthdate') || {}).value || '';
    if (birthDate && calculateAgeFromBirthDate(birthDate) < 18 && type !== 'child') {
        showToast('Under-18 accounts use TrustFirst Kids and need a linked parent account.');
        type = 'child';
    }
    selectedAccountType = type;
    document.querySelectorAll('.acct-type-card').forEach(c => c.classList.remove('selected'));
    var card = document.querySelector(`[data-type="${type}"]`);
    if (card) card.classList.add('selected');
    document.getElementById('acct-type-next').style.opacity = '1';
    document.getElementById('acct-type-next').style.pointerEvents = 'all';
}

function calculateAgeFromBirthDate(birthDateValue) {
    var dob = new Date(birthDateValue + 'T00:00:00');
    if (!birthDateValue || isNaN(dob.getTime())) return null;
    var today = new Date();
    var age = today.getFullYear() - dob.getFullYear();
    var m = today.getMonth() - dob.getMonth();
    if (m < 0 || (m === 0 && today.getDate() < dob.getDate())) age--;
    return age;
}

function handleBirthDateChange() {
    var input = document.getElementById('reg-birthdate');
    var status = document.getElementById('birthdate-status');
    var age = calculateAgeFromBirthDate(input ? input.value : '');
    if (!status) return;
    if (age === null) {
        status.textContent = '';
        return;
    }
    if (age < 13 || age > 120) {
        status.style.color = '#FF3B30';
        status.textContent = 'Enter a valid birth date.';
        return;
    }
    if (age < 18) {
        status.style.color = '#34C759';
        status.textContent = 'TrustFirst Kids account will be created. Parent link required next.';
        selectAccountType('child');
    } else {
        status.style.color = '#888';
        status.textContent = 'You can choose your account type on the next step.';
    }
}

function proceedFromRegistrationDetails() {
    var birthDate = (document.getElementById('reg-birthdate') || {}).value || '';
    var age = calculateAgeFromBirthDate(birthDate);
    if (age === null) {
        showToast('Please enter your birth date.');
        return;
    }
    if (age < 13 || age > 120) {
        showToast('Please enter a valid birth date.');
        return;
    }
    if (age < 18) {
        selectedAccountType = 'child';
        secureSave('pending_account_type', 'child');
        nextAuthStep('step-parent-link');
        return;
    }
    nextAuthStep('step-account-type');
}

function proceedAfterAccountType() {
    if (!selectedAccountType) return;
    if (selectedAccountType === 'child') {
        nextAuthStep('step-parent-link');
    } else {
        nextAuthStep('step-verify');
    }
}

function linkParentAccount() {
    var parentId = (document.getElementById('parent-link-id') || {}).value || '';
    if (!parentId.trim()) { showToast('Enter your parent\'s Trust-ID'); return; }

    if (window.sb) {
        sb.from('users')
            .select('id, username, full_name, verified, account_type, badge_tier')
            .eq('username', parentId.trim().toLowerCase().replace('@',''))
            .maybeSingle()
            .then(function(result) {
                if (!result.data) { showToast('Parent account not found. Check the username.'); return; }
                if (!result.data.verified) { showToast('Parent must be verified (any coloured badge) to link accounts.'); return; }
                if (result.data.account_type === 'child') { showToast('A child account cannot be a parent.'); return; }

                // All verified account types (blue, silver, red) can be parents
                secureSave('parent_link_request', {
                    parent_id: result.data.id,
                    parent_username: result.data.username,
                    parent_name: result.data.full_name,
                    parent_badge: result.data.badge_tier,
                    status: 'pending',
                    timestamp: Date.now()
                });

                showToast('Link request sent to ' + result.data.full_name + '! They must approve in Family Center.');

                // Notify parent
                if (window.sb) {
                    sb.from('notifications').insert({
                        user_id: result.data.id,
                        type: 'child_link_request',
                        message: 'A child account wants to link to you in Family Center',
                        preview_text: 'Open Family Center to approve',
                        read: false
                    }).then(function(){}).catch(function(){});
                }

                setTimeout(function() { completeRegistration(false); }, 2000);
            });
    } else {
        secureSave('parent_link_request', {
            parent_username: parentId.trim(),
            status: 'pending',
            timestamp: Date.now()
        });
        showToast('Link request saved. Parent must approve when online.');
        setTimeout(function() { completeRegistration(false); }, 2000);
    }
}

function getTierForType(type) {
    const map = { personal: 'verify-blue', business: 'verify-silver', government: 'verify-red', child: 'verify-green' };
    return map[type] || 'verify-blue';
}

function startScan() {
    // Real verification cannot happen client-side.
    // This must redirect to your real KYC flow (Didit / manual review queue).
    showToast('Identity verification requires document upload. This is reviewed by our team within 24 hours.');
    var box = document.getElementById('scan-box');
    // NOTE: this replaces scan-box's contents (including #scan-label), so do not
    // reference #scan-label afterwards — that was the null crash.
    if (box) box.innerHTML =
        '<i class="fa-solid fa-id-card" style="color:#FF9500; font-size:40px;"></i>' +
        '<p style="color:#FF9500; margin-top:10px; font-weight:600; font-size:14px;">Upload an ID document to complete verification</p>';
    // Wire to your actual KYC upload endpoint:
    // window.location.href = '/verify/upload/';
}

function skipVerification() {
    tfConfirm('Skip identity verification?', function() {
        completeRegistration(false);
    }, {
        icon: 'fa-solid fa-id-card',
        iconBg: 'rgba(255,149,0,0.1)',
        iconColor: '#FF9500',
        sub: 'Without verification you cannot post, comment or start chats.',
        confirmLabel: 'Skip anyway',
        cancelLabel: 'Go back',
        confirmBg: '#FF9500'
    });
}

function showAuthLoader() {
    document.querySelectorAll('.auth-step').forEach(s => s.style.display = 'none');
    document.getElementById('auth-loader').style.display = 'block';
}

function hideAuthLoader() {
    document.getElementById('auth-loader').style.display = 'none';
}

function showAuthError(message, returnStep) {
    hideAuthLoader();
    showToast(message);
    if (returnStep) nextAuthStep(returnStep);
}

// ---- MAIN REGISTRATION ----
async function completeRegistration(verified) {
    // Wait for Supabase to be ready
    await waitForSb();

    const firstName = (document.getElementById('reg-firstname')?.value || '').trim();
    const lastName = (document.getElementById('reg-lastname')?.value || '').trim();
    const name = (firstName + ' ' + lastName).trim();
    const email = (document.getElementById('reg-email')?.value || '').trim().toLowerCase();
    const username = (document.getElementById('reg-username')?.value || '').trim().toLowerCase();
    const password = document.getElementById('reg-pass')?.value || '';
    const confirmPass = document.getElementById('reg-confirm-pass')?.value || '';
    const birthDate = (document.getElementById('reg-birthdate')?.value || '').trim();
    const registrationAge = calculateAgeFromBirthDate(birthDate);
    if (registrationAge !== null && registrationAge < 18) selectedAccountType = 'child';
    var finalAccountType = selectedAccountType || 'personal';
    var parentLink = secureLoad('parent_link_request') || {};

    // Client-side validation
    if (firstName.length < 2) return showAuthError('First name must be at least 2 characters', 'step-register');
    if (lastName.length < 1) return showAuthError('Please enter your last name', 'step-register');
    if (!email || !isValidEmail(email)) return showAuthError('Enter a valid email', 'step-register');
    if (!username || !isValidUsername(username)) return showAuthError('Username: 3-20 chars, letters/numbers/underscore only', 'step-register');
    if (registrationAge === null || registrationAge < 13 || registrationAge > 120) return showAuthError('Please enter a valid birth date', 'step-register');
    if (registrationAge < 18 && !parentLink.parent_id && !parentLink.parent_username) return showAuthError('A parent or guardian Trust-ID is required for under-18 accounts', 'step-parent-link');

    if (password !== confirmPass) return showAuthError('Passwords do not match.', 'step-register');

    // Password policy enforcement
    const pwResult = PasswordPolicy.validate(password);
    if (!pwResult.valid) {
        const firstFail = pwResult.results.find(r => !r.passed);
        return showAuthError('Password requirement not met: ' + firstFail.label, 'step-register');
    }

    showAuthLoader();

    try {
        // Get device fingerprint
        const deviceInfo = await DeviceFingerprint.getDeviceInfo();

        // One-account enforcement checks
        const validation = await OneAccountPolicy.validateRegistration(
            email, username, deviceInfo.device_fingerprint
        );
        if (!validation.valid) {
            return showAuthError(validation.errors[0], 'step-register');
        }

        // Register with Supabase Auth
        const authData = await DB.signUp(email, password, {
            full_name: name,
            username: username,
            account_type: finalAccountType,
            birth_date: birthDate,
            is_kid: finalAccountType === 'child'
        });

        if (!authData.user || (authData.user.identities && authData.user.identities.length === 0)) {
            return showAuthError('This email is already registered. Please log in instead.', 'step-register');
        }

        // Create user profile in our users table
        let profile = null;
try {
    profile = await DB.createUserProfile({
        id: authData.user.id,
        email: email,
        username: username,
        full_name: name,
        account_type: finalAccountType,
        birth_date: birthDate,
        is_kid: finalAccountType === 'child',
        // New accounts start UNVERIFIED. A verified badge is granted only after
        // real verification (Didit ID / admin review), never at sign-up. The DB
        // also enforces this — these columns are frozen for non-admin writers.
        verified: false,
        badge_tier: null,
        trust_score: 20,
        parent_id: finalAccountType === 'child' ? (parentLink.parent_id || null) : null,
        parent_link_status: finalAccountType === 'child' ? 'pending' : null
    });
} catch(profileErr) {
    console.error('[Profile Create Error]', profileErr);
    return showAuthError('Account created but profile setup failed: ' + profileErr.message, 'step-register');
}

        // Register this device as trusted
        const geo = await GeoIP.lookup();
        await DB.registerDevice({
            user_id: authData.user.id,
            ...deviceInfo,
            ip_address: geo.ip,
            location_city: geo.city,
            location_country: geo.country,
            is_trusted: true,
            is_current: true
        });

        // Log the login activity
        await DB.logLoginActivity({
            user_id: authData.user.id,
            ip_address: geo.ip,
            location_city: geo.city,
            location_country: geo.country,
            user_agent: navigator.userAgent,
            login_method: 'password',
            status: 'success'
        });

        // Generate and publish E2E encryption keys
        await E2E.init();
        await E2E.publishKeyBundle(authData.user.id);

        // Set local state
        var phoneVal = (document.getElementById('reg-phone') || {}).value || '';
        currentUser = {
        is_admin: false,
            id: authData.user.id,
            name: name,
            email: email,
            phone: phoneVal,
            handle: '@' + username,
            username: username,
            type: finalAccountType,
            tier: getTierForType(finalAccountType),
            verified: verified,
            trust_score: verified ? 85 : 20,
            birth_date: birthDate,
            is_kid: finalAccountType === 'child',
            parent_id: finalAccountType === 'child' ? (parentLink.parent_id || null) : null
        };
        secureSave('current_user', currentUser);
        try { if (typeof _saveAccountToSwitcher === 'function') _saveAccountToSwitcher(currentUser); } catch (e) {}

        // Launch
        document.getElementById('splash').classList.add('splash-fade-out');
        setTimeout(() => launchApp(), 600);

    } catch (error) {
        console.error('[Registration]', error);
        let msg = 'Registration failed. ';
        if (error.message?.includes('duplicate')) {
            msg += 'This email or username is already taken.';
        } else if (error.message?.includes('password')) {
            msg += 'Password does not meet requirements.';
        } else {
            msg += error.message || 'Please try again.';
        }
        showAuthError(msg, 'step-register');
    }
}

// ---- MAIN LOGIN ----
async function authenticateUser(returnStep) {
    returnStep = returnStep || 'step-login';   // errors return to this step (X-style password page passes 'step-login-password')
    // Wait for Supabase to be ready
    await waitForSb();

    const regName = document.getElementById('reg-name');

    // If coming from registration verify step
       if (regName && regName.value && regName.value.trim().length > 0) {
        return completeRegistration(true);
    }

        // Check lockout
    const lockoutUntil = localStorage.getItem('tf_lockout_until');
    var burstAttempts = JSON.parse(localStorage.getItem('tf_burst') || '[]');
burstAttempts = burstAttempts.filter(function(t) { return Date.now() - t < 60000; });
if (burstAttempts.length >= 5) {
    showAuthError('Too many attempts. Please wait 60 seconds.', returnStep);
    return;
}
burstAttempts.push(Date.now());
localStorage.setItem('tf_burst', JSON.stringify(burstAttempts));
    if (lockoutUntil && Date.now() < parseInt(lockoutUntil)) {
        var remainMins = Math.ceil((parseInt(lockoutUntil) - Date.now()) / 60000);
        return showAuthError('Account locked. Try again in ' + remainMins + ' minute(s).', returnStep);
    }

    // Login flow
    const identifier = (document.getElementById('login-user')?.value || '').trim();
    const password = document.getElementById('login-pass')?.value || '';

    if (!identifier) return showAuthError('Enter your Trust-ID or email', returnStep);
    if (!password) return showAuthError('Enter your password', returnStep);

    showAuthLoader();

    try {
        let email = identifier;

        // Phone login: Supabase signs in on the number directly, so there is no
        // email to resolve. loginWithPhone puts E.164 in the identifier field.
        if (/^\+[0-9]{7,15}$/.test(identifier)) {
            const phoneAuth = await sb.auth.signInWithPassword({ phone: identifier, password });
            if (phoneAuth.error || !phoneAuth.data || !phoneAuth.data.user) {
                return showAuthError('Wrong password. Try again or use a code instead.', returnStep);
            }
            hideAuthLoader();
            return _finishPhoneLogin(phoneAuth.data.user);
        }

        // If user entered a username instead of email, look up the email
       if (!isValidEmail(identifier)) {
    const cleanUsername = identifier.replace('@', '').toLowerCase();
    const userProfile = await DB.getUserByUsername(cleanUsername);

    if (!userProfile) {
        // Could be a user added directly via Supabase dashboard (no users table profile)
        // We can't look up their email by username, so tell them to use their email instead
        return showAuthError(
            'Account not found by username. Try logging in with your email address instead.',
            returnStep
        );
    }

    if (userProfile.is_locked) {
        return showAuthError(
            'This account is locked. Contact support to unlock it.',
            returnStep
        );
    }

    email = userProfile.email;
}

        // Sign in with Supabase
        const authData = await DB.signIn(email, password);

        if (!authData.user) {
            return showAuthError('Invalid credentials', returnStep);
        }

        // Fetch full profile
        const profile = await DB.getUserProfile(authData.user.id);

        if (!profile) {
            return showAuthError('Account found but no profile exists. Please register again or contact support.', returnStep);
        }

        if (profile.is_locked) {
            await DB.signOut();
            return showAuthError(
                'This account is locked and frozen. Contact support to unlock.',
                'step-login'
            );
        }

        if (profile.is_banned) {
            await DB.signOut();
            return showAuthError(
                'This account has been permanently banned for policy violations.',
                'step-login'
            );
        }

        // Register/update device
        const deviceInfo = await DeviceFingerprint.getDeviceInfo();
        const geo = await GeoIP.lookup();

        await DB.registerDevice({
            user_id: authData.user.id,
            ...deviceInfo,
            ip_address: geo.ip,
            location_city: geo.city,
            location_country: geo.country,
            is_trusted: true,
            is_current: true
        });

        // Log login activity
        await DB.logLoginActivity({
            user_id: authData.user.id,
            ip_address: geo.ip,
            location_city: geo.city,
            location_country: geo.country,
            user_agent: navigator.userAgent,
            login_method: 'password',
            status: 'success'
        });

        // Make sure E2E keys exist
        await E2E.init();
        const existingKeys = await DB.getKeyBundle(authData.user.id);
        if (!existingKeys) {
            await E2E.publishKeyBundle(authData.user.id);
        }

        trackLogin(true, false);
        // Set local state
        currentUser = {
        is_admin: profile.is_admin || false,
            id: profile.id,
            name: profile.full_name,
            email: profile.email,
            handle: '@' + profile.username,
            username: profile.username,
            type: profile.account_type,
            tier: profile.badge_tier,
            verified: profile.verified,
            trust_score: profile.trust_score,
            ai_label: profile.ai_label,
            avatar_url: profile.avatar_url,
            bio: profile.bio
        };
        secureSave('current_user', currentUser);
        try { if (typeof _saveAccountToSwitcher === 'function') _saveAccountToSwitcher(currentUser); } catch (e) {}

        // Launch
        document.getElementById('splash').classList.add('splash-fade-out');
        setTimeout(() => launchApp(), 600);

    } catch (error) {
    hideAuthLoader();
    console.error('[Login Error]', error);

    let msg = '';
    const code = error?.message?.toLowerCase() || '';

    if (code.includes('email not confirmed')) {
        msg = 'Please check your email and click the confirmation link first.';
    } else if (code.includes('invalid login') || code.includes('invalid credentials')) {
        msg = 'Wrong email or password. Please try again.';
    } else if (code.includes('too many requests')) {
        msg = 'Too many attempts. Wait a moment and try again.';
    } else {
        msg = 'Login failed: ' + (error.message || 'Unknown error');
    }
    showAuthError(msg, returnStep);
}
}   // ← THIS is the missing closing brace for authenticateUser()
window.__authenticateUserImpl = authenticateUser;
if (window.__authenticateUserPending) { window.__authenticateUserPending = false; authenticateUser(); }

// ---- SESSION RESTORATION ----
async function restoreSession() {
    if (!window.sb) return false;
    try {
        // Check lockout
        const lockoutUntil = localStorage.getItem('tf_lockout_until');
        if (lockoutUntil && Date.now() < parseInt(lockoutUntil)) {
            console.debug('[Auth] Account temporarily locked out');
            return false;
        }
        localStorage.removeItem('tf_failed_logins');

        const session = await DB.getSession();
        if (!session) return false;

        let profile;
        try {
            profile = await DB.getUserProfile(session.user.id);
        } catch (netErr) {
            // Offline / DB unreachable: stay signed in with the cached profile
            // so the avatar, chats and cached messages still render.
            var cachedU = secureLoad('current_user');
            if (cachedU && cachedU.id === session.user.id) {
                currentUser = cachedU;
                isAdmin = cachedU.is_admin === true;
                try { await E2E.init(); } catch(e) {}
                console.warn('[Session] Offline, restored from cached profile');
                return true;
            }
            return false;
        }
        if (!profile || profile.is_locked || profile.is_banned) {
            await DB.signOut();
            return false;
        }

        // Update device last_active (best-effort — never block login on this)
        try {
            const deviceInfo = await DeviceFingerprint.getDeviceInfo();
            await DB.registerDevice({
                user_id: session.user.id,
                ...deviceInfo,
                is_current: true,
                last_active: new Date().toISOString()
            });
        } catch(e) { console.warn('[Session] device register skipped:', e && e.message); }

        currentUser = {
            id: profile.id,
            name: profile.full_name,
            email: profile.email,
            handle: '@' + profile.username,
            username: profile.username,
            type: profile.account_type,
            tier: profile.badge_tier,
            verified: profile.verified,
            trust_score: profile.trust_score,
            ai_label: profile.ai_label,
            avatar_url: profile.avatar_url,
            bio: profile.bio,
            is_admin: profile.is_admin || false
        };
        isAdmin = currentUser.is_admin === true;
        secureSave('current_user', currentUser);

        try { await E2E.init(); } catch(e) {}
        return true;
    } catch (e) {
        console.error('[Session] Restore failed:', e);
        return false;
    }
}

// ---- LOGOUT ----
async function logOut() {
    var sheet = document.createElement('div');
    sheet.style.cssText = 'position:fixed;bottom:0;left:0;right:0;z-index:99999;background:rgba(0,0,0,0.5);top:0;display:flex;align-items:flex-end;justify-content:center;';
    sheet.innerHTML =
        '<div style="background:var(--card-bg,#fff);border-radius:24px 24px 0 0;padding:28px 20px 36px;width:100%;max-width:430px;text-align:center;">' +
        '<div style="width:36px;height:4px;background:rgba(0,0,0,0.15);border-radius:2px;margin:0 auto 24px;"></div>' +
        '<p style="font-size:17px;font-weight:700;margin-bottom:8px;">Log out?</p>' +
        '<p style="font-size:14px;color:#888;margin-bottom:24px;">You\'ll need to sign back in to access your account.</p>' +
        '<button id="confirmLogoutBtn" style="width:100%;padding:16px;background:#FF3B30;color:#fff;border:none;border-radius:16px;font-size:16px;font-weight:700;cursor:pointer;margin-bottom:10px;">Log Out</button>' +
        '<button onclick="this.closest(\'div[style*=z-index\\:99999]\').remove()" style="width:100%;padding:16px;background:var(--bg-secondary,#f2f2f7);color:var(--text-primary,#000);border:none;border-radius:16px;font-size:16px;font-weight:600;cursor:pointer;">Cancel</button>' +
        '</div>';
    document.body.appendChild(sheet);
    // The inline Cancel selector breaks once cssText normalises the style attribute
    // (z-index:99999 → "z-index: 99999"), so wire Cancel + tap-outside here instead.
    var _lgBtns = sheet.querySelectorAll('button');
    if (_lgBtns.length > 1) { _lgBtns[1].onclick = function() { sheet.remove(); }; }
    sheet.addEventListener('click', function(e) { if (e.target === sheet) sheet.remove(); });
    document.getElementById('confirmLogoutBtn').onclick = async function() {
        sheet.remove();
        // Keep this account (with its current session token) in the switcher so it
        // can be tapped to sign straight back in.
        try {
            if (currentUser && window.sb) {
                var _s = await sb.auth.getSession();
                _saveAccountToSwitcher(currentUser, (_s && _s.data && _s.data.session) || null);
            }
        } catch(e) {}
        try { await DB.signOut(); } catch(e) {}
        localStorage.removeItem('tf_current_user');
        localStorage.removeItem('tf_failed_logins');
        localStorage.removeItem('tf_lockout_until');
        localStorage.setItem('tf_show_login', '1'); // land on the login page after reload
        currentUser = null;
        location.reload();
    };
}

