var _realOneSearchTimer = null;
window._realOnePickerResults = {};
function realOneSearch(q) {
    clearTimeout(_realOneSearchTimer);
    _realOneSearchTimer = setTimeout(function(){ _realOneDoSearch(q); }, 220);
}
async function _realOneDoSearch(q) {
    var listEl = document.getElementById('realOnePickerList');
    if (!listEl || !window.sb || !currentUser) return;
    q = (q || '').trim().replace(/^@/, '');
    var people = [];
    try {
        if (q) {
            var r = await sb.from('users').select('id,username,full_name,avatar_url')
                .or('username.ilike.%'+q+'%,full_name.ilike.%'+q+'%').neq('id', currentUser.id).limit(20);
            people = r.data || [];
        } else {
            var f = await sb.from('follows').select('following_id, users:following_id(id,username,full_name,avatar_url)')
                .eq('follower_id', currentUser.id).limit(30);
            people = (f.data || []).map(function(x){ return x.users; }).filter(Boolean);
        }
    } catch(e) {}
    window._realOnePickerResults = {};
    people.forEach(function(p){ if (p && p.id) window._realOnePickerResults[p.id] = p; });
    var circleIds = _realOnes().map(function(p){ return p.id; });
    if (!people.length) { listEl.innerHTML = '<div style="text-align:center;padding:24px;color:#aaa;font-size:14px;">'+(q?'No people found':'Follow people to add them as Real Ones')+'</div>'; return; }
    listEl.innerHTML = people.map(function(p){
        var inCircle = circleIds.indexOf(p.id) > -1;
        var avatarHtml = p.avatar_url ? '<img src="'+escapeHtml(p.avatar_url)+'" style="width:42px;height:42px;border-radius:50%;object-fit:cover;flex-shrink:0;">' : '<div style="width:42px;height:42px;border-radius:50%;background:#e0e0e0;display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fa-solid fa-user" style="color:#aaa;"></i></div>';
        return '<div style="display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:0.5px solid var(--border-color,#f5f5f5);">' +
            avatarHtml +
            '<div style="flex:1;min-width:0;"><b style="font-size:15px;color:var(--text-primary,#000);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+escapeHtml(p.full_name||p.username)+'</b><small style="color:#888;">@'+escapeHtml(p.username)+'</small></div>' +
            (inCircle
                ? '<span style="font-size:12px;color:#34C759;font-weight:700;"><i class="fa-solid fa-check"></i> Added</span>'
                : '<button onclick="addRealOne(\''+p.id+'\',this)" style="padding:7px 14px;border-radius:16px;border:none;background:#FF2D55;color:white;font-size:13px;font-weight:700;cursor:pointer;">Add</button>') +
        '</div>';
    }).join('');
}

function addRealOne(id, btn) {
    var p = window._realOnePickerResults[id];
    if (!p) return;
    var circle = _realOnes();
    if (circle.some(function(x){ return x.id === id; })) return;
    circle.push({ id: p.id, username: p.username, full_name: p.full_name || p.username, avatar_url: p.avatar_url || '' });
    _saveRealOnes(circle);
    if (btn) btn.outerHTML = '<span style="font-size:12px;color:#34C759;font-weight:700;"><i class="fa-solid fa-check"></i> Added</span>';
    renderRealOneList();
    triggerHaptic(15);
}

// Sends a REAL private notification to the chosen person (notifications table).
async function sendRealOneCheckIn(toId, btn) {
    var person = _realOnes().filter(function(p){ return p.id === toId; })[0] || {};
    var toName = person.full_name || person.username || 'your real one';
    if (btn) { btn.disabled = true; btn.textContent = 'Sending…'; }
    var ok = false;
    try {
        if (window.sb && currentUser && toId) {
            var res = await sb.from('notifications').insert({
                user_id: toId,
                actor_id: currentUser.id,
                type: 'real_one_checkin',
                message: (currentUser.name || currentUser.username || 'Someone') + ' is checking in on you',
                preview_text: 'Real One Check-In'
            });
            ok = !res.error;
            if (res.error) console.warn('[RealOne] notify failed:', res.error.message);
        }
    } catch(e) {}
    var sent = JSON.parse(localStorage.getItem('tf_real_one_sent') || '[]');
    sent.push({ to: toId, toName: toName, timestamp: Date.now() });
    localStorage.setItem('tf_real_one_sent', JSON.stringify(sent));
    if (btn) btn.outerHTML = '<span style="font-size:12px;background:rgba(52,199,89,0.12);color:#34C759;padding:6px 12px;border-radius:14px;font-weight:700;">Checked in</span>';
    showToast(ok ? (toName + ' got your check-in') : 'Check-in saved');
    triggerHaptic(30);
}

// ============================================
// APP INIT - Splash → Auth Check → Launch
// ============================================
window.addEventListener('DOMContentLoaded', async function() {
    // Hide login/signup page immediately — prevent any flash
    var htmlSplash = document.getElementById('splash');
    if (htmlSplash) htmlSplash.style.display = 'none';

    // Wait for Supabase to load
    var waitForSB = function() {
        return new Promise(function(resolve) {
            if (window.sb) return resolve();
            var check = setInterval(function() {
                if (window.sb) { clearInterval(check); resolve(); }
            }, 100);
            setTimeout(function() { clearInterval(check); resolve(); }, 5000);
        });
    };

    await waitForSB();

    // Check if user is already logged in
    var restored = false;
    try {
        restored = await restoreSession();
    } catch(e) {
        console.error('[Init] Session restore failed:', e);
    }

    if (restored) {
        // Already signed in — logo splash handles the min display time
        dismissSplash();
        launchApp();
    } else {
        // Not logged in — wait for logo, then reveal login form
        setTimeout(function() {
            dismissSplash();
            if (htmlSplash) htmlSplash.style.display = '';
            // After logging out, land on the login page (saved accounts switcher) not the splash.
            if (localStorage.getItem('tf_show_login')) {
                localStorage.removeItem('tf_show_login');
                if (typeof nextAuthStep === 'function') nextAuthStep('step-login');
            }
        }, 1500);
    }
});


async function verifyPassword(password, stored) {
  if (!stored || !stored.salt) return false;
  const encoder = new TextEncoder();
  const salt = new Uint8Array(stored.salt.match(/.{2}/g).map(byte => parseInt(byte, 16)));
  const keyMaterial = await crypto.subtle.importKey('raw', encoder.encode(password), 'PBKDF2', false, ['deriveBits']);
  const derivedBits = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt: salt, iterations: 100000, hash: 'SHA-256' },
    keyMaterial,
    256
  );
  const hashArray = Array.from(new Uint8Array(derivedBits));
  const hash = hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
  return hash === stored.hash;
}

function isStrongPassword(password) {
  return /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]).{8,}$/.test(password);
}

// Session validation
function validateSession() {
  const session = secureLoad('session');
  if (!session) return false;
  if (Date.now() > session.expires) {
    localStorage.removeItem('tf_session');
    localStorage.removeItem('tf_current_user');
    return false;
  }
  return true;
}

function launchApp() {
    const splash = document.getElementById('splash');
    if (splash) splash.remove();
    document.getElementById('composer-overlay').style.display = 'none';

    const app = document.getElementById('app');
    app.classList.remove('not-authenticated');
    app.classList.add('authenticated');

    isAdmin = currentUser && currentUser.is_admin === true;

    if (isChildAccount()) {
        const banner = document.createElement('div');
        banner.className = 'child-safe-banner';
        banner.style.display = 'block';
        banner.innerHTML = '<i class="fa-solid fa-shield-halved"></i> TrustFirst Kids: Safe Mode Active';
        app.insertBefore(banner, app.querySelector('.header-container'));
    }

    if (!isVerified()) {
        const banner = document.createElement('div');
        banner.style.cssText = 'background:#FF9500; color:white; padding:8px 20px; font-size:12px; font-weight:700; text-align:center;';
        banner.innerHTML = '<i class="fa-solid fa-triangle-exclamation"></i> Unverified, verify to post, comment and start chats';
        app.insertBefore(banner, app.querySelector('.header-container'));
    }

    initFeed();
    checkNetwork();

    // Land on a clean home feed — closes any overlay left visible by default
    // so nothing covers the app (feed/settings) after login.
    try { navHome(); } catch (e) { if (e) console.warn('[launchApp] navHome', e); }


    // Start child account monitoring
    if (isChildAccount()) {
        startChildMonitoring();
    }
}

// ============================================
// CHILD ACCOUNT MONITORING
// ============================================
var childActivityLog = [];

function startChildMonitoring() {
    console.debug('[ChildMonitor] Monitoring active for child account');

    // Intercept all actions and log them for parent
    var _origCanPerformAction = canPerformAction;
    canPerformAction = function(actionName) {
        logChildActivity('attempted_' + actionName.replace(/\s+/g,'_'), { action: actionName });
        return _origCanPerformAction(actionName);
    };

    // Monitor screen time
    var sessionStart = Date.now();
    window.addEventListener('beforeunload', function() {
        var mins = Math.round((Date.now() - sessionStart) / 60000);
        logChildActivity('session_ended', { duration_minutes: mins });
        sendChildReportToParent();
    });

    // Monitor every 5 minutes
    setInterval(function() {
        sendChildReportToParent();
    }, 5 * 60 * 1000);
}

function logChildActivity(type, data) {
    var entry = {
        type: type,
        data: data || {},
        timestamp: new Date().toISOString(),
        child_id: currentUser ? currentUser.id : null,
        child_name: currentUser ? currentUser.name : 'Unknown'
    };
    childActivityLog.push(entry);

    // Keep last 500 events
    if (childActivityLog.length > 500) childActivityLog = childActivityLog.slice(-200);

    // Save locally
    try {
        localStorage.setItem('child_activity_' + (currentUser ? currentUser.id : 'unknown'), JSON.stringify(childActivityLog.slice(-100)));
    } catch(e) { if (e) console.warn('[Suppressed error]', e); }
}

async function sendChildReportToParent() {
    if (!window.sb || !currentUser) return;
    if (childActivityLog.length === 0) return;

    var parentLink = secureLoad('parent_link_request');
    var parentId = parentLink ? parentLink.parent_id : null;
    if (!parentId) return;

    try {
        // Store activity report in Supabase
        await sb.from('child_activity_reports').insert({
            child_id: currentUser.id,
            child_name: currentUser.name,
            parent_id: parentId,
            activities: JSON.stringify(childActivityLog.slice(-50)),
            report_date: new Date().toISOString(),
            session_start: new Date(Date.now() - childActivityLog.length * 1000).toISOString()
        });

        // Clear sent activities
        childActivityLog = [];
    } catch(e) {
        console.warn('[ChildMonitor] Could not send report:', e.message);
    }
}

// Override key actions to log them for child accounts


// --- NETWORK ---
function checkNetwork() {
    function updateStatus() {
        const banner = document.getElementById('offline-banner');
        if (!banner) return;
        if (navigator.onLine) {
            banner.style.display = 'none';
            banner.classList.remove('active');
        } else {
            banner.style.display = 'block';
            banner.classList.add('active');
        }
    }
    window.addEventListener('online', updateStatus);
    window.addEventListener('offline', updateStatus);
    // Only show if actually offline at launch
    if (!navigator.onLine) updateStatus();
}

// --- CAMERA ---
async function startCamera() {
    if (!navigator.mediaDevices || !window.isSecureContext) {
        showToast('Camera requires a secure connection (HTTPS)');
        return;
    }
    try {
        if (mediaStream) stopCamera();
        mediaStream = await navigator.mediaDevices.getUserMedia({
            video: { facingMode: "user" },
            audio: false
        });
        const video = document.getElementById('camera-preview');
        video.srcObject = mediaStream;
        document.getElementById('camera-overlay').style.display = 'block';
    } catch (err) {
        showToast('Camera access denied. Check your browser permissions');
    }
}

function stopCamera() {
    if (mediaStream) {
        mediaStream.getTracks().forEach(track => track.stop());
        mediaStream = null;
    }
    document.getElementById('camera-overlay').style.display = 'none';
    // After stopCamera() restores the feed, re-apply nav home active state:
var homeIcon = document.getElementById('nav-home');
if (homeIcon) {
    document.querySelectorAll('.liquid-pill .nav-icon').forEach(function(i) { i.classList.remove('nav-active'); });
    homeIcon.classList.add('nav-active');
}
}


function takePhoto() {
    var video = document.getElementById('camera-preview');
    if (!video || !mediaStream) { showToast('Camera not ready'); return; }
    var canvas = document.createElement('canvas');
    canvas.width = video.videoWidth || 640;
    canvas.height = video.videoHeight || 480;
    canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height);
    canvas.toBlob(async function(blob) {
        if (!blob) { showToast('Could not capture photo'); return; }
        var file = new File([blob], 'photo_' + Date.now() + '.jpg', { type: 'image/jpeg' });
        if (window.sb && currentUser) {
            var path = currentUser.id + '/photos/' + file.name;
            var { data, error } = await sb.storage.from('media').upload(path, file, { upsert: true });
            if (error) { showToast('Upload failed: ' + error.message); return; }
            var { data: urlData } = sb.storage.from('media').getPublicUrl(path);
            showToast('Photo saved!');
            stopCamera();
            // Store URL for use in post composer
            window._lastCapturedPhotoUrl = urlData.publicUrl;
        } else {
            showToast('Sign in to save photos');
        }
    }, 'image/jpeg', 0.9);
}

function openMedia() { document.getElementById('file-input').click(); }

// Chat "Gallery": open the phone's real photos/videos straight from the tap.
// A PWA can't render the camera roll, so the native OS picker IS the gallery.
// Reset .value first so picking the same file twice still fires onchange.
function openChatMediaPicker() {
    var fi = document.getElementById('file-input');
    if (!fi) return;
    fi.accept = 'image/*,video/*';
    try { fi.value = ''; } catch (e) {}
    fi.click();
}

function filterChatList(query) {
    var rows = document.querySelectorAll('#chat-list-content .msg-row');
    var q = (query || '').toLowerCase().trim();
    rows.forEach(function(row) {
        var name = row.querySelector('b') ? row.querySelector('b').textContent.toLowerCase() : '';
        row.style.display = (q === '' || name.includes(q)) ? '' : 'none';
    });
}

async function searchUsersForMessage(query) {
    var results = document.getElementById('compose-results');
    if (!results) return;
    if (!query || query.trim().length < 2) {
        results.innerHTML = '<p style="text-align:center; color:#aaa; font-size:13px; padding:30px 0;">Search for someone to message</p>';
        return;
    }
    results.innerHTML = '<div style="text-align:center; padding:20px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;"></i></div>';
    var users = [];
    if (window.sb) {
        try {
            var r = await sb.from('users')
                .select('id,full_name,username,avatar_url,badge_tier,verified')
                .or('username.ilike.%' + query + '%,full_name.ilike.%' + query + '%')
                .limit(15);
            users = r.data || [];
        } catch(e) { if (e) console.warn('[Suppressed error]', e); }
    }
    if (!users.length) {
        // Fallback to local USERS array
        users = (typeof USERS !== 'undefined' ? USERS : [])
            .filter(function(u) {
                return (u.name || '').toLowerCase().includes(query.toLowerCase()) ||
                       (u.handle || '').toLowerCase().includes(query.toLowerCase());
            })
            .map(function(u) { return { id: u.id || null, full_name: u.name, username: u.handle.replace('@',''), badge_tier: u.tier, verified: true }; });
    }
    if (!users.length) {
        results.innerHTML = '<p style="text-align:center; color:#aaa; font-size:13px; padding:30px 0;">No users found for "' + escapeHtml(query) + '"</p>';
        return;
    }
    results.innerHTML = '';
    users.forEach(function(u) {
        var avatar = u.avatar_url || ('https://ui-avatars.com/api/?name=' + encodeURIComponent(u.full_name || 'U') + '&background=007AFF&color=fff');
        var badge = u.badge_tier || 'verify-blue';
        var div = document.createElement('div');
        div.style.cssText = 'display:flex; align-items:center; gap:12px; padding:13px 0; border-bottom:1px solid var(--border-color,#f5f5f5); cursor:pointer;';
        div.onclick = function() {
            if (!_canStartDM()) return;   // unverified users can't start a new conversation
            closePage('contacts-overlay');
            window._currentChatUserId = u.id || null;
            currentConversationId = null;
            openChat(u.full_name || u.username || 'User');
        };
        div.innerHTML = '<img src="' + escapeHtml(avatar) + '" style="width:46px; height:46px; border-radius:50%; object-fit:cover; flex-shrink:0;">' +
            '<div style="flex:1;">' +
            '<b style="color:var(--text-primary,#000);">' + escapeHtml(u.full_name || u.username || 'User') + '</b>' +
            (u.verified ? ' <i class="fa-solid fa-circle-check ' + badge + '" style="font-size:11px;"></i>' : '') +
            '<br><small style="color:#888;">@' + escapeHtml(u.username || '') + '</small></div>' +
            '<div style="width:36px; height:36px; border-radius:50%; background:rgba(0,122,255,0.1); display:flex; align-items:center; justify-content:center;">' +
            '<i class="fa-solid fa-paper-plane" style="color:#007AFF; font-size:14px;"></i></div>';
        results.appendChild(div);
    });
}

function openLocationSheet() {
    document.getElementById('locationSheet')?.remove();
    if (!document.getElementById('chat-body')) { showToast('Open a chat first to share location'); return; }
    var app = document.getElementById('app') || document.body;
    var sheet = document.createElement('div');
    sheet.id = 'locationSheet';
    sheet.style.cssText = 'position:absolute;inset:0;z-index:20100;background:var(--bg-primary,#0b0b0f);display:flex;flex-direction:column;';
    sheet.innerHTML =
        '<div style="padding:max(46px,env(safe-area-inset-top,46px)) 16px 10px;display:flex;align-items:center;justify-content:space-between;flex-shrink:0;">' +
            '<button onclick="document.getElementById(\'locationSheet\').remove()" style="width:36px;height:36px;border-radius:50%;background:rgba(128,128,128,0.18);border:none;color:var(--text-primary,#fff);font-size:16px;cursor:pointer;"><i class="fa-solid fa-xmark"></i></button>' +
            '<b style="font-size:17px;color:var(--text-primary,#fff);">Send location</b>' +
            '<button onclick="_locRecenter()" title="Recenter" style="width:36px;height:36px;border-radius:50%;background:rgba(128,128,128,0.18);border:none;color:#34C759;font-size:15px;cursor:pointer;"><i class="fa-solid fa-location-crosshairs"></i></button>' +
        '</div>' +
        '<div id="locMap" style="flex:1;position:relative;background:#1a2433;min-height:180px;"></div>' +
        '<div style="background:var(--bg-primary,#111);border-top:1px solid rgba(128,128,128,0.15);padding:12px 16px max(20px,env(safe-area-inset-bottom,20px));flex-shrink:0;max-height:46%;overflow-y:auto;">' +
            '<div onclick="_openLiveLocationPicker()" style="display:flex;align-items:center;gap:12px;padding:14px;border-radius:14px;background:rgba(52,199,89,0.12);cursor:pointer;margin-bottom:10px;">' +
                '<div style="width:38px;height:38px;border-radius:50%;background:rgba(52,199,89,0.2);display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fa-solid fa-location-arrow" style="color:#34C759;font-size:16px;"></i></div>' +
                '<span style="color:#34C759;font-size:15px;font-weight:700;">Share live location</span>' +
            '</div>' +
            '<div onclick="_sendCurrentLocation()" style="display:flex;align-items:center;gap:12px;padding:14px;border-radius:14px;background:rgba(0,122,255,0.1);cursor:pointer;">' +
                '<div style="width:38px;height:38px;border-radius:50%;background:rgba(0,122,255,0.2);display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fa-solid fa-location-dot" style="color:#007AFF;font-size:16px;"></i></div>' +
                '<div style="flex:1;"><div style="color:var(--text-primary,#fff);font-size:15px;font-weight:700;">Send your current location</div><div id="locAccuracy" style="color:#888;font-size:12px;margin-top:1px;">Locating…</div></div>' +
            '</div>' +
            '<div id="locNearby"></div>' +
        '</div>';
    app.appendChild(sheet);
    _locInitMap();
}

function _locInitMap() {
    var accEl = function(){ return document.getElementById('locAccuracy'); };
    if (!window.L) { if (accEl()) accEl().textContent = 'Map unavailable'; return; }
    try {
        var map = L.map('locMap', { zoomControl: false, attributionControl: false }).setView([-26.2041, 28.0473], 14);
        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19 }).addTo(map);
        window._locMap = map; window._locMarker = null; window._locPos = null;
        setTimeout(function(){ try { map.invalidateSize(); } catch(e){} }, 250);
        _getAccuratePosition(function(pos) {
            var lat = pos.coords.latitude, lng = pos.coords.longitude;
            window._locPos = { lat: lat, lng: lng, acc: pos.coords.accuracy };
            map.setView([lat, lng], 16);
            if (window._locMarker) map.removeLayer(window._locMarker);
            window._locMarker = L.circleMarker([lat, lng], { radius: 10, color: '#fff', weight: 3, fillColor: '#34C759', fillOpacity: 1 }).addTo(map);
            if (accEl()) accEl().textContent = 'Accurate to ' + Math.round(pos.coords.accuracy || 0) + 'm';
            _locLoadNearby(lat, lng);
        }, function(err) {
            if (accEl()) accEl().textContent = (err && err.code === 1) ? 'Allow location access to share it' : 'Could not get your location';
            if (err && err.code === 1 && typeof showLocationPermissionAlert === 'function') showLocationPermissionAlert();
        });
    } catch(e) { if (accEl()) accEl().textContent = 'Map error'; }
}

function _locRecenter() {
    if (window._locMap && window._locPos) window._locMap.setView([window._locPos.lat, window._locPos.lng], 16);
}

function _locLoadNearby(lat, lng) {
    var host = document.getElementById('locNearby');
    if (!host) return;
    fetch('https://nominatim.openstreetmap.org/reverse?format=json&lat=' + lat + '&lon=' + lng + '&zoom=18', { headers: { 'Accept': 'application/json' } })
        .then(function(r){ return r.json(); })
        .then(function(d) {
            if (!document.getElementById('locNearby')) return;
            var a = (d && d.address) || {};
            var name = (d && d.name) || a.road || a.suburb || a.neighbourhood || a.town || 'Current area';
            var full = (d && d.display_name) || '';
            host.innerHTML = '<div style="font-size:12px;font-weight:800;color:#888;text-transform:uppercase;letter-spacing:0.05em;margin:14px 2px 4px;">Nearby</div>' +
                '<div onclick="_sendCurrentLocation()" style="display:flex;align-items:center;gap:12px;padding:12px 4px;cursor:pointer;border-top:0.5px solid rgba(128,128,128,0.12);">' +
                    '<i class="fa-solid fa-location-dot" style="color:#888;font-size:16px;width:20px;text-align:center;flex-shrink:0;"></i>' +
                    '<div style="flex:1;min-width:0;"><div style="color:var(--text-primary,#fff);font-size:14px;font-weight:600;">' + escapeHtml(name) + '</div><div style="color:#888;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(full) + '</div></div>' +
                '</div>';
        }).catch(function(){});
}

// Live-location duration picker (map already chosen). Matches WhatsApp's sheet.
function _openLiveLocationPicker() {
    document.getElementById('liveLocPicker')?.remove();
    var ov = document.createElement('div');
    ov.id = 'liveLocPicker';
    ov.style.cssText = 'position:absolute;inset:0;z-index:20200;background:rgba(0,0,0,0.5);display:flex;align-items:flex-end;';
    ov.onclick = function(e){ if (e.target === ov) ov.remove(); };
    var durs = [{ l: '15 Minutes', v: 'For 15 minutes' }, { l: '1 Hour', v: 'For 1 hour' }, { l: '8 Hours', v: 'For 8 hours' }];
    window._liveLocSelectedDur = 'For 1 hour';
    ov.innerHTML =
        '<div style="width:100%;background:var(--bg-primary,#111);border-radius:22px 22px 0 0;padding:14px 20px max(24px,env(safe-area-inset-bottom,24px));" onclick="event.stopPropagation()">' +
            '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">' +
                '<b style="font-size:18px;color:var(--text-primary,#fff);">Share live location</b>' +
                '<button onclick="document.getElementById(\'liveLocPicker\').remove()" style="width:30px;height:30px;border-radius:50%;background:rgba(128,128,128,0.2);border:none;color:#888;cursor:pointer;"><i class="fa-solid fa-xmark"></i></button>' +
            '</div>' +
            '<div id="liveLocDurs">' + durs.map(function(d, i) {
                var on = (i === 1);
                return '<div onclick="_selLiveDur(this,\'' + d.v + '\')" data-v="' + d.v + '" style="text-align:center;padding:13px;border-radius:12px;margin-bottom:6px;font-size:16px;font-weight:' + (on ? '800' : '600') + ';color:' + (on ? 'var(--text-primary,#fff)' : '#888') + ';background:' + (on ? 'rgba(128,128,128,0.15)' : 'transparent') + ';cursor:pointer;">' + d.l + '</div>';
            }).join('') + '</div>' +
            '<div style="display:flex;align-items:center;gap:10px;margin-top:10px;">' +
                '<input id="liveLocCaption" placeholder="Add a caption..." style="flex:1;background:rgba(128,128,128,0.12);border:none;border-radius:24px;padding:12px 16px;font-size:15px;color:var(--text-primary,#fff);outline:none;">' +
                '<button onclick="_confirmLiveLocation()" style="width:48px;height:48px;border-radius:50%;background:#34C759;border:none;color:#fff;font-size:18px;cursor:pointer;flex-shrink:0;"><i class="fa-solid fa-location-arrow"></i></button>' +
            '</div>' +
        '</div>';
    (document.getElementById('app') || document.body).appendChild(ov);
}

function _selLiveDur(el, v) {
    window._liveLocSelectedDur = v;
    document.querySelectorAll('#liveLocDurs [data-v]').forEach(function(d) {
        var on = d.getAttribute('data-v') === v;
        d.style.background = on ? 'rgba(128,128,128,0.15)' : 'transparent';
        d.style.color = on ? 'var(--text-primary,#fff)' : '#888';
        d.style.fontWeight = on ? '800' : '600';
    });
}

function _confirmLiveLocation() {
    var cap = (document.getElementById('liveLocCaption') || {}).value || '';
    var dur = window._liveLocSelectedDur || 'For 1 hour';
    document.getElementById('liveLocPicker')?.remove();
    document.getElementById('locationSheet')?.remove();
    _sendLiveLocation(dur, cap);
}

function _sendCurrentLocation(caption) {
    document.getElementById('locationSheet')?.remove();
    _sendLiveLocation('Send My Current Location', caption || '');
}

var _liveLocWatch = null, _liveLocTimer = null, _liveLocMsgId = null, _liveLocLocalId = null;
var _LIVE_DUR = { 'For 15 minutes': 15*60000, 'For 1 hour': 60*60000, 'For 8 hours': 8*3600000, 'Until I turn it off': 24*3600000 };

// Accurate fix: try GPS (high accuracy, fresh) first — that's what phones use —
// and only fall back to coarse WiFi/IP if GPS times out (e.g. on a desktop).
// The old coarse-only path put the pin blocks/miles from where you actually are.
function _getAccuratePosition(onOk, onErr) {
    if (!navigator.geolocation) { if (onErr) onErr({ code: 2, message: 'no geolocation' }); return; }
    navigator.geolocation.getCurrentPosition(onOk, function() {
        navigator.geolocation.getCurrentPosition(onOk, function(e2){ if (onErr) onErr(e2); },
            { enableHighAccuracy: false, timeout: 15000, maximumAge: 20000 });
    }, { enableHighAccuracy: true, timeout: 12000, maximumAge: 0 });
}

function _sendLiveLocation(duration, caption) {
    if (!navigator.geolocation) { showToast('Location not available'); return; }
    var isLive = duration !== 'Send My Current Location';
    var durMs = _LIVE_DUR[duration] || 15*60000;
    caption = caption || '';
    var opts = { enableHighAccuracy: true, timeout: 20000, maximumAge: 5000 };
    _getAccuratePosition(function(pos) {
        console.log('[Location] position acquired:', pos.coords.latitude, pos.coords.longitude);
        var lat = pos.coords.latitude, lng = pos.coords.longitude;
        var chatBody = document.getElementById('chat-body');
        if (!chatBody) { showToast('Open a chat first to share location'); return; }
        var localId = 'loc' + Date.now();
        var liveUntil = isLive ? new Date(Date.now() + durMs).toISOString() : null;
        var m = {
            id: localId, sender_id: currentUser ? currentUser.id : null, message_type: 'location',
            location_lat: lat, location_lng: lng, location_live: isLive,
            location_live_until: liveUntil, ciphertext: caption || null, created_at: new Date().toISOString(), status: 'sent'
        };
        chatBody.insertAdjacentHTML('beforeend', renderMessageBubble(m));
        chatBody.scrollTop = chatBody.scrollHeight;
        triggerHaptic && triggerHaptic(15);
        if (window.sb && currentUser && currentConversationId) {
            window.sb.from('messages').insert({
                conversation_id: currentConversationId, sender_id: currentUser.id, message_type: 'location',
                location_lat: lat, location_lng: lng, location_live: isLive,
                location_live_until: liveUntil, ciphertext: caption || null, created_at: m.created_at
            }).select('id').single().then(function(res) {
                if (res.error) { console.error('[Location] insert failed:', res.error.message); showToast('Could not send location'); return; }
                if (isLive && res.data && res.data.id) _startLiveLocationWatch(res.data.id, localId, durMs, opts);
            });
        } else if (!currentConversationId) {
            showToast('Open a chat first to share location');
        }
    }, function(err) {
        console.warn('[Location] geolocation error:', err && err.code, err && err.message);
        if (err && err.code === 1) { showToast('Allow location access to share it'); showLocationPermissionAlert(); }
        else if (err && err.code === 3) { showToast('Location timed out. Try again'); }
        else { showToast('Couldn\'t get your location'); }
    });
}

// WhatsApp-style live tracking: keep updating the shared location for the
// chosen duration so the recipient sees the pin move. Auto-stops at the end.
function _startLiveLocationWatch(dbId, localId, durMs, opts) {
    _stopLiveLocation(true);
    _liveLocMsgId = dbId; _liveLocLocalId = localId;
    _liveLocWatch = navigator.geolocation.watchPosition(function(pos) {
        var lat = pos.coords.latitude, lng = pos.coords.longitude;
        if (window.sb) window.sb.from('messages').update({ location_lat: lat, location_lng: lng }).eq('id', dbId).then(function(){}).catch(function(){});
        // Update the sender's own bubble map preview
        var img = document.querySelector('[data-msg-id="' + localId + '"] img');
        if (img && typeof _osmTileUrl === 'function') img.src = _osmTileUrl(lat, lng, 15);
    }, function(err) { console.warn('[Location] watch error:', err && err.code); }, { enableHighAccuracy: true, timeout: 20000, maximumAge: 5000 });
    _liveLocTimer = setTimeout(function() { _stopLiveLocation(); }, durMs);
}

// "Stop sharing" on a live-location bubble → confirm, then stop + update the bubble.
function _confirmStopLiveLocation(msgId) {
    document.getElementById('stopLiveLocModal')?.remove();
    var ov = document.createElement('div');
    ov.id = 'stopLiveLocModal';
    ov.style.cssText = 'position:absolute;inset:0;z-index:19000;background:rgba(0,0,0,0.5);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:24px;';
    ov.onclick = function(e){ if (e.target === ov) ov.remove(); };
    ov.innerHTML = '<div style="width:100%;max-width:320px;background:var(--card-bg,#1c1c1e);border-radius:20px;padding:24px 20px;text-align:center;" onclick="event.stopPropagation()">' +
        '<b style="font-size:17px;color:var(--text-primary,#fff);display:block;margin-bottom:8px;">Stop sharing location?</b>' +
        '<p style="font-size:14px;color:#888;margin-bottom:20px;line-height:1.45;">Are you sure you want to stop sharing your live location?</p>' +
        '<div style="display:flex;gap:10px;">' +
            '<button onclick="document.getElementById(\'stopLiveLocModal\').remove()" style="flex:1;padding:13px;border-radius:14px;border:none;background:rgba(128,128,128,0.2);color:var(--text-primary,#fff);font-size:15px;font-weight:700;cursor:pointer;">Cancel</button>' +
            '<button onclick="_doStopLiveLocation(\'' + escapeHtml(String(msgId)) + '\')" style="flex:1;padding:13px;border-radius:14px;border:none;background:#FF3B30;color:#fff;font-size:15px;font-weight:700;cursor:pointer;">Stop sharing</button>' +
        '</div></div>';
    (document.getElementById('app') || document.body).appendChild(ov);
}

function _doStopLiveLocation(msgId) {
    document.getElementById('stopLiveLocModal')?.remove();
    if (typeof _stopLiveLocation === 'function') _stopLiveLocation(true);
    var bubble = document.querySelector('[data-msg-id="' + msgId + '"]');
    if (bubble) {
        var banner = bubble.querySelector('[data-live-banner]');
        if (banner) {
            banner.innerHTML = '<i class="fa-solid fa-location-arrow" style="color:#FF453A;font-size:13px;"></i><span style="color:rgba(255,255,255,0.9);font-size:13px;font-weight:600;">Live sharing ended</span>';
            banner.removeAttribute('data-live-banner');
        }
        var stopBtn = bubble.querySelector('[data-stop-live]'); if (stopBtn) stopBtn.remove();
    }
    showToast('Stopped sharing location');
    triggerHaptic && triggerHaptic(20);
}

function _stopLiveLocation(silent) {
    if (_liveLocWatch != null) { try { navigator.geolocation.clearWatch(_liveLocWatch); } catch(e){} _liveLocWatch = null; }
    if (_liveLocTimer) { clearTimeout(_liveLocTimer); _liveLocTimer = null; }
    if (_liveLocMsgId && window.sb) window.sb.from('messages').update({ location_live: false }).eq('id', _liveLocMsgId).then(function(){}).catch(function(){});
    _liveLocMsgId = null; _liveLocLocalId = null;
    if (!silent) showToast('Live location stopped');
}

function showLocationPermissionAlert() {
    var app = document.getElementById('app') || document.body;
    var a = document.createElement('div');
    a.style.cssText = 'position:absolute;inset:0;z-index:19000;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,0.4);backdrop-filter:blur(6px);padding:20px;';
    a.innerHTML =
        '<div style="background:white;border-radius:16px;padding:24px 20px;max-width:300px;width:100%;text-align:center;box-shadow:0 16px 48px rgba(0,0,0,0.3);">' +
            '<b style="font-size:17px;color:#000;display:block;margin-bottom:10px;">Please Allow Access</b>' +
            '<p style="font-size:13px;color:#555;line-height:1.5;margin-bottom:20px;">TrustFirst needs background location access to share your location even when the app is closed. Please go to device settings and allow location access.</p>' +
            '<div style="display:flex;gap:0;border-top:0.5px solid rgba(0,0,0,0.1);">' +
                '<button onclick="this.closest(\'[style*=inset]\').remove()" style="flex:1;padding:14px;background:transparent;border:none;border-right:0.5px solid rgba(0,0,0,0.1);color:#007AFF;font-size:15px;cursor:pointer;font-weight:500;">Not Now</button>' +
                '<button onclick="this.closest(\'[style*=inset]\').remove()" style="flex:1;padding:14px;background:transparent;border:none;color:#007AFF;font-size:15px;font-weight:700;cursor:pointer;">Settings</button>' +
            '</div>' +
        '</div>';
    app.appendChild(a);
}

function getLocation() {
    if (!navigator.geolocation) { showToast('Location not supported on this device'); return; }
    navigator.geolocation.getCurrentPosition(
        function(pos) {
            window._postLocationLat = pos.coords.latitude;
            window._postLocationLng = pos.coords.longitude;

        },
        function() { showToast('Location access was denied'); }
    );
}

// --- FEED ENGINE ---
async function initFeed() {
    var feed = document.getElementById('feed-panels');
    if (!feed) return;
    currentFeedPage = 1;

    // Instant render from the last cached feed so an offline open is never empty.
    var _cachedFeed = null;
    try { _cachedFeed = JSON.parse(localStorage.getItem('tf_feed_cache') || 'null'); } catch (e) {}
    if (_cachedFeed && _cachedFeed.length) {
        feed.innerHTML = '';
        _cachedFeed.filter(function(p) { return !isTrustClipPost(p); }).forEach(function(p) { try { feed.appendChild(renderRealPostCard(p)); } catch (e) {} });
    } else {
        feed.innerHTML = '';
        showSkeleton(feed, 'post', 4);
    }

    try {
        var posts = await RealData.getFeed(1, 20);
        if (posts && posts.length) {
            feed.innerHTML = '';
            posts.filter(function(p) { return !isTrustClipPost(p); }).forEach(function(p) { feed.appendChild(renderRealPostCard(p)); });
            try { localStorage.setItem('tf_feed_cache', JSON.stringify(posts.slice(0, 12))); } catch (e) {}
        } else if (!_cachedFeed || !_cachedFeed.length) {
            feed.innerHTML = '<div style="text-align:center;padding:60px 20px;color:#aaa;"><i class="fa-regular fa-newspaper" style="font-size:40px;margin-bottom:16px;display:block;"></i><p style="font-weight:600;color:var(--text-primary,#000);margin-bottom:6px;">Nothing here yet</p><p style="font-size:13px;">Follow people to see their posts here.</p></div>';
        }
    } catch(e) {
        console.error('[initFeed]', e);
        // Offline: keep the cached posts on screen; only show an error if there's nothing cached.
        if (!_cachedFeed || !_cachedFeed.length) {
            feed.innerHTML = '<div style="text-align:center;padding:40px 20px;color:#aaa;"><i class="fa-solid fa-wifi" style="font-size:30px;opacity:0.4;display:block;margin-bottom:12px;"></i><p style="margin-bottom:14px;">You\'re offline. Connect to load your feed.</p><button onclick="initFeed()" style="padding:10px 24px;border-radius:22px;border:none;background:#007AFF;color:#fff;font-size:14px;font-weight:700;cursor:pointer;">Retry</button></div>';
        }
    }

    var _pg1 = document.getElementById('profile-grid');
    if (_pg1 && typeof loadProfilePosts === 'function') loadProfilePosts(_pg1);
    renderParentRequests();
}

// Pull-to-refresh on feed
(function() {
    var startY = 0, pulling = false, refreshEl = null;
    var feedEl = document.getElementById('feed-panels');
    if (!feedEl) return;
    feedEl.addEventListener('touchstart', function(e) {
        if (feedEl.scrollTop === 0) { startY = e.touches[0].clientY; pulling = true; }
    }, { passive: true });
    feedEl.addEventListener('touchend', function(e) {
        if (pulling && (e.changedTouches[0].clientY - startY) > 70) {
            if (refreshEl) refreshEl.remove();
            initFeed();
        }
        pulling = false;
    }, { passive: true });
})();

function handleRepost(postId) {
    if (!canPerformAction('repost')) return;
    if (postId) _activePostMenuId = postId;
    openRepost(postId);
}

// Keep the feed DOM bounded so long scroll sessions stay smooth (recycles the
// oldest post cards off the top and compensates scrollTop so the view is stable).
function _capFeedDom(f) {
    if (!f) return;
    var CAP = 120;
    var cards = f.querySelectorAll('.post-card');
    if (cards.length <= CAP) return;
    var removeCount = cards.length - CAP;
    // Preserve distance-from-bottom so the viewport stays put after trimming the
    // top — correct in every browser (unlike manual delta, which fights scroll
    // anchoring on Chrome and is absent on Safari).
    var distFromBottom = f.scrollHeight - f.scrollTop;
    for (var i = 0; i < removeCount; i++) { if (cards[i]) cards[i].remove(); }
    f.scrollTop = Math.max(0, f.scrollHeight - distFromBottom);
}

// --- SCROLL HANDLER (single version) ---
document.addEventListener('DOMContentLoaded', function() {
    var feedEl = document.getElementById('feed-panels');
    if (!feedEl) return;
    feedEl.onscroll = function () {
    const btt = document.getElementById('btt');
    if (btt) btt.style.display = this.scrollTop > 500 ? 'block' : 'none';

    if (this.scrollTop + this.clientHeight >= this.scrollHeight - 200 && !isLoading) {
        isLoading = true;
        const loader = document.createElement('div');
        loader.id = 'feed-loader';
        loader.innerHTML = '<div style="text-align:center; padding:20px; color:#007AFF;"><i class="fa-solid fa-spinner fa-spin"></i></div>';
        this.appendChild(loader);

        var nextPage = (currentFeedPage || 1) + 1;
        RealData.getFeed(nextPage, 10).then(function(posts) {
            var el = document.getElementById('feed-loader');
            if (el) el.remove();
            if (posts && posts.length) {
                currentFeedPage = nextPage;
                var f = document.getElementById('feed-panels');
                posts.forEach(function(p) { if (f) f.appendChild(renderRealPostCard(p)); });
                _capFeedDom(f);
            }
            isLoading = false;
        }).catch(function() {
            var el = document.getElementById('feed-loader');
            if (el) el.remove();
            isLoading = false;
        });
    }
};
});


// --- INTERACTIONS ---
// ==========================================================================
// Social notifications — like, follow, mention, reply.
// One place so every trigger notifies the same way, nobody is notified about
// their own action, and Eddie (a bot) is never pinged. The notifications table
// only has user_id, actor_id, type, post_id, message, read; anything else the
// insert would reject, so these stick to those columns.
// ==========================================================================
var _TF_EDDIE_ID = 'edd1e000-0000-4000-8000-000000000001';

function _tfActorName() {
    return (currentUser && (currentUser.username || currentUser.name)) || 'Someone';
}

function _tfNotify(userId, row) {
    if (!window.sb || !currentUser || !userId) return;
    if (userId === currentUser.id || userId === _TF_EDDIE_ID) return;   // no self / bot pings
    sb.from('notifications').insert(Object.assign({
        user_id: userId, actor_id: currentUser.id, read: false
    }, row)).then(function () {}).catch(function () {});
}

// "X liked your post" — looked up so it fires once, to the owner only.
function tfNotifyLike(postId) {
    if (!postId || !window.sb || !currentUser) return;
    sb.from('posts').select('user_id').eq('id', postId).single().then(function (res) {
        var owner = res && res.data && res.data.user_id;
        if (owner) _tfNotify(owner, { type: 'like', post_id: postId,
            message: _tfActorName() + ' liked your post' });
    }).catch(function () {});
}

function tfNotifyFollow(targetUserId) {
    _tfNotify(targetUserId, { type: 'follow',
        message: _tfActorName() + ' started following you' });
}

// One "X mentioned you" per real @username in the text. Usernames are matched
// case-insensitively by trying both the written and lowercased form; a handle
// that resolves to nobody is simply skipped, and @eddie is left to its own
// reply flow rather than a mention ping.
function tfNotifyMentions(text, extra) {
    if (!text || !window.sb || !currentUser) return;
    var raw = (text.match(/@([a-zA-Z0-9_]{2,30})/g) || []).map(function (m) { return m.slice(1); });
    var variants = [];
    raw.forEach(function (n) {
        if (n.toLowerCase() === 'eddie') return;
        if (variants.indexOf(n) < 0) variants.push(n);
        if (variants.indexOf(n.toLowerCase()) < 0) variants.push(n.toLowerCase());
    });
    if (!variants.length) return;
    sb.from('users').select('id,username').in('username', variants).then(function (res) {
        var seen = {};
        (res.data || []).forEach(function (u) {
            if (seen[u.id]) return;
            seen[u.id] = true;
            _tfNotify(u.id, Object.assign({ type: 'mention',
                message: _tfActorName() + ' mentioned you' }, extra || {}));
        });
    }).catch(function () {});
}

function toggleLike(el) {
    if (typeof el === 'string') {
        el = document.querySelector('[data-post-id="' + el + '"] .post-icons div:first-child') || document.querySelector('[data-post-id="' + el + '"] .like-btn');
        if (!el) return;
    }
    // Resolve post ID from DOM
    var postCard = el.closest('[data-post-id]');
    var postId = postCard ? postCard.getAttribute('data-post-id') : null;
    if (postId) {
        realToggleLike(el, postId);
    } else {
        // Fallback: optimistic only (post has no ID yet — warn dev)
        console.warn('[toggleLike] No post ID found on element. Like will not persist.');
        var i = el.querySelector('i');
        var span = el.querySelector('span');
        triggerHaptic(30);
        i.classList.toggle('fa-regular');
        i.classList.toggle('fa-solid');
        var liked = i.classList.contains('fa-solid');
        i.style.color = liked ? '#FF3B30' : '';
        if (span) span.textContent = liked ? (parseInt(span.textContent)||0)+1 : Math.max(0,(parseInt(span.textContent)||0)-1);
        i.classList.add('like-active');
        setTimeout(function(){ i.classList.remove('like-active'); }, 300);
    }
}

function toggleBookmark(el) {
    var postCard = el.closest('[data-post-id]');
    var postId = postCard ? postCard.getAttribute('data-post-id') : null;
    if (postId) {
        realToggleBookmark(el, postId);
    } else {
        console.warn('[toggleBookmark] No post ID found. Bookmark will not persist.');
        var i = el.querySelector('i');
        triggerHaptic(15);
        i.classList.toggle('fa-regular');
        i.classList.toggle('fa-solid');
        var bookmarked = i.classList.contains('fa-solid');
        i.style.color = bookmarked ? '#007AFF' : '';
        i.classList.add('bookmark-active');
        setTimeout(function(){ i.classList.remove('bookmark-active'); }, 300);
    }
}

function openRepost(postId) {
    if (postId) _activePostMenuId = postId;
    if (window.sb && currentUser && postId) {
        sb.from('reposts').select('id').eq('user_id', currentUser.id).eq('post_id', postId).maybeSingle().then(function(res) {
            var label = document.getElementById('repost-btn-label');
            if (label) label.textContent = res.data ? 'Remove Repost' : 'Repost';
        });
    }
    document.getElementById('repost-sheet').classList.add('active');
    triggerHaptic(10);
}

function closeRepost() {
    document.getElementById('repost-sheet').classList.remove('active');
}

async function handleRepostOrUndo(el) {
    if (!_activePostMenuId || !window.sb || !currentUser) { animateRepost(el); return; }
    var existing = await sb.from('reposts').select('id').eq('user_id', currentUser.id).eq('post_id', _activePostMenuId).maybeSingle();
    animateRepost(el);
}

function animateRepost(el) {
    const i = el.querySelector('i');
    i.style.color = '#34C759';
    i.classList.add('repost-spin');
    triggerHaptic(50);
    // Find and update the repost counter in the original post
    if (_activePostMenuId) {
        var postEl = document.querySelector('[data-post-id="' + _activePostMenuId + '"]');
        if (postEl) {
            var repostDivs = postEl.querySelectorAll('.post-icons > div');
            repostDivs.forEach(function(d) {
                if (d.querySelector('.fa-retweet')) {
                    var s = d.querySelector('span');
                    if (s) s.textContent = (parseInt(s.textContent)||0) + 1;
                    d.querySelector('i').style.color = '#34C759';
                }
            });
        }
    }
    setTimeout(async function() {
        i.classList.remove('repost-spin');
        closeRepost();
        if (_activePostMenuId && window.sb && currentUser) {
            var postId = _activePostMenuId;
            // Check if already reposted — toggle
            var existing = await sb.from('reposts').select('id').eq('user_id', currentUser.id).eq('post_id', postId).maybeSingle();
            var postEl = document.querySelector('[data-post-id="' + postId + '"]');
            if (existing.data) {
                // UNDO repost
                await sb.from('reposts').delete().eq('id', existing.data.id);
                var cur = await sb.from('posts').select('repost_count').eq('id', postId).single();
                await sb.from('posts').update({ repost_count: Math.max(0, (cur.data?.repost_count || 1) - 1) }).eq('id', postId);
                if (postEl) {
                    postEl.querySelectorAll('.post-icons > div').forEach(function(d) {
                        if (d.querySelector('.fa-retweet')) {
                            var s = d.querySelector('span');
                            if (s) s.textContent = Math.max(0, (parseInt(s.textContent)||0) - 1);
                            d.querySelector('i').style.color = '';
                            d.setAttribute('data-reposted', 'false');
                        }
                    });
                }
                // Remove from localStorage reposts tab
                var reposts = JSON.parse(localStorage.getItem('user_reposts_' + currentUser.id) || '[]');
                reposts = reposts.filter(function(p) { return p.id !== postId; });
                localStorage.setItem('user_reposts_' + currentUser.id, JSON.stringify(reposts));
                showToast('Repost removed');
            } else {
                // NEW repost
                var { error } = await sb.from('reposts').insert({ user_id: currentUser.id, post_id: postId });
                if (error) {
                    if (postEl) {
                        postEl.querySelectorAll('.post-icons > div').forEach(function(d) {
                            if (d.querySelector('.fa-retweet')) {
                                var s = d.querySelector('span');
                                if (s) s.textContent = Math.max(0, (parseInt(s.textContent)||0) - 1);
                                d.querySelector('i').style.color = '';
                            }
                        });
                    }
                    showToast('Repost failed. Try again.');
                } else {
                    var cur = await sb.from('posts').select('repost_count,text_content,media_url,post_type,created_at,users:user_id(full_name,username,avatar_url,badge_tier,verified,ai_label)').eq('id', postId).single();
                    await sb.from('posts').update({ repost_count: (cur.data?.repost_count || 0) + 1 }).eq('id', postId);
                    if (postEl) postEl.querySelectorAll('.post-icons > div').forEach(function(d) {
                        if (d.querySelector('.fa-retweet')) d.setAttribute('data-reposted', 'true');
                    });
                    // Save to localStorage for reposts tab
                    var reposts = JSON.parse(localStorage.getItem('user_reposts_' + currentUser.id) || '[]');
                    if (cur.data) reposts.unshift(cur.data);
                    localStorage.setItem('user_reposts_' + currentUser.id, JSON.stringify(reposts));
                }
            }
        }
    }, 600);
}

// --- MESSAGES ---
function launchMessageHub() {
    // Everyone can open messages to read and reply; sending is gated per-conversation
    // (unverified users can reply to verified-initiated chats but can't start new ones).
    const nav = document.querySelector('.nav-container');
    if (nav) nav.style.display = 'none';
    openPage('msg-overlay');
    document.querySelectorAll('.m-tab').forEach(function(t) { t.classList.remove('active'); });
    var primaryTab = document.querySelector('.m-tab');
    if (primaryTab) primaryTab.classList.add('active');
    fillMsgContent();
    // Re-load on every open to reflect new messages
    setTimeout(fillMsgContent, 600);
}

setMsgTab('primary', document.querySelector('.m-tab'));
function closeMessageHub() {
    if (window._vnAudio) { try { window._vnAudio.pause(); window._vnAudio.currentTime = 0; } catch(e){} window._vnAudio = null; window._vnActiveBubble = null; }
    closePage('msg-overlay');
    closePage('chat-interface');
    var nav = document.querySelector('.nav-container');
    if (nav) nav.style.display = 'flex';
    navSetState('collapsed');
}

// ==========================================================================
// LIQUID GLASS INBOX FILTER TRAY
// ==========================================================================
var activeInboxFilter = null;
var filterTrayExpanded = false;

var INBOX_FILTERS = [
    { id: 'unread',      label: 'Unread',           icon: 'fa-envelope',         color: '#007AFF' },
    { id: 'unanswered',  label: 'Unanswered',        icon: 'fa-reply',            color: '#FF9500' },
    { id: 'story_reply', label: 'Story replies',     icon: 'fa-images',           color: '#FF2D55' },
    { id: 'golden',      label: 'Golden Badge users', icon: 'fa-crown',           color: '#FFD700' },
    { id: '10k_plus',    label: '10K+ followers',    icon: 'fa-users',            color: '#34C759' },
];

var INBOX_FILTERS_EXTRA = [
    { id: 'followers',   label: 'Followers',         icon: 'fa-user-check',       color: '#5856D6' },
    { id: 'following',   label: 'Following',         icon: 'fa-user-plus',        color: '#007AFF' },
    { id: 'businesses',  label: 'Businesses',        icon: 'fa-briefcase',        color: '#FF9500' },
];

function openInboxFilterTray() {
    var existing = document.getElementById('inboxFilterTray');
    if (existing) { existing.remove(); return; }
    filterTrayExpanded = false;
    renderInboxFilterTray();
}

function renderInboxFilterTray() {
    var existing = document.getElementById('inboxFilterTray');
    if (existing) existing.remove();

    var tray = document.createElement('div');
    tray.id = 'inboxFilterTray';
    tray.style.cssText = 'position:absolute;bottom:0;left:0;right:0;z-index:9000;animation:slideUpOverlay 0.38s cubic-bezier(0.32,0.72,0,1);';

    function makeFilterRow(f) {
        var isActive = activeInboxFilter === f.id;
        return '<div onclick="selectInboxFilter(\'' + f.id + '\')" ' +
            'style="display:flex;align-items:center;justify-content:space-between;padding:15px 20px;' +
            'border-bottom:0.5px solid rgba(255,255,255,0.07);cursor:pointer;transition:background 0.15s;" ' +
            'onmouseover="this.style.background=\'rgba(255,255,255,0.06)\'" onmouseout="this.style.background=\'\'">' +
            // Left icon + label
            '<div style="display:flex;align-items:center;gap:14px;">' +
                '<div style="width:38px;height:38px;border-radius:12px;background:' + f.color + '1A;border:0.5px solid ' + f.color + '33;display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
                    '<i class="fa-solid ' + f.icon + '" style="color:' + f.color + ';font-size:15px;"></i>' +
                '</div>' +
                '<span style="font-size:15px;font-weight:600;color:white;">' + f.label + '</span>' +
            '</div>' +
            // Right radio
            '<div style="width:24px;height:24px;border-radius:50%;' +
                (isActive
                    ? 'background:' + f.color + ';border:none;box-shadow:0 2px 10px ' + f.color + '66,inset 0 1px 0 rgba(255,255,255,0.3);display:flex;align-items:center;justify-content:center;'
                    : 'background:rgba(255,255,255,0.06);border:0.5px solid rgba(255,255,255,0.2);') +
                '">' +
                (isActive ? '<i class="fa-solid fa-check" style="color:white;font-size:11px;"></i>' : '') +
            '</div>' +
        '</div>';
    }

    var extraHTML = '';
    if (filterTrayExpanded) {
        extraHTML = '<div id="filterExtraItems" style="animation:fadeUp 0.3s ease backwards;">' +
            INBOX_FILTERS_EXTRA.map(makeFilterRow).join('') +
        '</div>';
    }

    tray.innerHTML =
        // Scrim
        '<div onclick="document.getElementById(\'inboxFilterTray\').remove();" ' +
        'style="position:fixed;top:0;left:0;right:0;bottom:0;z-index:-1;background:rgba(0,0,0,0.4);backdrop-filter:blur(6px);"></div>' +

        '<div style="background:rgba(18,18,22,0.88);backdrop-filter:blur(60px) saturate(220%) brightness(0.85);-webkit-backdrop-filter:blur(60px) saturate(220%) brightness(0.85);border-radius:28px 28px 0 0;border-top:0.5px solid rgba(255,255,255,0.12);box-shadow:0 -20px 60px rgba(0,0,0,0.65),0 -1px 0 rgba(255,255,255,0.06) inset;padding-bottom:48px;">' +

            // Grab handle
            '<div style="text-align:center;padding:12px 0 4px;">' +
                '<div style="width:36px;height:4px;background:rgba(255,255,255,0.2);border-radius:2px;display:inline-block;"></div>' +
            '</div>' +

            // Header
            '<div style="display:flex;align-items:center;justify-content:space-between;padding:10px 20px 14px;border-bottom:0.5px solid rgba(255,255,255,0.08);">' +
                '<h3 style="font-size:17px;font-weight:800;color:white;margin:0;">Filter Inbox</h3>' +
                (activeInboxFilter ? '<button onclick="clearInboxFilter()" style="background:rgba(255,59,48,0.15);border:0.5px solid rgba(255,59,48,0.3);border-radius:12px;padding:5px 12px;color:#FF3B30;font-size:12px;font-weight:700;cursor:pointer;">Clear</button>' : '') +
            '</div>' +

            // Main filter rows
            INBOX_FILTERS.map(makeFilterRow).join('') +

            // Extra rows (if expanded)
            extraHTML +

            // See more / See less
            '<div onclick="toggleFilterTrayExpand()" style="display:flex;align-items:center;justify-content:center;gap:8px;padding:14px;cursor:pointer;color:rgba(255,255,255,0.45);font-size:13px;font-weight:700;" onmouseover="this.style.color=\'rgba(255,255,255,0.8)\'" onmouseout="this.style.color=\'rgba(255,255,255,0.45)\'">' +
                (filterTrayExpanded ? '<i class="fa-solid fa-chevron-up" style="font-size:12px;"></i> See less' : '<i class="fa-solid fa-chevron-down" style="font-size:12px;"></i> See more') +
            '</div>' +

        '</div>';

    (document.getElementById('msg-overlay') || document.getElementById('app') || document.body).appendChild(tray);
    // Swipe the sheet down to dismiss.
    var _fSheet = tray.lastElementChild;
    if (_fSheet && typeof attachSheetSwipeClose === 'function') attachSheetSwipeClose(_fSheet, _fSheet, function(){ tray.remove(); });
}

function toggleFilterTrayExpand() {
    filterTrayExpanded = !filterTrayExpanded;
    renderInboxFilterTray();
    triggerHaptic(10);
}

function selectInboxFilter(filterId) {
    activeInboxFilter = (activeInboxFilter === filterId) ? null : filterId;
    triggerHaptic(20);

    // Apply to chat list
    applyInboxFilter(activeInboxFilter);

    // Update the filter button badge
    var btn = document.getElementById('inboxFilterBtn');
    if (btn) {
        if (activeInboxFilter) {
            btn.style.background = 'rgba(0,122,255,0.2)';
            btn.style.borderColor = 'rgba(0,122,255,0.4)';
            btn.innerHTML = '<i class="fa-solid fa-sliders" style="font-size:12px;"></i> Filtered';
        } else {
            btn.style.background = 'rgba(0,122,255,0.07)';
            btn.style.borderColor = 'rgba(0,122,255,0.2)';
            btn.innerHTML = '<i class="fa-solid fa-sliders" style="font-size:12px;"></i> Filter';
        }
    }

    showToast(activeInboxFilter ? 'Showing: ' + filterId.replace(/_/g,' ') : 'Filter cleared');
    document.getElementById('inboxFilterTray').remove();
}

function clearInboxFilter() {
    activeInboxFilter = null;
    applyInboxFilter(null);
    var btn = document.getElementById('inboxFilterBtn');
    if (btn) {
        btn.style.background = 'rgba(0,122,255,0.07)';
        btn.style.borderColor = 'rgba(0,122,255,0.2)';
        btn.innerHTML = '<i class="fa-solid fa-sliders" style="font-size:12px;"></i> Filter';
    }
    document.getElementById('inboxFilterTray').remove();
    showToast('Filter cleared');
}

function applyInboxFilter(filterId) {
    var rows = document.querySelectorAll('#chat-list-content .msg-row');
    rows.forEach(function(row) {
        if (!filterId) { row.style.display = ''; return; }
        var show = false;
        switch(filterId) {
            case 'unread':      show = row.dataset.unread === 'true'; break;
            case 'unanswered':  show = row.dataset.unanswered === 'true'; break;
            case 'story_reply': show = row.dataset.type === 'story_reply'; break;
            case 'golden':      show = row.dataset.tier === 'golden'; break;
            case '10k_plus':    show = row.dataset.tier === '10k_plus'; break;
            case 'followers':   show = row.dataset.isFollower === 'true'; break;
            case 'following':   show = row.dataset.isFollowing === 'true'; break;
            case 'businesses':  show = row.dataset.accountType === 'business'; break;
            default:            show = true;
        }
        row.style.display = show ? '' : 'none';
    });
}

// Render attribute for chat media: private chat_media / voice_messages assets
// get a placeholder + data-tfmedia (the signer swaps in a signed URL, so the
// dead public URL is never fetched). Public assets keep a normal src.
function _mediaSrcAttr(url, isVideo) {
    if (url && /\/(chat_media|voice_messages)\//.test(url)) {
        return 'data-tfmedia="' + escapeHtml(url) + '"' +
            (isVideo ? '' : ' src="data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///ywAAAAAAQABAAACAUwAOw=="');
    }
    return 'src="' + escapeHtml(url || '') + '"';
}

// ── Safe links in messages ────────────────────────────────────────────────
// Only http(s) links are ever treated as clickable. javascript:, data:,
// file:, etc. are never linked or opened — this blocks the most common
// harmful-link tricks.
function _isSafeUrl(url) {
    try {
        var u = new URL(url);
        return (u.protocol === 'http:' || u.protocol === 'https:') && !!u.hostname && u.hostname.indexOf('.') > 0;
    } catch (e) { return false; }
}
// Readable text for a message row, or null when it is encrypted and this
// device holds no key for it.
//
// E2E keys are generated per device and never leave it, so signing in
// somewhere new produces a keypair that cannot open anything sent before.
// Every render path used to fall back to `m.ciphertext`, which is why those
// chats filled up with base64 instead of words. Ciphertext is only ever shown
// when there is no nonce, meaning the row was never encrypted (group chats and
// older plaintext messages).
function _msgPlainText(m) {
    if (m.content) return m.content;
    if (!m.nonce) return m.ciphertext || '';
    return null;
}

function _firstUrl(text) {
    var m = (text || '').match(/https?:\/\/[^\s]+/);
    if (!m) return null;
    var u = m[0].replace(/[.,!?)\]]+$/, '');
    return _isSafeUrl(u) ? u : null;
}
// Escape text, then turn safe http(s) URLs into in-app-browser links.
function _linkifyMessage(text, isSent) {
    var esc = escapeHtml(text || '');
    var color = isSent ? '#cfe6ff' : '#0a84ff';
    return esc.replace(/(https?:\/\/[^\s<]+)/g, function(match) {
        var trail = '';
        var core = match.replace(/((?:&amp;|[.,!?)\]])+)$/, function(p) { trail = p; return ''; });
        var realUrl = core.replace(/&amp;/g, '&');
        if (!_isSafeUrl(realUrl)) return match;
        var enc = encodeURIComponent(realUrl).replace(/'/g, '%27');
        return '<span onclick="event.stopPropagation();openLinkInApp(decodeURIComponent(\'' + enc + '\'))" ' +
            'style="color:' + color + ';text-decoration:underline;cursor:pointer;word-break:break-all;">' + core + '</span>' + trail;
    });
}
// A lightweight link preview card (favicon + domain), clickable.
function _linkPreviewCard(url) {
    if (!url || !_isSafeUrl(url)) return '';
    var host;
    try { host = new URL(url).hostname.replace(/^www\./, ''); } catch (e) { return ''; }
    var fav = 'https://www.google.com/s2/favicons?domain=' + encodeURIComponent(host) + '&sz=64';
    var enc = encodeURIComponent(url).replace(/'/g, '%27');
    return '<div onclick="openLinkInApp(decodeURIComponent(\'' + enc + '\'))" style="margin-top:6px;display:flex;align-items:center;gap:10px;border-radius:12px;border:0.5px solid rgba(0,0,0,0.12);background:var(--bg-secondary,rgba(0,0,0,0.04));padding:9px 11px;cursor:pointer;max-width:80%;">' +
        '<img src="' + escapeHtml(fav) + '" style="width:30px;height:30px;border-radius:7px;flex-shrink:0;background:#fff;" onerror="this.style.visibility=\'hidden\'">' +
        '<div style="flex:1;min-width:0;">' +
            '<b style="font-size:13px;color:var(--text-primary,#000);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(host) + '</b>' +
            '<small style="font-size:11px;color:#888;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(url) + '</small>' +
        '</div>' +
        '<i class="fa-solid fa-arrow-up-right-from-square" style="color:#999;font-size:12px;flex-shrink:0;"></i>' +
    '</div>';
}
// Open a link inside a sandboxed in-app browser (never a raw new tab).
function openLinkInApp(url) {
    if (!_isSafeUrl(url)) { showToast('That link looks unsafe and was blocked'); return; }
    var host = '';
    try { host = new URL(url).hostname.replace(/^www\./, ''); } catch (e) {}
    var existing = document.getElementById('inAppBrowser'); if (existing) existing.remove();
    var ov = document.createElement('div');
    ov.id = 'inAppBrowser';
    ov.style.cssText = 'position:absolute;inset:0;z-index:30000;background:#fff;display:flex;flex-direction:column;';
    var encUrl = encodeURIComponent(url).replace(/'/g, '%27');
    ov.innerHTML =
        '<div style="flex-shrink:0;display:flex;align-items:center;gap:8px;padding:max(46px,env(safe-area-inset-top,46px)) 12px 10px;background:var(--card-bg,#fff);border-bottom:0.5px solid rgba(0,0,0,0.1);">' +
            '<i class="fa-solid fa-xmark" onclick="document.getElementById(\'inAppBrowser\').remove()" style="font-size:20px;color:var(--text-primary,#000);cursor:pointer;width:34px;text-align:center;"></i>' +
            '<div style="flex:1;min-width:0;text-align:center;"><b style="font-size:14px;color:var(--text-primary,#000);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block;"><i class="fa-solid fa-lock" style="font-size:10px;color:#34C759;margin-right:5px;"></i>' + escapeHtml(host) + '</b></div>' +
            '<i class="fa-solid fa-arrow-up-right-from-square" onclick="window.open(decodeURIComponent(\'' + encUrl + '\'),\'_blank\',\'noopener,noreferrer\')" style="font-size:16px;color:#007AFF;cursor:pointer;width:34px;text-align:center;" title="Open in browser"></i>' +
        '</div>' +
        '<div id="iabHint" style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);color:#aaa;text-align:center;font-size:13px;width:80%;"><i class="fa-solid fa-spinner fa-spin" style="font-size:22px;display:block;margin-bottom:10px;"></i>Loading…<br><span style="font-size:11px;">If the page stays blank, tap the ⤴ icon to open it in your browser.</span></div>' +
        '<iframe src="' + escapeHtml(url) + '" referrerpolicy="no-referrer" sandbox="allow-scripts allow-same-origin allow-forms allow-popups allow-popups-to-escape-sandbox" style="flex:1;width:100%;border:none;background:#fff;" onload="var h=document.getElementById(\'iabHint\');if(h)h.style.display=\'none\';"></iframe>';
    (document.getElementById('app') || document.body).appendChild(ov);
    if (typeof triggerHaptic === 'function') triggerHaptic(10);
}

// ── Delivery / read receipts + presence ────────────────────────────────────
// Tick semantics (WhatsApp-style): 1 grey ✓ = stored, recipient offline;
// 2 grey ✓✓ = delivered to their device; 2 blue ✓✓ = seen. Explicit optimistic
// m.status (uploading/failed/sent) wins; otherwise derive from timestamps.
function _deriveMsgStatus(m) {
    if (m.status) return m.status;
    if (m.read_at) return 'read';
    if (m.delivered_at) return 'delivered';
    return 'sent';
}
function _tickInner(status, variant) {
    var isMedia = variant === 'media', isCap = variant === 'caption';
    var readColor = isMedia ? '#4eaaff' : (isCap ? '#cfe9ff' : '#007AFF');
    var dim = isMedia ? 'rgba(255,255,255,0.92)' : (isCap ? 'rgba(255,255,255,0.85)' : '#8a8a8e');
    var shadow = isMedia ? 'text-shadow:0 1px 3px rgba(0,0,0,0.7);' : '';
    var fs = isMedia ? '11px' : '10px';
    var clockColor = (variant === 'meta') ? '#aaa' : 'rgba(255,255,255,0.75)';
    if (status === 'uploading') return '<i class="fa-regular fa-clock" style="color:' + clockColor + ';font-size:9px;' + shadow + '"></i>';
    if (status === 'failed') return '';
    if (status === 'read') return '<span style="color:' + readColor + ';font-size:' + fs + ';' + shadow + '">✓✓</span>';
    if (status === 'delivered') return '<span style="color:' + dim + ';font-size:' + fs + ';' + shadow + '">✓✓</span>';
    return '<span style="color:' + dim + ';font-size:' + fs + ';' + shadow + '">✓</span>'; // sent
}
// Stable, targetable tick container so realtime UPDATEs can restyle it in place.
function _tickSpan(m, variant) {
    return '<span class="tf-tick" data-tick-for="' + escapeHtml(String(m.id || '')) + '" data-tick-variant="' + variant + '">' +
        _tickInner(_deriveMsgStatus(m), variant) + '</span>';
}
// Realtime: a message row changed (delivered_at/read_at) — restyle its ticks live.
function handleMessageUpdate(m) {
    if (!m || !m.id) return;
    var els = document.querySelectorAll('.tf-tick[data-tick-for="' + String(m.id).replace(/["\\]/g, '') + '"]');
    if (!els.length) return;
    var status = _deriveMsgStatus(m);
    els.forEach(function(el) { el.innerHTML = _tickInner(status, el.getAttribute('data-tick-variant') || 'meta'); });
}
function _markChatRead(convId) {
    if (!convId || !window.sb || !currentUser) return;
    try { sb.rpc('mark_messages_read', { p_conv: convId }).then(function(){}, function(){}); } catch(e) {}
}
function _markChatDelivered(convId) {
    if (!convId || !window.sb || !currentUser) return;
    try { sb.rpc('mark_messages_delivered', { p_conv: convId }).then(function(){}, function(){}); } catch(e) {}
}
// Shared presence: "online" = last_seen within ~70s (heartbeat pings every 25s).
function _presenceFrom(lastSeenIso) {
    if (!lastSeenIso) return { online: false, label: '' };
    var diff = Date.now() - new Date(lastSeenIso).getTime();
    if (diff < 0) diff = 0;
    if (diff < 70000) return { online: true, label: 'Active now' };
    if (diff < 3600000) return { online: false, label: 'Active ' + Math.max(1, Math.floor(diff / 60000)) + 'm ago' };
    if (diff < 86400000) return { online: false, label: 'Active ' + Math.floor(diff / 3600000) + 'h ago' };
    try { return { online: false, label: 'Last seen ' + new Date(lastSeenIso).toLocaleDateString('en-ZA', { day: 'numeric', month: 'short' }) }; } catch (e) { return { online: false, label: '' }; }
}

// ==========================================================================
// CORE MESSAGE RENDERER — handles all message types from Supabase
// ==========================================================================
function renderMessageBubble(m, replyMap) {
    var isSent = currentUser && m.sender_id === currentUser.id;
    var time = m.created_at
        ? new Date(m.created_at).toLocaleTimeString('en-ZA', { hour: '2-digit', minute: '2-digit' })
        : '';
    var status = _deriveMsgStatus(m); // 'uploading' | 'sent' | 'delivered' | 'read' | 'failed'
    var msgType = m.message_type || 'text';
    var align = isSent ? 'margin-left:auto;' : '';
    var msgId = m.id || ('m' + Date.now() + Math.random());

    var tickHtml = isSent ? _tickSpan(m, 'meta') : '';
    var timeHtml = '<div style="display:flex;align-items:center;gap:3px;justify-content:' + (isSent ? 'flex-end' : 'flex-start') + ';margin-top:3px;">' +
        '<small style="font-size:10px;color:rgba(0,0,0,0.35);">' + time + '</small>' + tickHtml + '</div>';

    // White-on-dark tick for media bubbles (rendered over the image/video).
    var mediaTick = isSent ? _tickSpan(m, 'media') : '';

    var wrapStyle = 'position:relative;display:flex;flex-direction:column;' + (isSent ? 'align-items:flex-end;' : 'align-items:flex-start;') + 'margin-bottom:6px;padding:0 2px;';
    var bubbleAttr = ' data-msg-id="' + escapeHtml(String(msgId)) + '" data-msg-type="' + escapeHtml(msgType) + '" data-msg-status="' + escapeHtml(status) + '" data-msg-mine="' + (isSent ? '1' : '0') + '" data-msg-bubble="true"';

    // Quoted reply block (privacy-safe: resolved client-side from reply_to_id).
    var replyQuote = '';
    if (m.reply_to_id && replyMap && replyMap[m.reply_to_id]) {
        var _rq = replyMap[m.reply_to_id];
        replyQuote = '<div style="border-left:3px solid ' + (isSent ? 'rgba(255,255,255,0.7)' : '#FF9500') + ';padding:4px 8px;margin-bottom:5px;background:' + (isSent ? 'rgba(255,255,255,0.14)' : 'rgba(0,0,0,0.05)') + ';border-radius:6px;max-width:100%;overflow:hidden;">' +
            '<div style="font-size:12px;font-weight:800;color:' + (isSent ? 'rgba(255,255,255,0.95)' : '#FF9500') + ';">' + escapeHtml(_rq.name || 'Reply') + '</div>' +
            '<div style="font-size:12px;color:' + (isSent ? 'rgba(255,255,255,0.75)' : 'var(--text-secondary,#888)') + ';white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(_rq.preview || '') + '</div>' +
        '</div>';
    }

    // Failed badge — red "!" beside the bubble (WhatsApp-style), vertically centered.
    var failedBadge = (status === 'failed')
        ? '<div data-fail-badge="1" style="position:absolute;top:50%;transform:translateY(-50%);' + (isSent ? 'left:-26px;' : 'right:-26px;') + 'width:20px;height:20px;border-radius:50%;background:#FF3B30;display:flex;align-items:center;justify-content:center;z-index:3;box-shadow:0 2px 6px rgba(255,59,48,0.5);">' +
          '<span style="color:white;font-size:12px;font-weight:900;line-height:1;">!</span></div>'
        : '';

    // ── SYSTEM NOTICE (group events / deletions) — centered, no bubble ──────
    if (msgType === 'system') {
        var sysText = m.content || m.ciphertext || '';
        return '<div style="display:flex;justify-content:center;margin:8px 0;">' +
            '<span data-msg-id="' + escapeHtml(String(msgId)) + '" data-msg-bubble="true" style="background:rgba(120,120,128,0.16);color:var(--text-secondary,#666);font-size:12px;font-weight:600;padding:6px 14px;border-radius:14px;max-width:80%;text-align:center;line-height:1.4;">' +
                escapeHtml(sysText) +
            '</span></div>';
    }

    // ── DELETED MESSAGE — placeholder where a removed message used to be ────
    if (msgType === 'deleted' || m.is_deleted) {
        var delText = m.deleted_by_admin ? 'This message was deleted by the admin' : 'This message was deleted';
        return '<div style="' + wrapStyle + '">' +
            '<div data-msg-id="' + escapeHtml(String(msgId)) + '" data-msg-bubble="true" style="' + align + 'background:transparent;border:1px dashed rgba(128,128,128,0.4);color:#999;padding:9px 14px;border-radius:16px;max-width:78%;font-size:13px;font-style:italic;display:flex;align-items:center;gap:7px;">' +
                '<i class="fa-solid fa-ban" style="font-size:12px;"></i>' + escapeHtml(delText) +
            '</div>' + timeHtml + '</div>';
    }

    // ── DELETED (soft-delete placeholder) ──────────────────────────────────
    if (m.is_deleted || msgType === 'deleted') {
        var delTxt = m.deleted_by_admin ? 'This message was deleted by the admin' : 'This message was deleted';
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' style="' + align + 'background:rgba(0,0,0,0.05);color:#999;font-style:italic;padding:9px 14px;border-radius:16px;max-width:78%;font-size:13px;display:flex;align-items:center;gap:7px;">' +
                '<i class="fa-solid fa-ban" style="font-size:11px;opacity:0.6;"></i>' + delTxt +
            '</div>' + timeHtml + '</div>';
    }

    // ── CHECKLIST ──────────────────────────────────────────────────────────
    if (msgType === 'checklist') {
        var ck = {}; try { ck = JSON.parse(m.content || m.ciphertext || '{}'); } catch(e) { ck = {}; }
        var cItems = ck.items || [];
        var doneN = cItems.filter(function(x){ return x.done; }).length;
        var ckRows = cItems.map(function(it, i){
            var d = !!it.done;
            return '<div onclick="_ckToggleMsg(this,\'' + escapeHtml(String(msgId)) + '\',' + i + ')" style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:0.5px solid rgba(0,0,0,0.06);cursor:pointer;">' +
                '<div data-ck-check style="width:22px;height:22px;border-radius:50%;border:2px solid #007AFF;background:' + (d?'#007AFF':'transparent') + ';display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fa-solid fa-check" style="color:white;font-size:11px;display:' + (d?'block':'none') + ';"></i></div>' +
                '<span style="font-size:14px;color:' + (d?'#aaa':'var(--text-primary,#000)') + ';text-decoration:' + (d?'line-through':'none') + ';">' + escapeHtml(it.label||'') + '</span>' +
            '</div>';
        }).join('');
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' data-ck="' + escapeHtml(JSON.stringify(ck)) + '" style="' + align + 'background:var(--card-bg,#fff);border:1px solid #e0e0e0;border-radius:16px;max-width:280px;overflow:hidden;box-shadow:0 2px 8px rgba(0,0,0,0.06);">' +
                '<div style="background:linear-gradient(135deg,rgba(88,86,214,0.08),rgba(0,122,255,0.06));padding:14px 16px 4px;"><b style="font-size:15px;font-weight:700;color:var(--text-primary,#000);">' + escapeHtml(ck.title||'Checklist') + '</b><p style="font-size:11px;color:#888;margin:2px 0 8px;font-weight:600;text-transform:uppercase;letter-spacing:0.04em;">Checklist</p></div>' +
                '<div style="padding:0 16px 4px;">' + ckRows + '</div>' +
                '<div style="padding:8px 16px 10px;text-align:center;"><small data-ck-count style="color:#888;font-size:12px;">' + doneN + ' of ' + cItems.length + ' completed</small></div>' +
            '</div>' + timeHtml + '</div>';
    }

    // ── TEXT ──────────────────────────────────────────────────────────────
    if (msgType === 'text') {
        // A nonce means the row is encrypted. If we have no plaintext by now,
        // this device cannot read it, and dumping the base64 into the bubble
        // (which is what used to happen) is worse than saying so.
        var text = _msgPlainText(m);
        if (text === null) {
            return '<div style="' + wrapStyle + '">' +
                '<div style="background:rgba(120,120,128,0.12);color:var(--text-secondary,#666);' +
                'padding:11px 15px;border-radius:16px;max-width:78%;font-size:13.5px;line-height:1.4;' +
                'border:1px dashed rgba(120,120,128,0.35);' + align + '">' +
                    '<i class="fa-solid fa-lock" style="font-size:11px;margin-right:6px;opacity:0.7;"></i>' +
                    'This message was encrypted for another device, so it cannot be opened here.' +
                '</div>' + timeHtml + '</div>';
        }
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' style="background:' + (isSent ? '#007AFF' : 'rgba(0,0,0,0.07)') + ';color:' + (isSent ? 'white' : 'var(--text-primary,#000)') + ';padding:11px 15px;border-radius:' + (isSent ? '20px 20px 4px 20px' : '20px 20px 20px 4px') + ';max-width:78%;font-size:15px;line-height:1.4;word-wrap:break-word;' + align + 'position:relative;">' +
                replyQuote + _linkifyMessage(text, isSent) + failedBadge +
            '</div>' + _linkPreviewCard(_firstUrl(text)) + timeHtml + '</div>';
    }

    // ── VOICE MESSAGE ─────────────────────────────────────────────────────
    if (msgType === 'voice') {
        var dur = m.voice_duration_seconds || 0;
        var mins = Math.floor(dur / 60), secs = dur % 60;
        var durStr = mins + ':' + (secs < 10 ? '0' : '') + secs;
        var audioUrl = escapeHtml(m.media_url || m.ciphertext || '');
        // Static waveform bars
        var bars = '';
        var heights = [4,7,12,9,16,11,8,14,6,10,13,7,15,9,5,11,8,14,6,12,10,7,13,9,4,11,8,6];
        bars = heights.map(function(h){
            return '<div style="width:3px;height:' + h + 'px;background:rgba(255,255,255,0.8);border-radius:2px;flex-shrink:0;"></div>';
        }).join('');
        var loOnce = !!m.listen_once;
        var loAttr = loOnce ? ' data-listen-once="1"' : '';
        var loBadge = loOnce ? '<div style="width:22px;height:22px;border-radius:50%;border:1.5px solid rgba(255,255,255,0.9);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:#fff;flex-shrink:0;" title="Listen once">1</div>' : '';

        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + loAttr + ' onclick="playVoiceNote(this,\'' + audioUrl + '\')" style="background:#007AFF;padding:10px 14px;border-radius:' + (isSent ? '20px 20px 4px 20px' : '20px 20px 20px 4px') + ';max-width:260px;' + align + 'display:flex;align-items:center;gap:10px;cursor:pointer;position:relative;">' +
                '<div id="vn-play-' + msgId + '" style="width:38px;height:38px;border-radius:50%;background:rgba(255,255,255,0.2);display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
                    '<i class="fa-solid fa-play" style="color:white;font-size:14px;margin-left:2px;"></i></div>' +
                '<div style="flex:1;min-width:0;">' +
                    '<div style="display:flex;align-items:flex-end;gap:2px;height:20px;overflow:hidden;">' + bars + '</div>' +
                    '<div style="display:flex;align-items:center;gap:4px;margin-top:4px;">' +
                        '<small style="color:rgba(255,255,255,0.8);font-size:11px;">' + durStr + '</small>' +
                        '<span style="color:rgba(255,255,255,0.4);font-size:9px;">•</span>' +
                        '<small style="color:rgba(255,255,255,0.5);font-size:10px;">' + time + '</small>' +
                        (isUploading ? '' : mediaTick) +
                    '</div>' +
                '</div>' + loBadge + failedBadge +
            '</div></div>';
    }

    // ── ALBUM (multiple images sent at once) ──────────────────────────────
    if (msgType === 'album') {
        var urls = m.media_urls || [];
        if (typeof urls === 'string') { try { urls = JSON.parse(urls); } catch(e){ urls = []; } }
        var isUploadingAl = status === 'uploading';
        var show = urls.slice(0, 4);
        var moreN = urls.length - 4;
        var cells = show.map(function(u, i) {
            var ov = (i === 3 && moreN > 0) ? '<div style="position:absolute;inset:0;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;color:#fff;font-size:28px;font-weight:800;">+' + moreN + '</div>' : '';
            return '<div style="position:relative;aspect-ratio:1;overflow:hidden;cursor:pointer;" onclick="openFullScreenMedia(\'' + escapeHtml(u) + '\',\'image\')">' +
                '<img ' + _mediaSrcAttr(escapeHtml(u), false) + ' style="width:100%;height:100%;object-fit:cover;" onerror="this.style.background=\'#333\'">' + ov + '</div>';
        }).join('');
        var cols = (show.length === 1) ? '1fr' : '1fr 1fr';
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' style="' + align + 'max-width:250px;border-radius:16px;overflow:hidden;position:relative;">' +
                '<div style="display:grid;grid-template-columns:' + cols + ';gap:2px;background:#000;">' + cells + '</div>' +
                (isUploadingAl ? '<div style="position:absolute;inset:0;background:rgba(0,0,0,0.3);display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-spinner fa-spin" style="color:#fff;font-size:22px;"></i></div>' : '') +
                '<div style="position:absolute;bottom:6px;right:8px;display:flex;align-items:center;gap:3px;">' +
                    '<small style="color:rgba(255,255,255,0.9);font-size:10px;text-shadow:0 1px 3px rgba(0,0,0,0.6);">' + time + '</small>' +
                    (isUploadingAl ? '' : mediaTick) +
                '</div>' + failedBadge +
            '</div></div>';
    }

    // ── IMAGE ─────────────────────────────────────────────────────────────
    if (msgType === 'image') {
        var imgUrl = escapeHtml(m.media_url || '');
        var isUploading = status === 'uploading';
        var cap = (m.content || m.ciphertext || '').trim();
        var capTick = isSent ? _tickSpan(m, 'caption') : '';
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' style="' + align + 'max-width:240px;border-radius:16px;overflow:hidden;position:relative;cursor:pointer;' + (cap ? 'background:' + (isSent ? '#007AFF' : 'rgba(0,0,0,0.07)') + ';' : '') + '">' +
                '<div style="position:relative;" onclick="openFullScreenMedia(\'' + imgUrl + '\',\'image\')">' +
                    '<img ' + _mediaSrcAttr(imgUrl, false) + ' style="width:100%;display:block;" onerror="this.style.background=\'#eee\'">' +
                    (isUploading ? '<div style="position:absolute;inset:0;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;">' +
                        '<div onclick="event.stopPropagation();cancelUpload(\'' + msgId + '\')" style="width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,0.2);border:2px solid white;display:flex;align-items:center;justify-content:center;cursor:pointer;">' +
                            '<i class="fa-solid fa-xmark" style="color:white;font-size:16px;"></i></div>' +
                        '<small style="color:rgba(255,255,255,0.8);font-size:10px;" id="upload-prog-' + msgId + '">Uploading…</small></div>' : '') +
                    (cap ? '' : '<div style="position:absolute;bottom:6px;right:8px;display:flex;align-items:center;gap:3px;">' +
                        '<small style="color:rgba(255,255,255,0.9);font-size:10px;text-shadow:0 1px 3px rgba(0,0,0,0.6);">' + time + '</small>' +
                        (isUploading ? '<i class="fa-regular fa-clock" style="color:rgba(255,255,255,0.8);font-size:9px;"></i>' : mediaTick) +
                    '</div>') +
                '</div>' +
                (cap ? '<div style="padding:7px 12px 9px;">' +
                    '<div style="color:' + (isSent ? '#fff' : 'var(--text-primary,#000)') + ';font-size:14px;line-height:1.35;word-wrap:break-word;">' + _linkifyMessage(cap, isSent) + '</div>' +
                    '<div style="display:flex;align-items:center;gap:3px;justify-content:flex-end;margin-top:2px;">' +
                        '<small style="font-size:10px;color:' + (isSent ? 'rgba(255,255,255,0.7)' : 'rgba(0,0,0,0.35)') + ';">' + time + '</small>' + capTick +
                    '</div></div>' : '') +
                failedBadge +
            '</div></div>';
    }

    // ── VIDEO ─────────────────────────────────────────────────────────────
    if (msgType === 'video') {
        var vidUrl = escapeHtml(m.media_url || '');
        var vidDur = m.video_duration ? (Math.floor(m.video_duration/60) + ':' + String(m.video_duration%60).padStart(2,'0')) : '';
        var isUploading = status === 'uploading';
        var capV = (m.content || m.ciphertext || '').trim();
        var capVTick = isSent ? _tickSpan(m, 'caption') : '';
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' style="' + align + 'max-width:240px;border-radius:16px;overflow:hidden;position:relative;cursor:pointer;' + (capV ? 'background:' + (isSent ? '#007AFF' : 'rgba(0,0,0,0.07)') + ';' : '') + '" onclick="openFullScreenMedia(\'' + vidUrl + '\',\'video\')">' +
                '<div style="position:relative;">' +
                    '<video ' + _mediaSrcAttr(vidUrl, true) + ' style="width:100%;display:block;" preload="metadata" muted playsinline></video>' +
                    '<div style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;">' +
                        '<div style="width:46px;height:46px;border-radius:50%;background:rgba(0,0,0,0.45);backdrop-filter:blur(4px);display:flex;align-items:center;justify-content:center;">' +
                            '<i class="fa-solid fa-play" style="color:white;font-size:18px;margin-left:3px;"></i></div></div>' +
                    (vidDur ? '<div style="position:absolute;top:6px;left:8px;display:flex;align-items:center;gap:4px;background:rgba(0,0,0,0.55);backdrop-filter:blur(4px);border-radius:8px;padding:3px 7px;">' +
                        '<i class="fa-solid fa-volume-xmark" style="color:white;font-size:8px;"></i>' +
                        '<small style="color:white;font-size:10px;font-weight:700;">' + vidDur + '</small></div>' : '') +
                    (isUploading ? '<div style="position:absolute;inset:0;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;flex-direction:column;gap:8px;">' +
                        '<div onclick="event.stopPropagation();cancelUpload(\'' + msgId + '\')" style="width:36px;height:36px;border-radius:50%;background:rgba(255,255,255,0.2);border:2px solid white;display:flex;align-items:center;justify-content:center;cursor:pointer;">' +
                            '<i class="fa-solid fa-xmark" style="color:white;font-size:16px;"></i></div>' +
                        '<small style="color:rgba(255,255,255,0.8);font-size:10px;" id="upload-prog-' + msgId + '">Uploading…</small></div>' : '') +
                    (capV ? '' : '<div style="position:absolute;bottom:6px;right:8px;display:flex;align-items:center;gap:3px;">' +
                        '<small style="color:rgba(255,255,255,0.9);font-size:10px;text-shadow:0 1px 3px rgba(0,0,0,0.6);">' + time + '</small>' +
                        (isUploading ? '<i class="fa-regular fa-clock" style="color:rgba(255,255,255,0.8);font-size:9px;"></i>' : mediaTick) +
                    '</div>') +
                '</div>' +
                (capV ? '<div style="padding:7px 12px 9px;">' +
                    '<div style="color:' + (isSent ? '#fff' : 'var(--text-primary,#000)') + ';font-size:14px;line-height:1.35;word-wrap:break-word;">' + _linkifyMessage(capV, isSent) + '</div>' +
                    '<div style="display:flex;align-items:center;gap:3px;justify-content:flex-end;margin-top:2px;">' +
                        '<small style="font-size:10px;color:' + (isSent ? 'rgba(255,255,255,0.7)' : 'rgba(0,0,0,0.35)') + ';">' + time + '</small>' + capVTick +
                    '</div></div>' : '') +
                failedBadge +
            '</div></div>';
    }

    // ── DOCUMENT / FILE ───────────────────────────────────────────────────
    if (msgType === 'document' || msgType === 'file') {
        var fileName = m.file_name || 'Document';
        var fileSize = m.file_size ? _formatFileSize(m.file_size) : '';
        var fileUrl  = escapeHtml(m.media_url || '');
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' onclick="openDocumentViewer(\'' + fileUrl + '\',\'' + escapeHtml(fileName) + '\')" style="background:#007AFF;padding:12px 14px;border-radius:' + (isSent ? '20px 20px 4px 20px' : '20px 20px 20px 4px') + ';max-width:260px;' + align + 'display:flex;align-items:center;gap:10px;cursor:pointer;position:relative;">' +
                '<div style="width:38px;height:44px;background:rgba(255,255,255,0.2);border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
                    '<i class="fa-solid fa-file" style="color:white;font-size:18px;"></i></div>' +
                '<div style="flex:1;min-width:0;">' +
                    '<div style="color:white;font-size:13px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(fileName) + '</div>' +
                    (fileSize ? '<div style="color:rgba(255,255,255,0.6);font-size:11px;margin-top:2px;">' + fileSize + '</div>' : '') +
                    '<div style="color:rgba(255,255,255,0.5);font-size:10px;margin-top:6px;text-align:right;">' + time + '</div>' +
                '</div>' + failedBadge +
            '</div></div>';
    }

    // ── LOCATION (static + live, WhatsApp-style) ──────────────────────────
    if (msgType === 'location') {
        var lat = m.location_lat || 0, lng = m.location_lng || 0;
        var isLive = m.location_live || false;
        var untilDate = m.location_live_until ? new Date(m.location_live_until) : null;
        var wasLive = isLive || !!untilDate;
        var stillLive = isLive && untilDate && untilDate.getTime() > Date.now();
        var ended = wasLive && !stillLive;
        var untilStr = untilDate ? untilDate.toLocaleTimeString('en-ZA', { hour: '2-digit', minute: '2-digit' }) : '';
        var locCap = (m.ciphertext || m.content || '').trim();
        var mapUrl = _osmTileUrl(lat, lng, 15);
        var myAvatar = (isSent && currentUser && currentUser.avatar_url) ? currentUser.avatar_url : '';
        var hasChrome = locCap || wasLive;
        var locTick = isSent ? _tickSpan(m, 'caption') : '';
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' style="' + align + 'max-width:260px;border-radius:16px;overflow:hidden;position:relative;' + (hasChrome ? 'background:' + (isSent ? '#007AFF' : 'rgba(0,0,0,0.07)') + ';' : '') + '">' +
                '<div style="height:150px;position:relative;overflow:hidden;cursor:pointer;background:linear-gradient(135deg,#2a3d52,#1a2433);" onclick="openLocationOnMap(' + lat + ',' + lng + ',\'' + escapeHtml(String(msgId)) + '\',' + (isSent ? 1 : 0) + ',' + (wasLive ? 1 : 0) + ')">' +
                    '<img src="' + mapUrl + '" style="width:100%;height:100%;object-fit:cover;" onerror="this.style.display=\'none\'">' +
                    (wasLive && myAvatar
                        ? '<div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:56px;height:56px;border-radius:50%;background:' + (stillLive ? 'rgba(52,199,89,0.35)' : 'rgba(120,120,128,0.4)') + ';display:flex;align-items:center;justify-content:center;"><img src="' + escapeHtml(myAvatar) + '" style="width:44px;height:44px;border-radius:50%;object-fit:cover;border:2px solid #fff;' + (ended ? 'filter:grayscale(0.6);' : '') + '"></div>'
                        : '<div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-100%);display:flex;flex-direction:column;align-items:center;"><div style="width:16px;height:16px;border-radius:50%;background:#FF3B30;border:2.5px solid #fff;box-shadow:0 2px 8px rgba(0,0,0,0.4);"></div><div style="width:2px;height:9px;background:#FF3B30;"></div></div>') +
                    (hasChrome ? '' : '<div style="position:absolute;bottom:6px;right:8px;display:flex;align-items:center;gap:3px;"><small style="color:#fff;font-size:10px;text-shadow:0 1px 3px rgba(0,0,0,0.7);">' + time + '</small>' + (isSent ? mediaTick : '') + '</div>') +
                '</div>' +
                (stillLive ? '<div data-live-banner style="display:flex;align-items:center;gap:8px;padding:9px 14px;background:rgba(0,0,0,0.28);"><i class="fa-solid fa-location-arrow" style="color:#34C759;font-size:13px;"></i><span style="color:#fff;font-size:13px;font-weight:600;">Live until ' + untilStr + '</span></div>'
                    : (ended ? '<div style="display:flex;align-items:center;gap:8px;padding:9px 14px;background:rgba(0,0,0,0.28);"><i class="fa-solid fa-location-arrow" style="color:#FF453A;font-size:13px;"></i><span style="color:' + (isSent ? 'rgba(255,255,255,0.9)' : '#888') + ';font-size:13px;font-weight:600;">Live sharing ended</span></div>' : '')) +
                (locCap ? '<div style="padding:8px 12px;color:' + (isSent ? '#fff' : 'var(--text-primary,#000)') + ';font-size:14px;line-height:1.35;word-wrap:break-word;">' + _linkifyMessage(locCap, isSent) + '<div style="display:flex;justify-content:flex-end;gap:3px;margin-top:2px;"><small style="font-size:10px;color:' + (isSent ? 'rgba(255,255,255,0.7)' : 'rgba(0,0,0,0.35)') + ';">' + time + '</small>' + locTick + '</div></div>' : '') +
                (isSent && stillLive ? '<div data-stop-live onclick="event.stopPropagation();_confirmStopLiveLocation(\'' + escapeHtml(String(msgId)) + '\')" style="padding:12px;text-align:center;border-top:0.5px solid rgba(255,255,255,0.15);cursor:pointer;"><span style="color:#FF453A;font-size:15px;font-weight:800;">Stop sharing</span></div>' : '') +
                failedBadge +
            '</div>' + (hasChrome ? '' : timeHtml) + '</div>';
    }

    // ── CONTACT ───────────────────────────────────────────────────────────
    if (msgType === 'contact') {
        var contactName = m.contact_name || m.file_name || 'Contact';
        var contactNumber = m.contact_number || m.ciphertext || '';
        var cleanNumber = contactNumber.replace(/[^+\d]/g,'');
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' style="background:' + (isSent ? '#007AFF' : 'rgba(0,0,0,0.07)') + ';border-radius:' + (isSent ? '20px 20px 4px 20px' : '20px 20px 20px 4px') + ';max-width:260px;' + align + 'overflow:hidden;position:relative;">' +
                '<div style="display:flex;align-items:center;gap:12px;padding:14px 14px 10px;">' +
                    '<div style="width:44px;height:44px;border-radius:50%;background:' + (isSent ? 'rgba(255,255,255,0.2)' : '#007AFF') + ';display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
                        '<i class="fa-solid fa-person" style="color:white;font-size:18px;"></i></div>' +
                    '<div style="flex:1;min-width:0;">' +
                        '<div style="color:' + (isSent ? 'white' : 'var(--text-primary,#000)') + ';font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(contactName) + '</div>' +
                        (contactNumber ? '<div style="color:' + (isSent ? 'rgba(255,255,255,0.7)' : '#007AFF') + ';font-size:13px;margin-top:2px;">' + escapeHtml(contactNumber) + '</div>' : '') +
                    '</div>' + failedBadge +
                '</div>' +
                (cleanNumber ? '<div onclick="window.location.href=\'tel:' + cleanNumber + '\'" style="border-top:0.5px solid ' + (isSent ? 'rgba(255,255,255,0.2)' : 'rgba(0,0,0,0.08)') + ';padding:10px;text-align:center;cursor:pointer;">' +
                    '<span style="color:' + (isSent ? 'white' : '#007AFF') + ';font-size:14px;font-weight:700;">Call</span></div>' : '') +
            '</div>' + timeHtml + '</div>';
    }

    // ── AUDIO (music file) ────────────────────────────────────────────────
    if (msgType === 'audio') {
        var audioFileUrl = escapeHtml(m.media_url || m.ciphertext || '');
        var audioFileName = m.file_name || 'Audio';
        var audioDur = m.voice_duration_seconds || 0;
        var aMins = Math.floor(audioDur / 60), aSecs = audioDur % 60;
        var aDurStr = audioDur ? (aMins + ':' + (aSecs < 10 ? '0' : '') + aSecs) : '0:03';
        var aBars = '';
        var aHeights = [4,8,14,9,18,12,7,16,5,11,15,8,17,10,6,13,9,15,7,11];
        aBars = aHeights.map(function(h){
            return '<div style="width:3px;height:' + h + 'px;background:rgba(0,0,0,0.35);border-radius:2px;flex-shrink:0;"></div>';
        }).join('');
        return '<div style="' + wrapStyle + '">' +
            '<div' + bubbleAttr + ' onclick="playVoiceNote(this,\'' + audioFileUrl + '\')" style="background:rgba(0,0,0,0.07);padding:10px 14px;border-radius:' + (isSent ? '20px 20px 4px 20px' : '20px 20px 20px 4px') + ';max-width:260px;' + align + 'display:flex;align-items:center;gap:10px;cursor:pointer;position:relative;">' +
                '<div id="vn-play-' + msgId + '" style="width:38px;height:38px;border-radius:50%;background:#007AFF;display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
                    '<i class="fa-solid fa-play" style="color:white;font-size:14px;margin-left:2px;"></i></div>' +
                '<div style="flex:1;min-width:0;">' +
                    '<div style="display:flex;align-items:flex-end;gap:2px;height:20px;overflow:hidden;">' + aBars + '</div>' +
                    '<div style="display:flex;align-items:center;gap:4px;margin-top:4px;">' +
                        '<small style="color:#888;font-size:11px;">' + aDurStr + '</small>' +
                        '<span style="color:rgba(0,0,0,0.3);font-size:9px;">•</span>' +
                        '<small style="color:#aaa;font-size:10px;">' + time + '</small>' +
                    '</div>' +
                '</div>' + failedBadge +
            '</div></div>';
    }

    // ── FALLBACK ──────────────────────────────────────────────────────────
    return '<div style="' + wrapStyle + '">' +
        '<div' + bubbleAttr + ' style="background:rgba(0,0,0,0.07);padding:11px 15px;border-radius:20px 20px 20px 4px;max-width:78%;font-size:15px;' + align + '">' +
            escapeHtml(m.content || m.ciphertext || '[Message]') +
        '</div>' + timeHtml + '</div>';
}

// Helper: format bytes to human string
function _formatFileSize(bytes) {
    if (!bytes) return '';
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1048576) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / 1048576).toFixed(1) + ' MB';
}

function openChat(userName) {
    var nav = document.querySelector('.nav-container');
    if (nav) nav.style.display = 'none';
    openPage('chat-interface');
    document.getElementById('chat-user-name').textContent = userName;
var handleEl = document.getElementById('chat-user-handle');
if (handleEl) handleEl.textContent = '@' + userName.toLowerCase().replace(/\s+/g,'_');

    var chatBody = document.getElementById('chat-body');
    chatBody.innerHTML = '';
    if (!currentConversationId && window._currentChatUserId && window.sb && currentUser) {
        (async function() {
            try {
                var uid = currentUser.id, oid = window._currentChatUserId;
                var isSelf = (uid === oid);
                var shared = null;
                var { data: myC } = await window.sb.from('conversation_participants').select('conversation_id').eq('user_id', uid);
                var myIds = (myC||[]).map(function(p){ return p.conversation_id; });
                if (isSelf) {
                    // Self-chat: find a conversation where current user is the ONLY participant
                    if (myIds.length) {
                        var { data: othersInMine } = await window.sb.from('conversation_participants')
                            .select('conversation_id').in('conversation_id', myIds).neq('user_id', uid);
                        var withOthers = new Set((othersInMine||[]).map(function(p){ return p.conversation_id; }));
                        shared = myIds.find(function(id){ return !withOthers.has(id); }) || null;
                    }
                } else {
                    var { data: theirC } = await window.sb.from('conversation_participants').select('conversation_id').eq('user_id', oid);
                    var theirIds = (theirC||[]).map(function(p){ return p.conversation_id; });
                    shared = myIds.find(function(id){ return theirIds.includes(id); }) || null;
                }
                if (shared) { currentConversationId = shared; }
                else {
                    var { data: cr, error: crErr } = await window.sb.from('conversations').insert({
                        type: 'direct',
                        created_by: uid,
                        created_at: new Date().toISOString(),
                        updated_at: new Date().toISOString()
                    }).select('id').single();
                    if (crErr) { console.error('[openChat] conversation insert failed:', crErr); showToast('Could not start chat – check Supabase RLS'); }
                    if (cr) {
                        var _parts = [{ conversation_id: cr.id, user_id: uid, is_blocked: false }];
                        if (!isSelf) _parts.push({ conversation_id: cr.id, user_id: oid, is_blocked: false });
                        var { error: partsInsertErr } = await window.sb.from('conversation_participants').insert(_parts);
                        if (partsInsertErr) console.error('[openChat] participants insert failed:', partsInsertErr);
                    }
                    if (cr) currentConversationId = cr.id;
                }
                // Reload messages now that conversation ID is resolved
                if (currentConversationId) {
                    var _body = document.getElementById('chat-body');
                    if (_body) {
                        DB.getMessages(currentConversationId).then(function(msgs) {
                            var body = document.getElementById('chat-body');
                            if (!body) return;
                            var _rmap = _buildReplyMap(msgs);
                            body.innerHTML = msgs.length === 0
                                ? '<div style="text-align:center;padding:40px 0;color:#aaa;font-size:14px;">No messages yet. Say hello!</div>'
                                : msgs.map(function(m){ return renderMessageBubble(m, _rmap); }).join('');
                            body.scrollTop = body.scrollHeight;
                            _markChatRead(currentConversationId); // conversation just resolved → mark read
                        }).catch(function(){});
                    }
                }
            } catch(e) { console.warn('[openChat conv]', e); }
        })();
    }

// Profile summary card — loads real data from Supabase
var summaryCard = document.createElement('div');
summaryCard.style.cssText = 'text-align:center;padding:32px 20px 20px;border-bottom:1px solid var(--border-color,#f0f0f0);';
summaryCard.innerHTML = '<div style="width:80px;height:80px;border-radius:50%;background:#007AFF;display:flex;align-items:center;justify-content:center;margin:0 auto 14px;font-size:28px;font-weight:700;color:white;">' +
    escapeHtml((userName || '?').charAt(0).toUpperCase()) + '</div>' +
    '<b style="display:block;font-size:18px;font-weight:800;color:var(--text-primary,#000);">' + escapeHtml(userName) + '</b>' +
    '<p style="color:#888;font-size:13px;margin:2px 0 16px;">Loading…</p>';
chatBody.appendChild(summaryCard);

// Hydrate with real Supabase data
if (window.sb && window._currentChatUserId) {
    sb.from('users')
        .select('id,full_name,username,avatar_url,post_count,last_seen,verified,badge_tier')
        .eq('id', window._currentChatUserId)
        .maybeSingle()
        .then(function(res) {
            var u = res.data || {};
            var name = u.full_name || u.username || userName;
            var handle = u.username ? '@' + u.username : '';
            var avatar = u.avatar_url;
            var followers = u.follower_count || 0;
            var posts = u.post_count || 0;
            var _sp = _presenceFrom(u.last_seen);
            var onlineStatus = _sp.label
                ? (_sp.online ? '<span style="color:#34C759;font-weight:700;">● ' + _sp.label + '</span>' : _sp.label)
                : '';

            var avatarHtml = avatar
                ? '<img src="' + escapeHtml(avatar) + '" style="width:80px;height:80px;border-radius:50%;object-fit:cover;border:3px solid var(--bg-primary,#fff);box-shadow:0 4px 16px rgba(0,0,0,0.12);" onerror="this.style.display=\'none\';this.nextSibling.style.display=\'flex\'">' +
                  '<div style="display:none;width:80px;height:80px;border-radius:50%;background:#007AFF;align-items:center;justify-content:center;font-size:28px;font-weight:700;color:white;border:3px solid var(--bg-primary,#fff);box-shadow:0 4px 16px rgba(0,0,0,0.12);">' + escapeHtml(name.charAt(0).toUpperCase()) + '</div>'
                : '<div style="width:80px;height:80px;border-radius:50%;background:#007AFF;display:flex;align-items:center;justify-content:center;font-size:28px;font-weight:700;color:white;border:3px solid var(--bg-primary,#fff);box-shadow:0 4px 16px rgba(0,0,0,0.12);">' + escapeHtml(name.charAt(0).toUpperCase()) + '</div>';

            // Update header avatar too
            var hImg = document.getElementById('chat-header-avatar');
            var hFallback = document.getElementById('chat-header-avatar-fallback');
            if (avatar && hImg) { hImg.src = avatar; hImg.style.display = 'block'; if(hFallback) hFallback.style.display = 'none'; }
            // Online dot on the header avatar
            var _hdrAv = (hImg && hImg.style.display !== 'none') ? hImg : hFallback;
            if (_hdrAv && _hdrAv.parentElement) {
                var _hd = document.getElementById('chat-header-online-dot');
                if (_sp.online) {
                    if (!_hd) { _hd = document.createElement('span'); _hd.id = 'chat-header-online-dot'; _hdrAv.parentElement.style.position = 'relative'; _hdrAv.parentElement.appendChild(_hd); }
                    _hd.style.cssText = 'position:absolute;bottom:0;right:0;width:11px;height:11px;border-radius:50%;background:#34C759;border:2px solid var(--bg-primary,#fff);';
                } else if (_hd) { _hd.remove(); }
            }

            summaryCard.innerHTML =
                '<div style="position:relative;display:inline-block;margin-bottom:14px;">' + avatarHtml +
                (_sp.online ? '<span style="position:absolute;bottom:6px;right:6px;width:16px;height:16px;border-radius:50%;background:#34C759;border:3px solid var(--bg-primary,#fff);"></span>' : '') + '</div>' +
                '<b style="display:block;font-size:18px;font-weight:800;color:var(--text-primary,#000);">' + escapeHtml(name) +
                (u.verified ? ' <i class="fa-solid fa-circle-check ' + escapeHtml(u.badge_tier || 'verify-blue') + '" style="font-size:13px;"></i>' : '') + '</b>' +
                '<p style="color:#888;font-size:13px;margin:2px 0 6px;">' + escapeHtml(handle) + '</p>' +
                (onlineStatus ? '<p style="font-size:12px;margin:0 0 6px;">' + onlineStatus + '</p>' : '') +
                '<p style="font-size:13px;color:#888;margin-bottom:16px;">' + followers.toLocaleString() + ' followers · ' + posts.toLocaleString() + ' posts</p>' +
                '<button onclick="viewUserProfile(\'' + escapeHtml(u.id || '') + '\')" style="padding:10px 28px;border-radius:25px;border:1px solid var(--border-color,#ddd);background:transparent;color:var(--text-primary,#000);font-size:14px;font-weight:700;cursor:pointer;">View Profile</button>';
        }).catch(function() {});
}

    // Insert date separators + sample messages
    var today = new Date();
    var yesterday = new Date(today); yesterday.setDate(today.getDate() - 1);

    function dateSep(label) {
        var iso = chatDateLabelToISO(label);
        var clickAttr = iso ? 'onclick="openChatCalModal(\'' + iso + '\')" style="cursor:pointer;"' : '';
        return '<div style="text-align:center;margin:16px 0 8px;" ' + clickAttr + '><span style="display:inline-block;padding:4px 14px;border-radius:20px;background:var(--bg-secondary,rgba(0,0,0,0.06));font-size:11px;font-weight:700;color:#888;">' + label + '</span></div>';
    }
    function chatDateLabelToISO(label) {
        try {
            if (label === 'Today') {
                var t = new Date();
                return t.getFullYear()+'-'+String(t.getMonth()+1).padStart(2,'0')+'-'+String(t.getDate()).padStart(2,'0');
            }
            var d = new Date(label);
            if (!isNaN(d)) return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');
        } catch(e) {}
        return null;
    }

    var _msgCacheKey = 'tf_msgs_cache_' + (currentConversationId || 'pending');
    var _cachedMsgs = null;
    try { _cachedMsgs = JSON.parse(localStorage.getItem(_msgCacheKey) || 'null'); } catch(e) {}
    if (_cachedMsgs && _cachedMsgs.length) {
        var _rmapC = _buildReplyMap(_cachedMsgs);
        chatBody.innerHTML = _cachedMsgs.map(function(m){ return renderMessageBubble(m, _rmapC); }).join('');
        chatBody.scrollTop = chatBody.scrollHeight;
    } else {
        chatBody.innerHTML = '<div style="text-align:center;padding:40px 0;color:#aaa;font-size:14px;">Loading messages...</div>';
    }
    var _fetchProm = (window.sb && currentConversationId)
        ? DB.getMessages(currentConversationId)
        : Promise.resolve([]);
    _fetchProm.then(function(msgs) {
        if (msgs && msgs.length) {
            // Only overwrite the cache with a non-empty result (so an offline
            // empty fetch never wipes the messages the user came to re-read).
            try { if (currentConversationId) localStorage.setItem('tf_msgs_cache_' + currentConversationId, JSON.stringify(msgs)); } catch(e) {}
            var _rmapM = _buildReplyMap(msgs);
            chatBody.innerHTML = msgs.map(function(m){ return renderMessageBubble(m, _rmapM); }).join('');
            chatBody.scrollTop = chatBody.scrollHeight;
            _loadMsgReactions(msgs);
            _markChatRead(currentConversationId); // I opened the chat → mark their msgs read
            chatBody.querySelectorAll('div[style*="background:#007AFF"],div[style*="rgba(0,0,0,0.07)"]').forEach(function(b){
                if (!b.getAttribute('data-msg-bubble')) b.setAttribute('data-msg-bubble','true');
            });
        } else if (navigator.onLine || !_cachedMsgs || !_cachedMsgs.length) {
            chatBody.innerHTML = '<div style="text-align:center;padding:40px 0;color:#aaa;font-size:14px;">No messages yet. Say hello!</div>';
        }
    }).catch(function(){
        // Offline / fetch failed — keep the cached messages on screen instead of blanking them.
        if (!_cachedMsgs || !_cachedMsgs.length) chatBody.innerHTML = '<div style="text-align:center;padding:40px 0;color:#aaa;font-size:14px;">No messages yet. Say hello!</div>';
    });

    chatBody.scrollTop = chatBody.scrollHeight;
setTimeout(function() { setupChatLongPress(); }, 300);
    setTimeout(function() {
        var input = document.getElementById('chat-msg-input');
        if (input) input.focus();
    }, 350);
}

function toggleEmoji() {
    const picker = document.getElementById('emoji-picker');
    picker.style.display = picker.style.display === 'grid' ? 'none' : 'grid';
}

function insertEmoji(emoji) {
    const input = document.querySelector('#chat-interface input[placeholder="Message..."]');
    if (input) {
        input.value += emoji;
        input.focus();
    }
    document.getElementById('emoji-picker').style.display = 'none';
}

function toggleAttach() {
    const menu = document.getElementById('attach-menu');
    if (menu) menu.style.display = menu.style.display === 'flex' ? 'none' : 'flex';
}

// ==========================================================================
// DOCUMENT / FILE VIEWER
// ==========================================================================
function openDocumentViewer(url, fileName) {
    var existing = document.getElementById('docViewer');
    if (existing) existing.remove();
    var app = document.getElementById('app') || document.body;

    var viewer = document.createElement('div');
    viewer.id = 'docViewer';
    viewer.style.cssText = 'position:absolute;inset:0;z-index:19600;background:white;display:flex;flex-direction:column;overflow:hidden;';
    viewer.innerHTML =
        // Top bar
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:max(52px,env(safe-area-inset-top,52px)) 16px 12px;border-bottom:0.5px solid #eee;flex-shrink:0;">' +
            '<div onclick="document.getElementById(\'docViewer\').remove()" style="width:34px;height:34px;border-radius:50%;background:#f0f0f0;display:flex;align-items:center;justify-content:center;cursor:pointer;">' +
                '<i class="fa-solid fa-xmark" style="color:#000;font-size:15px;"></i></div>' +
            '<div style="display:flex;align-items:center;gap:4px;cursor:pointer;">' +
                '<span style="font-size:15px;font-weight:700;color:#000;">' + escapeHtml(fileName || 'Document') + '</span>' +
                '<i class="fa-solid fa-chevron-down" style="color:#aaa;font-size:11px;"></i></div>' +
            '<div style="width:34px;"></div>' +
        '</div>' +
        // Content area
        '<div style="flex:1;overflow:auto;display:flex;align-items:flex-start;justify-content:center;padding:20px;background:#f9f9f9;">' +
            '<iframe ' + (/\/(chat_media|voice_messages)\//.test(url || '') ? 'data-tfmedia="' + escapeHtml(url) + '" src="about:blank"' : 'src="' + escapeHtml(url || '') + '"') + ' style="width:100%;min-height:500px;border:none;border-radius:12px;background:white;box-shadow:0 2px 16px rgba(0,0,0,0.08);" title="' + escapeHtml(fileName || 'Document') + '"></iframe>' +
        '</div>' +
        // Bottom toolbar
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:12px 20px max(24px,env(safe-area-inset-bottom,24px));border-top:0.5px solid #eee;background:white;flex-shrink:0;">' +
            '<button onclick="showToast(\'Search coming soon\')" style="width:40px;height:40px;border-radius:50%;background:#f0f0f0;border:none;color:#555;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;">' +
                '<i class="fa-solid fa-magnifying-glass"></i></button>' +
            '<button onclick="if(navigator.share)navigator.share({url:\'' + escapeHtml(url) + '\',title:\'' + escapeHtml(fileName || 'Document') + '\'})" style="width:40px;height:40px;border-radius:50%;background:#f0f0f0;border:none;color:#555;font-size:16px;cursor:pointer;display:flex;align-items:center;justify-content:center;">' +
                '<i class="fa-solid fa-arrow-up-from-bracket"></i></button>' +
        '</div>';

    app.appendChild(viewer);
}

