function closeMusicHub() {
    stopMusicPreview();
    var hub = document.getElementById('thoughtMusicHub');
    if (hub) {
        hub.style.transform = 'translateY(100%)';
        hub.style.transition = 'transform 0.3s cubic-bezier(0.32,0.72,0,1)';
        setTimeout(function() {
            var h = document.getElementById('thoughtMusicHub');
            if (h) h.remove();
        }, 300);
    }
}

async function searchRealMusic(query, genrePillEl) {
    if (!query || !query.trim()) return;

    // Update genre pill active state
    if (genrePillEl) {
        var _mdark = document.documentElement.getAttribute('data-theme') === 'dark';
        document.querySelectorAll('.music-genre-pill').forEach(function(p) {
            p.style.background = _mdark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.05)';
            p.style.color = _mdark ? '#bbb' : '#555';
        });
        genrePillEl.style.background = '#007AFF';
        genrePillEl.style.color = 'white';
    }

    // Update search input
    var searchInput = document.getElementById('realMusicSearch');
    if (searchInput && genrePillEl) searchInput.value = query;

    var clearBtn = document.getElementById('musicClearBtn');
    if (clearBtn) clearBtn.style.display = query ? 'block' : 'none';

    var list = document.getElementById('musicTrackList');
    if (!list) return;

    // Show loading skeleton
    list.innerHTML = '<div style="padding:16px;">' +
        [1,2,3,4,5,6].map(function() {
            return '<div style="display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid rgba(0,0,0,0.05);">' +
                '<div style="width:52px;height:52px;border-radius:14px;background:linear-gradient(90deg,#f0f0f0 25%,#e0e0e0 50%,#f0f0f0 75%);background-size:200% 100%;animation:shimmer 1.5s infinite;flex-shrink:0;"></div>' +
                '<div style="flex:1;">' +
                    '<div style="height:14px;background:linear-gradient(90deg,#f0f0f0 25%,#e0e0e0 50%,#f0f0f0 75%);background-size:200% 100%;animation:shimmer 1.5s infinite;border-radius:7px;margin-bottom:8px;width:70%;"></div>' +
                    '<div style="height:11px;background:linear-gradient(90deg,#f0f0f0 25%,#e0e0e0 50%,#f0f0f0 75%);background-size:200% 100%;animation:shimmer 1.5s infinite;border-radius:6px;width:45%;"></div>' +
                '</div>' +
            '</div>';
        }).join('') +
        '</div>';

    // Add shimmer animation if not exists
    if (!document.getElementById('shimmerStyle')) {
        var s = document.createElement('style');
        s.id = 'shimmerStyle';
        s.textContent = '@keyframes shimmer{0%{background-position:200% 0}100%{background-position:-200% 0}}';
        document.head.appendChild(s);
    }

    // Clear previous timer
    clearTimeout(_musicSearchTimer);
    _musicSearchTimer = setTimeout(async function() {
        try {
            // Proxied through our server: calling iTunes straight from the
            // browser hit CORS and failed as a false "connection error".
            var res = await fetch('/api/music/search/?q=' + encodeURIComponent(query) + '&country=ZA');
            var data = await res.json();
            var tracks = data.results || [];

            if (tracks.length === 0) {
                list.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">' +
                    '<i class="fa-solid fa-face-sad-tear" style="font-size:30px;color:#ccc;display:block;margin-bottom:12px;"></i>' +
                    'No songs found for "' + escapeHtml(query) + '"</div>';
                return;
            }

            renderMusicTracks(tracks, list);

        } catch(err) {
            console.error('[MusicHub]', err);
            list.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">' +
                '<i class="fa-solid fa-wifi-slash" style="font-size:30px;color:#FF3B30;display:block;margin-bottom:12px;"></i>' +
                '<b style="display:block;margin-bottom:6px;">Connection error</b>' +
                '<p style="font-size:13px;">Check your internet and try again</p>' +
                '<button onclick="searchRealMusic(\'' + escapeHtml(query) + '\')" style="margin-top:14px;padding:10px 24px;border-radius:20px;border:none;background:#007AFF;color:white;font-size:14px;font-weight:700;cursor:pointer;">Retry</button></div>';
        }
    }, 400); // debounce
}

function renderMusicTracks(tracks, container) {
    container.innerHTML = '<div style="padding:0 16px;">';

    tracks.forEach(function(track) {
        if (!track.previewUrl) return; // Only show tracks with playable previews

        var artUrl = (track.artworkUrl100 || '').replace('100x100', '300x300');
        var trackName = track.trackName || 'Unknown';
        var artistName = track.artistName || 'Unknown';
        var duration = track.trackTimeMillis ? formatMusicDuration(track.trackTimeMillis) : '';
        var genre = track.primaryGenreName || '';
        var isExplicit = track.trackExplicitness === 'explicit';
        var previewUrl = track.previewUrl;
        var storeUrl = track.trackViewUrl || '';
        var trackId = 'track_' + (track.trackId || track.id || Date.now() + '_' + Math.floor(Math.random() * 1e6));

        var item = document.createElement('div');
        item.id = trackId;
        item.style.cssText = 'display:flex;align-items:center;gap:12px;padding:12px 0;border-bottom:0.5px solid rgba(0,0,0,0.05);cursor:pointer;border-radius:12px;transition:background 0.15s;';
        item.setAttribute('data-preview', previewUrl);
        item.setAttribute('data-name', trackName);
        item.setAttribute('data-artist', artistName);
        item.setAttribute('data-art', artUrl);

        item.onmouseover = function() { this.style.background = 'rgba(0,0,0,0.03)'; };
        item.onmouseout = function() { this.style.background = ''; };

        item.innerHTML =
            // Album art with 1px edge highlight
            '<div style="position:relative;flex-shrink:0;width:52px;height:52px;">' +
                '<img src="' + escapeHtml(artUrl) + '" ' +
                    'style="width:52px;height:52px;border-radius:12px;object-fit:cover;' +
                    'box-shadow:0 2px 8px rgba(0,0,0,0.15),0 0 0 1px rgba(255,255,255,0.6) inset;" ' +
                    'onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\'">' +
                '<div style="display:none;width:52px;height:52px;border-radius:12px;background:linear-gradient(135deg,#007AFF,#5856D6);align-items:center;justify-content:center;">' +
                    '<i class="fa-solid fa-music" style="color:white;font-size:20px;"></i>' +
                '</div>' +
                // Playing indicator overlay
                '<div id="playing_' + trackId + '" style="display:none;position:absolute;inset:0;border-radius:12px;background:rgba(0,122,255,0.7);align-items:center;justify-content:center;">' +
                    '<i class="fa-solid fa-pause" style="color:white;font-size:16px;"></i>' +
                '</div>' +
            '</div>' +

            // Track info
            '<div style="flex:1;min-width:0;">' +
                '<div style="display:flex;align-items:center;gap:5px;margin-bottom:2px;">' +
                    '<b style="font-size:14px;color:var(--text-primary,#000);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:180px;">' + escapeHtml(trackName) + '</b>' +
                    (isExplicit ? '<span style="font-size:9px;background:rgba(0,0,0,0.15);color:#888;padding:1px 5px;border-radius:4px;font-weight:700;flex-shrink:0;">E</span>' : '') +
                '</div>' +
                '<small style="color:#888;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block;max-width:200px;">' +
                    escapeHtml(artistName) +
                    (genre ? ' · <span style="color:#aaa;">' + escapeHtml(genre) + '</span>' : '') +
                '</small>' +
            '</div>' +

            // Duration + play glass button
            '<div style="display:flex;align-items:center;gap:8px;flex-shrink:0;">' +
                '<small style="color:#ccc;font-size:11px;">' + duration + '</small>' +
                '<button id="playBtn_' + trackId + '" ' +
                    'onclick="event.stopPropagation();toggleMusicPreview(\'' + trackId + '\',\'' + escapeHtml(previewUrl) + '\',\'' + escapeHtml(trackName) + '\',\'' + escapeHtml(artistName) + '\',\'' + escapeHtml(artUrl) + '\')" ' +
                    'style="width:38px;height:38px;border-radius:50%;' +
                    'background:rgba(255,255,255,0.8);backdrop-filter:blur(10px);' +
                    'border:0.5px solid rgba(0,0,0,0.1);' +
                    'box-shadow:2px 2px 8px rgba(0,0,0,0.1),-1px -1px 4px rgba(255,255,255,0.8);' +
                    'display:flex;align-items:center;justify-content:center;cursor:pointer;transition:0.2s;" ' +
                    'onmouseover="this.style.background=\'rgba(0,122,255,0.15)\';this.style.borderColor=\'rgba(0,122,255,0.3)\'" ' +
                    'onmouseout="this.style.background=\'rgba(255,255,255,0.8)\';this.style.borderColor=\'rgba(0,0,0,0.1)\'">' +
                    '<i id="playIcon_' + trackId + '" class="fa-solid fa-play" style="color:#007AFF;font-size:12px;margin-left:2px;"></i>' +
                '</button>' +
            '</div>';

        // Click the row to select this track for the Thought
        item.onclick = function(e) {
            if (e.target.closest('button')) return;
            selectRealMusicTrack(trackName, artistName, artUrl, previewUrl);
        };

        container.appendChild(item);
    });

}

function toggleMusicPreview(trackId, previewUrl, trackName, artistName, artUrl) {
    var playIcon = document.getElementById('playIcon_' + trackId);
    var playingOverlay = document.getElementById('playing_' + trackId);

    // If same track — toggle pause/play
    if (_currentPlayingBtn === trackId && _musicAudio) {
        if (_musicAudio.paused) {
            _musicAudio.play().catch(function(){});
            if (playIcon) { playIcon.className = 'fa-solid fa-pause'; playIcon.style.marginLeft = '0'; }
            if (playingOverlay) playingOverlay.style.display = 'flex';
            var npBar = document.getElementById('musicNowPlaying');
            if (npBar) npBar.style.display = 'flex';
        } else {
            _musicAudio.pause();
            if (playIcon) { playIcon.className = 'fa-solid fa-play'; playIcon.style.marginLeft = '2px'; }
            if (playingOverlay) playingOverlay.style.display = 'none';
        }
        return;
    }

    // Different track — hard stop everything first
    stopMusicPreview();

    // Small delay so stopMusicPreview fully cleans up
    setTimeout(function() {
        _currentPlayingBtn = trackId;

        // Show loading state
        if (playIcon) {
            playIcon.className = 'fa-solid fa-spinner fa-spin';
            playIcon.style.marginLeft = '0';
            playIcon.style.color = '#007AFF';
        }

        // Remove old audio element
        var old = document.getElementById('tfMusicAudioEl');
        if (old) { old.pause(); old.src = ''; old.remove(); }

        // Create fresh audio element in DOM
        var audioEl = document.createElement('audio');
        audioEl.id = 'tfMusicAudioEl';
        audioEl.volume = 1.0;
        audioEl.muted = false;
        audioEl.preload = 'auto';
        audioEl.style.cssText = 'display:none;position:absolute;width:0;height:0;';
        audioEl.src = previewUrl;

        var appEl = document.getElementById('app') || document.body;
        appEl.appendChild(audioEl);
        _musicAudio = audioEl;

        audioEl.addEventListener('canplay', function() {
            if (_currentPlayingBtn !== trackId) return; // another track took over
            if (playIcon) {
                playIcon.className = 'fa-solid fa-pause';
                playIcon.style.marginLeft = '0';
                playIcon.style.color = '#007AFF';
            }
            if (playingOverlay) playingOverlay.style.display = 'flex';
            showNowPlayingBar(trackName, artistName, artUrl);
        });

        audioEl.addEventListener('timeupdate', function() {
            if (!audioEl.duration || _currentPlayingBtn !== trackId) return;
            var pct = (audioEl.currentTime / audioEl.duration) * 100;
            var fill = document.getElementById('npProgressFill');
            if (fill) fill.style.width = pct + '%';
        });

        audioEl.addEventListener('ended', function() {
            stopMusicPreview();
        });

        audioEl.addEventListener('error', function() {
            if (_currentPlayingBtn !== trackId) return;
            stopMusicPreview();
            showToast('Preview not available for this track');
        });

        var promise = audioEl.play();
        if (promise) {
            promise.then(function() {
                triggerHaptic(15);
            }).catch(function(err) {
                if (err.name === 'NotAllowedError') {
                    showToast('Tap play again to start audio');
                    if (playIcon) { playIcon.className = 'fa-solid fa-play'; playIcon.style.marginLeft = '2px'; }
                    _currentPlayingBtn = null;
                } else {
                    // Retry without crossOrigin
                    audioEl.removeAttribute('crossorigin');
                    audioEl.load();
                    audioEl.play().catch(function() {
                        stopMusicPreview();
                        showToast('Preview unavailable');
                    });
                }
            });
        }
    }, 80);
}

// Fallback: play without crossOrigin (fixes some CORS audio errors)
function tryPlayWithoutCors(trackId, previewUrl, trackName, artistName, artUrl) {
    var playIcon = document.getElementById('playIcon_' + trackId);

    var old = document.getElementById('tfMusicAudioEl');
    if (old) old.remove();

    var audioEl = document.createElement('audio');
    audioEl.id = 'tfMusicAudioEl';
    audioEl.volume = 1.0;
    audioEl.muted = false;
    audioEl.preload = 'auto';
    // No crossOrigin this time
    audioEl.src = previewUrl;
    audioEl.style.display = 'none';

    var appEl = document.getElementById('app') || document.body;
    appEl.appendChild(audioEl);
    _musicAudio = audioEl;
    _currentPlayingBtn = trackId;

    audioEl.addEventListener('canplay', function() {
        if (playIcon) { playIcon.className = 'fa-solid fa-pause'; playIcon.style.marginLeft = '0'; }
        var playingOverlay = document.getElementById('playing_' + trackId);
        if (playingOverlay) playingOverlay.style.display = 'flex';
        showNowPlayingBar(trackName, artistName, artUrl);
    });

    audioEl.addEventListener('timeupdate', function() {
        if (!audioEl.duration) return;
        var pct = (audioEl.currentTime / audioEl.duration) * 100;
        var fill = document.getElementById('npProgressFill');
        if (fill) fill.style.width = pct + '%';
    });

    audioEl.addEventListener('ended', function() { stopMusicPreview(); });

    audioEl.addEventListener('error', function() {
        stopMusicPreview();
        showToast('Preview unavailable for this track');
        if (playIcon) { playIcon.className = 'fa-solid fa-play'; playIcon.style.marginLeft = '2px'; }
    });

    audioEl.play().catch(function(err) {
        console.error('[MusicPreview-Fallback]', err);
        stopMusicPreview();
        showToast('Preview unavailable for this track');
    });
}

function stopMusicPreview() {
    // Kill audio element completely
    var audioEl = document.getElementById('tfMusicAudioEl');
    if (audioEl) {
        try { audioEl.pause(); } catch(e) { if (e) console.warn('[Suppressed error]', e); }
        audioEl.src = '';
        try { audioEl.load(); } catch(e) { if (e) console.warn('[Suppressed error]', e); }
        audioEl.remove();
    }
    if (_musicAudio) {
        try { _musicAudio.pause(); _musicAudio.src = ''; } catch(e) { if (e) console.warn('[Suppressed error]', e); }
        _musicAudio = null;
    }

    // Reset every play button icon in the hub
    document.querySelectorAll('[id^="playIcon_"]').forEach(function(icon) {
        icon.className = 'fa-solid fa-play';
        icon.style.marginLeft = '2px';
        icon.style.color = '#007AFF';
    });
    // Hide all album art playing overlays
    document.querySelectorAll('[id^="playing_"]').forEach(function(el) {
        el.style.display = 'none';
    });
    // Hide now playing bar
    var npBar = document.getElementById('musicNowPlaying');
    if (npBar) npBar.style.display = 'none';
    var fill = document.getElementById('npProgressFill');
    if (fill) fill.style.width = '0%';

    _currentPlayingBtn = null;
}

function showNowPlayingBar(trackName, artistName, artUrl) {
    var bar = document.getElementById('musicNowPlaying');
    if (!bar) return;

    bar.style.display = 'flex';

    var title = document.getElementById('npTitle');
    var artist = document.getElementById('npArtist');
    var art = document.getElementById('npArtImg');
    var fill = document.getElementById('npProgressFill');

    if (title) title.textContent = trackName;
    if (artist) artist.textContent = artistName;
    if (art && artUrl) {
        art.src = artUrl;
        art.onerror = function() { this.style.display = 'none'; };
    }
    if (fill) fill.style.width = '0%';
}

