function pickThoughtGif(gifUrl) {
    if (gifUrl && gifUrl.startsWith('http')) {
        var previewRow = document.getElementById('thoughtGifPreview');
        if (!previewRow) {
            previewRow = document.createElement('div');
            previewRow.id = 'thoughtGifPreview';
            previewRow.style.cssText = 'padding:0 20px 8px;';
            var ta = document.getElementById('thoughtInput') || document.querySelector('#thoughtsOverlay textarea');
            if (ta && ta.parentElement) ta.parentElement.insertAdjacentElement('afterend', previewRow);
        }
        previewRow.innerHTML = '<div style="position:relative;display:inline-block;">'
            + '<img src="'+escapeHtml(gifUrl)+'" style="max-height:120px;border-radius:12px;display:block;">'
            + '<div onclick="document.getElementById(\'thoughtGifPreview\').innerHTML=\'\';window._thoughtGifUrl=null;" style="position:absolute;top:-6px;right:-6px;width:20px;height:20px;border-radius:50%;background:#FF3B30;color:white;font-size:11px;font-weight:900;display:flex;align-items:center;justify-content:center;cursor:pointer;line-height:1;">✕</div>'
            + '</div>';
        window._thoughtGifUrl = gifUrl;
    } else {
        insertThoughtEmoji(gifUrl);
    }
    document.getElementById('thoughtGifSheet')?.remove();
    triggerHaptic(15);
}

var _thoughtGifTimer = null;
function filterThoughtGifs(query) {
    var clear = document.getElementById('gifClearBtn');
    if (clear) clear.style.display = query ? 'block' : 'none';
    clearTimeout(_thoughtGifTimer);
    _thoughtGifTimer = setTimeout(function() { loadThoughtGifs(query || 'trending'); }, 400);
}

async function loadThoughtGifs(query) {
    var grid = document.getElementById('thoughtGifGrid');
    if (!grid) return;
    grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:28px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:22px;"></i></div>';
    try {
        var res = await fetch('/api/giphy/search/?q=' + encodeURIComponent(query) + '&type=gifs');
        var data = await res.json();
        var items = data.data || [];
        grid.innerHTML = '';
        if (!items.length) { grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:28px;color:#888;font-size:13px;">No GIFs found</div>'; return; }
        items.forEach(function(item) {
            var src = (item.images.fixed_height_small || item.images.original).url;
            var original = item.images.original.url;
            var cell = document.createElement('div');
            cell.style.cssText = 'border-radius:12px;overflow:hidden;background:#f0f0f0;aspect-ratio:1;cursor:pointer;transition:transform 0.15s;';
            cell.onmouseover = function(){ this.style.transform='scale(0.96)'; };
            cell.onmouseout = function(){ this.style.transform='scale(1)'; };
            cell.onclick = function() { pickThoughtGif(original); document.getElementById('thoughtGifSheet')?.remove(); };
            var img = document.createElement('img');
            img.src = src;
            img.style.cssText = 'width:100%;height:100%;object-fit:cover;display:block;';
            img.loading = 'lazy';
            cell.appendChild(img);
            grid.appendChild(cell);
        });
    } catch(e) {
        grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:28px;color:#888;font-size:13px;">Could not load GIFs</div>';
    }
}

function selectGifCategory(el, cat) {
    var _dark = document.documentElement.getAttribute('data-theme') === 'dark';
    document.querySelectorAll('#thoughtGifSheet [onclick*="selectGifCategory"]').forEach(function(btn) {
        btn.style.background = _dark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.05)';
        btn.style.color = _dark ? '#bbb' : '#555';
    });
    if (el) { el.style.background = '#007AFF'; el.style.color = 'white'; }
    var q = {Trending:'trending',Reactions:'reaction',Love:'love',Funny:'funny',Cute:'cute',Sports:'sports'};
    loadThoughtGifs(q[cat] || cat.toLowerCase());
}

function openThoughtAudience(btn) {
    var existing = document.getElementById('thoughtAudienceMenu');
    if (existing) { existing.remove(); return; }

    var dark = document.documentElement.getAttribute('data-theme') === 'dark';
    var menuBg = dark ? 'rgba(28,28,32,0.97)' : 'rgba(255,255,255,0.94)';
    var txt = dark ? '#fff' : '#000';
    var sub = dark ? '#9a9a9f' : '#888';
    var bord = dark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.06)';

    var menu = document.createElement('div');
    menu.id = 'thoughtAudienceMenu';
    menu.style.cssText = 'position:absolute;bottom:98px;left:50%;transform:translateX(-50%);width:262px;z-index:10020;background:' + menuBg + ';backdrop-filter:blur(50px) saturate(200%);-webkit-backdrop-filter:blur(50px) saturate(200%);border:0.5px solid ' + bord + ';border-radius:22px;box-shadow:0 12px 40px rgba(0,0,0,0.35);overflow:hidden;animation:jellyPop 0.28s cubic-bezier(0.68,-0.55,0.27,1.55);';

    var options = [
        { key: 'everyone', icon: 'fa-globe', label: 'Everyone', desc: 'Visible to all', color: '#007AFF' },
        { key: 'followers', icon: 'fa-user-check', label: 'Followers only', desc: 'Only your followers', color: '#34C759' },
        { key: 'trustcircle', icon: 'fa-star', label: 'TrustCircle', desc: 'Your trusted circle', color: '#FF9500' },
        { key: 'none', icon: 'fa-lock', label: 'Only Me', desc: 'Private, just you', color: '#888' }
    ];

    menu.innerHTML = options.map(function(opt, i) {
        var border = i < options.length - 1 ? 'border-bottom:0.5px solid ' + bord + ';' : '';
        return '<div onclick="selectThoughtAudience(\'' + opt.key + '\',\'' + opt.label + '\',\'' + opt.icon + '\')" style="display:flex;align-items:center;gap:12px;padding:14px 18px;cursor:pointer;' + border + '">' +
            '<div style="width:34px;height:34px;border-radius:10px;background:' + opt.color + '22;display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
            '<i class="fa-solid ' + opt.icon + '" style="color:' + opt.color + ';font-size:14px;"></i></div>' +
            '<div style="flex:1;"><b style="font-size:14px;color:' + txt + ';display:block;">' + opt.label + '</b><small style="color:' + sub + ';font-size:11px;">' + opt.desc + '</small></div>' +
            '</div>';
    }).join('');

    var overlay = document.getElementById('thoughtsOverlay');
    if (overlay) overlay.appendChild(menu);

    // Close when clicking outside
    setTimeout(function() {
        document.addEventListener('click', function handler(e) {
            if (!menu.contains(e.target) && e.target !== btn) {
                menu.remove();
                document.removeEventListener('click', handler);
            }
        });
    }, 100);
}

function selectThoughtAudience(key, label, icon) {
    window._thoughtAudience = key;
    try { localStorage.setItem('tf_thought_audience', key); } catch (e) {}
    var labelEl = document.getElementById('thoughtAudienceLabel');
    var iconEl = document.getElementById('thoughtAudienceIcon');
    if (labelEl) labelEl.textContent = label;
    if (iconEl) { iconEl.className = 'fa-solid ' + icon; iconEl.style.fontSize = '16px'; }
    var menu = document.getElementById('thoughtAudienceMenu');
    if (menu) menu.remove();
    triggerHaptic(10);
}

async function shareThought() {
    var input = document.getElementById('thoughtInput');
    var text = input ? input.value.trim() : '';
    var musicData = thoughtSelectedMusic;
    var gifUrl = window._thoughtGifUrl || null;

    // Allow any combination of text / song / GIF — never fully empty
    if (!text && !musicData && !gifUrl) {
        showToast('Add a thought, GIF or song first');
        return;
    }

    var shareBtn = document.getElementById('thoughtShareBtn');
    if (shareBtn) { shareBtn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>'; shareBtn.disabled = true; }

    // Text, GIF (media_url) and music (thought_music) are stored separately so
    // the profile cloud can show all three together.
    var postData = {
        user_id: currentUser?.id,
        text_content: text,
        post_type: 'thought',
        status: 'published',
        visibility: window._thoughtAudience || 'everyone'
    };
    if (gifUrl) { postData.media_url = gifUrl; postData.media_type = 'gif'; }
    if (musicData) { postData.thought_music = musicData; }

    try {
        if (window.sb && currentUser) {
            var { error: _thErr } = await sb.from('posts').insert(postData);
            if (_thErr) { console.error('[Thought] insert failed:', _thErr.message); showToast('Could not share'); if (shareBtn){ shareBtn.innerHTML='Share'; shareBtn.disabled=false; } return; }
        }
    } catch(e) { console.warn('[Thought]', e); }

    // Remember for instant display on the profile cloud (survives reload via DB).
    var cur = { text: text, gif: gifUrl, music: musicData || null, ts: Date.now() };
    try { localStorage.setItem('tf_current_thought', JSON.stringify(cur)); } catch(e) {}
    _renderThoughtCloud(document.querySelector('.thought-cloud'), cur);

    window._thoughtGifUrl = null;
    closeThoughts();
    triggerHaptic(50);

    // Refresh feed
    setTimeout(function() { if (typeof initFeed === 'function') initFeed(); }, 800);
}

// Render a thought (GIF plays on top, text under it, music line last) into the
// small profile cloud. Used both after sharing and when loading the profile.
function _renderThoughtCloud(el, d) {
    if (!el) return;
    d = d || {};
    var hasGif = !!d.gif, hasText = !!(d.text && String(d.text).trim()), hasMusic = !!(d.music && d.music.name);
    if (!hasGif && !hasText && !hasMusic) { el.classList.remove('has-media'); el.textContent = 'Thinking...'; return; }
    el.classList.add('has-media');
    var html = '';
    if (hasGif) html += '<img src="' + escapeHtml(d.gif) + '" style="width:100%;max-height:120px;object-fit:cover;border-radius:10px;display:block;">';
    if (hasText) html += '<div class="tc-text" style="font-size:12px;font-weight:700;line-height:1.3;margin-top:' + (hasGif ? '5px' : '0') + ';word-break:break-word;">' + escapeHtml(d.text) + '</div>';
    if (hasMusic) html += '<div style="display:flex;align-items:center;gap:5px;margin-top:5px;font-size:10px;font-weight:700;opacity:0.85;"><i class="fa-solid fa-music" style="font-size:9px;flex-shrink:0;"></i><span style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(d.music.name) + (d.music.artist ? ' · ' + escapeHtml(d.music.artist) : '') + '</span></div>';
    el.innerHTML = html;
}

// Load the current user's latest thought into the profile cloud (cache first,
// then the freshest copy from the DB).
function loadProfileThought() {
    var el = document.getElementById('profileThoughtCloud');
    if (!el) return;
    var cur = null;
    try { cur = JSON.parse(localStorage.getItem('tf_current_thought') || 'null'); } catch(e) {}
    if (cur) _renderThoughtCloud(el, cur);
    if (window.sb && currentUser) {
        sb.from('posts').select('text_content,media_url,media_type,thought_music,created_at')
            .eq('user_id', currentUser.id).eq('post_type', 'thought')
            .order('created_at', { ascending: false }).limit(1).maybeSingle()
            .then(function(res) {
                if (res && res.data) {
                    var d = res.data;
                    var data = { text: d.text_content || '', gif: (d.media_type === 'gif' ? d.media_url : null), music: d.thought_music || null };
                    _renderThoughtCloud(el, data);
                    try { localStorage.setItem('tf_current_thought', JSON.stringify(data)); } catch(e) {}
                }
            }, function() {});
    }
}

function closeThoughts() {
    var overlay = document.getElementById('thoughtsOverlay');
    if (overlay) {
        overlay.style.opacity = '0';
        overlay.style.transform = 'scale(0.97)';
        overlay.style.transition = 'opacity 0.25s ease, transform 0.25s ease';
        setTimeout(function() { overlay.remove(); }, 250);
    }
    if (_thoughtPreviewCtx) { try { _thoughtPreviewCtx.close(); } catch(e) { if (e) console.warn('[Suppressed error]', e); } _thoughtPreviewCtx = null; }
}

function openSoundtrackSheet(track) {
    var existing = document.getElementById('soundtrackSheet');
    if (existing) existing.remove();

    track = track || thoughtSelectedMusic || {
        name: 'Afrobeats Vibes', artist: 'Artist Name',
        artUrl: 'https://picsum.photos/seed/album/200/200', previewUrl: null
    };

    var sheet = document.createElement('div');
    sheet.id = 'soundtrackSheet';
    sheet.className = 'soundtrack-sheet';

    sheet.innerHTML =
        // Top action bar
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px 0;">' +
            '<button onclick="document.getElementById(\'soundtrackSheet\').remove()" style="background:none;border:none;color:rgba(255,255,255,0.5);font-size:15px;font-weight:600;cursor:pointer;">New song</button>' +
            '<div style="width:36px;height:4px;background:rgba(255,255,255,0.18);border-radius:2px;"></div>' +
            '<button onclick="confirmSoundtrackSelection()" style="background:#007AFF;border:none;color:white;font-size:15px;font-weight:700;padding:8px 22px;border-radius:20px;cursor:pointer;">Done</button>' +
        '</div>' +

        // Album art + track info
        '<div style="display:flex;flex-direction:column;align-items:center;padding:24px 20px 16px;">' +
            '<img src="' + escapeHtml(track.artUrl || '') + '" onerror="this.style.display=\'none\'" style="width:88px;height:88px;border-radius:18px;object-fit:cover;box-shadow:0 8px 32px rgba(0,0,0,0.5);margin-bottom:14px;">' +
            '<b style="color:white;font-size:17px;font-weight:800;margin-bottom:4px;">' + escapeHtml(track.name || 'Song Title') + '</b>' +
            '<small style="color:rgba(255,255,255,0.5);font-size:13px;">' + escapeHtml(track.artist || 'Artist') + '</small>' +
        '</div>' +

        // Progress controls row
        '<div style="display:flex;align-items:center;gap:14px;padding:0 20px 12px;">' +
            // 30s selector
            '<button onclick="set30sDuration(this)" style="width:42px;height:42px;border-radius:50%;background:rgba(255,255,255,0.1);border:0.5px solid rgba(255,255,255,0.18);display:flex;align-items:center;justify-content:center;flex-shrink:0;cursor:pointer;">' +
                '<span style="color:white;font-size:11px;font-weight:800;line-height:1;">30<br>sec</span>' +
            '</button>' +
            // Progress line
            '<div style="flex:1;height:3px;background:rgba(255,255,255,0.15);border-radius:2px;position:relative;cursor:pointer;" id="trackProgressBar">' +
                '<div id="trackProgressFill" style="width:0%;height:100%;background:#007AFF;border-radius:2px;transition:width 0.2s;"></div>' +
                '<div id="trackProgressThumb" style="position:absolute;top:50%;left:0%;transform:translate(-50%,-50%);width:12px;height:12px;border-radius:50%;background:white;box-shadow:0 2px 8px rgba(0,0,0,0.4);cursor:grab;"></div>' +
            '</div>' +
            // Stop/Preview
            '<button id="stPreviewBtn" onclick="toggleSoundtrackPreview(this,\'' + escapeHtml(track.previewUrl || '') + '\')" style="width:42px;height:42px;border-radius:50%;background:rgba(255,255,255,0.1);border:0.5px solid rgba(255,255,255,0.18);display:flex;align-items:center;justify-content:center;flex-shrink:0;cursor:pointer;">' +
                '<i class="fa-solid fa-play" style="color:white;font-size:14px;margin-left:2px;"></i>' +
            '</button>' +
        '</div>' +

        // Waveform scrubber
        '<div style="padding:8px 20px 0;">' +
            '<div class="liquid-glass-waveform">' +
                '<input type="range" class="waveform-slider" id="waveformScrubber" min="0" max="100" value="0" oninput="scrubWaveform(this)">' +
            '</div>' +
            '<div style="display:flex;justify-content:space-between;margin-top:6px;">' +
                '<small style="color:rgba(255,255,255,0.3);font-size:10px;">0:00</small>' +
                '<small id="waveformScrubTime" style="color:rgba(255,255,255,0.5);font-size:10px;font-weight:700;">0:00</small>' +
                '<small style="color:rgba(255,255,255,0.3);font-size:10px;">0:30</small>' +
            '</div>' +
        '</div>';

    (document.getElementById('app') || document.body).appendChild(sheet);
    setupWaveformDrag();
    // Hook real-time scrubber position to audio playback
    if (_musicAudio) {
        _musicAudio.addEventListener('timeupdate', function() {
            var scrubber = document.getElementById('waveformScrubber');
            var fill = document.getElementById('trackProgressFill');
            var thumb = document.getElementById('trackProgressThumb');
            var timeEl = document.getElementById('waveformScrubTime');
            if (!scrubber || !_musicAudio.duration) return;
            var pct = (_musicAudio.currentTime / _musicAudio.duration) * 100;
            scrubber.value = pct;
            if (fill) fill.style.width = pct + '%';
            if (thumb) thumb.style.left = pct + '%';
            if (timeEl) {
                var s = Math.floor(_musicAudio.currentTime);
                timeEl.textContent = Math.floor(s/60) + ':' + (s%60 < 10 ? '0' : '') + (s%60);
            }
        });
    }
}

function toggleSoundtrackPreview(btn, previewUrl) {
    var icon = btn.querySelector('i');
    if (icon.classList.contains('fa-stop')) {
        icon.className = 'fa-solid fa-play';
        icon.style.marginLeft = '2px';
        stopMusicPreview();
    } else {
        icon.className = 'fa-solid fa-stop';
        icon.style.marginLeft = '0';
        if (previewUrl) toggleMusicPreview('soundtrack_tmp', previewUrl, '', '', '');
        else showToast('No preview available');
    }
}

function scrubWaveform(input) {
    var pct = parseFloat(input.value) || 0;
    var fill = document.getElementById('trackProgressFill');
    var thumb = document.getElementById('trackProgressThumb');
    var timeEl = document.getElementById('waveformScrubTime');
    var totalSecs = (_musicAudio && _musicAudio.duration && _musicAudio.duration > 0) ? _musicAudio.duration : 30;
    var currentSec = (pct / 100) * totalSecs;
    var m = Math.floor(currentSec / 60);
    var s = Math.floor(currentSec % 60);
    if (fill)  fill.style.width = pct + '%';
    if (thumb) thumb.style.left = pct + '%';
    if (timeEl) timeEl.textContent = m + ':' + (s < 10 ? '0' : '') + s;
    input.style.setProperty('--pct', pct + '%');
    if (_musicAudio && _musicAudio.duration) {
        _musicAudio.currentTime = (_musicAudio.duration * pct) / 100;
    }
}

function scrubWaveformWindow(input, totalDur, windowSecs) {
    var startSec = parseFloat(input.value);
    var endSec   = startSec + windowSecs;
    var pct      = (startSec / Math.max(totalDur - windowSecs, 1)) * 100;

    var fill  = document.getElementById('trackProgressFill');
    var thumb = document.getElementById('trackProgressThumb');
    var wvS   = document.getElementById('wvStart');
    var wvE   = document.getElementById('wvEnd');

    if (fill)  fill.style.width  = pct + '%';
    if (thumb) thumb.style.left  = pct + '%';
    if (wvS)   wvS.textContent   = formatSecs(startSec);
    if (wvE)   wvE.textContent   = formatSecs(endSec);

    input.style.setProperty('--pct', pct + '%');

    // Seek the audio preview to the selected start
    if (_musicAudio && !_musicAudio.paused && _musicAudio.duration) {
        _musicAudio.currentTime = startSec;
    }
}

function set30sDuration(btn) {
    var existing = document.getElementById('clipLenPicker');
    if (existing) { existing.remove(); return; }
    var startSec = (_musicAudio && _musicAudio.currentTime) ? Math.floor(_musicAudio.currentTime) : 0;
    var picker = document.createElement('div');
    picker.id = 'clipLenPicker';
    picker.style.cssText = 'position:absolute;left:20px;right:20px;bottom:calc(100% + 8px);background:rgba(30,30,36,0.95);backdrop-filter:blur(20px);border-radius:18px;border:0.5px solid rgba(255,255,255,0.15);padding:16px 18px;z-index:100;';
    picker.innerHTML =
        '<p style="color:rgba(255,255,255,0.5);font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:0.06em;margin:0 0 10px;">Clip length</p>' +
        '<div style="display:flex;align-items:center;gap:12px;">' +
            '<span style="color:rgba(255,255,255,0.5);font-size:12px;">10s</span>' +
            '<input type="range" id="clipLenSlider" min="10" max="30" step="1" value="30" style="flex:1;accent-color:#007AFF;">' +
            '<span style="color:rgba(255,255,255,0.5);font-size:12px;">30s</span>' +
        '</div>' +
        '<p id="clipLenLabel" style="color:white;font-size:15px;font-weight:700;text-align:center;margin:10px 0 0;">30s clip · from ' + formatSecs(startSec) + '</p>';
    // Parent must be position:relative — soundtrack sheet is
    var sheet = document.getElementById('soundtrackSheet');
    if (sheet) { sheet.style.position = 'relative'; sheet.appendChild(picker); }
    document.getElementById('clipLenSlider').addEventListener('input', function() {
        var len = parseInt(this.value);
        var label = document.getElementById('clipLenLabel');
        if (label) label.textContent = len + 's clip · from ' + formatSecs(startSec);
        if (_musicAudio) { _musicAudio.currentTime = startSec; }
        window._selectedClipLen = len;
        window._selectedClipStart = startSec;
        if (_musicAudio && _musicAudio.paused) _musicAudio.play().catch(function(){});
        // Auto-stop at clip end
        clearTimeout(window._clipStopTimer);
        window._clipStopTimer = setTimeout(function() { if (_musicAudio) _musicAudio.pause(); }, len * 1000);
    });
    window._selectedClipLen = 30;
    window._selectedClipStart = startSec;
    triggerHaptic(15);
}

function setupWaveformDrag() {
    var bar = document.getElementById('trackProgressBar');
    if (!bar) return;
    bar.addEventListener('click', function(e) {
        var rect = bar.getBoundingClientRect();
        var pct = Math.max(0, Math.min(100, ((e.clientX - rect.left) / rect.width) * 100));
        var scrubber = document.getElementById('waveformScrubber');
        if (scrubber) { scrubber.value = pct; scrubber.dispatchEvent(new Event('input')); }
    });
}

function confirmSoundtrackSelection() {
    document.getElementById('soundtrackSheet').remove();
    showToast('🎵 Soundtrack added to Thought');
    triggerHaptic(20);
}
