let currentSearchTab = 'all';

const hashtagData = [
    { tag: '#TrustFirst', posts: '12.5K', trending: true },
    { tag: '#LiquidGlass', posts: '8.2K', trending: true },
    { tag: '#SafeSpace', posts: '5.1K', trending: false },
    { tag: '#SouthAfrica', posts: '45K', trending: true },
    { tag: '#Verified', posts: '22K', trending: false },
    { tag: '#TrustClips', posts: '9.8K', trending: true },
];

function simulateRealtimeSearch() {
    const searchBox = document.getElementById('s-input');
    const searchTerm = searchBox.value.toLowerCase().trim();

    searchBox.style.background = searchTerm.length > 0 ? 'rgba(0, 122, 255, 0.05)' : 'transparent';

    const discoveryPage = document.getElementById('discovery-page');

   if (!discoveryPage) return;
    if (searchTerm.length < 1) {
        discoveryPage.style.display = 'none';
        return;
    }
    discoveryPage.style.cssText = 'display:flex;flex-direction:column;position:absolute;top:0;left:0;width:100%;height:100%;z-index:3500;background:var(--bg-primary,#fff);overflow:hidden;';

    if (searchTerm.length > 0) {
        let tabsHtml = `
            <div style="display:flex;align-items:center;gap:10px;padding:54px 16px 12px;background:var(--bg-primary,#fff);flex-shrink:0;">
                <div class="liquid-glass-btn" onclick="resetNav()" style="cursor:pointer;"><i class="fa-solid fa-chevron-left"></i></div>
                <b style="font-size:17px;color:var(--text-primary,#000);flex:1;">Search</b>
            </div>
            <div class="search-tabs" style="flex-shrink:0;border-bottom:1px solid var(--border-color,#f0f0f0);">
                <div class="search-tab ${currentSearchTab === 'all' ? 'active' : ''}" onclick="currentSearchTab='all'; simulateRealtimeSearch();">All</div>
                <div class="search-tab ${currentSearchTab === 'users' ? 'active' : ''}" onclick="currentSearchTab='users'; simulateRealtimeSearch();">Users</div>
                <div class="search-tab ${currentSearchTab === 'hashtags' ? 'active' : ''}" onclick="currentSearchTab='hashtags'; simulateRealtimeSearch();">Hashtags</div>
                <div class="search-tab ${currentSearchTab === 'posts' ? 'active' : ''}" onclick="currentSearchTab='posts'; simulateRealtimeSearch();">Posts</div>
                <div class="search-tab ${currentSearchTab === 'clips' ? 'active' : ''}" onclick="currentSearchTab='clips'; simulateRealtimeSearch();">Clips</div>
            </div>
            <div id="search-results-area" style="flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;padding-bottom:120px;"></div>`;

        discoveryPage.innerHTML = tabsHtml;

        setTimeout(() => {
            const area = document.getElementById('search-results-area');
            if (!area) return;
            area.innerHTML = '';

            // Users — real DB query
            if (currentSearchTab === 'all' || currentSearchTab === 'users') {
                var usersPlaceholder = '<div class="search-result-section"><h4>Users</h4><div id="searchUsersGrid"><div style="text-align:center;padding:20px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;"></i></div></div></div>';
                area.innerHTML += usersPlaceholder;
                if (window.sb) {
                    sb.from('users')
                      .select('id,name,username,avatar_url,verified')
.or('name.ilike.%'+searchTerm+'%,username.ilike.%'+searchTerm+'%')
                      .limit(8)
                      .then(function(r) {
                          var el = document.getElementById('searchUsersGrid'); if (!el) return;
                          if (r.data && r.data.length) {
                              el.innerHTML = r.data.map(function(u) {
                                  var av = u.avatar_url ? '<img src="'+escapeHtml(u.avatar_url)+'" style="width:44px;height:44px;border-radius:50%;object-fit:cover;">' : '<div style="width:44px;height:44px;border-radius:50%;background:#007AFF;display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700;font-size:18px;">'+(u.display_name||'?')[0].toUpperCase()+'</div>';
                                  return '<div class="msg-row" style="padding:12px 0;border-bottom:1px solid var(--border-color,#f5f5f5);cursor:pointer;" onclick="viewUserProfile(\''+u.id+'\')">'+av+'<div style="flex:1;margin-left:12px;"><b style="color:var(--text-primary,#000);">'+escapeHtml(u.display_name||u.username||'')+'</b>'+(u.identity_verified?'<i class="fa-solid fa-circle-check verify-blue" style="font-size:10px;margin-left:4px;"></i>':'')+'<br><small style="color:#888;">@'+escapeHtml(u.username||'')+'</small></div></div>';
                              }).join('');
                          } else {
                              el.innerHTML = '<div style="text-align:center;padding:20px;color:#888;font-size:13px;">No users found</div>';
                          }
                      });
                }
            }

            // Hashtags
            if (currentSearchTab === 'all' || currentSearchTab === 'hashtags') {
                const matchedTags = hashtagData.filter(h => h.tag.toLowerCase().includes(searchTerm.replace('#','')));
if (matchedTags.length > 0) {
    const tagsToShow = matchedTags;
                    let html = '<div class="search-result-section"><h4>Hashtags</h4>';
                    tagsToShow.forEach(h => {
                        html += `<div class="hashtag-result">
                            <div class="hashtag-icon">#</div>
                            <div style="flex:1;"><b>${escapeHtml(h.tag)}</b><br><small style="color:#888;">${h.posts} posts${h.trending ? ' • Trending' : ''}</small></div>
                        </div>`;
                    });
                    html += '</div>';
                    area.innerHTML += html;
                }
            }

            // Posts
            if (currentSearchTab === 'all' || currentSearchTab === 'posts') {
                area.innerHTML += '<div class="search-result-section"><h4>Posts</h4><div id="searchPostsGrid" style="display:block;"></div></div>';
                if (window.sb) {
                    sb.from('posts').select('*, users:user_id(id,full_name,username,avatar_url,badge_tier,verified,ai_label), quoted_post:quoted_post_id(*, users:user_id(id,full_name,username,avatar_url,badge_tier,verified,ai_label))').ilike('text_content', '%'+searchTerm+'%').eq('status','published').neq('is_hidden',true).limit(9)
                    .then(function(r){
                        var el=document.getElementById('searchPostsGrid'); if(!el)return;
                        if (r.data && r.data.length) {
                            el.innerHTML = '';
                            r.data.forEach(function(p){ if(typeof renderRealPostCard==='function') el.appendChild(renderRealPostCard(p)); });
                        } else {
                            el.innerHTML = '<div style="text-align:center;padding:20px;color:#888;font-size:13px;">No posts found</div>';
                        }
                    });
                }
            }

            // Clips
            if (currentSearchTab === 'all' || currentSearchTab === 'clips') {
                area.innerHTML += '<div class="search-result-section"><h4>Clips</h4><div id="searchClipsGrid" style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:3px;"><div style="grid-column:1/-1;text-align:center;padding:20px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;"></i></div></div></div>';
                if (window.sb) {
                    sb.from('posts').select('id,media_url,thumbnail_url,view_count,text_content').eq('post_type','video').eq('status','published').eq('is_hidden',false).or('text_content.ilike.%'+searchTerm+'%,tags.cs.{'+searchTerm+'}').limit(9)
                    .then(function(r){
                        var el=document.getElementById('searchClipsGrid'); if(!el)return;
                        el.innerHTML = (r.data&&r.data.length) ? r.data.map(function(p){var t=p.thumbnail_url||p.media_url||'';return '<div style="aspect-ratio:9/16;background:#111;border-radius:8px;position:relative;overflow:hidden;">'+(t?'<img src="'+escapeHtml(t)+'" style="width:100%;height:100%;object-fit:cover;opacity:0.8;">':'<div style="width:100%;height:100%;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-play" style="color:rgba(255,255,255,0.3);font-size:20px;"></i></div>')+'<div style="position:absolute;bottom:6px;left:6px;color:white;font-size:11px;font-weight:700;"><i class="fa-solid fa-play"></i> '+(p.view_count||0)+'</div></div>';}).join('') : '<div style="grid-column:1/-1;text-align:center;padding:20px;color:#888;font-size:13px;">No clips found</div>';
                    });
                }
            }

            if (area.innerHTML === '') {
                area.innerHTML = '<div style="text-align:center; padding:60px 20px; color:#888;"><i class="fa-solid fa-magnifying-glass" style="font-size:30px; margin-bottom:15px; display:block;"></i>No results found</div>';
            }
        }, 200);
    }
}

