function doOpenDeviceContactsSettings() {
    document.getElementById('contactsAccessModal').remove();
    var ua = navigator.userAgent;
    if (/android/i.test(ua)) {
        // Try Android intent to app settings
        var tried = false;
        try {
            var iframe = document.createElement('iframe');
            iframe.style.display = 'none';
            iframe.src = 'intent://settings/application-details#Intent;scheme=android-settings;end';
            document.body.appendChild(iframe);
            setTimeout(function() { document.body.removeChild(iframe); }, 500);
            tried = true;
        } catch(e) {}
        if (!tried) showToast('Go to Settings → Apps → TrustFirst → Permissions → Contacts');
    } else {
        // iOS — cannot open Settings directly from web, show instructions
        showToast('Go to Settings → Privacy & Security → Contacts → TrustFirst');
    }
}

async function detectContactsPermission() {
    // Try Permissions API first
    if (navigator.permissions) {
        try {
            var result = await navigator.permissions.query({ name: 'contacts' });
            if (result.state === 'granted') return 'Full';
            if (result.state === 'prompt') return 'Not set';
            if (result.state === 'denied') return 'None';
        } catch(e) {}
    }
    // Fall back to ContactsManager availability + localStorage record
    if (!('contacts' in navigator && 'ContactsManager' in window)) return 'None';
    var stored = localStorage.getItem('tf_contacts_access_level');
    if (stored) return stored;
    return 'Limited';
}

