async function syncContacts() {
    showToast('Syncing contacts...');
    try {
        // Use Web Contacts API (Chrome Android + some browsers)
        if (!('contacts' in navigator && 'ContactsManager' in window)) {
            toast('Contact sync not supported on this device.', 'info');
            return;
        }
        const props = ['name', 'tel', 'email'];
        localStorage.setItem('tf_contacts_access_level', 'Full');
        const contacts = await navigator.contacts.select(props, { multiple: true });
        if (!contacts.length) return;

        // Hash phone numbers before sending to protect privacy
        const hashed = await Promise.all(contacts.flatMap(c =>
            (c.tel || []).map(async t => {
                const normalized = t.replace(/\s+/g, '');
                const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(normalized));
                return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2,'0')).join('');
            })
        ));

        const { data, error } = await window.sb
            .rpc('match_contacts_by_phone_hash', { hashes: hashed });

        if (error) throw error;
        const count = data?.length || 0;
        toast(`Found ${count} contact${count !== 1 ? 's' : ''} on TrustFirst.`, 'success');
        if (count) renderContactSuggestions(data);

    } catch (e) {
        toast('Contact sync failed. Check permissions.', 'error');
    }
}


async function setup2FA(method, toggleEl) {
    if (!window._sb || !currentUser) { showToast('Please log in first.'); return; }

    if (method === 'phone') { open2FAPhoneSetup(toggleEl); return; }
    if (method === 'email') { open2FAEmailSetup(toggleEl); return; }

    if (method === 'authenticator') {
        window._2faAuthToggle = toggleEl || document.getElementById('twofaAuthToggle');
        // Show authenticator setup modal with QR code
        var existing = document.getElementById('twoFAModal');
        if (existing) existing.remove();
        var modal = document.createElement('div');
        modal.id = 'twoFAModal';
        modal.style.cssText = 'position:absolute;inset:0;z-index:16000;background:rgba(0,0,0,0.6);backdrop-filter:blur(14px);display:flex;align-items:center;justify-content:center;padding:20px;';
        modal.innerHTML =
            '<div style="background:var(--card-bg,#fff);border-radius:24px;padding:28px 22px;width:100%;max-width:380px;box-shadow:0 20px 60px rgba(0,0,0,0.3);text-align:center;">' +
                '<div style="width:56px;height:56px;border-radius:50%;background:rgba(255,149,0,0.1);display:flex;align-items:center;justify-content:center;margin:0 auto 16px;"><i class="fa-solid fa-shield-halved" style="color:#FF9500;font-size:24px;"></i></div>' +
                '<h3 style="font-size:19px;font-weight:800;color:var(--text-primary,#000);margin-bottom:8px;">Authenticator App</h3>' +
                '<p style="font-size:13px;color:#888;margin-bottom:20px;line-height:1.6;">Open Google Authenticator, Microsoft Authenticator, or any TOTP app and scan the QR code below.</p>' +
                '<div id="twofa-qr-box" style="width:180px;height:180px;margin:0 auto 16px;border-radius:16px;background:#f5f5f5;display:flex;align-items:center;justify-content:center;border:2px dashed #ddd;box-sizing:border-box;overflow:hidden;flex-shrink:0;">' +
                    '<i class="fa-solid fa-spinner fa-spin" style="color:#aaa;font-size:28px;"></i>' +
                '</div>' +
                '<p id="twofa-secret-label" style="font-size:11px;color:#aaa;margin-bottom:20px;">Loading secret key…</p>' +
                '<p style="font-size:13px;font-weight:700;color:var(--text-primary,#000);margin-bottom:8px;">Enter the 6-digit code to confirm</p>' +
                '<input id="twofa-code-input" type="number" inputmode="numeric" placeholder="000000" maxlength="6" style="width:100%;padding:14px;border-radius:14px;border:1.5px solid var(--border-color,#eee);font-size:20px;text-align:center;outline:none;letter-spacing:8px;color:var(--text-primary,#000);background:var(--bg-secondary,#f9f9f9);-webkit-user-select:text;user-select:text;" onfocus="this.style.borderColor=\'#FF9500\'" onblur="this.style.borderColor=\'var(--border-color,#eee)\'">' +
                '<button onclick="verify2FACode()" style="width:100%;padding:15px;border-radius:14px;border:none;background:#FF9500;color:#fff;font-size:16px;font-weight:700;cursor:pointer;margin-top:14px;">Verify &amp; Activate</button>' +
                '<button onclick="document.getElementById(\'twoFAModal\').remove();var _t=document.getElementById(\'twofaAuthToggle\');if(_t)_t.classList.remove(\'active\');" style="width:100%;padding:13px;border-radius:14px;border:none;background:var(--bg-secondary,#f0f0f0);color:var(--text-secondary,#666);font-size:14px;cursor:pointer;margin-top:8px;">Cancel</button>' +
            '</div>';
        document.getElementById('app').appendChild(modal);
        // Enroll TOTP
        try {
            var { data, error } = await window._sb.auth.mfa.enroll({ factorType: 'totp' });
            if (error) throw error;
            window._totpFactorId = data.id;
            var qrBox = document.getElementById('twofa-qr-box');
            var secretLabel = document.getElementById('twofa-secret-label');
            if (qrBox && (data.totp?.uri || data.totp?.qr_code)) {
    qrBox.style.background = 'white';
    qrBox.style.border = '2px solid #eee';
    qrBox.style.padding = '12px';
    qrBox.style.boxSizing = 'border-box';
    qrBox.style.overflow = 'hidden';
    qrBox.innerHTML = '';
    if (data.totp.uri && typeof QRCode !== 'undefined') {
                // Render a real scannable QR from the otpauth:// URI using the loaded qrcodejs lib
                try {
                    new QRCode(qrBox, { text: data.totp.uri, width: 156, height: 156, colorDark: '#000000', colorLight: '#ffffff', correctLevel: QRCode.CorrectLevel.M });
                } catch (_e) {
                    qrBox.innerHTML = (data.totp.qr_code && data.totp.qr_code.startsWith('data:'))
                        ? '<img src="' + data.totp.qr_code + '" style="width:100%;height:100%;object-fit:contain;border-radius:8px;" alt="Scan QR">'
                        : (data.totp.qr_code || '');
                }
            } else if (data.totp.qr_code && data.totp.qr_code.startsWith('data:')) {
                qrBox.innerHTML = '<img src="' + data.totp.qr_code + '" style="width:100%;height:100%;object-fit:contain;border-radius:8px;" alt="Scan QR">';
            } else {
                qrBox.innerHTML = data.totp.qr_code;
            }
    var svgEl = qrBox.querySelector('svg');
    if (svgEl) {
        // Set viewBox BEFORE overriding width/height so we capture the natural size
        if (!svgEl.getAttribute('viewBox')) {
            var nativeW = svgEl.getAttribute('width') || '200';
            var nativeH = svgEl.getAttribute('height') || '200';
            svgEl.setAttribute('viewBox', '0 0 ' + nativeW + ' ' + nativeH);
        }
        svgEl.setAttribute('width', '156');
        svgEl.setAttribute('height', '156');
        svgEl.style.cssText = 'width:100%;height:100%;display:block;';
    }
}
            if (secretLabel && data.totp?.secret) {
                secretLabel.textContent = 'Manual key: ' + data.totp.secret;
                secretLabel.style.userSelect = 'text';
                secretLabel.style.webkitUserSelect = 'text';
            }
        } catch(e) {
            showToast('Could not generate QR code: ' + e.message);
            document.getElementById('twoFAModal').remove();
            var _at2 = document.getElementById('twofaAuthToggle'); if (_at2) _at2.classList.remove('active');
        }
        return;
    }
}

async function verify2FACode() {
    var codeInput = document.getElementById('twofa-code-input');
    if (!codeInput) return;
    var code = codeInput.value.trim();
    if (code.length !== 6) { showToast('Enter the full 6-digit code'); return; }
    if (!window._totpFactorId) { showToast('Session expired. Try again.'); return; }
    try {
        var { data: challengeData, error: challengeError } = await window._sb.auth.mfa.challenge({ factorId: window._totpFactorId });
        if (challengeError) throw challengeError;
        var { error: verifyError } = await window._sb.auth.mfa.verify({
            factorId: window._totpFactorId,
            challengeId: challengeData.id,
            code: code
        });
        if (verifyError) throw verifyError;
        document.getElementById('twoFAModal').remove();
        var _at = window._2faAuthToggle || document.getElementById('twofaAuthToggle');
        if (_at) _at.classList.add('active');
        showToast('Authenticator app enabled ✓');
        window._totpFactorId = null;
        window._2faAuthToggle = null;
    } catch(e) {
        showToast('Invalid code. Check your app and try again.');
    }
}


