// ==========================================================================
const languages = [
    { code: 'en', name: 'English', native: 'English' },
    { code: 'es', name: 'Spanish', native: 'Español' },
    { code: 'fr', name: 'French', native: 'Français' },
    { code: 'pt', name: 'Portuguese', native: 'Português' },
    { code: 'de', name: 'German', native: 'Deutsch' },
    { code: 'it', name: 'Italian', native: 'Italiano' },
    { code: 'ar', name: 'Arabic', native: 'العربية' },
    { code: 'hi', name: 'Hindi', native: 'हिन्दी' },
    { code: 'zh', name: 'Chinese', native: '中文' },
    { code: 'ja', name: 'Japanese', native: '日本語' },
    { code: 'ru', name: 'Russian', native: 'Русский' },
    { code: 'tr', name: 'Turkish', native: 'Türkçe' },
    { code: 'sw', name: 'Swahili', native: 'Kiswahili' },
    { code: 'af', name: 'Afrikaans', native: 'Afrikaans' },
];

let currentLanguage = secureLoad('language') || 'en';

function renderLanguages() {
    // Whenever this page is drawn, the auto-translate switch has to reflect
    // what is actually saved rather than the markup's default.
    _tfSyncTranslateToggle();
    const list = document.getElementById('language-list');
    if (!list) return;
    list.innerHTML = '';
    languages.forEach(function(lang) {
        const isActive = lang.code === currentLanguage;
        const row = document.createElement('div');
        row.className = 'settings-row';
        row.style.cursor = 'pointer';
        row.style.background = isActive ? 'rgba(0,122,255,0.06)' : '';
        row.innerHTML =
            '<div style="display:flex; gap:12px; align-items:center;">' +
                '<span style="font-size:20px;">' + getLangFlag(lang.code) + '</span>' +
                '<div>' +
                    '<b style="font-size:15px; color:var(--text-primary,#000);">' + lang.name + '</b>' +
                    '<br><small style="color:#888;">' + lang.native + '</small>' +
                '</div>' +
            '</div>' +
            (isActive ? '<i class="fa-solid fa-check" style="color:#007AFF; font-size:16px;"></i>' : '<i class="fa-solid fa-chevron-right" style="color:#ccc; font-size:12px;"></i>');
        row.onclick = function() { setLanguage(lang.code); };
        list.appendChild(row);
    });
}

function getLangFlag(code) {
    var flags = { en:'🇬🇧', es:'🇪🇸', fr:'🇫🇷', pt:'🇵🇹', de:'🇩🇪', it:'🇮🇹', ar:'🇸🇦', hi:'🇮🇳', zh:'🇨🇳', ja:'🇯🇵', ru:'🇷🇺', tr:'🇹🇷', sw:'🇰🇪', af:'🇿🇦' };
    return flags[code] || '🌐';
}

function setLanguage(code) {
    currentLanguage = code;
    secureSave('language', code);

    var isRTL = (code === 'ar');
    document.documentElement.setAttribute('dir', isRTL ? 'rtl' : 'ltr');
    document.documentElement.setAttribute('lang', code);

    var map = TRANSLATIONS[code] || TRANSLATIONS['en'];

    // Placeholders that actually update visible UI
    var placeholders = {
        '#navSearchInput':   map['search'] || 'Search',
        '#composer-text':    map['create'] || "What's on your mind?",
        '#chat-msg-input':   'Message...',
        '#comment-input':    map['comments'] || 'Add a comment...',
        '#msg-search-input': map['search'] || 'Search chats',
    };
    Object.keys(placeholders).forEach(function(sel) {
        var el = document.querySelector(sel);
        if (el) el.placeholder = placeholders[sel];
    });

    // Thought input language
    var thoughtInput = document.getElementById('thoughtInput');
    var thoughtPhrases = {
        ar: 'ما الذي تفكر فيه؟', fr: 'À quoi pensez-vous ?',
        es: '¿Qué estás pensando?', zu: 'Ucabangani?',
        pt: 'O que você está pensando?'
    };
    if (thoughtInput) thoughtInput.placeholder = thoughtPhrases[code] || 'What are you thinking?';

    // RTL layout
    var rtlTargets = '.post-header,.msg-row,.activity-item,.settings-row,.nav-container,.header-container';
    document.querySelectorAll(rtlTargets).forEach(function(el) {
        el.style.direction = isRTL ? 'rtl' : '';
    });

    // Update the back button direction for RTL
    document.querySelectorAll('.liquid-glass-btn').forEach(function(btn) {
        var icon = btn.querySelector('.fa-chevron-left');
        if (icon) icon.className = isRTL ? 'fa-solid fa-chevron-right' : 'fa-solid fa-chevron-left';
    });

    // Apply translations to all data-i18n elements
    document.querySelectorAll('[data-i18n]').forEach(function(el) {
        var key = el.getAttribute('data-i18n');
        if (map[key]) el.textContent = map[key];
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el) {
        var key = el.getAttribute('data-i18n-placeholder');
        if (map[key]) el.placeholder = map[key];
    });

    renderLanguages();
    triggerHaptic(15);
    // No toast: the whole interface changing language is its own confirmation.
    // Full-UI machine translation (the ~30-key dictionary above only covers a
    // few labels; this translates everything else via the server endpoint).
    if (code === 'en') { restoreDOMEnglish(); _tfSetTranslateObserver(false); }
    else { translateDOM(code); if ((localStorage.getItem('tf_auto_translate') || '1') !== '0') _tfSetTranslateObserver(true); }
}
// The toggle is hardcoded as "active" in the markup, so it always drew itself
// on no matter what was saved. Turning auto-translate off and coming back
// showed it on again, and the next tap just saved "off" a second time, which
// made the setting look broken. Draw it from the stored value instead.
function _tfAutoTranslateOn() {
    try { return (localStorage.getItem('tf_auto_translate') || '1') !== '0'; }
    catch (e) { return true; }
}
function _tfSyncTranslateToggle() {
    var el = document.getElementById('translate-toggle');
    if (el) el.classList.toggle('active', _tfAutoTranslateOn());
}

function toggleAutoTranslate(el) {
    el.classList.toggle('active');
    var on = el.classList.contains('active');
    try { localStorage.setItem('tf_auto_translate', on ? '1' : '0'); } catch (e) {}
    // Being switched on is not the same as having something to translate. With
    // the app in English this used to report "off" and drop the observer even
    // though the setting had just been saved as on, which read as the toggle
    // not working at all.
    if (on) {
        if (currentLanguage && currentLanguage !== 'en') {
            _tfSetTranslateObserver(true);
            translateDOM(currentLanguage);
            showToast('Auto-translate on');
        } else {
            showToast('Auto-translate on. Pick a language below to see it.');
        }
    } else {
        _tfSetTranslateObserver(false);
        showToast('Auto-translate off');
    }
    triggerHaptic(10);
}

// ── Whole-app machine translation ───────────────────────────────────────────
var _tfTransCache = (function(){ try { return JSON.parse(localStorage.getItem('tf_trans_cache') || '{}'); } catch (e) { return {}; } })();
window._tfTx = window._tfTx || [];
function _tfCollectTextNodes(root) {
    var out = [];
    try {
        var walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT, {
            acceptNode: function(node) {
                var v = node.nodeValue;
                if (!v || v.trim().length < 2 || !/[A-Za-z]/.test(v)) return NodeFilter.FILTER_REJECT;
                var p = node.parentElement;
                if (!p) return NodeFilter.FILTER_REJECT;
                var tag = p.tagName;
                if (tag === 'SCRIPT' || tag === 'STYLE' || tag === 'TEXTAREA' || tag === 'INPUT' || p.isContentEditable) return NodeFilter.FILTER_REJECT;
                if (p.closest('[data-no-translate],.tf-mention,.tf-hashtag,#tfMentionDropdown')) return NodeFilter.FILTER_REJECT;
                return NodeFilter.FILTER_ACCEPT;
            }
        });
        var n; while ((n = walker.nextNode())) out.push(n);
    } catch (e) {}
    return out;
}
function _tfApplyNode(node, orig, translated, lang) {
    var lead = (orig.match(/^\s*/) || [''])[0], trail = (orig.match(/\s*$/) || [''])[0];
    node.nodeValue = lead + translated + trail;
    node._tfLang = lang;
    if (window._tfTx.indexOf(node) < 0) window._tfTx.push(node);
}
async function translateDOM(lang) {
    if (!lang || lang === 'en') { restoreDOMEnglish(); return; }
    var root = document.getElementById('app') || document.body;
    var nodes = _tfCollectTextNodes(root).filter(function(n){ return n._tfLang !== lang; });
    if (!nodes.length) return;
    var pending = {};
    nodes.forEach(function(node) {
        var orig = node._tfOrig != null ? node._tfOrig : node.nodeValue;
        node._tfOrig = orig;
        var key = orig.trim();
        var ck = lang + '::' + key;
        if (_tfTransCache[ck]) { _tfApplyNode(node, orig, _tfTransCache[ck], lang); return; }
        (pending[key] = pending[key] || []).push(node);
    });
    var keys = Object.keys(pending);
    for (var i = 0; i < keys.length; i += 40) {
        var chunk = keys.slice(i, i + 40);
        try {
            var resp = await fetch('/api/translate-text/', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ q: chunk, target: lang }) });
            if (!resp.ok) continue;
            var data = await resp.json();
            var tr = data.t || [];
            chunk.forEach(function(key, j) {
                var translated = tr[j] || key;
                _tfTransCache[lang + '::' + key] = translated;
                (pending[key] || []).forEach(function(node) { _tfApplyNode(node, node._tfOrig, translated, lang); });
            });
            try { localStorage.setItem('tf_trans_cache', JSON.stringify(_tfTransCache)); } catch (e) {}
        } catch (e) {}
    }
}
function restoreDOMEnglish() {
    (window._tfTx || []).forEach(function(node) {
        if (node && node._tfOrig != null) { try { node.nodeValue = node._tfOrig; } catch (e) {} node._tfLang = 'en'; }
    });
}
var _tfObserver = null, _tfObsTimer = null;
function _tfSetTranslateObserver(on) {
    if (on) {
        if (_tfObserver) return;
        var root = document.getElementById('app') || document.body;
        _tfObserver = new MutationObserver(function() {
            if (currentLanguage === 'en') return;
            clearTimeout(_tfObsTimer);
            _tfObsTimer = setTimeout(function() { translateDOM(currentLanguage); }, 1200);
        });
        try { _tfObserver.observe(root, { childList: true, subtree: true }); } catch (e) {}
    } else if (_tfObserver) {
        _tfObserver.disconnect(); _tfObserver = null;
    }
}
// Re-apply a previously chosen language on load (was never applied on reload).
// The observer only comes back if auto-translate was actually left on: it used
// to be switched on unconditionally, quietly undoing the setting every reload.
(function _tfInitLanguage() {
    function go() {
        _tfSyncTranslateToggle();
        if (!currentLanguage || currentLanguage === 'en') return;
        try {
            translateDOM(currentLanguage);
            if (_tfAutoTranslateOn()) _tfSetTranslateObserver(true);
        } catch (e) {}
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', function(){ setTimeout(go, 900); });
    else setTimeout(go, 900);
})();

