// ==========================================================================
// LOCAL CIRCLES
// ==========================================================================
async function renderLocalCircles() {
    const content = document.getElementById('local-circles-content');
    if (!content) return;

    content.innerHTML = '<div style="text-align:center;padding:60px 20px;">' +
        '<i class="fa-solid fa-location-dot" style="font-size:40px;color:#007AFF;margin-bottom:15px;display:block;"></i>' +
        '<p style="color:#888;font-size:14px;">Getting your location...</p></div>';

    if (!navigator.geolocation) {
        content.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">Geolocation not supported on this device.</div>';
        return;
    }

    navigator.geolocation.getCurrentPosition(async function(pos) {
        const lat = pos.coords.latitude;
        const lng = pos.coords.longitude;
        const accuracy = Math.round(pos.coords.accuracy);

        // Save location for this user
        if (window.sb && currentUser) {
            await sb.from('users').update({
                last_lat: lat,
                last_lng: lng,
                last_location_updated: new Date().toISOString()
            }).eq('id', currentUser.id);
        }

        // Find nearby users (within ~50km using a simple bounding box)
        const R = 0.45; // ~50km in degrees
        let nearbyUsers = [];
        if (window.sb && currentUser) {
            const { data } = await sb.from('users')
                .select('id,full_name,username,avatar_url,badge_tier,verified,last_lat,last_lng')
                .neq('id', currentUser.id)
                .eq('verified', true)
                .gte('last_lat', lat - R)
                .lte('last_lat', lat + R)
                .gte('last_lng', lng - R)
                .lte('last_lng', lng + R)
                .not('last_lat', 'is', null)
                .limit(20);
            nearbyUsers = data || [];
        }

        // Calculate distances
        nearbyUsers = nearbyUsers.map(function(u) {
            const d = getDistanceKm(lat, lng, u.last_lat, u.last_lng);
            return Object.assign({}, u, { distanceKm: d });
        }).sort(function(a, b) { return a.distanceKm - b.distanceKm; });

        // Build UI — real map (initialised after the HTML is mounted)
        let html =
            '<div id="lcMap" style="height:220px;margin:15px 20px;border-radius:20px;overflow:hidden;position:relative;background:#1a1a2e;z-index:0;">' +
                '<div style="position:absolute;bottom:10px;right:12px;z-index:500;color:rgba(255,255,255,0.85);font-size:11px;background:rgba(0,0,0,0.45);padding:3px 8px;border-radius:10px;pointer-events:none;">±' + accuracy + 'm accuracy</div>' +
            '</div>';

        html += '<div style="padding:10px 20px;"><h4 style="margin-bottom:5px;color:var(--text-primary,#000);">Verified People Nearby</h4>' +
            '<small style="color:#888;">Only verified users appear here</small></div>';

        if (nearbyUsers.length === 0) {
            html += '<div style="text-align:center;padding:40px 20px;color:#888;">' +
                '<i class="fa-solid fa-user-slash" style="font-size:30px;color:#ccc;display:block;margin-bottom:12px;"></i>' +
                'No verified users found nearby yet</div>';
        } else {
            nearbyUsers.forEach(function(u) {
                const avatar = u.avatar_url || ('https://ui-avatars.com/api/?name=' + encodeURIComponent(u.full_name || 'U') + '&background=007AFF&color=fff');
                const dist = u.distanceKm < 1 ? Math.round(u.distanceKm * 1000) + 'm away' : u.distanceKm.toFixed(1) + ' km away';
                html += '<div class="local-user-card" onclick="viewUserProfile(\'' + u.id + '\')" style="cursor:pointer;">' +
                    '<img src="' + escapeHtml(avatar) + '" style="width:44px;height:44px;border-radius:50%;object-fit:cover;">' +
                    '<div style="flex:1;">' +
                        '<b>' + escapeHtml(u.full_name || u.username || 'User') + '</b>' +
                        (u.verified ? ' <i class="fa-solid fa-circle-check ' + (u.badge_tier || 'verify-blue') + '" style="font-size:10px;"></i>' : '') +
                        '<br><small style="color:#888;">@' + escapeHtml(u.username || '') + '</small>' +
                    '</div>' +
                    '<div class="distance-badge">' + dist + '</div>' +
                '</div>';
            });
        }

        content.innerHTML = html;

        // Real Leaflet map: your actual position + nearby verified users at their
        // real coordinates (was a fake radar with randomly-placed dots).
        if (window.L) {
            setTimeout(function() {
                try {
                    if (window._lcMap) { try { window._lcMap.remove(); } catch(e){} window._lcMap = null; }
                    var map = L.map('lcMap', { zoomControl: false, attributionControl: false }).setView([lat, lng], 13);
                    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { maxZoom: 19 }).addTo(map);
                    window._lcMap = map;
                    L.circle([lat, lng], { radius: (pos.coords.accuracy || 100), color: '#007AFF', weight: 1, fillColor: '#007AFF', fillOpacity: 0.08 }).addTo(map);
                    L.circleMarker([lat, lng], { radius: 9, color: '#fff', weight: 3, fillColor: '#007AFF', fillOpacity: 1 }).addTo(map).bindTooltip('You', { direction: 'top' });
                    nearbyUsers.forEach(function(u) {
                        if (u.last_lat == null || u.last_lng == null) return;
                        var m = L.circleMarker([u.last_lat, u.last_lng], { radius: 7, color: '#fff', weight: 2, fillColor: '#34C759', fillOpacity: 0.95 }).addTo(map);
                        m.bindTooltip((u.full_name || u.username || 'User'), { direction: 'top' });
                        m.on('click', function(){ if (typeof viewUserProfile === 'function') viewUserProfile(u.id); });
                    });
                    setTimeout(function(){ try { map.invalidateSize(); } catch(e){} }, 200);
                } catch (e) { console.warn('[LocalCircle map]', e); }
            }, 60);
        }

    }, function(err) {
        let msg = 'Location access denied.';
        if (err.code === 1) msg = 'Please allow location access in your browser settings.';
        else if (err.code === 2) msg = 'Location unavailable. Try again.';
        content.innerHTML = '<div style="text-align:center;padding:40px 20px;">' +
            '<i class="fa-solid fa-location-slash" style="font-size:40px;color:#FF3B30;display:block;margin-bottom:15px;"></i>' +
            '<p style="color:#888;font-size:14px;">' + msg + '</p>' +
            '<button onclick="renderLocalCircles()" style="margin-top:16px;padding:11px 24px;border-radius:25px;border:none;background:#007AFF;color:white;font-size:14px;font-weight:700;cursor:pointer;">Try Again</button>' +
            '</div>';
    }, { enableHighAccuracy: true, timeout: 10000, maximumAge: 60000 });
}

function getDistanceKm(lat1, lon1, lat2, lon2) {
    if (!lat2 || !lon2) return 999;
    const R = 6371;
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
              Math.sin(dLon/2) * Math.sin(dLon/2);
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
}

