// ---- Floating Picture-in-Picture for minimized video calls --------------
function _syncCallPip() {
    var st = document.getElementById('call-pip-status');
    if (st) {
        var ov = document.getElementById('call-overlay');
        var s = ov ? ov.getAttribute('data-state') : '';
        st.textContent = s === 'connected'
            ? (_callTimerSeconds > 0 ? (Math.floor(_callTimerSeconds / 60) + ':' + ((_callTimerSeconds % 60) < 10 ? '0' : '') + (_callTimerSeconds % 60)) : 'Connected')
            : (s === 'ringing' ? 'Ringing…' : 'Connecting…');
    }
    var vid = document.getElementById('call-pip-video');
    var fallback = document.getElementById('call-pip-fallback');
    if (vid && fallback) fallback.style.display = (vid.srcObject && vid.style.display !== 'none') ? 'none' : 'flex';
}
function _callPipMakeDraggable(el) {
    if (!el || el._dragBound) return;
    el._dragBound = true;
    var startX = 0, startY = 0, baseL = 0, baseT = 0, moved = false, dragging = false;
    function down(e) {
        if (e.target && e.target.closest && e.target.closest('[data-nodrag]')) return;
        dragging = true; moved = false;
        var p = e.touches ? e.touches[0] : e;
        startX = p.clientX; startY = p.clientY;
        var r = el.getBoundingClientRect();
        baseL = r.left; baseT = r.top;
        el.style.transition = 'none'; el.style.cursor = 'grabbing';
        document.addEventListener('mousemove', move); document.addEventListener('mouseup', up);
        document.addEventListener('touchmove', move, { passive: false }); document.addEventListener('touchend', up);
    }
    function move(e) {
        if (!dragging) return;
        var p = e.touches ? e.touches[0] : e;
        var dx = p.clientX - startX, dy = p.clientY - startY;
        if (Math.abs(dx) > 5 || Math.abs(dy) > 5) moved = true;
        if (e.cancelable) e.preventDefault();
        var w = el.offsetWidth, h = el.offsetHeight;
        var nl = Math.min(Math.max(6, baseL + dx), window.innerWidth - w - 6);
        var nt = Math.min(Math.max(44, baseT + dy), window.innerHeight - h - 6);
        el.style.left = nl + 'px'; el.style.top = nt + 'px'; el.style.right = 'auto'; el.style.bottom = 'auto';
    }
    function up() {
        dragging = false; el.style.cursor = 'grab';
        document.removeEventListener('mousemove', move); document.removeEventListener('mouseup', up);
        document.removeEventListener('touchmove', move); document.removeEventListener('touchend', up);
        if (!moved) maximizeCall();
    }
    el.addEventListener('mousedown', down);
    el.addEventListener('touchstart', down, { passive: true });
}

// ===== MINI-PLAYER STATE =====
var _miniLiveMode = null; // 'creator' | 'viewer'

function minimizeLive() {
    var overlay = document.getElementById('live-overlay');
    if (overlay) overlay.style.display = 'none';
    _miniLiveMode = 'creator';
    var title = (document.getElementById('liveTitle') && document.getElementById('liveTitle').value) || 'Live Stream';
    var viewers = document.getElementById('live-viewer-count') ? document.getElementById('live-viewer-count').textContent : '0';
    var avatar = (currentUser && currentUser.avatar_url) ? currentUser.avatar_url : ('https://ui-avatars.com/api/?name='+(currentUser ? encodeURIComponent(currentUser.full_name||'Me') : 'Me')+'&background=007AFF&color=fff&size=80');
    _showMiniPlayer(title, viewers, avatar);
}

function minimizeViewerLive() {
    var overlay = document.getElementById('live-viewer-overlay');
    if (overlay) overlay.style.display = 'none';
    _miniLiveMode = 'viewer';
    var title = document.getElementById('viewer-streamer-name') ? document.getElementById('viewer-streamer-name').textContent : 'Live Stream';
    var viewers = document.getElementById('viewer-live-count') ? document.getElementById('viewer-live-count').textContent : '0';
    var avatar = document.getElementById('viewer-streamer-avatar') ? document.getElementById('viewer-streamer-avatar').src : '';
    _showMiniPlayer(title, viewers, avatar);
}

function _showMiniPlayer(title, viewers, avatar) {
    var mp = document.getElementById('liveMiniPlayer');
    if (!mp) return;
    var a1 = document.getElementById('miniLiveAvatar1');
    var a2 = document.getElementById('miniLiveAvatar2');
    var t = document.getElementById('miniLiveTitle');
    var v = document.getElementById('miniLiveViewers');
    if (a1) a1.src = avatar;
    if (t) t.textContent = title;
    if (v) v.textContent = '+' + viewers;
    mp.style.display = 'block';
    mp.style.animation = 'slideUpOverlay 0.3s cubic-bezier(0.32,0.72,0,1)';
    // Keep live nav bar visible while mini-player shows
    var nav = document.querySelector('.nav-container');
    if (nav) nav.style.display = 'flex';
}

function maximizeLive() {
    var mp = document.getElementById('liveMiniPlayer');
    if (mp) mp.style.display = 'none';
    if (_miniLiveMode === 'creator') {
        var overlay = document.getElementById('live-overlay');
        if (overlay) overlay.style.display = 'block';
    } else if (_miniLiveMode === 'viewer') {
        var overlay = document.getElementById('live-viewer-overlay');
        if (overlay) overlay.style.display = 'block';
    }
    _miniLiveMode = null;
}

function closeMiniLive(e) {
    if (e) e.stopPropagation();
    var mp = document.getElementById('liveMiniPlayer');
    if (mp) mp.style.display = 'none';
    if (_miniLiveMode === 'creator') {
        endLive();
    } else if (_miniLiveMode === 'viewer') {
        closeViewerLive();
    }
    _miniLiveMode = null;
}

