function toggleLiveCamera() {
    facingMode = facingMode === 'user' ? 'environment' : 'user';
    if (liveStream) liveStream.getTracks().forEach(t => t.stop());
    navigator.mediaDevices.getUserMedia({ video: { facingMode }, audio: true }).then(stream => {
        liveStream = stream;
        document.getElementById('live-preview').srcObject = stream;
    });
}

function toggleLiveMic() {
    if (!liveStream) return;
    const audioTrack = liveStream.getAudioTracks()[0];
    if (audioTrack) {
        audioTrack.enabled = !audioTrack.enabled;
        triggerHaptic(10);
    }
}

function sendLiveComment() {
    const input = document.getElementById('live-chat-input');
    const text = input.value.trim();
    if (!text) return;
    input.value = '';
    // Saved + broadcast so viewers actually see the host's messages.
    liveChatSend(text);
}

