function ctv_react(btn, emoji) {
    btn.style.background = 'rgba(0,122,255,0.25)';
    btn.style.transform = 'scale(1.3)';
    setTimeout(function(){ btn.style.transform = 'scale(1)'; }, 200);
    triggerHaptic(20);
}

function ctv_heart(btn) {
    var icon = btn.querySelector('i');
    if (icon.classList.contains('fa-regular')) {
        icon.classList.replace('fa-regular','fa-solid');
        btn.style.background = 'rgba(255,59,48,0.35)';
        triggerHaptic(30);
    } else {
        icon.classList.replace('fa-solid','fa-regular');
        btn.style.background = 'rgba(255,59,48,0.15)';
    }
}

// ==========================================================================
//
// ==========================================================================
// Reels are muted by default (browsers block sound on autoplay). Tapping the
// speaker button flips this for every reel; the choice sticks across reels.
if (typeof window._reelsMuted === 'undefined') window._reelsMuted = true;

// Tap a reel to toggle play/pause and flash the matching icon. A pause icon
// stays visible while paused; a play icon flashes briefly when resuming.
function reelTogglePlay(video) {
    if (!video) return;
    var page = video.closest('.reel-page');
    var ind = page ? page.querySelector('.reel-play-indicator') : null;
    var icon = ind ? ind.querySelector('i') : null;
    if (video.paused) {
        video.muted = window._reelsMuted;
        video.play().catch(function(){});
        if (ind && icon) {
            icon.className = 'fa-solid fa-play'; icon.style.marginLeft = '4px';
            ind.style.opacity = '1';
            clearTimeout(ind._hideT);
            ind._hideT = setTimeout(function(){ ind.style.opacity = '0'; }, 500);
        }
    } else {
        video.pause();
        if (ind && icon) {
            clearTimeout(ind._hideT);
            icon.className = 'fa-solid fa-pause'; icon.style.marginLeft = '0';
            ind.style.opacity = '1';
        }
    }
    if (typeof triggerHaptic === 'function') triggerHaptic(10);
}

// Heart button on a reel (initReels): toggle like + persist to the likes table.
function reelHeartTap(el, postId) {
    var icon = el.querySelector('i');
    var span = el.querySelector('span');
    if (!icon) return;
    var liked = icon.classList.contains('fa-solid');
    var n = span ? (parseInt((span.textContent || '0').replace(/[^\d]/g, '')) || 0) : 0;
    if (liked) {
        icon.classList.replace('fa-solid', 'fa-regular'); icon.style.color = '';
        if (span) span.textContent = Math.max(0, n - 1);
        if (postId && window.sb && currentUser) sb.from('likes').delete().eq('user_id', currentUser.id).eq('post_id', postId).then(function(){}).catch(function(){});
    } else {
        icon.classList.replace('fa-regular', 'fa-solid'); icon.style.color = '#FF3B30';
        if (span) span.textContent = n + 1;
        if (postId && window.sb && currentUser) { sb.from('likes').insert({ user_id: currentUser.id, post_id: postId }).then(function(){}).catch(function(){}); tfNotifyLike(postId); }
    }
    if (typeof triggerHaptic === 'function') triggerHaptic(20);
}

// Speaker button: unmute/mute every reel and play the current one with sound.
function toggleReelMute(btn) {
    var wasMuted = (window._reelsMuted !== false);
    window._reelsMuted = !window._reelsMuted;
    var scroller = document.getElementById('reel-scroller');
    (scroller ? scroller.querySelectorAll('video.reel-video') : []).forEach(function(v) {
        v.muted = window._reelsMuted;
    });
    document.querySelectorAll('.reel-mute-btn i').forEach(function(i) {
        i.className = window._reelsMuted ? 'fa-solid fa-volume-xmark' : 'fa-solid fa-volume-high';
    });
    if (typeof triggerHaptic === 'function') triggerHaptic(15);
    // Just unmuted? A browser can't read the phone's hardware volume slider (no
    // web API exists, and iOS makes video.volume read-only), so we can't auto-
    // detect a silent device. Instead we nudge: a pill slides out of the icon
    // reminding them to turn their device volume up, then tucks back in.
    if (wasMuted && window._reelsMuted === false) showReelVolumePill(btn);
}

// The nudge pill. Slides out from behind the reel speaker icon, holds a beat,
// then retracts into it. Purely a hint — see the note in toggleReelMute for why
// we can't gate this on the actual device volume.
function showReelVolumePill(btn) {
    if (!btn) return;
    var host = btn.parentNode; if (!host) return;
    var prev = host.querySelector('.reel-vol-pill'); if (prev) { clearTimeout(prev._t); prev.remove(); }
    var pill = document.createElement('div');
    pill.className = 'reel-vol-pill';
    pill.style.cssText =
        'position:absolute;top:max(54px,env(safe-area-inset-top,54px));right:14px;height:38px;' +
        'display:flex;align-items:center;max-width:0;overflow:hidden;white-space:nowrap;' +
        'background:rgba(0,0,0,0.6);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);' +
        'color:#fff;border-radius:19px;z-index:29;pointer-events:none;' +
        'transition:max-width 0.4s cubic-bezier(0.32,0.72,0,1);';
    // Right padding clears the round button that sits on top of the pill's tail.
    pill.innerHTML =
        '<span style="padding:0 48px 0 16px;display:inline-flex;align-items:center;gap:7px;font-size:12.5px;font-weight:600;">' +
            '<i class="fa-solid fa-volume-high" style="font-size:12px;"></i>Turn up your device volume</span>';
    host.appendChild(pill);
    requestAnimationFrame(function () { pill.style.maxWidth = '280px'; });
    pill._t = setTimeout(function () {
        pill.style.maxWidth = '0';
        setTimeout(function () { if (pill.parentNode) pill.remove(); }, 450);
    }, 2000);
}

// Attach an invisible slide-to-scrub progress bar to a reel video. The bar
// sits at the bottom of the reel (above the sound-hub pill), stays thin while
// the video plays, and expands when the user drags it to forward/rewind.
function wireReelScrub(video) {
    if (!video) return;
    var page = video.closest('.reel-page');
    if (!page || page.querySelector('.reel-scrub')) return;
    var bar = document.createElement('div');
    bar.className = 'reel-scrub';
    bar.style.cssText = 'position:absolute;left:0;right:0;bottom:0;height:24px;z-index:40;display:flex;align-items:flex-end;padding:0 10px 6px;touch-action:none;cursor:pointer;';
    bar.innerHTML =
        '<div class="reel-scrub-track" style="position:relative;width:100%;height:3px;border-radius:3px;background:rgba(255,255,255,0.25);transition:height 0.15s,background 0.15s;">' +
            '<div class="reel-scrub-fill" style="position:absolute;left:0;top:0;bottom:0;width:0%;background:#fff;border-radius:3px;"></div>' +
            '<div class="reel-scrub-knob" style="position:absolute;top:50%;left:0%;width:13px;height:13px;border-radius:50%;background:#fff;transform:translate(-50%,-50%);opacity:0;transition:opacity 0.15s;box-shadow:0 1px 5px rgba(0,0,0,0.5);"></div>' +
        '</div>';
    page.appendChild(bar);
    var track = bar.querySelector('.reel-scrub-track');
    var fill = bar.querySelector('.reel-scrub-fill');
    var knob = bar.querySelector('.reel-scrub-knob');
    var scrubbing = false;

    video.addEventListener('timeupdate', function() {
        if (scrubbing || !video.duration) return;
        var p = (video.currentTime / video.duration) * 100;
        fill.style.width = p + '%';
        knob.style.left = p + '%';
    });

    function seekTo(clientX) {
        var r = track.getBoundingClientRect();
        var p = Math.max(0, Math.min(1, (clientX - r.left) / r.width));
        if (video.duration) video.currentTime = p * video.duration;
        fill.style.width = (p * 100) + '%';
        knob.style.left = (p * 100) + '%';
    }
    function expand() { track.style.height = '6px'; track.style.background = 'rgba(255,255,255,0.5)'; knob.style.opacity = '1'; }
    function collapse() { track.style.height = '3px'; track.style.background = 'rgba(255,255,255,0.25)'; knob.style.opacity = '0'; }

    bar.addEventListener('pointerdown', function(e) { scrubbing = true; expand(); seekTo(e.clientX); try { bar.setPointerCapture(e.pointerId); } catch(_){} e.stopPropagation(); });
    bar.addEventListener('pointermove', function(e) { if (scrubbing) { seekTo(e.clientX); e.stopPropagation(); } });
    bar.addEventListener('pointerup', function(e) { if (scrubbing) { scrubbing = false; collapse(); e.stopPropagation(); } });
    bar.addEventListener('pointercancel', function() { scrubbing = false; collapse(); });
}

// TrustClip pinch-to-zoom. Two fingers scale the video; every overlay fades so
// the clip fills the frame cleanly, then springs back when you lift a finger.
// Delegated on the scroller so it survives reel re-renders and binds only once.
function setupReelPinchZoom() {
    var scroller = document.getElementById('reel-scroller');
    if (!scroller || scroller._pinchHooked) return;
    scroller._pinchHooked = true;
    var pinching = false, d0 = 0, vid = null, tools = [];
    function dist(e) { var dx = e.touches[0].clientX - e.touches[1].clientX, dy = e.touches[0].clientY - e.touches[1].clientY; return Math.hypot(dx, dy); }
    function fade(v) { tools.forEach(function (el) { el.style.transition = 'opacity 0.2s'; el.style.opacity = v; }); }
    scroller.addEventListener('touchstart', function (e) {
        if (e.touches.length !== 2) return;
        var page = e.target.closest('.reel-page'); if (!page) return;
        vid = page.querySelector('.reel-video'); if (!vid) return;
        tools = [];
        page.querySelectorAll('.reel-ui, .reel-mute-btn, .reel-scrub').forEach(function (el) { tools.push(el); });
        pinching = true; d0 = dist(e) || 1;
        vid.style.transition = 'none';
        e.preventDefault();
    }, { passive: false });
    scroller.addEventListener('touchmove', function (e) {
        if (!pinching || e.touches.length !== 2 || !vid) return;
        var scale = Math.min(Math.max(dist(e) / d0, 1), 3);
        vid.style.transformOrigin = 'center center';
        vid.style.transform = 'scale(' + scale + ')';
        fade(Math.max(0, 1 - (scale - 1) * 1.4));
        e.preventDefault();
    }, { passive: false });
    function release() {
        if (!pinching) return;
        pinching = false;
        if (vid) { vid.style.transition = 'transform 0.3s cubic-bezier(0.32,0.72,0,1)'; vid.style.transform = 'scale(1)'; }
        fade(1);
        vid = null; tools = [];
    }
    scroller.addEventListener('touchend', function (e) { if (e.touches.length < 2) release(); }, { passive: false });
    scroller.addEventListener('touchcancel', release, { passive: false });
}

async function initReels() {
    const c = document.getElementById('reel-scroller');
    setupReelPinchZoom();   // idempotent; binds pinch/zoom once per scroller
    if (c.children.length > 0) c.innerHTML = ''; // force refresh
    try {
        // Video posts store the file in media_url with media_type='video'
        // (video_url is a legacy/unused column that stays null). Select only
        // columns that exist and match on media_type, falling back to a
        // join-less retry if the users relationship errors.
        var reelResp = await window.sb.from('posts')
            .select('id, media_url, video_url, thumbnail_url, user_id, like_count, comment_count, view_count, text_content, users:user_id(username, avatar_url, id_verified)')
            .or('media_type.eq.video,post_type.eq.trustclip,post_type.eq.video')
            .neq('is_hidden', true)
            .not('media_url', 'is', null)
            .order('created_at', { ascending: false })
            .limit(20);

        if (reelResp.error) {
            console.warn('[initReels] query failed, retrying without users join:', reelResp.error.message);
            reelResp = await window.sb.from('posts')
                .select('id, media_url, video_url, thumbnail_url, user_id, like_count, comment_count, view_count, text_content')
                .or('media_type.eq.video,post_type.eq.trustclip,post_type.eq.video')
                .neq('is_hidden', true)
                .not('media_url', 'is', null)
                .order('created_at', { ascending: false })
                .limit(20);
        }

        var reels = (reelResp.data || []);
        if (reels.length === 0) {
            c.innerHTML = '<div style="color:rgba(255,255,255,0.4);text-align:center;padding:40px;font-size:14px;">No reels yet. Be the first to post!</div>';
            return;
        }

        // Which reel authors have an active (last 24h) story? Only those get the
        // blue story ring on their avatar (tapping it opens their story).
        var _storyAuthors = {};
        try {
            var _authorIds = reels.map(function(p) { return p.user_id; }).filter(Boolean);
            if (_authorIds.length) {
                var _since = new Date(Date.now() - 86400000).toISOString();
                var _sres = await window.sb.from('stories').select('user_id').in('user_id', _authorIds).gte('created_at', _since);
                (_sres.data || []).forEach(function(r) { _storyAuthors[r.user_id] = true; });
            }
        } catch(e) { /* no story ring if the lookup fails */ }

        reels.forEach(function(post) {
            var profile = post.users || {};
            var username = profile.username || 'user';
            var avatar = profile.avatar_url || ('https://ui-avatars.com/api/?name=' + encodeURIComponent(username) + '&background=007AFF&color=fff&size=80');
            var likes = post.like_count > 999 ? (post.like_count/1000).toFixed(1)+'K' : (post.like_count || 0);
            var verified = profile.id_verified ? '<i class="fa-solid fa-circle-check verify-blue" style="font-size:12px;"></i>' : '';
            var hasStory = !!_storyAuthors[post.user_id];
            var avatarHtml = hasStory
                ? '<div onclick="openStoryViewer(\'' + post.user_id + '\')" style="width:42px;height:42px;border-radius:50%;padding:2.5px;background:linear-gradient(135deg,#007AFF,#00C7FF);flex-shrink:0;cursor:pointer;" title="View story">' +
                      '<img src="' + avatar + '" style="width:100%;height:100%;border-radius:50%;border:2px solid #000;object-fit:cover;display:block;">' +
                  '</div>'
                : '<img onclick="openProfile(\'' + post.user_id + '\')" src="' + avatar + '" style="width:38px;height:38px;border-radius:50%;object-fit:cover;flex-shrink:0;cursor:pointer;border:1.5px solid rgba(255,255,255,0.45);">';
            c.innerHTML += `
            <div class="reel-page" data-post-id="${post.id}">
                <video src="${post.media_url || post.video_url}" class="reel-video" autoplay muted loop playsinline preload="auto" style="width:100%;height:100%;object-fit:cover;opacity:1;" onclick="reelTogglePlay(this)"></video>
                <div class="reel-play-indicator" style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:82px;height:82px;border-radius:50%;background:rgba(0,0,0,0.42);display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity 0.2s;pointer-events:none;z-index:25;"><i class="fa-solid fa-play" style="color:#fff;font-size:32px;margin-left:4px;"></i></div>
                <button class="reel-mute-btn" onclick="toggleReelMute(this)" style="position:absolute;top:max(54px,env(safe-area-inset-top,54px));right:14px;width:38px;height:38px;border-radius:50%;background:rgba(0,0,0,0.5);border:none;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:30;"><i class="fa-solid fa-volume-xmark" style="color:#fff;font-size:15px;"></i></button>
                <div class="reel-ui">
                    <div style="flex:1;min-width:0;padding-right:8px;">
                        <div style="display:flex; align-items:center; gap:9px; margin-bottom:9px;">
                            ${avatarHtml}
                            <b style="font-weight:800;font-size:15px;cursor:pointer;" onclick="openProfile('${post.user_id}')">@${username}</b>
                            ${verified}
                            ${(currentUser && post.user_id === currentUser.id) ? '' : '<button class="follow-btn" onclick="toggleReelFollow(this)">Follow</button>'}
                        </div>
                        <p style="margin:0 0 10px; font-size:14px; line-height:1.35; max-width:88%;">${escapeHtml(post.text_content || '')}</p>
                        <div class="sound-ticker" onclick="openSoundHub('Original Sound','${post.media_url || post.video_url}')">
                            <i class="fa-solid fa-music"></i>
                            <span style="max-width:150px; overflow:hidden; white-space:nowrap; text-overflow:ellipsis; display:inline-block;">Original Sound</span>
                        </div>
                    </div>
                    <div class="reel-sidebar">
                        <div class="reel-action" onclick="reelHeartTap(this,'${post.id}')"><i class="fa-regular fa-heart"></i><br><span onclick="event.stopPropagation();openReelLikesModal('${post.id}','${likes}','${post.view_count||0}')" style="cursor:pointer;">${likes}</span></div>
                        <div class="reel-action" onclick="openComments('${post.id}')"><i class="fa-solid fa-comment-dots"></i><br>${post.comment_count || 0}</div>
                        <div class="reel-action" onclick="openShare()"><i class="fa-solid fa-share"></i><br>Share</div>
                        <div class="reel-action" onclick="toggleReelBookmark(this,'${post.id}')"><i class="fa-regular fa-bookmark"></i><br>Save</div>
                    </div>
                </div>
            </div>`;
        });
    } catch(e) {
        c.innerHTML = '<div style="color:rgba(255,255,255,0.4);text-align:center;padding:40px;font-size:14px;">Could not load clips.</div>';
    }
    // Prepend locally posted clips
    try {
        var localClips = JSON.parse(localStorage.getItem('tf-trust-clips') || '[]');
        localClips.forEach(function(clip) {
            var src = clip.videoSrc || '';
            if (!src) return;
            var div = document.createElement('div');
            div.className = 'reel-page';
            div.innerHTML = '<video src="'+escapeHtml(src)+'" class="reel-video" autoplay muted loop playsinline preload="auto" style="width:100%;height:100%;object-fit:cover;" onclick="reelTogglePlay(this)"></video>' +
                '<div class="reel-play-indicator" style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:82px;height:82px;border-radius:50%;background:rgba(0,0,0,0.42);display:flex;align-items:center;justify-content:center;opacity:0;transition:opacity 0.2s;pointer-events:none;z-index:25;"><i class="fa-solid fa-play" style="color:#fff;font-size:32px;margin-left:4px;"></i></div>' +
                '<button class="reel-mute-btn" onclick="toggleReelMute(this)" style="position:absolute;top:max(54px,env(safe-area-inset-top,54px));right:14px;width:38px;height:38px;border-radius:50%;background:rgba(0,0,0,0.5);border:none;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:30;"><i class="fa-solid fa-volume-xmark" style="color:#fff;font-size:15px;"></i></button>' +
                '<div class="reel-ui"><div><div style="display:flex;align-items:center;gap:10px;margin-bottom:8px;">' +
                '<b style="font-weight:900;">You</b></div>' +
                '<p style="margin:8px 0;font-size:14px;">'+escapeHtml(clip.caption||'')+'</p></div>' +
                '<div class="reel-sidebar"><div class="reel-action"><i class="fa-regular fa-heart"></i><br><span>0</span></div></div></div>';
            c.insertBefore(div, c.firstChild);
        });
    } catch(e) {}

    // Guaranteed long-press → context menu (the other gesture setup is gated
    // behind a flag and could be skipped, so bind an independent one here).
    setTimeout(function() {
        var sc = document.getElementById('reel-scroller');
        if (!sc || sc._lpMenu2) return;
        sc._lpMenu2 = true;
        var lt = null, lx = 0, ly = 0;
        sc.addEventListener('touchstart', function(e) {
            if (e.touches.length > 1) return;
            var t = e.touches[0]; lx = t.clientX; ly = t.clientY;
            var pg = e.target.closest('.reel-page');
            if (!pg || e.target.closest('button,a,.reel-action,.reel-sidebar,input,textarea')) return;
            clearTimeout(lt);
            lt = setTimeout(function() { lt = null; if (typeof openReelLongPressMenu === 'function') openReelLongPressMenu(pg); triggerHaptic(30); }, 480);
        }, { passive: true });
        sc.addEventListener('touchmove', function(e) { var t = e.touches[0]; if (t && (Math.abs(t.clientX - lx) > 12 || Math.abs(t.clientY - ly) > 12)) { clearTimeout(lt); lt = null; } }, { passive: true });
        sc.addEventListener('touchend', function() { clearTimeout(lt); lt = null; }, { passive: true });
        sc.addEventListener('touchcancel', function() { clearTimeout(lt); lt = null; }, { passive: true });
    }, 350);

    // Auto-play video when it enters viewport
    // Replace the setTimeout autoplay block at the bottom of initReels:
setTimeout(function() {
    var scroller = document.getElementById('reel-scroller');
    if (!scroller) return;
    var videos = scroller.querySelectorAll('video.reel-video');

    // Attach the slide-to-scrub progress bar to every reel
    videos.forEach(function(v) { wireReelScrub(v); });

    // Preload first video aggressively
    if (videos[0]) { videos[0].preload = 'auto'; videos[0].play().catch(function(){}); }

    if (window.IntersectionObserver) {
        var io = new IntersectionObserver(function(entries) {
            entries.forEach(function(entry) {
                var vid = entry.target;
                if (entry.isIntersecting) {
                    vid.currentTime = 0;
                    vid.muted = window._reelsMuted;
                    var p = vid.play();
                    if (p) p.catch(function(){});
                    // Clear any leftover pause icon from a previous reel
                    var _pg = vid.closest('.reel-page');
                    var _ind = _pg ? _pg.querySelector('.reel-play-indicator') : null;
                    if (_ind) _ind.style.opacity = '0';
                } else {
                    vid.pause();
                    // Reset so next view starts fresh
                    vid.currentTime = 0;
                }
            });
        }, { threshold: 0.75, rootMargin: '0px' });
        videos.forEach(function(v) {
            v.preload = 'auto';
            io.observe(v);
        });
    }

    // Scroll-snap smoother on mobile
    scroller.style.scrollSnapType = 'y mandatory';
    scroller.style.webkitOverflowScrolling = 'touch';

    // Preload next video when current plays
    scroller.addEventListener('scroll', function() {
        var vids = scroller.querySelectorAll('video.reel-video');
        var scrollPct = scroller.scrollTop / scroller.scrollHeight;
        var idx = Math.floor(scrollPct * vids.length);
        if (vids[idx+1]) { vids[idx+1].preload = 'auto'; vids[idx+1].load(); }
        if (vids[idx+2]) { vids[idx+2].preload = 'auto'; vids[idx+2].load(); }
        if (vids[idx+3]) { vids[idx+3].preload = 'auto'; vids[idx+3].load(); }
        if (vids[idx+4]) { vids[idx+4].preload = 'auto'; vids[idx+4].load(); }
    }, { passive: true });
}, 400);

    // Double tap to like on reels
    setTimeout(function() {
        var scroller = document.getElementById('reel-scroller');
        if (!scroller || scroller._dblPatched) return;
        scroller._dblPatched = true;

        var lastTap = 0, lastX = 0, lastY = 0, multiTouch = false;
        scroller.addEventListener('touchstart', function(e) { if (e.touches.length > 1) multiTouch = true; }, { passive: true });
        scroller.addEventListener('touchend', function(e) {
            // Ignore pinch/zoom (multi-touch) and gestures with fingers still down.
            if (multiTouch || e.touches.length > 0 || e.changedTouches.length !== 1) { multiTouch = false; return; }
            var t = e.changedTouches[0];
            var now = Date.now();
            var dx = Math.abs(t.clientX - lastX), dy = Math.abs(t.clientY - lastY);
            if (now - lastTap < 300 && dx < 40 && dy < 40) {
                var page = e.target.closest('.reel-page');
                if (!page) { lastTap = 0; return; }
                e.preventDefault();

                // Heart burst
                var heart = document.createElement('div');
                heart.style.cssText = 'position:absolute;top:50%;left:50%;transform:translate(-50%,-50%) scale(0);font-size:90px;pointer-events:none;z-index:200;opacity:1;transition:none;filter:drop-shadow(0 4px 20px rgba(255,59,48,0.5));';
                heart.textContent = '❤️';
                page.appendChild(heart);
                requestAnimationFrame(function() {
                    heart.style.transition = 'transform 0.7s cubic-bezier(0.175,0.885,0.32,1.275), opacity 0.5s ease 0.3s';
                    heart.style.transform = 'translate(-50%,-50%) scale(1.3)';
                    heart.style.opacity = '0';
                });
                setTimeout(function() { heart.remove(); }, 800);

                // Like the reel (single, real like — persisted, no fake inflation)
                var likeAction = page.querySelector('.reel-action');
                var pid = page.getAttribute('data-post-id');
                if (likeAction) {
                    var icon = likeAction.querySelector('i');
                    var span = likeAction.querySelector('span');
                    if (icon && icon.classList.contains('fa-regular')) {
                        icon.classList.replace('fa-regular', 'fa-solid');
                        icon.style.color = '#FF3B30';
                        if (span) { var n = parseInt((span.textContent || '0').replace(/[^\d]/g,'')) || 0; span.textContent = (n + 1); }
                        if (pid && window.sb && currentUser) {
                            sb.from('likes').insert({ user_id: currentUser.id, post_id: pid }).then(function(){}).catch(function(){});
                            tfNotifyLike(pid);
                        }
                    }
                }
                triggerHaptic(40);
                lastTap = 0;
            } else {
                lastTap = now; lastX = t.clientX; lastY = t.clientY;
            }
        }, { passive: false });

        // Long-press on a reel → context menu (Save / Share / Not interested / Report)
        if (!scroller._lpReelPatched) {
            scroller._lpReelPatched = true;
            var rlpTimer = null, rlpX = 0, rlpY = 0;
            scroller.addEventListener('touchstart', function(e) {
                if (e.touches.length > 1) return;
                var t = e.touches[0]; rlpX = t.clientX; rlpY = t.clientY;
                var page = e.target.closest('.reel-page');
                if (!page) return;
                clearTimeout(rlpTimer);
                rlpTimer = setTimeout(function() { rlpTimer = null; openReelLongPressMenu(page); }, 450);
            }, { passive: true });
            scroller.addEventListener('touchmove', function(e) {
                var t = e.touches[0];
                if (t && (Math.abs(t.clientX - rlpX) > 12 || Math.abs(t.clientY - rlpY) > 12)) { clearTimeout(rlpTimer); rlpTimer = null; }
            }, { passive: true });
            scroller.addEventListener('touchend', function() { clearTimeout(rlpTimer); rlpTimer = null; }, { passive: true });
            scroller.addEventListener('touchcancel', function() { clearTimeout(rlpTimer); rlpTimer = null; }, { passive: true });
        }
    }, 300);
}



function toggleReelBookmark(el) {
    const icon = el.querySelector('i');
    icon.classList.toggle('fa-regular');
    icon.classList.toggle('fa-solid');
    icon.style.color = icon.classList.contains('fa-solid') ? '#007AFF' : '';
    triggerHaptic(15);
}


