// ==========================================================================
// REALTIME SUBSCRIPTIONS
// ==========================================================================
function initRealtimeSubscriptions() {
    if (!window.sb) return;

    // Listen for new messages + receipt updates (delivered_at/read_at) in real-time
    sb.channel('messages')
        .on('postgres_changes', {
            event: 'INSERT',
            schema: 'public',
            table: 'messages'
        }, (payload) => {
            handleNewMessage(payload.new);
        })
        .on('postgres_changes', {
            event: 'UPDATE',
            schema: 'public',
            table: 'messages'
        }, (payload) => {
            handleMessageUpdate(payload.new);
        })
        .subscribe();

    // I'm online now — mark everything addressed to me as delivered (covers
    // messages that arrived while I was offline, so senders get their 2nd tick).
    try { sb.rpc('mark_all_delivered', {}).then(function(){}, function(){}); } catch (e) {}

    // Listen for screenshot events
    sb.channel('screenshots')
        .on('postgres_changes', {
            event: 'INSERT',
            schema: 'public',
            table: 'screenshot_events'
        }, (payload) => {
            handleScreenshotNotification(payload.new);
        })
        .subscribe();

    // Listen for profile views
    sb.channel('profile_views')
        .on('postgres_changes', {
            event: 'INSERT',
            schema: 'public',
            table: 'profile_views'
        }, (payload) => {
            handleProfileViewNotification(payload.new);
        })
        .subscribe();

    console.debug('[Realtime] Subscriptions active');
}

function handleNewMessage(message) {
    console.debug('[handleNewMessage] Received message:', message);

    // Don't double-render your own messages — already shown as temp bubble
    if (currentUser && message.sender_id === currentUser.id) {
        console.debug('[handleNewMessage] Own message, skipping realtime render');
        return;
    }

    // I'm online and just received this → receipt. If I'm looking at that chat
    // it's read; otherwise it's (at least) delivered to my device.
    if (message.conversation_id) {
        var _ci = document.getElementById('chat-interface');
        if (currentConversationId === message.conversation_id && _ci && _ci.style.display === 'block') {
            _markChatRead(message.conversation_id);
        } else {
            _markChatDelivered(message.conversation_id);
        }
    }

    if (!currentChatUser || document.getElementById('chat-interface').style.display !== 'block') {
        console.debug('[handleNewMessage] Chat not open, skipping');
        return;
    }

    function _appendToChat(text) {
        var chatBody = document.getElementById('chat-body');
        if (chatBody) {
            var msgObj = Object.assign({}, message, { content: text });
            chatBody.insertAdjacentHTML('beforeend', renderMessageBubble(msgObj));
            chatBody.scrollTop = chatBody.scrollHeight;
        }
    }

    // If no nonce, message is plain text — skip E2E
    if (!message.nonce) {
        console.debug('[handleNewMessage] No nonce, treating as plain text');
        _appendToChat(message.ciphertext || '');
        return;
    }

    E2E.decryptMessage(message.ciphertext, message.nonce, message.sender_id)
        .then(function(plaintext) {
            console.debug('[handleNewMessage] Decrypted OK, appending to chat');
            _appendToChat(plaintext);
        })
        .catch(function(err) {
            console.error('[handleNewMessage] E2E decrypt failed:', err, '| raw message:', message);
        });
}

async function handleScreenshotNotification(event) {
    try {
        const { data: { session } } = await sb.auth.getSession();
        if (!session || event.user_id === session.user.id) return;

        const toast = document.createElement('div');
        toast.className = 'screenshot-toast';
        toast.innerHTML = `<i class="fa-solid fa-camera"></i> Someone took a ${event.event_type === 'screenshot' ? 'screenshot' : 'screen recording'}!`;
        document.getElementById('app').appendChild(toast);
        triggerHaptic(50);
        setTimeout(() => toast.remove(), 4000);
    } catch (e) {
        console.error('[Screenshot]', e);
    }
}

function handleProfileViewNotification(view) {
    // Could show a subtle notification
    console.debug('[ProfileView] Someone viewed your profile');
}

// ==========================================================================
// HYBRID DATA LAYER — Uses local DB + syncs to Supabase when available
// ==========================================================================
const DataLayer = {
  async savePost(postData) {
    // Always save locally first
    const localId = await DB.add('posts', postData);

    // Try to sync to server
    if (SUPABASE_CONFIG.enabled && navigator.onLine) {
      const remote = await SupabaseAPI.createPost(postData);
      if (remote) {
        postData.remoteId = remote.id;
        postData.synced = true;
        await DB.update('posts', { ...postData, id: localId });
      }
    } else {
      // Queue for background sync
      await DB.queueSync('posts', { ...postData, localId });
    }

    return localId;
  },

  async getPosts(page = 1, limit = 10) {
    // Try server first if online
    if (SUPABASE_CONFIG.enabled && navigator.onLine) {
      const remote = await SupabaseAPI.fetchPosts(page, limit);
      if (remote && remote.length > 0) {
        // Cache locally
        for (const post of remote) {
          try { await DB.add('posts', { ...post, synced: true }); } catch (e) { /* exists */ }
        }
        return remote;
      }
    }

    // Fall back to local
    return DB.getAll('posts', 'createdAt', null, limit);
  },

  async saveMessage(messageData) {
    const localId = await DB.add('messages', messageData);

    if (SUPABASE_CONFIG.enabled && navigator.onLine) {
      const remote = await SupabaseAPI.sendMessage(messageData);
      if (remote) {
        messageData.remoteId = remote.id;
        messageData.synced = true;
        await DB.update('messages', { ...messageData, id: localId });
      }
    } else {
      await DB.queueSync('messages', { ...messageData, localId });
    }

    return localId;
  },

  async getMessages(conversationId) {
    if (SUPABASE_CONFIG.enabled && navigator.onLine) {
      const remote = await SupabaseAPI.fetchMessages(conversationId);
      if (remote) {
        // Cache fetched messages locally (IndexedDB) so the hub can show them
        // instantly and offline next time — mirrors how posts are cached in getFeed.
        for (const m of remote) {
          try { await DB.add('messages', { ...m, conversationId: conversationId, synced: true }); } catch (e) { /* already cached */ }
        }
        return remote;
      }
    }
    return DB.query('messages', 'conversationId', IDBKeyRange.only(conversationId));
  },

  async saveActivity(type, data) {
    return DB.add('activity', {
      userId: currentUser?.handle,
      type: type,
      data: data,
      date: new Date().toISOString().split('T')[0]
    });
  },

  async getActivity(type) {
    return DB.query('activity', 'type', IDBKeyRange.only(type));
  }
};

// Initialize DB on load
