// ==========================================================================
// VIDEO COMPRESSION ENGINE
// ==========================================================================
const VideoCompressor = {
  maxDuration: 60, // seconds
  maxFileSize: 50 * 1024 * 1024, // 50MB
  targetBitrate: 2500000, // 2.5 Mbps
  maxWidth: 1080,
  maxHeight: 1920,

  // Check if browser supports compression
  isSupported() {
    return typeof MediaRecorder !== 'undefined' &&
           typeof HTMLCanvasElement !== 'undefined' &&
           typeof OffscreenCanvas !== 'undefined' || typeof HTMLCanvasElement !== 'undefined';
  },

  // Get video metadata
  async getVideoInfo(file) {
    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.preload = 'metadata';
      video.onloadedmetadata = () => {
        resolve({
          duration: video.duration,
          width: video.videoWidth,
          height: video.videoHeight,
          frameRate: video.videoWidth >= 3840 ? 60 : 30, // browsers don't expose fps natively, assume 60 for 4K
          size: file.size,
          type: file.type
        });
        URL.revokeObjectURL(video.src);
      };
      video.onerror = reject;
      video.src = URL.createObjectURL(file);
    });
  },

  // Validate video before upload
  async validate(file) {
    const errors = [];

    if (!file.type.startsWith('video/')) {
      errors.push('File is not a video');
      return { valid: false, errors };
    }

    const info = await this.getVideoInfo(file);

    if (info.duration > this.maxDuration) {
      errors.push(`Video is too long (${Math.round(info.duration)}s). Maximum is ${this.maxDuration}s.`);
    }

    if (file.size > this.maxFileSize * 2) {
      errors.push(`File is too large (${Math.round(file.size / 1024 / 1024)}MB). Maximum is ${Math.round(this.maxFileSize / 1024 / 1024)}MB after compression.`);
    }

    return {
      valid: errors.length === 0,
      errors,
      info
    };
  },

  // Compress video using Canvas + MediaRecorder
  async compress(file, onProgress) {
    const info = await this.getVideoInfo(file);

    // If already small enough, return as-is
    if (file.size < this.maxFileSize && info.width <= this.maxWidth) {
      if (onProgress) onProgress(100);
      return file;
    }

    return new Promise((resolve, reject) => {
      const video = document.createElement('video');
      video.muted = true;
      video.playsInline = true;

      // Calculate target dimensions
      let targetW = info.width;
      let targetH = info.height;
      if (targetW > this.maxWidth) {
        const ratio = this.maxWidth / targetW;
        targetW = this.maxWidth;
        targetH = Math.round(targetH * ratio);
      }
      if (targetH > this.maxHeight) {
        const ratio = this.maxHeight / targetH;
        targetH = this.maxHeight;
        targetW = Math.round(targetW * ratio);
      }
      // Ensure even dimensions
      targetW = targetW % 2 === 0 ? targetW : targetW - 1;
      targetH = targetH % 2 === 0 ? targetH : targetH - 1;

      const canvas = document.createElement('canvas');
      canvas.width = targetW;
      canvas.height = targetH;
      const ctx = canvas.getContext('2d');

      video.onloadeddata = () => {
        const stream = canvas.captureStream(info.frameRate || 60);

        // Add audio track if present
        try {
          const audioCtx = new AudioContext();
          const source = audioCtx.createMediaElementSource(video);
          const dest = audioCtx.createMediaStreamDestination();
          source.connect(dest);
          source.connect(audioCtx.destination);
          dest.stream.getAudioTracks().forEach(track => stream.addTrack(track));
        } catch (e) {
          console.debug('[Compress] No audio track or audio context failed');
        }

        // Determine codec support
        let mimeType = 'video/webm;codecs=vp9';
        if (!MediaRecorder.isTypeSupported(mimeType)) {
          mimeType = 'video/webm;codecs=vp8';
        }
        if (!MediaRecorder.isTypeSupported(mimeType)) {
          mimeType = 'video/webm';
        }
        if (!MediaRecorder.isTypeSupported(mimeType)) {
          mimeType = 'video/mp4';
        }

        const recorder = new MediaRecorder(stream, {
          mimeType: mimeType,
          videoBitsPerSecond: this.targetBitrate
        });

        const chunks = [];
        recorder.ondataavailable = (e) => {
          if (e.data.size > 0) chunks.push(e.data);
        };

        recorder.onstop = () => {
          const blob = new Blob(chunks, { type: mimeType });
          const compressed = new File([blob], file.name.replace(/\.[^/.]+$/, '.webm'), {
            type: mimeType,
            lastModified: Date.now()
          });
          console.debug(`[Compress] ${Math.round(file.size / 1024)}KB → ${Math.round(compressed.size / 1024)}KB (${Math.round((1 - compressed.size / file.size) * 100)}% reduction)`);
          if (onProgress) onProgress(100);
          resolve(compressed);
        };

        recorder.start(100);
        video.play();

        // Draw frames
        const drawFrame = () => {
          if (video.ended || video.paused) {
            recorder.stop();
            return;
          }
          ctx.drawImage(video, 0, 0, targetW, targetH);
          if (onProgress) {
            const progress = Math.round((video.currentTime / video.duration) * 100);
            onProgress(progress);
          }
          requestAnimationFrame(drawFrame);
        };

        drawFrame();
      };

      video.onerror = reject;
      video.src = URL.createObjectURL(file);
    });
  },

  // Generate thumbnail
  async generateThumbnail(file, time = 1) {
    return new Promise((resolve) => {
      const video = document.createElement('video');
      video.preload = 'auto';
      video.muted = true;
      video.playsInline = true;

      video.onloadeddata = () => {
        video.currentTime = Math.min(time, video.duration * 0.1);
      };

      video.onseeked = () => {
        const canvas = document.createElement('canvas');
        canvas.width = 320;
        canvas.height = Math.round(320 * (video.videoHeight / video.videoWidth));
        const ctx = canvas.getContext('2d');
        ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
        canvas.toBlob((blob) => {
          URL.revokeObjectURL(video.src);
          resolve(blob);
        }, 'image/jpeg', 0.8);
      };

      video.src = URL.createObjectURL(file);
    });
  },

  // Show compression UI
  showCompressionUI() {
    const overlay = document.createElement('div');
    overlay.id = 'compression-overlay';
    overlay.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.8);z-index:99999;display:flex;align-items:center;justify-content:center;';
    overlay.innerHTML = `
      <div style="background:white;border-radius:25px;padding:30px;text-align:center;max-width:300px;width:90%;">
        <i class="fa-solid fa-compress" style="font-size:40px;color:#007AFF;margin-bottom:15px;"></i>
        <h3>Compressing Video</h3>
        <p style="color:#888;font-size:13px;margin:10px 0;">Optimizing for upload...</p>
        <div style="width:100%;height:6px;background:#f0f0f0;border-radius:3px;overflow:hidden;margin:15px 0;">
          <div id="compress-bar" style="height:100%;background:linear-gradient(90deg,#007AFF,#34C759);border-radius:3px;width:0%;transition:width 0.3s;"></div>
        </div>
        <span id="compress-percent" style="font-weight:700;color:#007AFF;">0%</span>
      </div>`;
    (document.getElementById('app') || document.body).appendChild(overlay);
  },

  updateCompressionUI(progress) {
    const bar = document.getElementById('compress-bar');
    const pct = document.getElementById('compress-percent');
    if (bar) bar.style.width = progress + '%';
    if (pct) pct.textContent = progress + '%';
  },

  hideCompressionUI() {
    const overlay = document.getElementById('compression-overlay');
    if (overlay) overlay.remove();
  }
};

