// EMAIL SERVICE — EmailJS / Resend / SMTP Ready
// ==========================================================================
const EMAIL_CONFIG = {
  provider: 'emailjs', // 'emailjs', 'resend', or 'smtp'
  emailjs: {
    serviceId: '',  // Your EmailJS service ID
    templateIds: {
      welcome: '',
      verification: '',
      passwordReset: '',
      parentApproval: '',
      securityAlert: '',
      newsletter: ''
    },
    publicKey: '' // Your EmailJS public key
  },
  resend: {
    apiKey: '',
    fromEmail: 'noreply@trustfirst.app',
    fromName: 'TrustFirst'
  },
  enabled: false // Flip true when configured
};

const EmailService = {
  // Initialize EmailJS
  init() {
    if (EMAIL_CONFIG.provider === 'emailjs' && EMAIL_CONFIG.emailjs.publicKey) {
      // Load EmailJS SDK dynamically
      const script = document.createElement('script');
      script.src = 'https://cdn.jsdelivr.net/npm/@emailjs/browser@3/dist/email.min.js';
      script.onload = () => {
        emailjs.init(EMAIL_CONFIG.emailjs.publicKey);
        EMAIL_CONFIG.enabled = true;
        console.debug('[Email] EmailJS initialized');
      };
      document.head.appendChild(script);
    }
  },

  async send(templateId, params) {
    if (!EMAIL_CONFIG.enabled) {
      console.debug('[Email] Service not configured. Would send:', { templateId, params });
      // Queue for later
      await DB.add('syncQueue', {
        type: 'email',
        data: { templateId, params },
        status: 'pending',
        createdAt: Date.now()
      });
      return { success: false, queued: true };
    }

    try {
      if (EMAIL_CONFIG.provider === 'emailjs') {
        const result = await emailjs.send(
          EMAIL_CONFIG.emailjs.serviceId,
          templateId,
          params
        );
        console.debug('[Email] Sent successfully:', result.status);
        return { success: true, result };
      }

      if (EMAIL_CONFIG.provider === 'resend') {
    const res = await fetch('/api/email/send/', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
            to: params.to_email,
            subject: params.subject,
            html: params.html_body
        })
    });
    const data = await res.json();
    if (!data.ok) throw new Error(data.error || 'Email failed');
    return { success: true, result: data };
}
    } catch (err) {
      console.error('[Email] Send failed:', err);
      return { success: false, error: err.message };
    }
  },

  // Pre-built email templates
  async sendWelcome(email, name) {
    return this.send(EMAIL_CONFIG.emailjs.templateIds.welcome, {
      to_email: email,
      to_name: name,
      subject: 'Welcome to TrustFirst! ',
      html_body: `
        <div style="font-family:-apple-system,sans-serif;max-width:600px;margin:0 auto;padding:40px;">
          <h1 style="font-size:32px;margin-bottom:10px;">Welcome to TrustFirst</h1>
          <p style="color:#555;font-size:16px;line-height:1.6;">Hi ${escapeHtml(name)},</p>
          <p style="color:#555;font-size:16px;line-height:1.6;">Your verified account is ready. You're now part of the world's most trusted social platform.</p>
          <div style="background:#f5f5f5;padding:20px;border-radius:15px;margin:20px 0;">
            <p style="margin:0;font-weight:bold;">Verify your identity to get your badge</p>
            <p style="margin:5px 0 0;color:#888;font-size:14px;">Show everyone your account is real.</p>
          </div>
          <a href="https://trustfirst.app" style="display:inline-block;background:#007AFF;color:white;padding:14px 28px;border-radius:25px;text-decoration:none;font-weight:bold;">Open TrustFirst</a>
          <p style="color:#aaa;font-size:12px;margin-top:30px;">© ${new Date().getFullYear()} TrustFirst. Built in South Africa 🇿🇦</p>
        </div>`
    });
  },

  async sendVerificationCode(email, code) {
    return this.send(EMAIL_CONFIG.emailjs.templateIds.verification, {
      to_email: email,
      subject: 'Your TrustFirst Verification Code',
      html_body: `
        <div style="font-family:-apple-system,sans-serif;max-width:600px;margin:0 auto;padding:40px;text-align:center;">
          <h1>Verification Code</h1>
          <p style="color:#555;">Enter this code to verify your identity:</p>
          <div style="background:#000;color:white;font-size:36px;font-weight:900;letter-spacing:10px;padding:20px;border-radius:15px;margin:20px 0;">${code}</div>
          <p style="color:#888;font-size:13px;">This code expires in 10 minutes. If you didn't request this, ignore this email.</p>
        </div>`
    });
  },

   async sendPasswordReset(email, resetLink) {
    var safeLink = resetLink;
    try {
        var url = new URL(resetLink);
        if (url.protocol !== 'https:' && url.protocol !== 'http:') {
            safeLink = 'https://trustfirst.app/reset';
        }
    } catch (e) {
        safeLink = 'https://trustfirst.app/reset';
    }
    return this.send(EMAIL_CONFIG.emailjs.templateIds.passwordReset, {
        to_email: email,
        subject: 'Reset Your TrustFirst Password',
        html_body: `
            <div style="font-family:-apple-system,sans-serif;max-width:600px;margin:0 auto;padding:40px;">
              <h1>Reset Password</h1>
              <p style="color:#555;line-height:1.6;">We received a request to reset your password.</p>
              <a href="${safeLink}" style="display:inline-block;background:#007AFF;color:white;padding:14px 28px;border-radius:25px;text-decoration:none;font-weight:bold;margin:20px 0;">Reset Password</a>
              <p style="color:#888;font-size:13px;">This link expires in 1 hour. If you didn't request this, your account is safe.</p>
            </div>`
    });
  },

  async sendParentApproval(parentEmail, childName, action) {
    return this.send(EMAIL_CONFIG.emailjs.templateIds.parentApproval, {
      to_email: parentEmail,
      subject: `TrustFirst: ${childName} needs your approval`,
      html_body: `
        <div style="font-family:-apple-system,sans-serif;max-width:600px;margin:0 auto;padding:40px;">
          <div style="background:linear-gradient(135deg,#34C759,#30D158);padding:20px;border-radius:15px;color:white;margin-bottom:20px;">
            <h2 style="margin:0;">Family Center Alert</h2>
          </div>
          <p style="color:#555;line-height:1.6;"><b>${escapeHtml(childName)}</b> wants to: <b>${escapeHtml(action)}</b></p>
          <div style="display:flex;gap:10px;margin:20px 0;">
            <a href="#approve" style="background:#34C759;color:white;padding:12px 24px;border-radius:20px;text-decoration:none;font-weight:bold;">Approve</a>
            <a href="#deny" style="background:#FF3B30;color:white;padding:12px 24px;border-radius:20px;text-decoration:none;font-weight:bold;">Deny</a>
          </div>
        </div>`
    });
  },

  async sendSecurityAlert(email, alertType, details) {
    return this.send(EMAIL_CONFIG.emailjs.templateIds.securityAlert, {
      to_email: email,
      subject: `⚠️ TrustFirst Security Alert: ${alertType}`,
      html_body: `
        <div style="font-family:-apple-system,sans-serif;max-width:600px;margin:0 auto;padding:40px;">
          <div style="background:#FF3B30;padding:15px;border-radius:15px;color:white;margin-bottom:20px;text-align:center;">
            <h2 style="margin:0;">⚠️ Security Alert</h2>
          </div>
          <p style="color:#555;line-height:1.6;"><b>Alert Type:</b> ${escapeHtml(alertType)}</p>
          <p style="color:#555;line-height:1.6;">${escapeHtml(details)}</p>
          <p style="color:#555;line-height:1.6;">If this wasn't you, secure your account immediately.</p>
          <a href="https://trustfirst.app/security" style="display:inline-block;background:#FF3B30;color:white;padding:14px 28px;border-radius:25px;text-decoration:none;font-weight:bold;">Secure Account</a>
        </div>`
    });
  }
};

