function renderPostActions(post, currentUser) {
    const isVerified = currentUser && currentUser.verified === true;

    return `
        <div class="post-actions" style="display:flex; align-items:center; gap:16px; padding:12px 16px;">
            <button class="post-action-btn like-btn" onclick="realToggleLike(this,'${post.id}')" data-liked="${post._liked ? 'true' : 'false'}" style="background:none; border:none; display:flex; align-items:center; gap:6px; cursor:pointer;">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="${post.liked ? '#FF3B30' : 'none'}" stroke="${post.liked ? '#FF3B30' : 'var(--text-primary)'}" stroke-width="2">
                    <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
                </svg>
                <span style="font-size:14px; color:var(--text-primary);">${post.likes || 0}</span>
            </button>

            <button class="post-action-btn comment-btn" onclick="${isVerified ? `openComments('${post.id}')` : `showVerifyPrompt()`}" style="background:none; border:none; display:flex; align-items:center; gap:6px; cursor:pointer; ${!isVerified ? 'opacity:0.5;' : ''}">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" stroke-width="2">
                    <path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/>
                </svg>
                <span style="font-size:14px; color:var(--text-primary);">${post.comments || 0}</span>
                ${!isVerified ? '<svg width="14" height="14" viewBox="0 0 24 24" fill="var(--text-tertiary)" stroke="none"><path d="M12 2C9.24 2 7 4.24 7 7v3H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8a2 2 0 0 0-2-2h-1V7c0-2.76-2.24-5-5-5zm3 10v8H9v-8h6zm-1-2h-4V7c0-1.66 1.34-3 3-3s3 1.34 3 3v3z"/></svg>' : ''}
            </button>

            <button class="post-action-btn bookmark-btn" onclick="realToggleBookmark(this,'${post.id}')" data-bookmarked="${post._bookmarked ? 'true' : 'false'}" style="background:none; border:none; cursor:pointer;">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="${post.bookmarked ? 'var(--text-primary)' : 'none'}" stroke="var(--text-primary)" stroke-width="2">
                    <path d="M19 21l-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/>
                </svg>
            </button>

            <button class="post-action-btn share-btn" onclick="openShareMenu('${post.id}')" style="background:none; border:none; cursor:pointer; margin-left:auto;">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="var(--text-primary)" stroke-width="2">
                    <path d="M4 12v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8"/><polyline points="16 6 12 2 8 6"/><line x1="12" y1="2" x2="12" y2="15"/>
                </svg>
            </button>
        </div>
    `;
}

function showVerifyPrompt() {
    const modal = document.createElement('div');
    modal.className = 'verify-prompt-overlay';
    modal.id = 'verifyPromptModal';
    modal.innerHTML = `
        <div class="verify-prompt-modal liquid-glass" style="
            position:fixed; top:0; left:0; right:0; bottom:0; z-index:10000;
            display:flex; align-items:center; justify-content:center;
            background:rgba(0,0,0,0.5); backdrop-filter:blur(10px);
        ">
            <div style="
                background:var(--card-bg); border-radius:20px; padding:32px; margin:20px;
                max-width:340px; width:100%; text-align:center;
                box-shadow:0 20px 60px rgba(0,0,0,0.3);
            ">
                <div style="width:64px; height:64px; border-radius:50%; background:linear-gradient(135deg, #007AFF, #00C7FF);
                    display:flex; align-items:center; justify-content:center; margin:0 auto 16px;">
                    <svg width="32" height="32" viewBox="0 0 24 24" fill="white" stroke="none">
                        <path d="M12 2C9.24 2 7 4.24 7 7v3H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-8a2 2 0 0 0-2-2h-1V7c0-2.76-2.24-5-5-5zm1 14.5V19h-2v-2.5a1.5 1.5 0 1 1 2 0zM15 10H9V7c0-1.66 1.34-3 3-3s3 1.34 3 3v3z"/>
                    </svg>
                </div>
                <h3 style="font-size:20px; font-weight:700; margin-bottom:8px; color:var(--text-primary);">Verification Required</h3>
                <p style="font-size:14px; color:var(--text-secondary); margin-bottom:24px; line-height:1.5;">
                    Commenting is available for verified users only. Get verified to join the conversation and build trust.
                </p>
                <button onclick="navigateTo('verification')" style="
                    width:100%; padding:14px; border-radius:14px; border:none;
                    background:linear-gradient(135deg, #007AFF, #00C7FF);
                    color:white; font-size:16px; font-weight:600; cursor:pointer;
                    margin-bottom:10px;
                ">Get Verified Now</button>
                <button onclick="document.getElementById('verifyPromptModal').remove()" style="
                    width:100%; padding:14px; border-radius:14px; border:none;
                    background:transparent; color:var(--text-secondary);
                    font-size:14px; cursor:pointer;
                ">Maybe Later</button>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    modal.addEventListener('click', (e) => {
        if (e.target === modal) modal.remove();
    });
}

