function t(key) {
    return (TRANSLATIONS[currentLanguage] && TRANSLATIONS[currentLanguage][key]) || TRANSLATIONS['en'][key] || key;
}

function changeLanguage(lang) {
    currentLanguage = lang;
    secureSave('language', lang);
    // Set RTL for Arabic
    if (lang === 'ar') {
        document.documentElement.setAttribute('dir', 'rtl');
    } else {
        document.documentElement.setAttribute('dir', 'ltr');
    }

    // Update all translatable elements
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        el.textContent = t(key);
    });

    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        const key = el.getAttribute('data-i18n-placeholder');
        el.placeholder = t(key);
    });

    showToast(`Language changed to ${getLanguageName(lang)}`);
}

function getLanguageName(code) {
    const names = { en:'English', es:'Español', fr:'Français', ar:'العربية', zu:'isiZulu', pt:'Português', hi:'हिन्दी', zh:'中文' };
    return names[code] || code;
}

function renderLanguageSelector() {
    return `
        <div class="language-selector" style="padding:16px;">
            <h3 style="font-size:18px; font-weight:700; margin-bottom:16px; color:var(--text-primary);" data-i18n="language">${t('language')}</h3>
            <div style="display:flex; flex-direction:column; gap:4px;">
                ${Object.keys(TRANSLATIONS).map(lang => `
                    <button onclick="changeLanguage('${lang}')" style="
                        display:flex; align-items:center; justify-content:space-between;
                        padding:14px 16px; border-radius:12px; border:none; width:100%;
                        background:${currentLanguage === lang ? 'rgba(0,122,255,0.1)' : 'transparent'};
                        cursor:pointer; text-align:left;
                    ">
                        <span style="font-size:16px; color:var(--text-primary); font-weight:${currentLanguage === lang ? '600' : '400'};">
                            ${getLanguageName(lang)}
                        </span>
                        ${currentLanguage === lang ? '<svg width="20" height="20" viewBox="0 0 24 24" fill="#007AFF" stroke="none"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg>' : ''}
                    </button>
                `).join('')}
            </div>
        </div>
    `;
}

 // ============================================
// REELS PAGE - Complete Implementation
// ============================================
let currentReelIndex = 0;
let reelsData = [];
var _videoFeedContext = 'feed';
var _videoFeedList   = [];
var _videoFeedIdx    = 0;

function openContextualVideo(videoUrl, context, startIndex, clipArray) {
    _videoFeedContext = context || 'feed';
    _videoFeedIdx    = startIndex || 0;

    if (clipArray && clipArray.length) {
        reelsData = clipArray.map(function(c) {
            return {
                id:             c.id || '',
                videoUrl:       c.videoUrl || c.video_url || c.media_url || videoUrl,
                username:       c.username || (c.users && ('@' + c.users.username)) || '@user',
                caption:        c.caption  || c.text_content || '',
                sound:          c.sound    || c.sound_name   || 'Original Audio',
                likes:          c.likes    || c.like_count   || 0,
                comments:       c.comments || c.comment_count || 0,
                liked:          false,
                bookmarked:     false,
                isOriginalSound: !c.sound_name
            };
        });
    } else {
        reelsData = [{
            id: 'single_' + Date.now(), videoUrl: videoUrl,
            username: '', caption: '', sound: '', likes: 0, comments: 0,
            liked: false, bookmarked: false, isOriginalSound: true
        }];
    }
    currentReelIndex = _videoFeedIdx;

    var navBar = document.querySelector('.nav-container');
    if (navBar) navBar.style.display = 'none';
    var screen = document.getElementById('reel-overlay');
    if (!screen) return;
    screen.style.display = 'block';
    screen.innerHTML =
        '<div id="reelsContainer" style="position:fixed;top:0;left:0;right:0;bottom:0;z-index:5000;background:#000;overflow:hidden;">' +
            '<button onclick="closeReelsPage()" style="position:absolute;top:50px;left:16px;z-index:5010;background:rgba(0,0,0,0.3);border:none;border-radius:50%;width:40px;height:40px;display:flex;align-items:center;justify-content:center;cursor:pointer;backdrop-filter:blur(10px);">' +
                '<svg width="24" height="24" viewBox="0 0 24 24" fill="white" stroke="white" stroke-width="2"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>' +
            '</button>' +
            '<div id="reelsLoading" style="display:none;"></div>' +
            '<div id="reelsViewport" style="width:100%;height:100%;overflow:hidden;position:relative;"></div>' +
            '<div id="speedIndicator" style="display:none;"></div>' +
            '<div id="reelContextMenu" style="display:none;"></div>' +
        '</div>';

    addReelsStyles();
    renderReel(currentReelIndex);
    setupReelGestures();
}

// Opens profile clips in a lightweight in-profile viewer (not the global TrustClip page)
function openProfileClipViewer(startIdx) {
    var clips = window._profileClips || [];
    if (!clips.length) return;
    var idx = startIdx || 0;
    var existing = document.getElementById('profileClipViewer');
    if (existing) existing.remove();
    var ov = document.createElement('div');
    ov.id = 'profileClipViewer';
    ov.style.cssText = 'position:absolute;inset:0;z-index:20000;background:#000;display:flex;flex-direction:column;overflow:hidden;';
    function renderClip(i) {
        var clip = clips[i] || {};
        var url = clip.videoUrl || clip.media_url || '';
        ov.innerHTML =
            '<button onclick="document.getElementById(\'profileClipViewer\').remove()" style="position:absolute;top:max(50px,env(safe-area-inset-top,50px));left:16px;z-index:10;background:rgba(0,0,0,0.4);border:none;border-radius:50%;width:40px;height:40px;display:flex;align-items:center;justify-content:center;cursor:pointer;backdrop-filter:blur(10px);">' +
                '<svg width="20" height="20" viewBox="0 0 24 24" fill="white" stroke="white" stroke-width="2.5"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>' +
            '</button>' +
            (i > 0 ? '<button onclick="window._profileClipViewerGo(' + (i-1) + ')" style="position:absolute;left:16px;top:50%;transform:translateY(-50%);z-index:10;background:rgba(0,0,0,0.35);border:none;border-radius:50%;width:36px;height:36px;display:flex;align-items:center;justify-content:center;cursor:pointer;"><svg width="18" height="18" viewBox="0 0 24 24" fill="white" stroke="white" stroke-width="2"><polyline points="15 18 9 12 15 6"/></svg></button>' : '') +
            (i < clips.length - 1 ? '<button onclick="window._profileClipViewerGo(' + (i+1) + ')" style="position:absolute;right:16px;top:50%;transform:translateY(-50%);z-index:10;background:rgba(0,0,0,0.35);border:none;border-radius:50%;width:36px;height:36px;display:flex;align-items:center;justify-content:center;cursor:pointer;"><svg width="18" height="18" viewBox="0 0 24 24" fill="white" stroke="white" stroke-width="2"><polyline points="9 18 15 12 9 6"/></svg></button>' : '') +
            '<video src="' + escapeHtml(url) + '" autoplay playsinline controls style="width:100%;height:100%;object-fit:contain;background:#000;"></video>' +
            '<div style="position:absolute;bottom:max(24px,env(safe-area-inset-bottom,24px));left:0;right:0;text-align:center;pointer-events:none;">' +
                '<small style="color:rgba(255,255,255,0.5);font-size:12px;">' + (i+1) + ' / ' + clips.length + '</small>' +
            '</div>';
    }
    window._profileClipViewerGo = function(i) { idx = i; renderClip(i); };
    renderClip(idx);
    var profileOv = document.getElementById('profile-overlay') || document.querySelector('.app') || document.body;
    profileOv.appendChild(ov);
}

function openFullScreenMedia(url, type) {
    var ov = document.createElement('div');
    ov.id = 'fsMediaOverlay';
    ov.style.cssText = 'position:fixed;inset:0;z-index:30000;background:#000;display:flex;align-items:center;justify-content:center;';

    // Back button (top-left, like the native viewer)
    var closeBtn = document.createElement('button');
    closeBtn.innerHTML = '<svg width="22" height="22" viewBox="0 0 24 24" fill="white" stroke="white" stroke-width="2.5"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>';
    closeBtn.style.cssText = 'position:absolute;top:max(46px,env(safe-area-inset-top,46px));left:16px;z-index:5;background:rgba(0,0,0,0.45);border:none;border-radius:50%;width:40px;height:40px;display:flex;align-items:center;justify-content:center;cursor:pointer;backdrop-filter:blur(10px);';
    closeBtn.onclick = function() { try { var v = ov.querySelector('video'); if (v) v.pause(); } catch(e){} ov.remove(); };
    ov.appendChild(closeBtn);

    var media;
    if (type === 'video') {
        // Real video player with native controls (scrubber, time, play/pause)
        media = document.createElement('video');
        media.controls = true; media.autoplay = true; media.setAttribute('playsinline', '');
        media.style.cssText = 'width:100%;height:100%;max-width:100%;max-height:100%;object-fit:contain;background:#000;';
    } else {
        media = document.createElement('img');
        media.style.cssText = 'max-width:100%;max-height:100%;object-fit:contain;';
        ov.style.cursor = 'pointer';
        ov.onclick = function(e) { if (e.target === ov) ov.remove(); };
    }
    ov.appendChild(media);
    document.body.appendChild(ov);

    // Private chat media needs a signed URL; public assets pass through.
    if (typeof tfSignMediaUrl === 'function') {
        tfSignMediaUrl(url).then(function(u) { media.src = u; if (type === 'video') media.play().catch(function(){}); });
    } else {
        media.src = url;
    }
}
let reelsTutorialShown = localStorage.getItem('trustfirst-reels-tutorial') === 'true';
let longPressTimer = null;
let isSpedUp = false;

/* ============================================================
   SENSITIVE CONTENT FILTER
   ============================================================ */
function checkSensitiveContent(videoEl, overlayContainer, reelData) {
    // Check if this clip was server-flagged (set a `is_sensitive` boolean in Supabase)
    var isSensitive = reelData && reelData.is_sensitive === true;
    if (!isSensitive) return;
    var existing = overlayContainer.querySelector('.tc-sensitive-overlay');
    if (existing) return;
    var ov = document.createElement('div');
    ov.className = 'tc-sensitive-overlay';
    ov.style.cssText = 'position:absolute;inset:0;z-index:50;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;backdrop-filter:blur(28px);-webkit-backdrop-filter:blur(28px);background:rgba(0,0,0,0.45);';
    ov.innerHTML =
        '<i class="fa-solid fa-eye-slash" style="font-size:40px;color:rgba(255,255,255,0.9);"></i>' +
        '<b style="font-size:18px;color:white;text-align:center;padding:0 24px;">Sensitive content</b>' +
        '<p style="font-size:13px;color:rgba(255,255,255,0.7);text-align:center;padding:0 32px;line-height:1.55;">This clip may contain content some people find disturbing.</p>' +
        '<button onclick="skipSensitiveVideo(this)" style="width:200px;padding:14px;border-radius:14px;background:#FF3B30;color:white;border:none;font-size:15px;font-weight:700;cursor:pointer;">Skip video</button>' +
        '<button onclick="watchSensitiveAnyway(this)" style="width:200px;padding:12px;border-radius:14px;background:transparent;color:rgba(255,255,255,0.65);border:1px solid rgba(255,255,255,0.25);font-size:14px;cursor:pointer;">Watch anyway</button>' +
        '<button onclick="openSensitiveLearnMore()" style="background:none;border:none;color:rgba(255,255,255,0.5);font-size:13px;cursor:pointer;text-decoration:underline;padding:0;">Learn more</button>';
    if (videoEl) videoEl.pause();
    overlayContainer.appendChild(ov);
}

function watchSensitiveAnyway(btn) {
    var ov = btn.closest('.tc-sensitive-overlay');
    if (ov) ov.remove();
    var videoEl = ov && ov.parentNode ? ov.parentNode.querySelector('video') : null;
    if (videoEl) videoEl.play().catch(function(){});
    triggerHaptic(10);
}

function skipSensitiveVideo(btn) {
    var ov = btn.closest('.tc-sensitive-overlay');
    if (ov) ov.remove();
    // Navigate to next reel
    var scroller = document.getElementById('reel-scroller') || document.getElementById('reelsViewport');
    if (scroller) scroller.scrollTop += scroller.clientHeight;
    triggerHaptic(10);
}

function openSensitiveLearnMore() {
    var existing = document.getElementById('sensitiveLearnMore');
    if (existing) existing.remove();
    var sheet = document.createElement('div');
    sheet.id = 'sensitiveLearnMore';
    sheet.style.cssText = 'position:fixed;inset:0;z-index:20000;display:flex;align-items:flex-end;background:rgba(0,0,0,0.6);backdrop-filter:blur(10px);';
    sheet.innerHTML =
        '<div style="width:100%;max-width:500px;margin:0 auto;background:var(--bg-primary,#fff);border-radius:22px 22px 0 0;padding:24px 24px 48px;animation:modalUp 0.35s cubic-bezier(0.32,0.72,0,1);">' +
            '<div style="width:36px;height:4px;background:#ccc;border-radius:2px;margin:0 auto 20px;"></div>' +
            '<b style="font-size:19px;color:var(--text-primary,#000);display:block;margin-bottom:12px;">Why this video is covered</b>' +
            '<p style="font-size:14px;color:#888;line-height:1.7;margin-bottom:12px;">TrustFirst uses a combination of human moderators and AI technology to identify content that may be disturbing, graphic, or emotionally difficult for some users.</p>' +
            '<p style="font-size:14px;color:#888;line-height:1.7;margin-bottom:20px;">This system works alongside our <b style="color:var(--text-primary,#000);">Community Guidelines</b> to help keep TrustFirst a safe space for everyone.</p>' +
            '<button onclick="document.getElementById(\'sensitiveLearnMore\').remove()" style="width:100%;padding:15px;border-radius:14px;background:#007AFF;color:white;border:none;font-size:15px;font-weight:700;cursor:pointer;">OK</button>' +
        '</div>';
    sheet.addEventListener('click', function(e){ if(e.target===sheet) sheet.remove(); });
    (document.getElementById('app') || document.body).appendChild(sheet);
}

