function scheduleLive() {
    var titleEl = document.getElementById('liveTitle');
    var dateEl  = document.getElementById('liveDate');
    var timeEl  = document.getElementById('liveTime');
    var descEl  = document.getElementById('liveDesc');
    if (!titleEl || !dateEl || !timeEl) { showToast('Schedule form not ready'); return; }
    const title = titleEl.value.trim();
    const date  = dateEl.value;
    const time  = timeEl.value;
    const desc  = descEl ? descEl.value.trim() : '';
    if (!title || !date || !time) {
        showToast('Please fill in title, date and time');
        return;
    }

    const scheduled = JSON.parse(localStorage.getItem('trustfirst-scheduled-lives') || '[]');
    scheduled.push({ title, date, time, desc, id: Date.now() });
    localStorage.setItem('trustfirst-scheduled-lives', JSON.stringify(scheduled));

    showToast('Live scheduled!');
    document.getElementById('liveSettingsPage').remove();
    showLiveSettings();
}

function cancelScheduledLive(index) {
    const scheduled = JSON.parse(localStorage.getItem('trustfirst-scheduled-lives') || '[]');
    scheduled.splice(index, 1);
    localStorage.setItem('trustfirst-scheduled-lives', JSON.stringify(scheduled));
    document.getElementById('liveSettingsPage').remove();
    showLiveSettings();
    showToast('Live cancelled');
}

function startLiveNow() {
    showToast('Starting live...');
    document.getElementById('liveSettingsPage').remove();
    openLiquidGlassCamera();
}

