function changeProfilePicture() {
    closeProfilePicOptions();

    var input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = async function(e) {
        var file = e.target.files[0];
        if (!file) return;

        // Validate
        if (!file.type.startsWith('image/')) {
            showToast('Please select an image file');
            return;
        }

        if (file.size > 5 * 1024 * 1024) {
            showToast('Image must be under 5MB');
            return;
        }

        // Optimistic update — reflect the picked image immediately so the avatar
        // visibly changes right away, independent of the upload result.
        try {
            var _previewReader = new FileReader();
            _previewReader.onload = function(ev){ try { updateAvatarsOnPage(ev.target.result); } catch(_e){} };
            _previewReader.readAsDataURL(file);
        } catch(_e){}

        showToast('Updating profile picture...');

        try {
            // Compress the image
            var compressed = await compressImage(file, 500, 0.85);

            // Upload to Supabase Storage (if available)
            if (window.sb && currentUser) {
                var fileName = currentUser.id + '/avatar_' + Date.now() + '.jpg';

                var uploadResult = await sb.storage
                    .from('avatars')
                    .upload(fileName, compressed, {
                        cacheControl: '3600',
                        upsert: true
                    });

                if (uploadResult.error) {
                    console.warn('[Avatar] Upload failed:', uploadResult.error);
                    // Fall back to local storage
                    saveAvatarLocally(compressed);
                    return;
                }

                // Get public URL
                var urlResult = sb.storage.from('avatars').getPublicUrl(fileName);
                var publicUrl = urlResult.data.publicUrl;

                // Update both users and profiles tables
                var ts = new Date().toISOString();
                await Promise.all([
                    sb.from('users').update({ avatar_url: publicUrl, updated_at: ts }).eq('id', currentUser.id),
                    sb.from('profiles').update({ avatar_url: publicUrl, updated_at: ts }).eq('id', currentUser.id)
                ]);

                if (currentUser) currentUser.avatar_url = publicUrl;
                secureSave('current_user', currentUser);
                updateAvatarsOnPage(publicUrl);
                showToast('Profile picture updated');

            } else {
                saveAvatarLocally(compressed);
            }

        } catch(err) {
            console.error('[Avatar]', err);
            showToast('Failed to update picture. Try again.');
        }
    };
    input.click();
}

function saveAvatarLocally(imageFile) {
    var reader = new FileReader();
    reader.onload = function(e) {
        var dataUrl = e.target.result;
        localStorage.setItem('trustfirst-avatar', dataUrl);
        if (currentUser) currentUser.avatar_url = dataUrl;
        secureSave('current_user', currentUser);
        updateAvatarsOnPage(dataUrl);
        showToast('Profile picture updated! ✨');
    };
    reader.readAsDataURL(imageFile);
}

function takeProfilePhoto() {
    closeProfilePicOptions();
    // Use the clip camera in photo mode
    if (typeof openLiquidGlassCamera === 'function') {
        openLiquidGlassCamera();
    } else if (typeof startCamera === 'function') {
        startCamera();
    }
}

function removeProfilePicture() {
    closeProfilePicOptions();

    if (!confirm('Remove your profile picture?')) return;

    var defaultPic = currentUser?.avatar_url || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(currentUser?.name || 'U') + '&background=007AFF&color=fff&bold=true&size=200';

    if (window.sb && currentUser) {
        sb.from('users').update({
            avatar_url: null,
            updated_at: new Date().toISOString()
        }).eq('id', currentUser.id);
    }

    localStorage.removeItem('trustfirst-avatar');
    if (currentUser) currentUser.avatar_url = null;
    secureSave('current_user', currentUser);

    updateAvatarsOnPage(defaultPic);
    showToast('Profile picture removed');
}

function updateAvatarsOnPage(newUrl) {
    if (!newUrl) return;

    // 1. All class-based avatar images (posts, profiles, users)
    document.querySelectorAll('.post-avatar, .profile-avatar, .user-avatar, .my-avatar, [data-user-avatar]').forEach(function(el) {
        if (el.tagName === 'IMG') { el.src = newUrl; }
        else { el.style.backgroundImage = 'url(' + newUrl + ')'; }
    });

    // 2. Profile page hero avatar
    var profileImg = document.getElementById('profile-avatar-img');
    if (profileImg) {
        profileImg.src = newUrl;
        profileImg.style.display = 'block';
        var ph = document.getElementById('profile-avatar-placeholder');
        if (ph) ph.style.display = 'none';
    }

    // 3. Comment bar avatar (composer)
    var commentBar = document.getElementById('comment-bar-avatar');
    if (commentBar) commentBar.src = newUrl;

    // 4. Story viewer avatar ring
    var storyAv = document.getElementById('story-avatar');
    if (storyAv) storyAv.src = newUrl;

    // 5. Account status overlay avatar
    var statusImg = document.getElementById('statusAvatarImg');
    var statusIcon = document.getElementById('statusAvatarIcon');
    if (statusImg) {
        statusImg.src = newUrl;
        statusImg.style.display = 'block';
        if (statusIcon) statusIcon.style.display = 'none';
    }



    // 7. Chat list avatars (dynamically rendered rows)
    document.querySelectorAll('.chat-item-avatar, .msg-avatar, [data-my-avatar]').forEach(function(el) {
        if (el.tagName === 'IMG') { el.src = newUrl; }
        else { el.style.backgroundImage = 'url(' + newUrl + ')'; }
    });

    // 8. Notification list — my avatar in sent/outgoing items
    document.querySelectorAll('.notif-my-avatar').forEach(function(el) {
        if (el.tagName === 'IMG') { el.src = newUrl; }
    });

    // 9. Persist to currentUser in memory + localStorage
    if (typeof currentUser !== 'undefined' && currentUser) {
        currentUser.avatar_url = newUrl;
        secureSave('current_user', currentUser);
    }
}

function closeProfilePicOptions() {
    var overlay = document.getElementById('profilePicOptions');
    if (overlay) overlay.remove();
}

// ============================================================
// REPORT A PROBLEM FLOW
// ============================================================
var _rpIncludeLogs = true;
var _rpScreenshots = [];

function openReportProblem() {
    var el = document.getElementById('reportProblemOverlay');
    if (!el) return;
    // Reset state
    _rpScreenshots = [];
    _rpIncludeLogs = true;
    var desc = document.getElementById('rp-description');
    if (desc) desc.value = '';
    document.getElementById('rp-screenshots').innerHTML = '';
    var sendBtn = document.getElementById('rp-send-btn');
    if (sendBtn) { sendBtn.style.opacity = '0.4'; sendBtn.style.pointerEvents = 'none'; }
    // Shake toggle init
    var shakeToggle = document.getElementById('rp-shake-toggle');
    if (shakeToggle) {
        var shakeEnabled = localStorage.getItem('tf-shake-report') !== '0';
        if (!shakeEnabled) shakeToggle.classList.remove('active');
        else shakeToggle.classList.add('active');
    }
    rpGoToScreen(1);
    el.style.display = 'flex';
    el.style.flexDirection = 'column';
    triggerHaptic(10);
}

function closeReportProblem() {
    var el = document.getElementById('reportProblemOverlay');
    if (el) el.style.display = 'none';
}

function rpGoToScreen(n) {
    [1, 2, 3].forEach(function(i) {
        var s = document.getElementById('rp-screen-' + i);
        if (s) s.style.display = (i === n) ? (i === 1 ? 'flex' : 'flex') : 'none';
        if (s && i === n) s.style.flexDirection = 'column';
    });
    // Show/hide send button only on screen 3
    var sendBtn = document.getElementById('rp-send-btn');
    if (sendBtn) sendBtn.style.display = (n === 3) ? 'block' : 'none';
    // Scroll to top
    var scroll = document.getElementById('rp-scroll');
    if (scroll) scroll.scrollTop = 0;
}

function rpSetIncludeLogs(include) {
    _rpIncludeLogs = include;
    rpGoToScreen(3);
}

function rpCheckSendReady() {
    var desc = document.getElementById('rp-description');
    var sendBtn = document.getElementById('rp-send-btn');
    if (!desc || !sendBtn) return;
    var hasText = desc.value.trim().length > 3;
    sendBtn.style.opacity = hasText ? '1' : '0.4';
    sendBtn.style.pointerEvents = hasText ? 'auto' : 'none';
}

function rpAttachScreenshot() {
    // Capture current visible state as a data note since canvas cross-origin blocks full capture
    showToast('Screenshot captured');
    var placeholder = 'screenshot_' + Date.now();
    _rpScreenshots.push({ type: 'screenshot', name: placeholder });
    rpRenderScreenshots();
}

function rpHandleUpload(input) {
    if (!input.files || !input.files[0]) return;
    var file = input.files[0];
    var reader = new FileReader();
    reader.onload = function(e) {
        _rpScreenshots.push({ type: 'upload', url: e.target.result, name: file.name });
        rpRenderScreenshots();
    };
    reader.readAsDataURL(file);
    input.value = '';
}

function rpRenderScreenshots() {
    var container = document.getElementById('rp-screenshots');
    if (!container) return;
    container.innerHTML = _rpScreenshots.map(function(s, i) {
        var bg = s.url ? 'url(' + s.url + ') center/cover' : 'rgba(0,0,0,0.08)';
        var icon = s.url ? '' : '<i class="fa-solid fa-camera" style="color:#888;font-size:18px;"></i>';
        return '<div style="position:relative;width:72px;height:72px;border-radius:10px;background:' + bg + ';border:1px solid var(--border-color,#eee);display:flex;align-items:center;justify-content:center;flex-shrink:0;">' +
            icon +
            '<div onclick="rpRemoveScreenshot(' + i + ')" style="position:absolute;top:-6px;right:-6px;width:20px;height:20px;background:#1c1c1e;border-radius:50%;display:flex;align-items:center;justify-content:center;cursor:pointer;border:2px solid var(--bg-primary,#fff);">' +
            '<i class="fa-solid fa-xmark" style="color:#fff;font-size:9px;"></i></div></div>';
    }).join('');
    rpCheckSendReady();
}

function rpRemoveScreenshot(index) {
    _rpScreenshots.splice(index, 1);
    rpRenderScreenshots();
}

async function submitReportProblem() {
    var desc = document.getElementById('rp-description');
    var text = desc ? desc.value.trim() : '';
    if (!text) return;

    var sendBtn = document.getElementById('rp-send-btn');
    if (sendBtn) { sendBtn.textContent = '…'; sendBtn.style.pointerEvents = 'none'; }

    var report = {
        description: text,
        include_logs: _rpIncludeLogs,
        screenshot_count: _rpScreenshots.length,
        user_id: currentUser ? currentUser.id : null,
        username: currentUser ? currentUser.username : null,
        app_version: '1.0',
        device: navigator.userAgent,
        timestamp: new Date().toISOString(),
        url: window.location.href
    };

    try {
        if (window.sb && window.sb.from) {
            await window.sb.from('bug_reports').insert([report]);
        }
        // Also store locally
        var history = JSON.parse(localStorage.getItem('tf_report_history') || '[]');
        history.unshift(report);
        localStorage.setItem('tf_report_history', JSON.stringify(history.slice(0, 50)));
    } catch(e) {
        console.warn('[Report] Could not save to DB, stored locally only');
    }

    closeReportProblem();
    showToast('Report sent. Thank you for helping us improve TrustFirst.');
}

// Shake detection for report trigger
(function initShakeToReport() {
    if (!window.DeviceMotionEvent) return;
    var lastShake = 0;
    var shakeHits = 0, lastHit = 0;
    // Use gravity-free acceleration so tilting doesn't trigger it, and require
    // several strong jolts in quick succession — a deliberate shake, not a nudge.
    // Raised after it kept firing on ordinary handling: a report should take a
    // deliberate shake, not a brisk walk or dropping the phone on a cushion.
    var JOLT = 24;        // per-axis-sum jolt strength
    var HITS_NEEDED = 4;  // consecutive jolts within the window
    function _attachShake() {
        window.addEventListener('devicemotion', function(e) {
        var shakeEnabled = localStorage.getItem('tf-shake-report') !== '0';
        if (!shakeEnabled) return;
        var a = e.acceleration && (e.acceleration.x || e.acceleration.y || e.acceleration.z) != null
            ? e.acceleration : e.accelerationIncludingGravity;
        if (!a) return;
        // Subtract ~gravity when only accelerationIncludingGravity is available.
        var base = e.acceleration && e.acceleration.x != null ? 0 : 9.8;
        var total = Math.max(0, Math.abs(a.x || 0) + Math.abs(a.y || 0) + Math.abs(a.z || 0) - base);
        var now = Date.now();
        if (total > JOLT) {
            if (now - lastHit < 700) shakeHits++; else shakeHits = 1;
            lastHit = now;
        }
        if (shakeHits >= HITS_NEEDED && now - lastShake > 2500) {
            lastShake = now; shakeHits = 0;
            // Don't open if already in auth or splash
            var app = document.getElementById('app');
            if (!app || !app.classList.contains('authenticated')) return;
            // Don't open if report overlay already open
            var existing = document.getElementById('reportProblemOverlay');
            if (existing && existing.style.display !== 'none') return;
            openReportProblem();
            rpGoToScreen(2);
        }
    });
    }
    if (typeof DeviceMotionEvent.requestPermission === 'function') {
        // iOS 13+ requires user gesture to get motion permission
        document.addEventListener('click', function _askMotion() {
            document.removeEventListener('click', _askMotion);
            DeviceMotionEvent.requestPermission().then(function(s){ if(s==='granted') _attachShake(); }).catch(function(){});
        }, { once: true });
    } else {
        _attachShake();
    }
})();

