// REAL CONTENT FLAG / REPORT SYSTEM
// ============================================
var FLAG_REASONS = [
    { id: 'spam', label: 'Spam', icon: 'fa-ban', desc: 'Repetitive, misleading, or mass-sent content' },
    { id: 'harassment', label: 'Harassment or Bullying', icon: 'fa-hand-fist', desc: 'Targeting, intimidating, or threatening someone' },
    { id: 'hate', label: 'Hate Speech', icon: 'fa-triangle-exclamation', desc: 'Slurs, stereotypes, or dehumanizing language' },
    { id: 'violence', label: 'Violence or Threats', icon: 'fa-skull-crossbones', desc: 'Threatening harm, graphic violence' },
    { id: 'nudity', label: 'Nudity or Sexual Content', icon: 'fa-eye-slash', desc: 'Explicit or suggestive content' },
    { id: 'minor_safety', label: 'Involves a Minor', icon: 'fa-child', desc: 'Content that may endanger children' },
    { id: 'impersonation', label: 'Impersonation', icon: 'fa-user-secret', desc: 'Pretending to be someone else' },
    { id: 'false_info', label: 'False Information', icon: 'fa-circle-exclamation', desc: 'Misleading or deliberately false claims' },
    { id: 'scam', label: 'Scam or Fraud', icon: 'fa-credit-card', desc: 'Attempting to deceive for financial gain' },
    { id: 'self_harm', label: 'Self-Harm or Suicide', icon: 'fa-heart-crack', desc: 'Promoting or depicting self-harm' },
    { id: 'ai_content', label: 'AI-Generated / Deepfake', icon: 'fa-robot', desc: 'Synthetic content pretending to be real' },
    { id: 'other', label: 'Something Else', icon: 'fa-flag', desc: 'Other violation not listed above' }
];

function openReportMenu(contentId, contentType) {
    contentType = contentType || 'post';
    contentId = escapeHtml(String(contentId || ''));
    contentType = escapeHtml(String(contentType));
    var existing = document.getElementById('reportOverlay');
    if (existing) existing.remove();

    var overlay = document.createElement('div');
    overlay.id = 'reportOverlay';
    overlay.style.cssText =
        'position:fixed; top:0; left:0; right:0; bottom:0; z-index:10000;' +
        'background:rgba(0,0,0,0.5); backdrop-filter:blur(10px);' +
        'display:flex; align-items:flex-end; justify-content:center;';

    var html =
        '<div id="reportSheet" style="' +
        'background:var(--card-bg,#fff); border-radius:20px 20px 0 0;' +
        'width:100%; max-width:500px; max-height:85vh; overflow-y:auto;' +
        'animation:slideUpShare 0.3s ease forwards; padding-bottom:40px;">' +
        '<div style="width:40px; height:4px; background:var(--text-tertiary,#ccc);' +
        'border-radius:2px; margin:12px auto 16px;"></div>' +
        '<div style="padding:0 20px 16px; border-bottom:1px solid var(--border-color,#eee);">' +
        '<h3 style="font-size:20px; font-weight:800; color:var(--text-primary,#000);">Report</h3>' +
        '<p style="font-size:13px; color:var(--text-secondary,#888); margin-top:4px;">' +
        'Why are you reporting this ' + contentType + '?</p></div>' +
        '<div style="padding:8px 0;">';

    FLAG_REASONS.forEach(function(reason) {
        html +=
            '<div onclick="submitReport(\'' + contentId + '\',\'' + contentType + '\',\'' + reason.id + '\')" style="' +
            'display:flex; align-items:center; gap:14px; padding:14px 20px;' +
            'cursor:pointer; transition:background 0.2s;' +
            'border-bottom:1px solid var(--border-color,#f0f0f0);"' +
            'onmouseover="this.style.background=\'var(--hover-bg,#f5f5f5)\'"' +
            'onmouseout="this.style.background=\'transparent\'">' +
            '<div style="width:40px; height:40px; border-radius:12px;' +
            'background:rgba(255,59,48,0.08); display:flex; align-items:center;' +
            'justify-content:center; flex-shrink:0;">' +
            '<i class="fa-solid ' + reason.icon + '" style="color:#FF3B30; font-size:16px;"></i></div>' +
            '<div style="flex:1;">' +
            '<b style="font-size:15px; color:var(--text-primary,#000); display:block;">' + reason.label + '</b>' +
            '<small style="color:var(--text-secondary,#888); font-size:12px;">' + reason.desc + '</small></div>' +
            '<i class="fa-solid fa-chevron-right" style="color:var(--text-tertiary,#ccc); font-size:12px;"></i></div>';
    });

    html += '</div>' +
        '<div style="padding:16px 20px;">' +
        '<button onclick="closeReportMenu()" style="' +
        'width:100%; padding:14px; border-radius:14px; border:none;' +
        'background:var(--bg-secondary,#f5f5f5); color:var(--text-primary,#000);' +
        'font-size:16px; font-weight:600; cursor:pointer;">Cancel</button></div></div>';

    overlay.innerHTML = html;
    overlay.addEventListener('click', function(e) {
        if (e.target === overlay) closeReportMenu();
    });
    document.body.appendChild(overlay);
}

async function submitReport(contentId, contentType, reasonId) {
    var reason = FLAG_REASONS.find(function(r) { return r.id === reasonId; });

    // Show confirmation with optional details
    var sheet = document.getElementById('reportSheet');
    if (!sheet) return;

    sheet.innerHTML =
        '<div style="width:40px; height:4px; background:var(--text-tertiary,#ccc);' +
        'border-radius:2px; margin:12px auto 20px;"></div>' +
        '<div style="padding:20px; text-align:center;">' +
        '<div style="width:60px; height:60px; border-radius:50%;' +
        'background:rgba(255,59,48,0.1); display:flex; align-items:center;' +
        'justify-content:center; margin:0 auto 16px;">' +
        '<i class="fa-solid ' + reason.icon + '" style="font-size:28px; color:#FF3B30;"></i></div>' +
        '<h3 style="font-size:18px; font-weight:700; color:var(--text-primary,#000);' +
        'margin-bottom:8px;">' + reason.label + '</h3>' +
        '<p style="font-size:13px; color:var(--text-secondary,#888); margin-bottom:20px;">' +
        'Add details to help us review faster (optional)</p>' +
        '<textarea id="reportDetails" placeholder="Describe what happened..." style="' +
        'width:100%; height:100px; padding:14px; border-radius:14px;' +
        'border:1px solid var(--border-color,#eee); background:var(--input-bg,#f5f5f5);' +
        'color:var(--text-primary,#000); font-size:14px; outline:none;' +
        'resize:none; box-sizing:border-box; margin-bottom:16px;"></textarea>' +
        '<label style="display:flex; align-items:center; gap:10px; margin-bottom:20px;' +
        'cursor:pointer; padding:12px; background:var(--bg-secondary,#f5f5f5);' +
        'border-radius:12px;">' +
        '<input type="checkbox" id="reportBlock" style="width:20px; height:20px; accent-color:#007AFF;">' +
        '<span style="font-size:14px; color:var(--text-primary,#000);">Also block this user</span></label>' +
        '<button onclick="finalizeReport(\'' + contentId + '\',\'' + contentType + '\',\'' + reasonId + '\')" style="' +
        'width:100%; padding:16px; border-radius:14px; border:none;' +
        'background:#FF3B30; color:white; font-size:16px; font-weight:700;' +
        'cursor:pointer; margin-bottom:10px;">Submit Report</button>' +
        '<button onclick="closeReportMenu()" style="' +
        'width:100%; padding:14px; border-radius:14px; border:none;' +
        'background:transparent; color:var(--text-secondary,#888);' +
        'font-size:14px; cursor:pointer;">Cancel</button></div>';
}

async function finalizeReport(contentId, contentType, reasonId) {
    var details = (document.getElementById('reportDetails') || {}).value || '';
    var alsoBlock = (document.getElementById('reportBlock') || {}).checked || false;

    var reportData = {
        content_id: contentId,
        content_type: contentType,
        reason: reasonId,
        details: details.trim(),
        reporter_id: currentUser ? currentUser.id : 'anonymous',
        timestamp: new Date().toISOString(),
        status: 'pending'
    };

    // Save to Supabase if available
    try {
        if (window.sb && currentUser) {
            await sb.from('content_reports').insert(reportData);
        }
    } catch(e) {
        console.warn('[Report] DB save failed, saving locally');
    }

    // Always save locally as backup
    var reports = JSON.parse(localStorage.getItem('trustfirst-reports') || '[]');
    reports.push(reportData);
    localStorage.setItem('trustfirst-reports', JSON.stringify(reports));

    // Show thank you
    var sheet = document.getElementById('reportSheet');
    if (sheet) {
        sheet.innerHTML =
            '<div style="padding:60px 20px; text-align:center;">' +
            '<div style="width:80px; height:80px; border-radius:50%;' +
            'background:rgba(52,199,89,0.1); display:flex; align-items:center;' +
            'justify-content:center; margin:0 auto 20px;">' +
            '<i class="fa-solid fa-check" style="font-size:40px; color:#34C759;"></i></div>' +
            '<h3 style="font-size:20px; font-weight:800; color:var(--text-primary,#000);' +
            'margin-bottom:8px;">Report Submitted</h3>' +
            '<p style="font-size:14px; color:var(--text-secondary,#888); line-height:1.5;' +
            'margin-bottom:24px;">Thank you for keeping TrustFirst safe. We\'ll review this within 24 hours.' +
            (alsoBlock ? '<br><br><b>User has been blocked.</b>' : '') + '</p>' +
            '<button onclick="closeReportMenu()" style="' +
            'padding:14px 40px; border-radius:14px; border:none;' +
            'background:#007AFF; color:white; font-size:16px; font-weight:600;' +
            'cursor:pointer;">Done</button></div>';
    }

    triggerHaptic(30);
}

function closeReportMenu() {
    var overlay = document.getElementById('reportOverlay');
    if (overlay) overlay.remove();
}

