    // ============================================
// USERNAME SYSTEM
// Display names can duplicate, usernames cannot
// ============================================
var usernameCheckTimer = null;

function checkUsernameAvailability(raw) {
    var statusEl = document.getElementById('username-status');
    if (!statusEl) return;

    // Clean the input — lowercase, no spaces, only letters/numbers/dots/underscores
    var cleaned = raw.toLowerCase().replace(/[^a-z0-9_]/g, '');
    var input = document.getElementById('reg-username');
    if (input && input.value !== cleaned) {
        input.value = cleaned;
    }

    if (cleaned.length < 3) {
        statusEl.innerHTML = '<span style="color:#888;">Minimum 3 characters</span>';
        return;
    }

    if (cleaned.length > 25) {
        statusEl.innerHTML = '<span style="color:#FF3B30;">Maximum 25 characters</span>';
        return;
    }

    // Reserved words
    var reserved = ['admin','trustfirst','official','support','help','system',
        'moderator','mod','staff','null','undefined','root','api'];
    if (reserved.indexOf(cleaned) > -1) {
        statusEl.innerHTML = '<span style="color:#FF3B30;"><i class="fa-solid fa-xmark"></i> This username is reserved</span>';
        return;
    }

    statusEl.innerHTML = '<span style="color:#888;"><i class="fa-solid fa-spinner fa-spin"></i> Checking...</span>';

    clearTimeout(usernameCheckTimer);
    usernameCheckTimer = setTimeout(async function() {
        try {
            if (window.sb) {
                var result = await sb.from('users')
                    .select('username')
                    .eq('username', cleaned)
                    .maybeSingle();

                if (result.data) {
                    statusEl.innerHTML = '<span style="color:#FF3B30;"><i class="fa-solid fa-xmark"></i> @' + cleaned + ' is taken, try @' + cleaned + '_' + Math.floor(Math.random()*99) + '</span>';
                } else {
                    statusEl.innerHTML = '<span style="color:#34C759;"><i class="fa-solid fa-check"></i> @' + cleaned + ' is available!</span>';
                }
            } else {
                statusEl.innerHTML = '<span style="color:#34C759;"><i class="fa-solid fa-check"></i> @' + cleaned + ' looks good</span>';
            }
        } catch(e) {
            statusEl.innerHTML = '<span style="color:#34C759;"><i class="fa-solid fa-check"></i> @' + cleaned + ' looks good</span>';
        }
    }, 500);
}

