// Government email domains
var GOV_EMAIL_DOMAINS = [
    '.gov', '.gov.za', '.gov.uk', '.gov.us', '.gov.au', '.gov.ca',
    '.gov.ng', '.gov.gh', '.gov.ke', '.gov.in', '.gov.br',
    '.mil', '.edu', '.ac.za', '.parliament', '.state.gov',
    '.gob.mx', '.gouv.fr', '.bund.de', '.gov.it', '.gov.jp'
];

function isGovEmail(email) {
    if (!email) return false;
    email = email.toLowerCase().trim();
    return GOV_EMAIL_DOMAINS.some(function(domain) {
        return email.endsWith(domain);
    });
}

// ============================================
// VERIFICATION FLOW PER ACCOUNT TYPE
// ============================================



function startVerificationForType(accountType) {
    switch(accountType) {
        case 'personal':
            nextAuthStep('step-verify');
            break;

        case 'child':
            nextAuthStep('step-parent-link');
            break;

        case 'business':
            showBusinessVerification();
            break;

        case 'government':
            showGovernmentVerification();
            break;

        default:
            nextAuthStep('step-verify');
    }
}

