function adminGrantGoldBadge(userId) {
    // Only admins can call this
    if (!currentUser || currentUser.role !== 'admin') {
        showToast('Only admins can grant gold badges');
        return;
    }

    var reason = prompt('Reason for granting gold badge to this user:');
    if (!reason) return;

    var confirmation = confirm(
        'Grant GOLD PUBLIC FIGURE badge to this user?\n\n' +
        'Reason: ' + reason + '\n\n' +
        'This gives them the highest trust tier.'
    );

    if (!confirmation) return;

    // Save to Supabase
    if (window.sb) {
        sb.from('users').update({
            account_type: 'public_figure',
            verified: true,
            gold_badge_reason: reason,
            gold_badge_granted_by: currentUser.id,
            gold_badge_granted_at: new Date().toISOString()
        }).eq('id', userId).then(function() {
            showToast('Gold badge granted ✨');
        });
    }
}

function adminRevokeGoldBadge(userId) {
    if (!currentUser || currentUser.role !== 'admin') return;
    if (!confirm('Revoke gold badge from this user?')) return;

    if (window.sb) {
        sb.from('users').update({
            account_type: 'personal',
            gold_badge_reason: null,
            gold_badge_granted_by: null,
            gold_badge_granted_at: null
        }).eq('id', userId).then(function() {
            showToast('Gold badge revoked');
        });
    }
}

// ============================================
// CHILD ACCOUNT LINKING (Enhanced)
// ============================================

function linkParentAccount() {
    var parentId = (document.getElementById('parent-link-id') || {}).value || '';
    if (!parentId.trim()) {
        showToast('Enter your parent\'s Trust-ID');
        return;
    }

    // Check if parent exists and is verified
    if (window.sb) {
        sb.from('users')
            .select('id, username, full_name, name, verified, account_type, badge_tier')
            .eq('username', parentId.trim().toLowerCase().replace('@',''))
            .maybeSingle()
            .then(function(result) {
                if (!result.data) {
                    showToast('Parent account not found. Check the username.');
                    return;
                }
                if (!result.data.verified) {
                    showToast('Parent must be verified before linking a Kids account');
                    return;
                }
                if (result.data.account_type === 'child') {
                    showToast('A child account cannot be a parent');
                    return;
                }

                // Send link request
                secureSave('parent_link_request', {
                    parent_id: result.data.id,
                    parent_username: result.data.username,
                    parent_name: result.data.full_name || result.data.name || result.data.username,
                    parent_badge: result.data.badge_tier,
                    status: 'pending',
                    timestamp: Date.now()
                });

                showToast('Link request sent. Your parent can approve it in Family Center.');
                sb.from('notifications').insert({
                    user_id: result.data.id,
                    type: 'child_link_request',
                    message: 'A child account wants to link to you in Family Center',
                    preview_text: 'Open Family Center to approve',
                    read: false
                }).then(function(){}).catch(function(){});
                setTimeout(function() {
                    completeRegistration(false);
                }, 2000);
            });
    } else {
        // Offline fallback
        secureSave('parent_link_request', {
            parent_username: parentId.trim(),
            status: 'pending',
            timestamp: Date.now()
        });
        showToast('Link request saved. Parent must approve when online.');
        setTimeout(function() { completeRegistration(false); }, 2000);
    }
}

