    // ============================================
// TRUSTFIRST REAL-TIME TRUST SCORE ENGINE
// ============================================
// Score range: 0-100
// Categories: Verification, Security, Account Age,
// Community, Identity Consistency, Activity Quality

var TRUST_WEIGHTS = {
    verification: 25,    // Max 25 pts
    security: 20,        // Max 20 pts
    account_age: 15,     // Max 15 pts
    community: 20,       // Max 20 pts
    identity: 10,        // Max 10 pts
    activity: 10         // Max 10 pts
};

// ============================================
// CORE CALCULATOR
// ============================================
function calculateTrustScore(userData) {
    if (!userData) userData = buildUserData();

    var scores = {
        verification: calcVerificationScore(userData),
        security: calcSecurityScore(userData),
        account_age: calcAccountAgeScore(userData),
        community: calcCommunityScore(userData),
        identity: calcIdentityScore(userData),
        activity: calcActivityScore(userData)
    };

    var total = 0;
    var breakdown = {};

    Object.keys(scores).forEach(function(key) {
        var raw = scores[key];
        var weighted = Math.round((raw.score / 100) * TRUST_WEIGHTS[key]);
        breakdown[key] = {
            raw: raw.score,
            weighted: weighted,
            max: TRUST_WEIGHTS[key],
            label: raw.label,
            details: raw.details,
            suggestions: raw.suggestions || []
        };
        total += weighted;
    });

    total = Math.max(0, Math.min(100, total));

    return {
        total: total,
        tier: getTrustTier(total),
        breakdown: breakdown,
        timestamp: Date.now()
    };
}

function getTrustTier(score) {
    if (score >= 90) return { name: 'Elite', color: '#FFD700', icon: 'fa-crown', bg: 'linear-gradient(135deg, #FFD700, #FFA500)' };
    if (score >= 75) return { name: 'Trusted', color: '#34C759', icon: 'fa-shield-halved', bg: 'linear-gradient(135deg, #34C759, #30D158)' };
    if (score >= 55) return { name: 'Established', color: '#007AFF', icon: 'fa-circle-check', bg: 'linear-gradient(135deg, #007AFF, #00C7FF)' };
    if (score >= 35) return { name: 'Building', color: '#FF9500', icon: 'fa-seedling', bg: 'linear-gradient(135deg, #FF9500, #FFCC00)' };
    if (score >= 15) return { name: 'New', color: '#888', icon: 'fa-user', bg: 'linear-gradient(135deg, #888, #aaa)' };
    return { name: 'Unverified', color: '#FF3B30', icon: 'fa-triangle-exclamation', bg: 'linear-gradient(135deg, #FF3B30, #FF6B6B)' };
}

// ============================================
// BUILD USER DATA FROM LOCAL STORAGE
// ============================================
function buildUserData() {
    var stored = secureLoad('trustfirst-session') || {};
    var loginHistory = JSON.parse(localStorage.getItem('tf-login-history') || '[]');
    var nameChanges = JSON.parse(localStorage.getItem('tf-name-changes') || '[]');
    var postHistory = JSON.parse(localStorage.getItem('tf-post-history') || '[]');
    var reports = JSON.parse(localStorage.getItem('tf-user-reports') || '[]');
    var violations = JSON.parse(localStorage.getItem('tf-violations') || '[]');

    return {
        verified: stored.verified || false,
        verification_method: stored.verification_method || 'none',
        account_type: stored.account_type || 'personal',
        created_at: stored.created_at || new Date().toISOString(),
        two_fa_enabled: stored.two_fa_enabled || false,
        password_strength: stored.password_strength || 'weak',
        failed_logins: (loginHistory.filter(function(l) { return l.failed; })).length,
        suspicious_logins: (loginHistory.filter(function(l) { return l.suspicious; })).length,
        total_logins: loginHistory.length,
        name_changes: nameChanges.length,
        profile_changes: parseInt(localStorage.getItem('tf-profile-changes') || '0'),
        reports_received: reports.length,
        confirmed_violations: violations.length,
        total_posts: postHistory.length,
        posts_today: countPostsToday(postHistory),
        avg_post_length: avgPostLength(postHistory),
        replies_sent: parseInt(localStorage.getItem('tf-replies') || '0'),
        likes_received: parseInt(localStorage.getItem('tf-likes-received') || '0'),
        reported_others: parseInt(localStorage.getItem('tf-reports-made') || '0'),
        blocked_by_count: parseInt(localStorage.getItem('tf-blocked-by') || '0')
    };
}

function countPostsToday(posts) {
    var today = new Date().toDateString();
    return posts.filter(function(p) {
        return new Date(p.timestamp).toDateString() === today;
    }).length;
}

function avgPostLength(posts) {
    if (posts.length === 0) return 0;
    var total = posts.reduce(function(sum, p) { return sum + (p.text || '').length; }, 0);
    return Math.round(total / posts.length);
}

// ============================================
// 1. VERIFICATION SCORE (25 pts max)
// ============================================
function calcVerificationScore(data) {
    var score = 0;
    var details = [];
    var suggestions = [];

    if (data.account_type === 'government' && data.verified) {
        score = 100;
        details.push({ text: 'Government verified (Elite)', pts: '+25', positive: true });
    } else if (data.verified && (data.verification_method === 'face_verify' || data.verification_method === 'stripe_id')) {
        score = 85;
        details.push({ text: 'Strong verification (ID or Face)', pts: '+21', positive: true });
    } else if (data.verified) {
        score = 60;
        details.push({ text: 'Basic verification (Email/Phone)', pts: '+15', positive: true });
        suggestions.push('Upgrade to Face or ID verification for a higher score');
    } else {
        score = 10;
        details.push({ text: 'Not verified', pts: '+2', positive: false });
        suggestions.push('Verify your identity to unlock full features');
    }

    return { score: score, label: 'Verification Strength', details: details, suggestions: suggestions };
}

// ============================================
// 2. SECURITY SCORE (20 pts max)
// ============================================
function calcSecurityScore(data) {
    var score = 50;
    var details = [];
    var suggestions = [];

    // 2FA
    if (data.two_fa_enabled) {
        score += 25;
        details.push({ text: 'Two-factor authentication enabled', pts: '+5', positive: true });
    } else {
        suggestions.push('Enable 2FA to increase your score by 5 points');
        details.push({ text: 'No 2FA enabled', pts: '0', positive: false });
    }

    // Password strength
    if (data.password_strength === 'strong') {
        score += 15;
        details.push({ text: 'Strong password', pts: '+3', positive: true });
    } else if (data.password_strength === 'medium') {
        score += 8;
        details.push({ text: 'Medium password', pts: '+1', positive: false });
        suggestions.push('Use a stronger password with symbols and numbers');
    } else {
        details.push({ text: 'Weak password', pts: '0', positive: false });
        suggestions.push('Your password is weak, update it in Security settings');
    }

    // Failed logins penalty
    if (data.failed_logins > 10) {
        score -= 25;
        details.push({ text: data.failed_logins + ' failed login attempts', pts: '-5', positive: false });
    } else if (data.failed_logins > 5) {
        score -= 15;
        details.push({ text: data.failed_logins + ' failed login attempts', pts: '-3', positive: false });
    } else if (data.failed_logins === 0) {
        score += 10;
        details.push({ text: 'No failed login attempts', pts: '+2', positive: true });
    }

    // Suspicious logins
    if (data.suspicious_logins > 0) {
        score -= (data.suspicious_logins * 10);
        details.push({ text: data.suspicious_logins + ' suspicious login(s) detected', pts: '-' + (data.suspicious_logins * 2), positive: false });
    }

    score = Math.max(0, Math.min(100, score));
    return { score: score, label: 'Security Health', details: details, suggestions: suggestions };
}

// ============================================
// 3. ACCOUNT AGE SCORE (15 pts max)
// ============================================
function calcAccountAgeScore(data) {
    var created = new Date(data.created_at);
    var now = new Date();
    var daysSince = Math.floor((now - created) / (1000 * 60 * 60 * 24));
    var score = 0;
    var details = [];

    if (daysSince >= 365) {
        score = 100;
        details.push({ text: 'Account over 1 year old', pts: '+15', positive: true });
    } else if (daysSince >= 180) {
        score = 80;
        details.push({ text: 'Account ' + daysSince + ' days old', pts: '+12', positive: true });
    } else if (daysSince >= 90) {
        score = 60;
        details.push({ text: 'Account ' + daysSince + ' days old', pts: '+9', positive: true });
    } else if (daysSince >= 30) {
        score = 40;
        details.push({ text: 'Account ' + daysSince + ' days old', pts: '+6', positive: true });
    } else if (daysSince >= 7) {
        score = 20;
        details.push({ text: 'Account ' + daysSince + ' days old', pts: '+3', positive: true });
    } else {
        score = 5;
        details.push({ text: 'New account (' + daysSince + ' days)', pts: '+1', positive: false });
    }

    return { score: score, label: 'Account Stability', details: details, suggestions: daysSince < 30 ? ['Your score will naturally increase over time'] : [] };
}

// ============================================
// 4. COMMUNITY RELIABILITY (20 pts max)
// ============================================
function calcCommunityScore(data) {
    var score = 70;
    var details = [];
    var suggestions = [];

    // Reports received — big penalty
    if (data.reports_received === 0) {
        score += 15;
        details.push({ text: 'Zero reports from other users', pts: '+3', positive: true });
    } else if (data.reports_received <= 2) {
        score -= 10;
        details.push({ text: data.reports_received + ' report(s) received', pts: '-2', positive: false });
    } else if (data.reports_received <= 5) {
        score -= 30;
        details.push({ text: data.reports_received + ' reports received', pts: '-6', positive: false });
    } else {
        score -= 50;
        details.push({ text: data.reports_received + ' reports, high risk', pts: '-10', positive: false });
    }

    // Confirmed violations — severe penalty
    if (data.confirmed_violations > 0) {
        score -= (data.confirmed_violations * 20);
        details.push({ text: data.confirmed_violations + ' confirmed violation(s)', pts: '-' + (data.confirmed_violations * 4), positive: false });
        suggestions.push('Violations significantly reduce your trust score');
    } else {
        score += 10;
        details.push({ text: 'No confirmed violations', pts: '+2', positive: true });
    }

    // Blocked by others
    if (data.blocked_by_count > 5) {
        score -= 15;
        details.push({ text: 'Blocked by ' + data.blocked_by_count + ' users', pts: '-3', positive: false });
    }

    // Positive interactions
    if (data.likes_received > 50) {
        score += 10;
        details.push({ text: 'Well-received content (' + data.likes_received + ' likes)', pts: '+2', positive: true });
    }

    score = Math.max(0, Math.min(100, score));
    return { score: score, label: 'Community Standing', details: details, suggestions: suggestions };
}

// ============================================
// 5. IDENTITY CONSISTENCY (10 pts max)
// ============================================
function calcIdentityScore(data) {
    var score = 80;
    var details = [];
    var suggestions = [];

    // Name changes
    if (data.name_changes === 0) {
        score += 20;
        details.push({ text: 'No name changes', pts: '+2', positive: true });
    } else if (data.name_changes <= 2) {
        score -= 5;
        details.push({ text: data.name_changes + ' name change(s)', pts: '-0.5', positive: false });
    } else {
        score -= (data.name_changes * 8);
        details.push({ text: data.name_changes + ' name changes, inconsistent', pts: '-' + Math.min(5, data.name_changes), positive: false });
        suggestions.push('Frequent name changes reduce trust, keep your identity consistent');
    }

    // Profile changes
    if (data.profile_changes > 10) {
        score -= 15;
        details.push({ text: 'Frequent profile switching', pts: '-1.5', positive: false });
    } else {
        details.push({ text: 'Stable profile identity', pts: '+1', positive: true });
    }

    score = Math.max(0, Math.min(100, score));
    return { score: score, label: 'Identity Consistency', details: details, suggestions: suggestions };
}

// ============================================
// 6. ACTIVITY QUALITY (10 pts max)
// ============================================
function calcActivityScore(data) {
    var score = 50;
    var details = [];
    var suggestions = [];

    // Post quality — avg length
    if (data.avg_post_length > 100) {
        score += 20;
        details.push({ text: 'Meaningful posts (avg ' + data.avg_post_length + ' chars)', pts: '+2', positive: true });
    } else if (data.avg_post_length > 40) {
        score += 10;
        details.push({ text: 'Decent post quality', pts: '+1', positive: true });
    } else if (data.total_posts > 0) {
        details.push({ text: 'Short posts, try adding more detail', pts: '0', positive: false });
        suggestions.push('Longer, more thoughtful posts increase your score');
    }

    // Spam detection — too many posts today
    if (data.posts_today > 20) {
        score -= 30;
        details.push({ text: data.posts_today + ' posts today, possible spam', pts: '-3', positive: false });
        suggestions.push('Quality over quantity, space out your posts');
    } else if (data.posts_today > 10) {
        score -= 10;
        details.push({ text: data.posts_today + ' posts today, a lot', pts: '-1', positive: false });
    } else if (data.posts_today > 0) {
        score += 10;
        details.push({ text: 'Healthy posting frequency', pts: '+1', positive: true });
    }

    // Real conversations — replies
    if (data.replies_sent > 20) {
        score += 20;
        details.push({ text: 'Active in conversations (' + data.replies_sent + ' replies)', pts: '+2', positive: true });
    } else if (data.replies_sent > 5) {
        score += 10;
        details.push({ text: 'Engages with community', pts: '+1', positive: true });
    } else {
        suggestions.push('Reply to posts and have conversations to build trust');
    }

    score = Math.max(0, Math.min(100, score));
    return { score: score, label: 'Activity Quality', details: details, suggestions: suggestions };
}

// ============================================
// RENDER TRUST SCORE UI
// ============================================
function renderTrustScore() {
    var container = document.getElementById('trust-score-content');
    if (!container) return;

    var result = calculateTrustScore();
    var tier = result.tier;
    var total = result.total;

    var html =
        // Hero card with animated ring
        '<div style="background:' + tier.bg + '; border-radius:24px; padding:30px; text-align:center; margin-bottom:20px; position:relative; overflow:hidden;">' +
        '<div style="position:absolute; top:0; left:0; right:0; bottom:0; background:rgba(0,0,0,0.1);"></div>' +
        '<div style="position:relative; z-index:1;">' +

        // SVG Ring
        '<div style="width:140px; height:140px; margin:0 auto 16px; position:relative;">' +
        '<svg width="140" height="140" viewBox="0 0 140 140" style="transform:rotate(-90deg);">' +
        '<circle cx="70" cy="70" r="60" fill="none" stroke="rgba(255,255,255,0.2)" stroke-width="10"/>' +
        '<circle cx="70" cy="70" r="60" fill="none" stroke="white" stroke-width="10" ' +
        'stroke-linecap="round" stroke-dasharray="' + Math.round(377 * total / 100) + ' 377" ' +
        'style="transition: stroke-dasharray 1.5s cubic-bezier(0.4,0,0.2,1);"/>' +
        '</svg>' +
        '<div style="position:absolute; top:50%; left:50%; transform:translate(-50%,-50%); text-align:center;">' +
        '<div style="font-size:36px; font-weight:900; color:white;">' + total + '</div>' +
        '<div style="font-size:11px; color:rgba(255,255,255,0.8); font-weight:600;">of 100</div>' +
        '</div></div>' +

        '<div style="display:flex; align-items:center; justify-content:center; gap:8px; margin-bottom:4px;">' +
        '<i class="fa-solid ' + tier.icon + '" style="color:white; font-size:18px;"></i>' +
        '<span style="color:white; font-size:20px; font-weight:800;">' + tier.name + '</span></div>' +
        '<p style="color:rgba(255,255,255,0.7); font-size:13px;">Your trust level on TrustFirst</p>' +
        '</div></div>' +

        // Real-time indicator
        '<div style="display:flex; align-items:center; gap:8px; margin-bottom:20px; padding:10px 14px; background:rgba(52,199,89,0.08); border-radius:12px;">' +
        '<div style="width:8px; height:8px; border-radius:50%; background:#34C759; animation:pulse 2s infinite;"></div>' +
        '<small style="color:#34C759; font-weight:600;">Score updates in real-time based on your activity</small></div>';

    // Category breakdowns
    var categories = [
        { key: 'verification', icon: 'fa-id-badge', color: '#007AFF' },
        { key: 'security', icon: 'fa-shield-halved', color: '#FF9500' },
        { key: 'account_age', icon: 'fa-clock', color: '#5856D6' },
        { key: 'community', icon: 'fa-users', color: '#34C759' },
        { key: 'identity', icon: 'fa-fingerprint', color: '#FF2D55' },
        { key: 'activity', icon: 'fa-chart-line', color: '#00C7FF' }
    ];

    categories.forEach(function(cat) {
        var data = result.breakdown[cat.key];
        var pct = Math.round((data.weighted / data.max) * 100);

        html +=
            '<div style="background:var(--card-bg,#fff); border:1px solid var(--border-color,#f0f0f0); border-radius:18px; padding:18px; margin-bottom:12px;">' +

            // Header row
            '<div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:12px;">' +
            '<div style="display:flex; align-items:center; gap:10px;">' +
            '<div style="width:36px; height:36px; border-radius:10px; background:' + cat.color + '15; display:flex; align-items:center; justify-content:center;">' +
            '<i class="fa-solid ' + cat.icon + '" style="color:' + cat.color + '; font-size:16px;"></i></div>' +
            '<div><b style="font-size:14px; color:var(--text-primary,#000);">' + data.label + '</b></div></div>' +
            '<div style="text-align:right;">' +
            '<b style="font-size:16px; color:' + cat.color + ';">' + data.weighted + '</b>' +
            '<small style="color:var(--text-tertiary,#999);">/' + data.max + '</small></div></div>' +

            // Progress bar
            '<div style="width:100%; height:6px; background:var(--bg-secondary,#f0f0f0); border-radius:3px; overflow:hidden; margin-bottom:12px;">' +
            '<div style="height:100%; width:' + pct + '%; background:' + cat.color + '; border-radius:3px; transition:width 1s ease;"></div></div>';

        // Detail items
        data.details.forEach(function(d) {
            html +=
                '<div style="display:flex; align-items:center; justify-content:space-between; padding:6px 0;">' +
                '<div style="display:flex; align-items:center; gap:8px;">' +
                '<i class="fa-solid ' + (d.positive ? 'fa-circle-check' : 'fa-circle-xmark') + '" style="color:' + (d.positive ? '#34C759' : '#FF3B30') + '; font-size:12px;"></i>' +
                '<small style="color:var(--text-secondary,#666); font-size:12px;">' + d.text + '</small></div>' +
                '<small style="color:' + (d.positive ? '#34C759' : '#FF3B30') + '; font-weight:700; font-size:12px;">' + d.pts + '</small></div>';
        });

        // Suggestions
        if (data.suggestions.length > 0) {
            data.suggestions.forEach(function(s) {
                html +=
                    '<div style="margin-top:8px; padding:8px 12px; background:rgba(255,149,0,0.06); border-radius:10px; display:flex; align-items:center; gap:8px;">' +
                    '<i class="fa-solid fa-lightbulb" style="color:#FF9500; font-size:12px;"></i>' +
                    '<small style="color:#FF9500; font-size:11px; font-weight:600;">' + s + '</small></div>';
            });
        }

        html += '</div>';
    });

    // How scoring works section
    html +=
        '<div style="margin-top:8px; padding:18px; background:var(--card-bg,#fff); border:1px solid var(--border-color,#f0f0f0); border-radius:18px;">' +
        '<div style="display:flex; align-items:center; gap:10px; margin-bottom:14px;">' +
        '<i class="fa-solid fa-circle-info" style="color:#007AFF;"></i>' +
        '<b style="font-size:14px; color:var(--text-primary,#000);">How Trust Score Works</b></div>' +
        '<p style="font-size:12px; color:var(--text-secondary,#888); line-height:1.6; margin-bottom:12px;">' +
        'Your Trust Score is calculated in real-time across 6 categories. ' +
        'It reflects how trustworthy and authentic your presence is on TrustFirst.</p>' +

        '<div style="display:grid; grid-template-columns:1fr 1fr; gap:8px;">';

    Object.keys(TRUST_WEIGHTS).forEach(function(key) {
        var cat = categories.find(function(c) { return c.key === key; });
        html +=
            '<div style="padding:10px; background:var(--bg-secondary,#f5f5f5); border-radius:10px; text-align:center;">' +
            '<b style="font-size:16px; color:' + (cat ? cat.color : '#000') + ';">' + TRUST_WEIGHTS[key] + '</b>' +
            '<small style="display:block; color:var(--text-tertiary,#999); font-size:10px; margin-top:2px;">' +
            key.replace('_', ' ').toUpperCase() + '</small></div>';
    });

    html += '</div></div>' +

        // Tier legend
        '<div style="margin-top:12px; padding:18px; background:var(--card-bg,#fff); border:1px solid var(--border-color,#f0f0f0); border-radius:18px;">' +
        '<b style="font-size:14px; color:var(--text-primary,#000); display:block; margin-bottom:12px;">Trust Tiers</b>';

    var tiers = [
        { min: 90, name: 'Elite', color: '#FFD700' },
        { min: 75, name: 'Trusted', color: '#34C759' },
        { min: 55, name: 'Established', color: '#007AFF' },
        { min: 35, name: 'Building', color: '#FF9500' },
        { min: 15, name: 'New', color: '#888' },
        { min: 0, name: 'Unverified', color: '#FF3B30' }
    ];

    tiers.forEach(function(t) {
        var isCurrent = tier.name === t.name;
        html +=
            '<div style="display:flex; align-items:center; gap:10px; padding:8px 10px; border-radius:10px;' +
            (isCurrent ? 'background:' + t.color + '10;' : '') + '">' +
            '<div style="width:12px; height:12px; border-radius:50%; background:' + t.color + ';' +
            (isCurrent ? 'box-shadow:0 0 8px ' + t.color + ';' : '') + '"></div>' +
            '<small style="flex:1; color:var(--text-secondary,#666); font-weight:' + (isCurrent ? '800' : '500') + ';">' +
            t.name + '</small>' +
            '<small style="color:var(--text-tertiary,#999);">' + t.min + '+</small></div>';
    });

    html += '</div>';

    container.innerHTML = html;

    // Save score
    secureSave('trust-score-cache', result);
}

// ============================================
// REAL-TIME SCORE TRACKING — LOG EVENTS
// ============================================
function logTrustEvent(type, data) {
    var events = JSON.parse(localStorage.getItem('tf-trust-events') || '[]');
    events.push({
        type: type,
        data: data || {},
        timestamp: Date.now()
    });
    // Keep last 500 events
    if (events.length > 500) events = events.slice(-500);
    localStorage.setItem('tf-trust-events', JSON.stringify(events));

    // Recalculate if score page is open
    if (document.getElementById('trust-score-overlay') &&
        document.getElementById('trust-score-overlay').style.display !== 'none') {
        renderTrustScore();
    }
}

// Track name changes
function trackNameChange(oldName, newName) {
    var changes = JSON.parse(localStorage.getItem('tf-name-changes') || '[]');
    changes.push({ from: oldName, to: newName, timestamp: Date.now() });
    localStorage.setItem('tf-name-changes', JSON.stringify(changes));
    logTrustEvent('name_change', { from: oldName, to: newName });
}

// Track posts
function trackNewPost(postText) {
    var history = JSON.parse(localStorage.getItem('tf-post-history') || '[]');
    history.push({ text: postText, timestamp: Date.now() });
    localStorage.setItem('tf-post-history', JSON.stringify(history));
    logTrustEvent('new_post', { length: postText.length });
    var analyticsStore = JSON.parse(localStorage.getItem('tf-analytics-posts') || '[]');
analyticsStore.unshift({ text: postText, ts: new Date().toISOString() });
localStorage.setItem('tf-analytics-posts', JSON.stringify(analyticsStore.slice(0, 200)));
}

// Track login
function trackLogin(success, suspicious) {
    var history = JSON.parse(localStorage.getItem('tf-login-history') || '[]');
    history.push({
        success: success,
        failed: !success,
        suspicious: suspicious || false,
        timestamp: Date.now()
    });
    localStorage.setItem('tf-login-history', JSON.stringify(history));
    if (!success) logTrustEvent('failed_login');
    if (suspicious) logTrustEvent('suspicious_login');
}

// Track reports received
function trackReportReceived(reason) {
    var reports = JSON.parse(localStorage.getItem('tf-user-reports') || '[]');
    reports.push({ reason: reason, timestamp: Date.now() });
    localStorage.setItem('tf-user-reports', JSON.stringify(reports));
    logTrustEvent('report_received', { reason: reason });
}

// Track replies
function trackReply() {
    var count = parseInt(localStorage.getItem('tf-replies') || '0');
    localStorage.setItem('tf-replies', String(count + 1));
    logTrustEvent('reply_sent');
}

// Track profile changes
function trackProfileChange() {
    var count = parseInt(localStorage.getItem('tf-profile-changes') || '0');
    localStorage.setItem('tf-profile-changes', String(count + 1));
    logTrustEvent('profile_change');
}

// ============================================
// QUICK TRUST BADGE FOR PROFILE/POSTS
// ============================================
function getTrustBadgeHTML() {
    var cached = secureLoad('trust-score-cache');
    if (!cached || typeof cached !== 'object' || !cached.total) {
        cached = calculateTrustScore();
    }

    var tier = cached.tier || getTrustTier(cached.total || 0);
    return '<span style="display:inline-flex; align-items:center; gap:4px; padding:2px 8px; ' +
        'background:' + tier.color + '15; border-radius:8px; font-size:11px; font-weight:700; color:' + tier.color + ';">' +
        '<i class="fa-solid ' + tier.icon + '" style="font-size:10px;"></i> ' + cached.total + '</span>';
}

    function navigateTo(page) {
    if (page === 'home' && typeof resetNav === 'function') {
        resetNav();
    } else if (page === 'reels' && typeof showReelsPage === 'function') {
        showReelsPage();
    } else if (typeof switchTab === 'function') {
        switchTab(page);
    }
}

 // ==========================================================================
// TRUSTFIRST — REAL DATA LAYER
// Paste at the END of your script, after all existing code
// ==========================================================================

var RealData = {

    async createPost(text, mediaUrl, mediaType, extra) {
        var client = window._sb || window.sb;
if (!client) { showToast('Not connected'); return null; }
var { data: { session } } = await client.auth.getSession();
if (!session) { showToast('Please log in'); return null; }

        var insertObj = {
            user_id: session.user.id,
            text_content: text,
            media_url: mediaUrl || null,
            media_type: mediaType || null,
            status: 'published',
            is_hidden: false
        };
        extra = extra || {};
        if (extra.location) {
            insertObj.location_name = extra.location.name || null;
            insertObj.location_address = extra.location.sub || extra.location.address || null;
            if (extra.location.lat != null && !isNaN(extra.location.lat)) insertObj.location_lat = extra.location.lat;
            if (extra.location.lng != null && !isNaN(extra.location.lng)) insertObj.location_lng = extra.location.lng;
        }
        if (extra.music) {
            // Store only the essentials (no fetched lyrics / internal fields).
            insertObj.thought_music = {
                name: extra.music.name || '', artist: extra.music.artist || '',
                artUrl: extra.music.artUrl || '', previewUrl: extra.music.previewUrl || '',
                style: extra.music.style || 1
            };
        }

        var { data, error } = await sb.from('posts').insert(insertObj)
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)').single();

        if (error) { showToast('Post failed: ' + error.message); return null; }
        return data;
    },

    async getFeed(page, limit) {
        page = page || 1; limit = limit || 20;
        var client = window._sb || window.sb;
if (!client) return [];
var { data: { session } } = await client.auth.getSession();
if (!session) return [];
var userId = session.user.id;
        var offset = (page - 1) * limit;

        var followRes = await client.from('follows').select('following_id').eq('follower_id', userId);
        var followIds = (followRes.data || []).map(function(f) { return f.following_id; });
        followIds.push(userId);

        var { data, error } = await client.from('posts')
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified), collab_user:collab_user_id (id, full_name, username, avatar_url, badge_tier, verified), quoted_post:quoted_post_id (id, text_content, media_url, thumbnail_url, post_type, media_type, users:user_id (full_name, username, avatar_url))')
            .in('user_id', followIds)
            .eq('is_hidden', false)
            .order('created_at', { ascending: false })
            .range(offset, offset + limit - 1);

        if (error) { console.error('[Feed]', error); return []; }

        var postIds = (data || []).map(function(p) { return p.id; });
        if (postIds.length === 0) return [];

        var likeRes = await client.from('likes').select('post_id').eq('user_id', userId).in('post_id', postIds);
        var likedIds = (likeRes.data || []).map(function(l) { return l.post_id; });

        var bmRes = await client.from('bookmarks').select('post_id').eq('user_id', userId).in('post_id', postIds);
        var bookmarkedIds = (bmRes.data || []).map(function(b) { return b.post_id; });

        var result = (data || []).map(function(p) {
            p._liked = likedIds.indexOf(p.id) > -1;
            p._bookmarked = bookmarkedIds.indexOf(p.id) > -1;
            return p;
        });
        // Kids-feed separation: child accounts only see content from approved
        // kids-content creators (white badge) — adult content never reaches the kids feed.
        if (typeof isChildAccount === 'function' && isChildAccount()) {
            result = result.filter(function(p) {
                return p.users && p.users.badge_tier === 'verify-white';
            });
        }
        return result;
    },

    async getDiscoverFeed(page, limit) {
        page = page || 1; limit = limit || 20;
        var offset = (page - 1) * limit;
        var { data, error } = await sb.from('posts')
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)')
            .eq('is_hidden', false)
            .order('created_at', { ascending: false })
            .range(offset, offset + limit - 1);
        return data || [];
    },

    async toggleLike(postId) {
        var session = await DB.getSession();
        if (!session) return;
        var userId = session.user.id;
        var check = await sb.from('likes').select('id').eq('user_id', userId).eq('post_id', postId).maybeSingle();
        if (check.data) {
            await sb.from('likes').delete().eq('id', check.data.id);
            var cur = await sb.from('posts').select('like_count').eq('id', postId).single();
            await sb.from('posts').update({ like_count: Math.max(0, (cur.data?.like_count || 1) - 1) }).eq('id', postId);
            return false;
        } else {
            await sb.from('likes').insert({ user_id: userId, post_id: postId });
            var cur = await sb.from('posts').select('like_count').eq('id', postId).single();
            await sb.from('posts').update({ like_count: (cur.data?.like_count || 0) + 1 }).eq('id', postId);
            tfNotifyLike(postId);
            return true;
        }
    },

    async toggleBookmark(postId) {
        var session = await DB.getSession();
        if (!session) return;
        var userId = session.user.id;
        var check = await sb.from('bookmarks').select('id').eq('user_id', userId).eq('post_id', postId).maybeSingle();
        if (check.data) {
            await sb.from('bookmarks').delete().eq('id', check.data.id);
            return false;
        } else {
            await sb.from('bookmarks').insert({ user_id: userId, post_id: postId });
            return true;
        }
    },

    async toggleFollow(targetUserId) {
        var session = await DB.getSession();
        if (!session) return;
        var userId = session.user.id;
        if (userId === targetUserId) return;
        var check = await sb.from('follows').select('id').eq('follower_id', userId).eq('following_id', targetUserId).maybeSingle();
        if (check.data) {
            await sb.from('follows').delete().eq('id', check.data.id);
            return false;
        } else {
            await sb.from('follows').insert({ follower_id: userId, following_id: targetUserId });
            tfNotifyFollow(targetUserId);
            return true;
        }
    },

    async postComment(postId, text, parentCommentId) {
        var session = await DB.getSession();
        if (!session) return null;
        var { data, error } = await sb.from('comments').insert({
            user_id: session.user.id,
            post_id: postId,
            text_content: text,
            parent_comment_id: parentCommentId || null
        }).select('*, users:user_id (full_name, username, avatar_url, badge_tier, verified)').single();
        if (error) { console.error('[Comment]', error); return null; }
        return data;
    },

    async getComments(postId) {
        var { data } = await sb.from('comments')
            .select('*, users:user_id (full_name, username, avatar_url, badge_tier, verified)')
            .eq('post_id', postId)
            .eq('is_hidden', false)
            .order('created_at', { ascending: false })
            .limit(50);
        return data || [];
    },

    async getNotifications() {
        var session = await DB.getSession();
        if (!session) return [];
        var { data } = await sb.from('notifications')
            .select('*, actor:actor_id (full_name, username, avatar_url, badge_tier)')
            .eq('user_id', session.user.id)
            .order('created_at', { ascending: false })
            .limit(50);
        return data || [];
    },

    async markNotificationsRead() {
        var session = await DB.getSession();
        if (!session) return;
        await sb.from('notifications')
            .update({ read: true })
            .eq('user_id', session.user.id)
            .eq('read', false);
    },

    async getCounts(userId) {
        var followers = await sb.from('follows').select('id', { count: 'exact', head: true }).eq('following_id', userId);
        var following = await sb.from('follows').select('id', { count: 'exact', head: true }).eq('follower_id', userId);
        var posts = await sb.from('posts').select('id', { count: 'exact', head: true }).eq('user_id', userId).eq('is_hidden', false);
        return {
            followers: followers.count || 0,
            following: following.count || 0,
            posts: posts.count || 0
        };
    },

    async searchUsers(query) {
        if (!query) return [];
        var { data } = await sb.from('users')
            .select('id, full_name, username, avatar_url, badge_tier, verified')
            .or('username.ilike.%' + query + '%,full_name.ilike.%' + query + '%')
            .limit(20);
        return data || [];
    },

    async getUserPosts(userId) {
        var { data } = await sb.from('posts')
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)')
            .eq('user_id', userId)
            .eq('is_hidden', false)
            .order('created_at', { ascending: false })
            .limit(50);
        return data || [];
    },

    async getBookmarkedPosts() {
        var session = await DB.getSession();
        if (!session) return [];
        var { data: bms } = await sb.from('bookmarks').select('post_id').eq('user_id', session.user.id).order('created_at', { ascending: false });
        if (!bms || bms.length === 0) return [];
        var postIds = bms.map(function(b) { return b.post_id; });
        var { data } = await sb.from('posts')
            .select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)')
            .in('id', postIds)
            .eq('is_hidden', false);
        return data || [];
    },

    async deletePost(postId) {
        var session = await DB.getSession();
        if (!session) return false;
        var { error } = await sb.from('posts').delete().eq('id', postId).eq('user_id', session.user.id);
        return !error;
    },

    async reportContent(contentId, contentType, reason, details) {
        var session = await DB.getSession();
        if (!session) return false;
        var { error } = await sb.from('content_reports').insert({
            reporter_id: session.user.id,
            content_id: contentId,
            content_type: contentType,
            reason: reason,
            details: details || ''
        });
        return !error;
    }
};

// ==========================================================================
// HELPER: Time ago
// ==========================================================================
function getTimeAgo(dateStr) {
    var diff = (Date.now() - new Date(dateStr).getTime()) / 1000;
    if (diff < 60) return 'now';
    if (diff < 3600) return Math.floor(diff / 60) + 'm';
    if (diff < 86400) return Math.floor(diff / 3600) + 'h';
    if (diff < 604800) return Math.floor(diff / 86400) + 'd';
    return new Date(dateStr).toLocaleDateString();
}

// ==========================================================================
// RENDER REAL POST CARD
// ==========================================================================
function renderRealPostCard(post) {
    var user = post.users || {};
    var card = document.createElement('div');
    card.className = 'post-card';
    card.setAttribute('data-post-id', post.id);
    card.setAttribute('data-user-id', user.id || post.user_id);
    card.style.animation = 'popIn 0.4s ease';

    var timeAgo = typeof getTimeAgo === 'function' ? getTimeAgo(post.created_at) : 'now';
    var avatarUrl = user.avatar_url || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(user.full_name || 'U') + '&background=007AFF&color=fff';
    var displayName = user.full_name || user.username || 'User';
    var handle = '@' + (user.username || 'user');
    var badgeClass = user.badge_tier || 'verify-blue';
    var likedClass = post._liked ? 'fa-solid' : 'fa-regular';
    var likedColor = post._liked ? 'color:#FF3B30;' : '';
    var bookmarkClass = post._bookmarked ? 'fa-solid' : 'fa-regular';
    var bookmarkColor = post._bookmarked ? 'color:#007AFF;' : '';
    var likeCount = post.like_count || 0;
    var commentCount = post.comment_count || 0;
    var repostCount = post.repost_count || 0;

    // Apply algorithm filters
    var _algoPrefs = JSON.parse(localStorage.getItem('trustfirst-algo') || '{}');
    var _postText = (post.text_content || '').toLowerCase();
    var _politicalKeywords = ['election','politics','government','democrat','republican','politician','vote','ballot','parliament','president','minister','anc','da ','eff ','party '];
    var _sensitiveKeywords = ['nudity','explicit','adult','nsfw','18+','sexual','gore','violence'];
    if (_algoPrefs.politicalContent === 'hide' && _politicalKeywords.some(function(k){ return _postText.includes(k); })) return document.createElement('div');
    if (_algoPrefs.sensitiveContent === 'strict' && _sensitiveKeywords.some(function(k){ return _postText.includes(k); })) return document.createElement('div');
    if (_algoPrefs.politicalContent === 'show') { /* boost, no filter */ }

    // Check follow state
    var followedUsers = JSON.parse(localStorage.getItem('tf-followed-users') || '[]');
    var isFollowing = followedUsers.indexOf(user.id || post.user_id) > -1;
    var isOwnPost = currentUser && currentUser.id === (user.id || post.user_id);

    // Build interactive block (poll / quiz / question) — rendered by a shared
    // helper so votePoll/answerQuiz can re-render just this block (no full reload).
    var interactiveHTML = '';
    if (post.post_type && ['poll', 'quiz', 'question'].indexOf(post.post_type) >= 0) {
        interactiveHTML = '<div id="ixblock_' + escapeHtml(String(post.id)) + '" data-opts="' + escapeHtml(JSON.stringify(post.poll_options || [])) + '" data-votes="' + escapeHtml(JSON.stringify(post.poll_votes || {})) + '" data-ct="' + (post.quiz_correct_answer || 0) + '">' + renderPollQuizBlock(post) + '</div>';
    }

    var collabUser = post.collab_user || null;
    var collabBadge = collabUser && collabUser.badge_tier ? collabUser.badge_tier : 'verify-blue';
    var hasCollab = !!(collabUser && collabUser.username);
    // "{name} is in {place}" header (Facebook-style) when the post has a location.
    var locHeaderHTML = post.location_name
        ? ' <span style="font-weight:400;color:var(--text-primary,#000);font-size:14px;">is in</span> <span style="font-weight:700;">' + escapeHtml(post.location_name) + '</span>'
        : '';
    card.innerHTML =
        '<div class="post-header">' +
            '<img src="' + escapeHtml(avatarUrl) + '" class="post-avatar" onclick="viewUserProfile(\'' + (user.id || post.user_id) + '\')" style="cursor:pointer;">' +
            '<div style="flex:1;min-width:0;">' +
                '<div class="post-info"><b style="display:flex;align-items:center;gap:4px;flex-wrap:wrap;">' +
                    '<span class="clickable-user" onclick="viewUserProfile(\'' + (user.id || post.user_id) + '\')">' + escapeHtml(displayName) + '</span>' +
                    (user.ai_label ? '<span class="tf-ai-badge">AI</span>' : (user.verified ? '<i class="fa-solid fa-circle-check ' + badgeClass + '" style="font-size:12px;"></i>' : '')) +
                    (hasCollab ? '<span style="font-weight:400;color:var(--text-primary,#000);font-size:14px;">and</span>' +
                        '<span class="clickable-user" onclick="viewUserProfile(\'' + escapeHtml(collabUser.id || '') + '\')" style="font-weight:700;">' + escapeHtml(collabUser.username || '') + '</span>' +
                        (collabUser.verified ? '<i class="fa-solid fa-circle-check ' + collabBadge + '" style="font-size:12px;"></i>' : '') : '') +
                    locHeaderHTML +
                '</b></div>' +
                '<div class="post-info"><small>' + escapeHtml(handle) + ' · ' + timeAgo + '</small></div>' +
            '</div>' +
            (!isOwnPost ? '<button class="feed-follow-btn' + (isFollowing ? ' following' : '') + '" onclick="' + (hasCollab ? 'openCollaboratorsModal(event,\'' + escapeHtml(post.id) + '\',\'' + escapeHtml(user.id || post.user_id) + '\',\'' + escapeHtml(collabUser && collabUser.id ? collabUser.id : '') + '\')' : 'realToggleFollow(this,\'' + (user.id || post.user_id) + '\')') + '" style="flex-shrink:0;">' + (isFollowing ? 'Following' : 'Follow') + '</button>' : '') +
            '<i class="fa-solid fa-ellipsis" style="margin-left:8px;padding:5px;cursor:pointer;flex-shrink:0;" onclick="openPostMenu(\'' + post.id + '\',\'' + (user.id || post.user_id) + '\')"></i>' +
        '</div>' +
        (function() {
            var txt = post.text_content || '';
            // New rich music sticker (stored in thought_music jsonb).
            var tm = post.thought_music;
            if (tm && typeof tm === 'string') { try { tm = JSON.parse(tm); } catch (e) { tm = null; } }
            if (tm && tm.name) {
                var bodyHTML = txt ? '<div class="post-content">' + (typeof formatPostText === 'function' ? formatPostText(txt) : escapeHtml(txt)) + '</div>' : '';
                var sticker = tfMusicStickerHTML({ name: tm.name, artist: tm.artist, artUrl: tm.artUrl, previewUrl: tm.previewUrl, style: tm.style || 1 }, { context: 'post', id: 'postmus_' + post.id });
                return bodyHTML + '<div style="margin:4px 16px 10px;">' + sticker + '</div>';
            }
            var musicMatch = txt.match(/^([\s\S]*?)\n\n🎵\s+(.+?)\s+—\s+(.+)$/);
            if (musicMatch) {
                var bodyText = musicMatch[1].trim();
                var mName = musicMatch[2].trim();
                var mArtist = musicMatch[3].trim();
                var musicBubble =
                    '<div onclick="openPostThoughtViewer(this,\'' + escapeHtml(post.id) + '\')" style="display:flex;align-items:center;gap:10px;background:rgba(0,122,255,0.06);border:0.5px solid rgba(0,122,255,0.15);border-radius:18px;padding:10px 14px;margin:4px 16px 8px;cursor:pointer;">' +
                        '<div style="width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,#007AFF,#5856D6);display:flex;align-items:center;justify-content:center;flex-shrink:0;box-shadow:0 2px 8px rgba(0,122,255,0.3);">' +
                            '<i class="fa-solid fa-music" style="color:white;font-size:16px;"></i>' +
                        '</div>' +
                        '<div style="flex:1;min-width:0;">' +
                            '<b style="font-size:13px;color:var(--text-primary,#000);display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHtml(mName) + '</b>' +
                            '<small style="color:#888;font-size:11px;">' + escapeHtml(mArtist) + '</small>' +
                        '</div>' +
                        '<div style="display:flex;align-items:flex-end;gap:2px;height:20px;flex-shrink:0;" id="postMusicBars_' + escapeHtml(post.id) + '">' +
                            [8,14,6,18,10,14,6].map(function(h){ return '<div style="width:3px;height:'+h+'px;background:#007AFF;border-radius:2px;animation:soundPulse 0.8s ease-in-out infinite;animation-delay:'+( Math.floor(Math.random()*5)*0.1)+'s;"></div>'; }).join('') +
                        '</div>' +
                    '</div>';
                return (bodyText ? '<div class="post-content">' + (typeof formatPostText === 'function' ? formatPostText(bodyText) : escapeHtml(bodyText)) + '</div>' : '') + musicBubble;
            }
            return txt ? '<div class="post-content">' + (typeof formatPostText === 'function' ? formatPostText(txt) : escapeHtml(txt).replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1" target="_blank" rel="noopener noreferrer" style="color:#007AFF;text-decoration:underline;">$1</a>')) + '</div>' : '';
        })() +
        (post.location_name ? tfLocationCardHTML(post) : '') +
        (post.media_url ? '<div class="post-media-box">' + ((post.media_type === 'video' || post.post_type === 'video') ?
    '<video src="' + escapeHtml(post.media_url) + '"' + (post.thumbnail_url ? ' poster="' + escapeHtml(post.thumbnail_url) + '"' : '') + ' controls playsinline preload="metadata" onloadedmetadata="try{this.currentTime=0.1;}catch(e){}" style="width:100%;max-height:480px;border-radius:12px;object-fit:contain;background:#000;display:block;"></video>' :
    '<img src="' + escapeHtml(post.media_url) + '" class="post-img" loading="lazy" style="object-fit:contain;max-height:480px;" onerror="this.closest(\'.post-media-box\').style.display=\'none\'">') + '</div>' : '') +
        interactiveHTML +
        '<div class="post-icons">' +
            '<div onclick="realToggleLike(this,\'' + post.id + '\')" data-liked="' + (post._liked ? 'true' : 'false') + '">' +
                '<i class="' + likedClass + ' fa-heart" style="' + likedColor + '"></i> ' +
                '<span style="font-size:13px;color:#888;">' + likeCount + '</span>' +
            '</div>' +
            '<div onclick="realOpenComments(\'' + post.id + '\')">' +
                '<i class="fa-regular fa-comment"></i>' +
                ' <span style="font-size:13px;color:#888;">' + commentCount + '</span>' +
            '</div>' +
            '<div onclick="handleRepost(\'' + post.id + '\')">' +
    '<i class="fa-solid fa-retweet"></i>' +
    ' <span style="font-size:13px;color:#888;">' + repostCount + '</span>' +
'</div>' +
'<div onclick="realToggleBookmark(this,\'' + post.id + '\')" data-bookmarked="' + (post._bookmarked ? 'true' : 'false') + '">' +
    '<i class="' + bookmarkClass + ' fa-bookmark" style="' + bookmarkColor + '"></i>' +
'</div>' +
'<div onclick="openShare(\'' + post.id + '\')"><i class="fa-solid fa-share-nodes"></i></div>' +
        '</div>';

    // Track view when post scrolls into viewport — deduplicated per session
    if (post.id && !String(post.id).startsWith('local_') && window.sb && currentUser) {
        var _viewedKey = 'tf_viewed_' + currentUser.id;
        var _viewedSet = JSON.parse(localStorage.getItem(_viewedKey) || '[]');
        if (_viewedSet.indexOf(post.id) === -1) {
            var viewObserver = new IntersectionObserver(function(entries, obs) {
                if (entries[0].isIntersecting) {
                    obs.disconnect();
                    var _viewed = JSON.parse(localStorage.getItem(_viewedKey) || '[]');
                    if (_viewed.indexOf(post.id) !== -1) return; // double-check
                    _viewed.push(post.id);
                    if (_viewed.length > 500) _viewed = _viewed.slice(-500); // keep list lean
                    localStorage.setItem(_viewedKey, JSON.stringify(_viewed));
                    sb.from('posts').update({ view_count: (post.view_count || 0) + 1 }).eq('id', post.id).then(function(){});
                }
            }, { threshold: 0.5 });
            viewObserver.observe(card);
        }
    }
    return card;
}

function openCollaboratorsModal(event, postId, mainUserId, collabUserId) {
    if (event && event.stopPropagation) event.stopPropagation();
    var existing = document.getElementById('collaboratorsModal');
    if (existing) { existing.remove(); return; }
    var modal = document.createElement('div');
    modal.id = 'collaboratorsModal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:30000;display:flex;align-items:flex-end;justify-content:center;background:rgba(0,0,0,0.4);animation:fadeIn 0.2s ease;';
    modal.onclick = function(e) { if (e.target === modal) modal.remove(); };

    var followedUsers = JSON.parse(localStorage.getItem('tf-followed-users') || '[]');
    var isFollowingMain = followedUsers.indexOf(mainUserId) > -1;
    var isFollowingCollab = followedUsers.indexOf(collabUserId) > -1;

    // Fetch both users' display data from current post cards
    var mainCard = document.querySelector('[data-post-id="' + postId + '"]');
    var mainAvatar = '', mainName = '', mainUsername = '', mainVerified = false;
    var collabAvatar = '', collabName = '', collabUsername = '', collabVerified = false;
    if (mainCard) {
        var mainImg = mainCard.querySelector('.post-avatar');
        if (mainImg) mainAvatar = mainImg.src;
        var names = mainCard.querySelectorAll('.clickable-user');
        if (names[0]) mainUsername = names[0].textContent.trim();
        if (names[1]) collabUsername = names[1].textContent.trim();
    }

    function makeRow(avatar, name, username, userId, verified, isFollowing) {
        var initials = (username || name || 'U').charAt(0).toUpperCase();
        var avatarHtml = avatar
            ? '<img src="' + escapeHtml(avatar) + '" style="width:52px;height:52px;border-radius:50%;object-fit:cover;flex-shrink:0;">'
            : '<div style="width:52px;height:52px;border-radius:50%;background:#007AFF;display:flex;align-items:center;justify-content:center;color:white;font-size:20px;font-weight:700;flex-shrink:0;">' + escapeHtml(initials) + '</div>';
        return '<div style="display:flex;align-items:center;gap:14px;padding:14px 0;border-bottom:0.5px solid var(--border-color,#f0f0f0);">' +
            avatarHtml +
            '<div style="flex:1;min-width:0;">' +
                '<div style="display:flex;align-items:center;gap:5px;">' +
                    '<b style="font-size:15px;color:var(--text-primary,#000);">' + escapeHtml(username || name || 'User') + '</b>' +
                    (verified ? '<i class="fa-solid fa-circle-check verify-blue" style="font-size:13px;"></i>' : '') +
                '</div>' +
                (name && name !== username ? '<div style="font-size:13px;color:#888;margin-top:1px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(name) + '</div>' : '') +
            '</div>' +
            '<button onclick="(function(btn,uid,wasFollowing){' +
                'var f=JSON.parse(localStorage.getItem(\'tf-followed-users\')||\'[]\');' +
                'if(wasFollowing){f=f.filter(function(i){return i!==uid;});btn.textContent=\'Follow\';btn.style.background=\'#007AFF\';btn.style.color=\'white\';}' +
                'else{if(f.indexOf(uid)===-1)f.push(uid);btn.textContent=\'Following\';btn.style.background=\'rgba(0,0,0,0.06)\';btn.style.color=\'var(--text-primary,#000)\';}' +
                'localStorage.setItem(\'tf-followed-users\',JSON.stringify(f));' +
                'if(window.sb&&window.currentUser){sb.from(wasFollowing?\'follows\':\'follows\')[wasFollowing?\'delete\':\'insert\'](wasFollowing?undefined:{follower_id:currentUser.id,following_id:uid}).eq(wasFollowing?\'follower_id\':\'id\',wasFollowing?currentUser.id:undefined).then(function(){});}' +
                '})(this,\'' + escapeHtml(userId) + '\',' + (isFollowing ? 'true' : 'false') + ')" ' +
                'style="padding:8px 18px;border-radius:22px;border:none;font-size:14px;font-weight:700;cursor:pointer;flex-shrink:0;background:' + (isFollowing ? 'rgba(0,0,0,0.06);color:var(--text-primary,#000)' : '#007AFF;color:white') + ';">' +
                (isFollowing ? 'Following' : 'Follow') +
            '</button>' +
        '</div>';
    }

    modal.innerHTML =
        '<div style="background:var(--bg-primary,#fff);border-radius:24px 24px 0 0;width:100%;max-width:480px;padding:0 20px 32px;">' +
            '<div style="display:flex;justify-content:center;padding:12px 0 8px;">' +
                '<div style="width:36px;height:4px;background:rgba(0,0,0,0.15);border-radius:2px;"></div>' +
            '</div>' +
            '<h3 style="text-align:center;font-size:18px;font-weight:800;color:var(--text-primary,#000);margin:0 0 16px;">Collaborators</h3>' +
            makeRow(mainAvatar, mainName, mainUsername, mainUserId, mainVerified, isFollowingMain) +
            (collabUserId ? makeRow(collabAvatar, collabName, collabUsername, collabUserId, collabVerified, isFollowingCollab) : '') +
        '</div>';
    document.body.appendChild(modal);
}

function openPostThoughtViewer(el, postId) {
    // Parse music name from the sticker label inside the clicked element
    var nameEl = el.querySelector('b');
    var artistEl = el.querySelector('small');
    var mName = nameEl ? nameEl.textContent : 'Song';
    var mArtist = artistEl ? artistEl.textContent : '';
    // Get the post text if any
    var card = el.closest('[data-post-id]');
    var textEl = card ? card.querySelector('.post-content') : null;
    var thoughtText = textEl ? textEl.textContent.trim() : '';
    openThoughtViewer(thoughtText || '🎵', mName + ', ' + mArtist, { name: mName, artist: mArtist, artUrl: null, previewUrl: null });
}

// Format post text — linkify hashtags and mentions
var _mvT = null;
function _scheduleMentionVerify() { clearTimeout(_mvT); _mvT = setTimeout(function(){ if (typeof verifyMentions === 'function') verifyMentions(document); }, 600); }
function formatPostText(text) {
    if (!text) return '';
    var safe = escapeHtml(text);
    // Linkify URLs first (before hashtag/mention so they don't double-process)
    safe = safe.replace(/(https?:\/\/[^\s&lt;&quot;]+)/g, '<a href="$1" target="_blank" rel="noopener noreferrer" style="color:#007AFF;text-decoration:underline;word-break:break-all;">$1</a>');
    safe = safe.replace(/(^|[\s(>])#([A-Za-z0-9_]{2,50})/g, '$1<span class="tf-hashtag" onclick="openHashtag(event,\'$2\')" style="color:#007AFF;font-weight:600;cursor:pointer;">#$2</span>');
    // Mentions render blue optimistically; the sweep below strips styling/clicks
    // for accounts that don't exist or are banned/suspended (→ plain text).
    safe = safe.replace(/(^|[\s(>])@([A-Za-z0-9_.]{2,30})/g, '$1<span class="tf-mention" data-u="$2" onclick="openMentionUser(event,\'$2\')" style="color:#007AFF;font-weight:600;cursor:pointer;">@$2</span>');
    _scheduleMentionVerify();
    return safe;
}

function searchHashtag(tag) {
    navOpenSearch();
    setTimeout(function() {
        var input = document.getElementById('navSearchInput');
        if (input) {
            input.value = '#' + tag;
            handleNavSearch('#' + tag);
        }
    }, 400);
}

async function viewUserByUsername(username) {
    if (window.sb) {
        var result = await sb.from('users').select('id').eq('username', username.toLowerCase()).maybeSingle();
        if (result.data) { viewUserProfile(result.data.id); return; }
    }
    showToast('@' + username);
}

// ==========================================================================
// REAL LIKE TOGGLE
// ==========================================================================
async function realToggleLike(el, postId) {
    if (!canPerformAction('like a post')) return;
    var icon = el.querySelector('i') || el.querySelector('svg');
    var count = el.querySelector('span');
    var liked = el.getAttribute('data-liked') === 'true';
    var prevCount = count ? parseInt(count.textContent) || 0 : 0;
    triggerHaptic(30);

    // Optimistic UI
    if (liked) {
        if (icon?.classList) { icon.className = 'fa-regular fa-heart'; icon.style.color = ''; }
        if (count) count.textContent = Math.max(0, prevCount - 1);
        el.setAttribute('data-liked', 'false');
    } else {
        if (icon?.classList) { icon.className = 'fa-solid fa-heart'; icon.style.color = '#FF3B30'; }
        if (count) count.textContent = prevCount + 1;
        el.setAttribute('data-liked', 'true');
    }

    var result = await RealData.toggleLike(postId);
    if (result === undefined) {
        // Rollback on auth failure
        if (liked) {
            if (icon?.classList) { icon.className = 'fa-solid fa-heart'; icon.style.color = '#FF3B30'; }
            if (count) count.textContent = prevCount;
            el.setAttribute('data-liked', 'true');
        } else {
            if (icon?.classList) { icon.className = 'fa-regular fa-heart'; icon.style.color = ''; }
            if (count) count.textContent = prevCount;
            el.setAttribute('data-liked', 'false');
        }
    }
}

// ==========================================================================
// REAL BOOKMARK TOGGLE
// ==========================================================================
async function realToggleBookmark(el, postId) {
    if (!canPerformAction('bookmark')) return;
    var icon = el.querySelector('i');
    var bookmarked = el.getAttribute('data-bookmarked') === 'true';
    triggerHaptic(15);

    // Optimistic UI
    if (bookmarked) {
        icon.className = 'fa-regular fa-bookmark'; icon.style.color = '';
        el.setAttribute('data-bookmarked', 'false');
    } else {
        icon.className = 'fa-solid fa-bookmark'; icon.style.color = '#007AFF';
        el.setAttribute('data-bookmarked', 'true');
    }

    try {
        var result = await RealData.toggleBookmark(postId);
        if (result === undefined) throw new Error('auth');
        // Silent success — no toast needed for bookmark
    } catch(e) {
        // Rollback
        if (bookmarked) {
            icon.className = 'fa-solid fa-bookmark'; icon.style.color = '#007AFF';
            el.setAttribute('data-bookmarked', 'true');
        } else {
            icon.className = 'fa-regular fa-bookmark'; icon.style.color = '';
            el.setAttribute('data-bookmarked', 'false');
        }
        showToast('Could not save. Try again.');
    }
}

// ==========================================================================
// REAL COMMENTS
// ==========================================================================
currentCommentPostId = null;

async function realOpenComments(postId) {
    if (!currentUser) return;
    currentCommentPostId = postId;
    // This surface (the modal sheet) is now where the thread renders + posts.
    window._activeCommentList = document.getElementById('comment-list');
    window._activeCommentInput = document.getElementById('comment-input');

    var overlay = document.getElementById('comment-overlay');
    if (overlay) {
        overlay.style.display = 'flex';
        // Opened from a quoted post, the detail sheet sits at 9900 and the
        // comment sheet's own 6500 put it underneath, invisible: tapping
        // "Post your comment" looked like it did nothing. Same post id either
        // way, so the comments themselves are already the same thread.
        overlay.style.zIndex = document.querySelector('.post-detail-overlay') ? '9950' : '';
    }
    if (typeof syncCommentBarAvatar === 'function') syncCommentBarAvatar();

    var list = document.getElementById('comment-list');
    // Skeleton only when there is nothing to show. Reopening the same post
    // keeps the existing list on screen while fresh data loads behind it.
    var hadCache = window._cmt && window._cmt.postId === postId;
    if (list && !hadCache) list.innerHTML = renderSkeletonHTML('message', 4);

    // The owner id powers the "From creator" filter; fetched alongside the
    // comments rather than after them, because this network bills per trip.
    var ok = await _fetchCommentThread(postId);
    if (!ok || !_cList()) return;   // viewer moved on mid-fetch
    _renderSortChips();
    _renderCommentList();
}

// Fetch a post's comment thread + like/reaction/creator-liked maps and store it
// in window._cmt. Shared by the modal sheet and the post-detail page so both
// show the exact same thread.
async function _fetchCommentThread(postId) {
    var results = await Promise.all([
        RealData.getComments(postId),
        (async function () {
            try { var r = await sb.from('posts').select('user_id').eq('id', postId).single(); return (r.data && r.data.user_id) || null; }
            catch (e) { return null; }
        })()
    ]);
    var comments = results[0];
    if (currentCommentPostId !== postId) return false;   // viewer moved on mid-fetch
    var likeCountMap = {}, userLikedSet = new Set(), creatorLikedSet = new Set();
    var reactionMap = {}, myReactionMap = {};
    var _ownerId = results[1];
    if (window.sb && currentUser && comments.length) {
        try {
            var cIds = comments.map(function (c) { return c.id; });
            var _cr = await Promise.all([
                sb.from('comment_likes').select('comment_id, user_id').in('comment_id', cIds),
                sb.from('comment_reactions').select('comment_id, user_id, emoji').in('comment_id', cIds)
            ]);
            var allLikes = _cr[0].data, allReacts = _cr[1].data;
            if (allLikes) allLikes.forEach(function (l) {
                likeCountMap[l.comment_id] = (likeCountMap[l.comment_id] || 0) + 1;
                if (l.user_id === currentUser.id) userLikedSet.add(l.comment_id);
                if (_ownerId && l.user_id === _ownerId) creatorLikedSet.add(l.comment_id);
            });
            if (allReacts) allReacts.forEach(function (r) {
                var m = reactionMap[r.comment_id] = reactionMap[r.comment_id] || {};
                m[r.emoji] = (m[r.emoji] || 0) + 1;
                if (r.user_id === currentUser.id) myReactionMap[r.comment_id] = r.emoji;
            });
        } catch (e) { /* non-critical */ }
    }
    window._cmt = { postId: postId, comments: comments, likes: likeCountMap,
                    liked: userLikedSet, ownerId: results[1], creatorLiked: creatorLikedSet,
                    reactions: reactionMap, myReaction: myReactionMap,
                    expanded: (window._cmt && window._cmt.postId === postId && window._cmt.expanded) || new Set() };
    return true;
}

// ---- comment sheet: sorting, counting, in-place updates -------------------

var _COMMENT_SORTS = [
    { key: 'newest',   label: 'Newest' },
    { key: 'relevant', label: 'Most relevant' },
    { key: 'media',    label: 'With media' },
    { key: 'creator',  label: 'From creator' },
    { key: 'all',      label: 'All comments' }
];

function _setCommentSheetCount(n) {
    var t = document.getElementById('commentSheetTitle');
    if (t) t.textContent = n ? (n.toLocaleString() + ' comment' + (n === 1 ? '' : 's')) : 'Comments';
}

// The sort lives behind a label in the header rather than a row of chips: five
// of them overflowed the sheet and pushed the comments down.
function _renderSortChips() {
    var label = document.getElementById('commentSortLabel');
    if (!label) return;
    var cur = window._commentSort || 'newest';
    var match = _COMMENT_SORTS.filter(function (s) { return s.key === cur; })[0];
    label.textContent = match ? match.label : 'Newest';
}

function toggleCommentSortMenu(evt) {
    if (evt) evt.stopPropagation();
    var open = document.getElementById('commentSortMenu');
    if (open) { open.remove(); return; }

    var btn = document.getElementById('commentSortBtn');
    var sheet = document.getElementById('comment-overlay');
    if (!btn || !sheet) return;
    var cur = window._commentSort || 'newest';

    var menu = document.createElement('div');
    menu.id = 'commentSortMenu';
    // Anchored under the button, inside the sheet so it scrolls away with it.
    var b = btn.getBoundingClientRect(), s = sheet.getBoundingClientRect();
    menu.style.cssText = 'position:absolute;z-index:20;min-width:186px;' +
        'top:' + (b.bottom - s.top + 6) + 'px;right:' + (s.right - b.right) + 'px;' +
        'border:1px solid;border-radius:14px;' +
        'box-shadow:0 10px 34px rgba(0,0,0,0.22);overflow:hidden;padding:5px;';
    menu.innerHTML = _COMMENT_SORTS.map(function (opt) {
        var on = opt.key === cur;
        return '<div onclick="setCommentSort(\'' + opt.key + '\')" ' +
            'style="display:flex;align-items:center;justify-content:space-between;gap:14px;' +
            'padding:11px 12px;border-radius:9px;cursor:pointer;font-size:14px;' +
            (on ? 'font-weight:700;' : 'font-weight:500;') +
            'color:var(--text-primary,#000);">' +
            '<span>' + opt.label + '</span>' +
            (on ? '<i class="fa-solid fa-check" style="color:#0A84FF;font-size:12px;"></i>' : '') +
            '</div>';
    }).join('');
    sheet.appendChild(menu);

    // Close on the next tap anywhere else.
    setTimeout(function () {
        document.addEventListener('click', function once() {
            var m = document.getElementById('commentSortMenu');
            if (m) m.remove();
            document.removeEventListener('click', once);
        });
    }, 0);
}

function setCommentSort(mode) {
    window._commentSort = mode;
    var menu = document.getElementById('commentSortMenu');
    if (menu) menu.remove();
    _renderSortChips();
    _renderCommentList();
    if (typeof triggerHaptic === 'function') triggerHaptic(10);
}

// The comment thread renders into whichever surface is active — the modal sheet
// (#comment-list) or the post-detail page's own inline list — so the exact same
// logic (reactions, likes, replies, long-press) serves both, one at a time.
function _cList() { return window._activeCommentList || document.getElementById('comment-list'); }

function _renderCommentList() {
    var list = _cList();
    var st = window._cmt;
    if (!list || !st) return;
    var mode = window._commentSort || 'newest';

    _setCommentSheetCount(st.comments.length);

    var comments = st.comments.slice();
    if (mode === 'media')   comments = comments.filter(function (c) { return c.gif_url || c.clip_id; });
    if (mode === 'creator') comments = comments.filter(function (c) { return st.ownerId && c.user_id === st.ownerId; });

    if (!comments.length) {
        var msg = mode === 'media' ? 'No comments with media yet.'
                : mode === 'creator' ? 'Nothing from the creator yet.'
                : 'No comments yet. Be the first!';
        list.innerHTML = '<div style="text-align:center;padding:40px;color:#888;">' +
            '<i class="fa-regular fa-comment" style="font-size:30px;color:#ccc;display:block;margin-bottom:10px;"></i>' +
            msg + '</div>';
        return;
    }

    // Build the thread. childrenOf maps a comment to its DIRECT replies; roots
    // are top-level comments. A reply whose parent got filtered/deleted is
    // promoted to a root, not lost.
    var childrenOf = {}, roots = [], idSet = {};
    comments.forEach(function (c) { idSet[c.id] = true; });
    comments.forEach(function (c) {
        if (c.parent_comment_id && idSet[c.parent_comment_id]) {
            (childrenOf[c.parent_comment_id] = childrenOf[c.parent_comment_id] || []).push(c);
        } else {
            roots.push(c);
        }
    });
    // Flatten EVERY descendant of a root (any depth) into one list, oldest-first,
    // so a reply-to-a-reply (e.g. a back-and-forth with Eddie) renders instead of
    // vanishing — the old code only rendered a root's direct children.
    function descendantsOf(rootId) {
        var out = [];
        (function walk(pid) {
            (childrenOf[pid] || [])
                .slice().sort(function (a, b) { return new Date(a.created_at) - new Date(b.created_at); })
                .forEach(function (k) { out.push(k); walk(k.id); });
        })(rootId);
        return out;
    }

    if (mode === 'relevant') {
        roots.sort(function (a, b) {
            return (st.likes[b.id] || 0) - (st.likes[a.id] || 0) ||
                   (new Date(b.created_at) - new Date(a.created_at));
        });
    } else if (mode === 'all') {
        roots.sort(function (a, b) { return new Date(a.created_at) - new Date(b.created_at); });
    } else {
        roots.sort(function (a, b) { return new Date(b.created_at) - new Date(a.created_at); });
    }

    st.expanded = st.expanded || new Set();
    list.innerHTML = '';
    roots.forEach(function (c) {
        list.appendChild(_buildCommentNode(c, 0));
        var kids = descendantsOf(c.id);
        if (!kids.length) return;
        // Replies collapse behind a "View N replies" toggle (Instagram-style);
        // expansion is remembered in st.expanded so rebuilds keep it.
        var open = st.expanded.has(c.id);
        var wrap = document.createElement('div');
        wrap.className = 'c-replies';
        wrap.setAttribute('data-parent', c.id);
        wrap.style.display = open ? 'block' : 'none';
        kids.forEach(function (k) { wrap.appendChild(_buildCommentNode(k, 1)); });
        var toggle = document.createElement('div');
        toggle.className = 'c-replies-toggle';
        toggle.style.cssText = 'margin:0 0 10px 52px;font-size:13px;color:var(--text-secondary,#888);font-weight:700;cursor:pointer;display:flex;align-items:center;gap:9px;';
        var lbl = 'View ' + kids.length + ' repl' + (kids.length === 1 ? 'y' : 'ies');
        toggle.innerHTML = '<span style="width:22px;height:1px;background:rgba(136,136,136,0.45);display:inline-block;flex-shrink:0;"></span><span class="c-rt-label">' + (open ? 'Hide replies' : lbl) + '</span>';
        toggle.onclick = function () {
            var nowOpen = wrap.style.display === 'none';
            wrap.style.display = nowOpen ? 'block' : 'none';
            toggle.querySelector('.c-rt-label').textContent = nowOpen ? 'Hide replies' : lbl;
            if (nowOpen) st.expanded.add(c.id); else st.expanded.delete(c.id);
            if (typeof triggerHaptic === 'function') triggerHaptic(6);
        };
        list.appendChild(toggle);
        list.appendChild(wrap);
    });
    // Delegation is on the list, so this no-ops after the first call.
    if (typeof setupCommentLongPress === 'function') setupCommentLongPress();
}

// Walk parent links up to the top-level comment id (used to expand the right
// thread when a nested reply is posted).
function _rootAncestorId(cid) {
    var st = window._cmt; if (!st) return cid;
    var byId = {}; st.comments.forEach(function (c) { byId[c.id] = c; });
    var cur = byId[cid], guard = 0;
    while (cur && cur.parent_comment_id && byId[cur.parent_comment_id] && guard++ < 100) cur = byId[cur.parent_comment_id];
    return cur ? cur.id : cid;
}

// Drop one new comment into the open sheet without rebuilding it, so posting
// never yanks the reader back to the top of the thread.
function _appendCommentInPlace(c) {
    var st = window._cmt;
    var list = _cList();
    if (!st || !list) return null;
    st.comments.push(c);
    _setCommentSheetCount(st.comments.length);

    // An empty state has no node to insert next to; rebuild cleanly.
    if (!list.querySelector('.comment-item')) { _renderCommentList(); return null; }

    if (c.parent_comment_id) {
        // A reply (at any depth): expand its thread and rebuild so nested replies
        // always render in order — the flattened "View N replies" group can't be
        // spliced into reliably by hand.
        st.expanded = st.expanded || new Set();
        st.expanded.add(_rootAncestorId(c.parent_comment_id));
        _renderCommentList();
        var rNode = list.querySelector('[data-comment-id="' + c.id + '"]');
        if (rNode) { try { rNode.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch (e) {} }
        return rNode;
    }

    var node = _buildCommentNode(c, 0);
    if ((window._commentSort || 'newest') === 'all') {
        list.appendChild(node);
    } else {
        list.insertBefore(node, list.firstChild);
    }
    try { node.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); } catch (e) {}
    return node;
}

function _buildCommentNode(c, depth) {
        var u = c.users || {};
        var avatar = u.avatar_url || 'https://ui-avatars.com/api/?name=' + encodeURIComponent(u.full_name || 'U') + '&background=007AFF&color=fff';
        var _st = window._cmt;
        var userLiked = _st ? _st.liked.has(c.id) : false;
        var likeCount = (_st && _st.likes[c.id]) || 0;
        var isBot = (c.user_id === _EDDIE_USER_ID);
        // "Liked by creator": the post owner liked this comment (and it isn't the
        // owner's own comment).
        var creatorLiked = !!(_st && _st.creatorLiked && _st.creatorLiked.has(c.id) && c.user_id !== _st.ownerId);
        var item = document.createElement('div');
        item.className = 'comment-item' + (depth ? ' comment-reply' : '');
        if (depth) item.style.cssText = 'margin-left:38px;';
        item.setAttribute('data-comment-id', c.id || '');
        item.setAttribute('data-user-id', c.user_id || '');
        item.setAttribute('data-username', u.username || u.full_name || 'User');
        item.setAttribute('data-comment-text', c.text_content || '');
        item.innerHTML =
            '<img src="' + escapeHtml(avatar) + '" class="comment-avatar" style="align-self:flex-start;' + (depth ? 'width:28px;height:28px;' : '') + '">' +
            '<div class="comment-bubble" style="flex:1;">' +
                '<div style="display:flex;align-items:center;gap:5px;margin-bottom:3px;">' +
                    '<b style="font-size:13px;color:var(--text-primary,#000);cursor:pointer;" onclick="closeComments();viewUserProfile(\'' + escapeHtml(c.user_id || '') + '\')">' + escapeHtml(u.full_name || u.username || 'User') + '</b>' +
                    (isBot
                        ? '<span style="font-size:9px;font-weight:700;letter-spacing:0.4px;background:#000;color:#fff;padding:1px 5px;border-radius:4px;">AI</span>'
                        : (u.verified ? '<i class="fa-solid fa-circle-check ' + (u.badge_tier || 'verify-blue') + '" style="font-size:9px;"></i>' : '')) +
                    '<small style="color:#aaa;font-size:11px;margin-left:4px;">' + getTimeAgo(c.created_at) + '</small>' +
                    (creatorLiked ? '<span style="display:inline-flex;align-items:center;gap:3px;margin-left:6px;font-size:11px;color:var(--text-secondary,#888);white-space:nowrap;"><i class="fa-solid fa-heart" style="color:#FF3B30;font-size:9px;"></i>by creator</span>' : '') +
                '</div>' +
                (c.clip_id
                    ? '<div onclick="openClipFromComment(\'' + escapeHtml(c.clip_id) + '\')" style="display:inline-flex;align-items:center;gap:8px;background:rgba(255,149,0,0.12);border:1px solid rgba(255,149,0,0.3);border-radius:12px;padding:8px 12px;margin:2px 0 6px;cursor:pointer;"><i class="fa-solid fa-clapperboard" style="color:#FF9500;font-size:14px;"></i><span style="font-size:13px;font-weight:600;color:var(--text-primary,#000);">' + escapeHtml(c.text_content || 'Replied with a TrustClip') + '</span><i class="fa-solid fa-play" style="color:#FF9500;font-size:10px;"></i></div>'
                    : (c.gif_url
                        ? '<img src="' + escapeHtml(c.gif_url) + '" style="width:140px;max-width:60%;aspect-ratio:1;object-fit:cover;border-radius:12px;display:block;margin:2px 0 6px;">'
                        : '<p style="font-size:14px;line-height:1.4;margin:0 0 6px;">' + escapeHtml(c.text_content || '') + '</p>')) +
                '<div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;">' +
                    '<div onclick="toggleCommentLike(this,\'' + c.id + '\')" style="display:flex;align-items:center;gap:4px;cursor:pointer;">' +
                        '<i class="fa-' + (userLiked ? 'solid' : 'regular') + ' fa-heart" style="font-size:13px;color:' + (userLiked ? '#FF3B30' : '#888') + ';transition:0.2s;"></i>' +
                        '<span style="font-size:11px;color:#888;">' + likeCount + '</span>' +
                    '</div>' +
                    '<span class="c-reacts" data-reacts="' + (c.id || '') + '" style="display:inline-flex;align-items:center;gap:6px;">' + _commentReactChipsHTML(c.id) + '</span>' +
                    '<span onclick="openCommentReply(\'' + escapeHtml(u.full_name || u.username || 'User') + '\',\'' + escapeHtml(c.id || '') + '\',' + (isBot ? 'true' : 'false') + ')" style="font-size:12px;color:#888;cursor:pointer;font-weight:600;">Reply</span>' +
                '</div>' +
            '</div>';
        return item;
}

// Reaction chips shown next to a comment's like heart. The current user's own
// pick is highlighted red. Returns '' when nobody has reacted yet.
function _commentReactChipsHTML(cid) {
    var st = window._cmt;
    if (!st || !st.reactions) return '';
    var map = st.reactions[cid] || {};
    var mine = st.myReaction ? st.myReaction[cid] : null;
    var order = ['❤️', '👏', '🔥', '😂', '🙌'];
    var seen = {}, parts = [];
    order.forEach(function (e) { seen[e] = true; if ((map[e] || 0) > 0) parts.push(_reactChip(e, map[e], mine === e)); });
    Object.keys(map).forEach(function (e) { if (!seen[e] && map[e] > 0) parts.push(_reactChip(e, map[e], mine === e)); });
    return parts.join('');
}
function _reactChip(emoji, n, isMine) {
    return '<span style="display:inline-flex;align-items:center;gap:3px;font-size:12px;line-height:1;padding:2px 7px;border-radius:11px;background:' +
        (isMine ? 'rgba(255,59,48,0.14)' : 'rgba(136,136,136,0.14)') + ';color:' + (isMine ? '#FF3B30' : '#888') +
        ';font-weight:' + (isMine ? '700' : '500') + ';">' + emoji + ' ' + n + '</span>';
}
// Repaint just one comment's chip row after a reaction so the reader's scroll
// position never jumps (rebuilding the whole thread would).
function _updateCommentReactionRow(cid) {
    var cl = _cList();
    var row = cl ? cl.querySelector('.comment-item[data-comment-id="' + cid + '"] .c-reacts') : null;
    if (row) row.innerHTML = _commentReactChipsHTML(cid);
}
// Sync a comment's like heart + count in the DOM. Used when a reaction clears an
// existing like (a comment carries a like OR a reaction, never both). Scoped to
// the active list so a stale hidden modal node isn't updated instead.
function _setCommentLikeUI(cid, liked, count) {
    var cl = _cList();
    var item = cl ? cl.querySelector('.comment-item[data-comment-id="' + cid + '"]') : null;
    if (!item) return;
    var icon = item.querySelector('.fa-heart');
    if (!icon) return;
    icon.className = 'fa-' + (liked ? 'solid' : 'regular') + ' fa-heart';
    icon.style.color = liked ? '#FF3B30' : '#888';
    var span = icon.parentElement ? icon.parentElement.querySelector('span') : null;
    if (span && typeof count === 'number') span.textContent = count;
}

// Slide-a-sheet-down-to-close. `handle` is where the drag must begin (so inner
// scrolling and taps still work); `sheet` is what visually slides; `onClose`
// fires once it's dragged far enough or flicked, after the slide-out finishes.
// Idempotent per handle, so it's safe to call on every open.
function attachSheetSwipeClose(handle, sheet, onClose) {
    if (!handle || !sheet || handle._swipeClose) return;
    handle._swipeClose = true;
    var startY = 0, lastY = 0, startT = 0, dragging = false;
    handle.addEventListener('touchstart', function (e) {
        if (!e.touches[0]) return;
        startY = lastY = e.touches[0].clientY; startT = Date.now(); dragging = true;
        sheet.style.transition = 'none';
    }, { passive: true });
    handle.addEventListener('touchmove', function (e) {
        if (!dragging || !e.touches[0]) return;
        lastY = e.touches[0].clientY;
        sheet.style.transform = 'translateY(' + Math.max(0, lastY - startY) + 'px)';
    }, { passive: true });
    handle.addEventListener('touchend', function () {
        if (!dragging) return;
        dragging = false;
        var dy = lastY - startY;
        var vy = dy / Math.max(1, Date.now() - startT);   // px per ms (flick speed)
        sheet.style.transition = 'transform 0.28s cubic-bezier(0.32,0.72,0,1)';
        if (dy > 90 || vy > 0.5) {                         // far enough, or a quick flick
            sheet.style.transform = 'translateY(100%)';
            setTimeout(function () { sheet.style.transform = ''; sheet.style.transition = ''; if (onClose) onClose(); }, 240);
        } else {
            sheet.style.transform = 'translateY(0)';       // snap back
        }
    }, { passive: true });
}
// Add / change / clear the current user's reaction on a comment. One reaction
// per person: tapping the same emoji again removes it, a different one swaps it.
async function reactToComment(emoji) {
    var overlay = document.getElementById('commentCtxOverlay');
    if (overlay) overlay.remove();
    var item = window._ctxComment;
    if (!item) return;
    var cid = item.getAttribute('data-comment-id') || item.getAttribute('data-id');
    if (!cid) return;
    if (typeof triggerHaptic === 'function') triggerHaptic(20);

    var st = window._cmt;
    if (st) {
        st.reactions = st.reactions || {};
        st.myReaction = st.myReaction || {};
        var map = st.reactions[cid] = st.reactions[cid] || {};
        var mine = st.myReaction[cid] || null;
        if (mine === emoji) {                                     // toggle off
            map[emoji] = Math.max(0, (map[emoji] || 1) - 1);
            st.myReaction[cid] = null;
        } else {
            if (mine) map[mine] = Math.max(0, (map[mine] || 1) - 1); // swap old out
            map[emoji] = (map[emoji] || 0) + 1;
            st.myReaction[cid] = emoji;
        }
        _updateCommentReactionRow(cid);
    }

    // One or the other: adding a reaction clears this user's like on the comment.
    if (st && st.myReaction[cid] && st.liked && st.liked.has(cid)) {
        st.liked.delete(cid);
        st.likes = st.likes || {};
        st.likes[cid] = Math.max(0, (st.likes[cid] || 1) - 1);
        _setCommentLikeUI(cid, false, st.likes[cid]);
        if (window.sb && currentUser) {
            try { await sb.from('comment_likes').delete().eq('user_id', currentUser.id).eq('comment_id', cid); } catch (e) {}
        }
    }

    if (window.sb && currentUser) {
        try {
            var mineNow = st ? st.myReaction[cid] : emoji;
            if (mineNow) {
                await sb.from('comment_reactions').upsert(
                    { user_id: currentUser.id, comment_id: cid, emoji: mineNow },
                    { onConflict: 'comment_id,user_id' });
            } else {
                await sb.from('comment_reactions').delete()
                    .eq('user_id', currentUser.id).eq('comment_id', cid);
            }
        } catch (e) { /* optimistic UI stays; reconciles on next open */ }
    }
}

// Eddie's fixed bot account. Matches EDDIE_USER_ID in core/eddie_views.py.
var _EDDIE_USER_ID = 'edd1e000-0000-4000-8000-000000000001';

// ==========================================================================
// OVERRIDE: postComment — make it real
// ==========================================================================
var _originalPostComment = typeof postComment === 'function' ? postComment : null;

postComment = async function() {
    if (!currentCommentPostId) {
        // Try to get postId from comment sheet if available
        var sheet = document.getElementById('comment-sheet') || document.getElementById('comments-overlay');
        var pid = sheet ? sheet.getAttribute('data-post-id') : null;
        if (pid) { currentCommentPostId = pid; }
        else { if (_originalPostComment) _originalPostComment(); return; }
    }
    if (!canPerformAction('comment')) return;

    var input = window._activeCommentInput || document.getElementById('comment-input');
    if (!input) return;
    var text = input.value.trim();
    if (!text) return;

    if (containsBannedWords(text)) {
        showToast('Comment violates guidelines');
        return;
    }

    // One tap, one comment. The insert can take seconds on a slow network and
    // nothing visible happened during it, so people tapped send again and got
    // duplicates. Re-entry is ignored until the first insert settles.
    if (window._cmtPosting) return;
    window._cmtPosting = true;

    var replyCtx = window._replyingTo;
    var result = null;
    try {
        result = await RealData.postComment(currentCommentPostId, text,
                                            replyCtx && replyCtx.id);
    } finally {
        window._cmtPosting = false;
    }
    if (result) {
        input.value = '';
        window._replyingTo = null;
        _renderReplyBar();
        triggerHaptic(15);
        // The new comment drops straight into the open sheet; reloading the
        // whole list scrolled the reader back to the top every time.
        _appendCommentInPlace(result);
        // Immediately update the comment count on the post card in the feed
        var postCard = document.querySelector('[data-post-id="' + currentCommentPostId + '"]');
        if (postCard) {
            postCard.querySelectorAll('button, div').forEach(function(btn) {
                if (btn.querySelector('.fa-comment, .fa-comment-dots')) {
                    var span = btn.querySelector('span');
                    if (span) span.textContent = (parseInt(span.textContent) || 0) + 1;
                }
            });
        }
        // Notify the post owner (about a comment), and separately the parent
        // comment's author when this is a reply to their comment, and anyone
        // named with @username. A reply to your own comment on your own post
        // must not fire three times, so each target is de-duplicated and
        // self-notification is filtered by _tfNotify.
        if (window.sb && currentUser) {
            try {
                var postData = await sb.from('posts').select('user_id').eq('id', currentCommentPostId).single();
                var ownerId = postData.data && postData.data.user_id;
                var parentAuthorId = null;
                if (replyCtx && replyCtx.id) {
                    var pc = await sb.from('comments').select('user_id').eq('id', replyCtx.id).single();
                    parentAuthorId = pc.data && pc.data.user_id;
                }
                if (parentAuthorId) {
                    _tfNotify(parentAuthorId, {
                        type: 'comment_reply', post_id: currentCommentPostId, comment_id: result.id,
                        message: _tfActorName() + ' replied to your comment'
                    });
                }
                // The post-owner ping is skipped when they were already told as
                // the parent-comment author, to avoid a double buzz.
                if (ownerId && ownerId !== parentAuthorId) {
                    _tfNotify(ownerId, {
                        type: 'comment', post_id: currentCommentPostId, comment_id: result.id,
                        message: _tfActorName() + ' commented on your post'
                    });
                }
                tfNotifyMentions(text, { post_id: currentCommentPostId });
            } catch(e) { /* notification failure is non-critical */ }
        }
        // Eddie answers when tagged, and also when this is a reply to something
        // Eddie itself said, so a thread carries on without re-tagging.
        var replyingToEddie = !!(replyCtx && replyCtx.eddie);
        _eddieAnswerMention('comment', result.id, text, currentCommentPostId,
                            replyingToEddie);
    } else {
        showToast('Comment failed');
    }
};

// ==========================================================================
// @eddie mentions — tag Eddie on a post or comment and it replies in thread
// ==========================================================================

// \b after "eddie" so "@eddies" and "@eddie_smith" do not summon the bot.
function _eddieTagged(text) {
    return /@eddie\b/i.test(text || '');
}

// Ask the server to answer a mention. The server re-reads the text from the
// database and decides for itself whether Eddie was addressed, so nothing here
// is trusted; this is only the nudge.
//
// No thinking indicator: a comment thread is not a chat window, and a spinner
// sitting in someone else's conversation is noise. The reply simply appears.
async function _eddieAnswerMention(sourceType, sourceId, text, postId, replyingToEddie) {
    if (!sourceId) return;
    if (!replyingToEddie && !_eddieTagged(text)) return;

    try {
        var token = await _eddieToken();
        var r = await fetch('/api/eddie/mention/', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json',
                       'Authorization': 'Bearer ' + token },
            body: JSON.stringify({ source_type: sourceType, source_id: sourceId })
        });
        var j = await r.json().catch(function(){ return {}; });

        if (!r.ok) {
            // Out of quota is that person's own limit, and it stops Eddie only
            // for them. Say it once, quietly, and never in the thread itself.
            if (r.status === 429) showToast(j.error || 'You have used up Eddie for today');
            return;
        }
        if (j.duplicate) return;

        // Eddie's reply drops into the open thread in place; a full reload
        // would scroll the reader away from the conversation.
        if (postId) _eddieBumpCommentCount(postId);
        if (j.comment && postId && currentCommentPostId === postId) {
            j.comment.users = { full_name: 'Eddie', username: 'eddie' };
            _appendCommentInPlace(j.comment);
        }
    } catch (e) {
        /* Eddie staying quiet is better than an error toast on someone's post. */
    }
}

function _eddieBumpCommentCount(postId) {
    var card = document.querySelector('[data-post-id="' + postId + '"]');
    if (!card) return;
    card.querySelectorAll('button, div').forEach(function(btn) {
        if (btn.querySelector('.fa-comment, .fa-comment-dots')) {
            var span = btn.querySelector('span');
            if (span) span.textContent = (parseInt(span.textContent) || 0) + 1;
        }
    });
}

