async function chBumpReaction2(channelId, postId, emoji, btn) {
    var parts = btn.textContent.trim().split(' ');
    var count = (parseInt(parts[1])||0) + 1;
    btn.textContent = emoji + ' ' + count;
    btn.style.background = 'rgba(0,122,255,0.12)';
    triggerHaptic(15);
    if (window.sb) {
        var { data: post } = await sb.from('channel_posts').select('reactions').eq('id',postId).single();
        var reacts = (post && post.reactions) || {};
        reacts[emoji] = count;
        await sb.from('channel_posts').update({ reactions: reacts }).eq('id', postId);
    }
}

async function toggleChannelFollow(channelId, btn) {
    if (!currentUser) { showToast('Please log in'); return; }
    var isFollowing = btn.textContent.trim() === 'Following';
    if (isFollowing) {
        if (window.sb) await sb.from('channel_followers').delete().eq('channel_id',channelId).eq('user_id',currentUser.id);
        btn.textContent = 'Follow';
        btn.style.background = '#007AFF';
        btn.style.color = 'white';

    } else {
        if (window.sb) await sb.from('channel_followers').insert({ channel_id: channelId, user_id: currentUser.id });
        btn.textContent = 'Following';
        btn.style.background = '#f0f0f0';
        btn.style.color = '#333';

    }
    triggerHaptic(20);
}

