    btn.closest('div').parentElement.parentElement.remove();
    var display = document.getElementById('cp-nickname-display');
    if (display) display.textContent = value || 'Tap to set a nickname';
    var chatTitle = document.getElementById('chat-user-name');
    if (chatTitle && value) chatTitle.setAttribute('data-real-name', chatTitle.textContent);
