// --- SEARCH IN CHAT ---
function openCPSearch() {
    closeContactProfile();

    // Transform header into search bar
    var header = document.querySelector('#chat-interface .header-container');
    if (!header) return;

    var originalHTML = header.innerHTML;

    header.innerHTML =
        '<button id="chatSearchCancelBtn" style="background:none;border:none;cursor:pointer;padding:4px 8px;color:#007AFF;font-size:15px;font-weight:600;">Cancel</button>' +
        '<div style="flex:1;display:flex;align-items:center;gap:8px;background:rgba(0,0,0,0.06);border-radius:20px;padding:8px 14px;margin:0 8px;border:0.5px solid rgba(0,0,0,0.08);">' +
            '<i class="fa-solid fa-magnifying-glass" style="color:#aaa;font-size:13px;"></i>' +
            '<input id="chatSearchInput" type="text" placeholder="Search messages..." style="flex:1;border:none;background:transparent;outline:none;font-size:15px;color:var(--text-primary,#000);caret-color:#007AFF;" oninput="performChatSearch(this.value)">' +
            '<span id="chatSearchCount" style="font-size:12px;color:#aaa;white-space:nowrap;"></span>' +
        '</div>' +
        '<div style="display:flex;gap:4px;">' +
            '<button onclick="navigateChatSearch(-1)" style="background:none;border:none;cursor:pointer;padding:6px;color:#007AFF;font-size:18px;"><i class="fa-solid fa-chevron-up"></i></button>' +
            '<button onclick="navigateChatSearch(1)" style="background:none;border:none;cursor:pointer;padding:6px;color:#007AFF;font-size:18px;"><i class="fa-solid fa-chevron-down"></i></button>' +
        '</div>';

    header.style.transition = 'all 0.3s ease';
    window._chatSearchOriginalHTML = originalHTML;
var cancelBtn = document.getElementById('chatSearchCancelBtn');
if (cancelBtn) cancelBtn.addEventListener('click', function(){ closeChatSearch(); });
    setTimeout(function() { var si = document.getElementById('chatSearchInput'); if(si) si.focus(); }, 200);
}

var _chatSearchResults = [];
var _chatSearchIdx = 0;

function performChatSearch(query) {
    // Remove previous highlights
    var chatBody = document.getElementById('chat-body');
    if (!chatBody) return;
    chatBody.querySelectorAll('.chat-highlight').forEach(function(el) {
        el.outerHTML = el.textContent;
    });
    _chatSearchResults = [];
    _chatSearchIdx = 0;

    var countEl = document.getElementById('chatSearchCount');
    if (!query || query.trim().length < 2) {
        if (countEl) countEl.textContent = '';
        return;
    }

    var bubbles = chatBody.querySelectorAll('div[style*="background:#007AFF"],div[style*="rgba(0,0,0,0.07)"]');
    var regex = new RegExp('(' + query.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + ')', 'gi');
    var found = 0;

    bubbles.forEach(function(bubble) {
        if (!bubble.textContent.toLowerCase().includes(query.toLowerCase())) return;
        bubble.innerHTML = bubble.textContent.replace(regex, function(match) {
            found++;
            return '<mark class="chat-highlight" style="background:#FFD700;color:#000;border-radius:3px;padding:0 2px;">' + escapeHtml(match) + '</mark>';
        });
        _chatSearchResults.push(bubble);
    });

    if (countEl) countEl.textContent = found > 0 ? found + ' found' : 'Not found';
    if (_chatSearchResults.length > 0) {
        _chatSearchResults[0].scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
}

function navigateChatSearch(direction) {
    if (_chatSearchResults.length === 0) return;
    _chatSearchIdx = (_chatSearchIdx + direction + _chatSearchResults.length) % _chatSearchResults.length;
    _chatSearchResults[_chatSearchIdx].scrollIntoView({ behavior: 'smooth', block: 'center' });
    var countEl = document.getElementById('chatSearchCount');
    if (countEl) countEl.textContent = (_chatSearchIdx + 1) + ' of ' + _chatSearchResults.length;
    triggerHaptic(10);
}

function closeChatSearch() {
    var chatBody = document.getElementById('chat-body');
    if (chatBody) {
        chatBody.querySelectorAll('.chat-highlight').forEach(function(el) {
            el.outerHTML = el.textContent;
        });
    }
    _chatSearchResults = [];
    _chatSearchIdx = 0;
    var header = document.querySelector('#chat-interface .header-container');
    if (header && window._chatSearchOriginalHTML) {
        header.innerHTML = window._chatSearchOriginalHTML;
        window._chatSearchOriginalHTML = null;
    }
}

// Wire up typing indicator in chat
document.addEventListener('DOMContentLoaded', function() {
    var chatInput = document.getElementById('chat-msg-input');
    if (!chatInput) return;
    var typingTimeout = null;
    chatInput.addEventListener('input', function() {
        if (!cpTypingEnabled) return;
        clearTimeout(typingTimeout);
        var typingEl = document.getElementById('chat-typing-indicator');
        if (!typingEl) {
            typingEl = document.createElement('div');
            typingEl.id = 'chat-typing-indicator';
            typingEl.style.cssText = 'padding:6px 20px;font-size:12px;color:#888;font-style:italic;';
            typingEl.textContent = 'You are typing...';
            var body = document.getElementById('chat-body');
            if (body) body.after(typingEl);
        }
        typingEl.style.display = 'block';
        typingTimeout = setTimeout(function() {
            if (typingEl) typingEl.style.display = 'none';
        }, 2000);
    });
});

