    panel.style.cssText = 'position:absolute;bottom:80px;left:0;right:0;background:var(--card-bg,#fff);border-top:1px solid var(--border-color,#eee);z-index:6010;display:flex;flex-direction:column;animation:slideUpOverlay 0.25s ease;max-height:320px;';

    panel.innerHTML =
        '<div style="display:flex;gap:8px;padding:10px 12px;border-bottom:1px solid var(--border-color,#eee);">' +
            '<div style="flex:1;display:flex;align-items:center;gap:8px;background:var(--bg-secondary,#f0f0f0);border-radius:20px;padding:8px 14px;">' +
                '<i class="fa-solid fa-magnifying-glass" style="color:#aaa;font-size:13px;"></i>' +
                '<input id="gifSearchBox" type="text" placeholder="Search GIFs & Stickers..." style="flex:1;border:none;background:transparent;outline:none;font-size:14px;color:var(--text-primary,#000);" oninput="searchGiphy(this.value,\'gif\')">' +
            '</div>' +
        '</div>' +
        '<div style="display:flex;gap:0;padding:8px 12px 4px;">' +
            '<button onclick="switchGiphyTab(\'gif\')" id="gif-tab-btn" style="padding:7px 18px;border-radius:20px;border:none;background:#007AFF;color:white;font-size:13px;font-weight:700;cursor:pointer;margin-right:6px;">GIF</button>' +
            '<button onclick="switchGiphyTab(\'sticker\')" id="sticker-tab-btn" style="padding:7px 18px;border-radius:20px;border:none;background:var(--bg-secondary,#f0f0f0);color:var(--text-primary,#000);font-size:13px;font-weight:700;cursor:pointer;">Stickers</button>' +
        '</div>' +
        '<div id="giphy-grid" style="flex:1;overflow-y:auto;display:grid;grid-template-columns:1fr 1fr 1fr;gap:3px;padding:0 3px 10px;-webkit-overflow-scrolling:touch;">' +
            '<div style="grid-column:1/-1;text-align:center;padding:20px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:20px;"></i></div>' +
        '</div>';

   var chBroadcast = document.getElementById('ch-broadcast');
    var chatInterface = document.getElementById('chat-interface');
    var container = (chBroadcast && chBroadcast.style.display !== 'none') ? chBroadcast : chatInterface;
    if (container) container.appendChild(panel);

