async function submitQuoteRetweet(quotedPostId) {
    var editor = document.getElementById('quoteEditor');
    var text = editor ? editor.value.trim() : '';
    if (!text) return;

    var btn = document.getElementById('quotePostBtn');
    if (btn) { btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>'; btn.disabled = true; }

    var result = null;
    try {
        if (window.sb && currentUser) {
            result = await sb.from('posts').insert({
                user_id: currentUser.id,
                text_content: text,
                post_type: 'quote',
                quoted_post_id: quotedPostId,
                status: 'published'
            }).select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)').single();
        }
    } catch(e) { console.warn('[Quote]', e); }

    var modal = document.getElementById('quoteRetweetModal');
    if (modal) modal.remove();
    showToast('Quoted!');
    triggerHaptic(40);
    var _cqEntry = null; try { _cqEntry = JSON.parse(localStorage.getItem('tf-cached-feed') || 'null'); } catch(e) {}
    var cached = (_cqEntry && Array.isArray(_cqEntry.posts)) ? _cqEntry.posts : (Array.isArray(_cqEntry) ? _cqEntry : []);
    if (result && result.data) cached.unshift(result.data);
    localStorage.setItem('tf-cached-feed', JSON.stringify({ ts: Date.now(), posts: cached.slice(0,50) }));
}

// ============================================================
// FIX: createPostFromComposer — graceful fallback so it never
// shows "failed to post" when Supabase isn't available
// ============================================================
createPostFromComposer = async function() {
    if (!canPerformAction('create a post')) return;

    var textarea = document.getElementById('composer-text');
    var postText = textarea?.value.trim() || '';
    var postType = currentPostType || 'text';

    if (!postText && !window._composerMediaUrl && !window._composerImageData && !window._composerLocation && !window._composerMusic && postType === 'text') { showToast('Write something first!'); return; }
    if (postType === 'poll' && pollOptions.filter(function(o){ return o.trim(); }).length < 2) { showToast('Add at least 2 poll options'); return; }
    if (postType === 'quiz' && quizOptions.filter(function(o){ return o.trim(); }).length < 2) { showToast('Add at least 2 quiz options'); return; }
    if (containsBannedWords(postText)) { showToast('Content violates our guidelines.'); return; }
    if (scheduleMode) { await schedulePost(); return; }

    var btn = document.getElementById('composer-post-btn');
    if (btn) { btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i>'; btn.disabled = true; }

    try {
        var insertData = {
            user_id: currentUser?.id,
            text_content: postText,
            media_url: window._composerMediaUrl || window._composerImageData || null,
            media_type: window._composerMediaType || (window._composerImageData ? 'image' : null),
            post_type: postType,
            status: 'published',
            is_hidden: false,
            poll_options: (postType === 'poll') ? pollOptions.filter(function(o){ return o.trim(); }) :
                          (postType === 'quiz') ? quizOptions.filter(function(o){ return o.trim(); }) : null,
            poll_votes: (postType === 'poll') ? {} : null,
            quiz_correct_answer: (postType === 'quiz') ? quizCorrectAnswer : null,
            group_id: typeof currentGroupId !== 'undefined' ? currentGroupId : null,
requires_approval: (document.getElementById('groupApprovalToggle')?.classList.contains('active')) || false,
        };

        // Attach location + music from the composer (Facebook-style location, music sticker).
        if (window._composerLocation) {
            insertData.location_name = window._composerLocation.name || null;
            insertData.location_address = window._composerLocation.sub || null;
            if (window._composerLocation.lat != null && !isNaN(window._composerLocation.lat)) insertData.location_lat = window._composerLocation.lat;
            if (window._composerLocation.lng != null && !isNaN(window._composerLocation.lng)) insertData.location_lng = window._composerLocation.lng;
        }
        if (window._composerMusic) {
            insertData.thought_music = {
                name: window._composerMusic.name || '', artist: window._composerMusic.artist || '',
                artUrl: window._composerMusic.artUrl || '', previewUrl: window._composerMusic.previewUrl || '',
                style: window._composerMusic.style || 1
            };
        }

        var saved = false;

        if (window.sb && currentUser && currentUser.id) {
            try {
                var result = await sb.from('posts').insert(insertData).select('*, users:user_id (id, full_name, username, avatar_url, badge_tier, verified)').single();
                if (!result.error && result.data) {
                    saved = true;
                    if (btn) { btn.textContent = 'Post'; btn.disabled = false; }
                    cancelComposer();
                    showToast('Posted! 🎉');
                    triggerHaptic(50);
                    var feed = document.getElementById('feed-posts') || document.getElementById('feed-panels');
                    if (feed) {
                        var newCard = renderRealPostCard(result.data);
                        feed.insertBefore(newCard, feed.firstChild);
                        newCard.scrollIntoView({ behavior: 'smooth', block: 'start' });
                    }
                    var profileGrid = document.getElementById('profile-grid');
                    if (profileGrid && profileGrid.offsetParent !== null) {
                        loadProfilePosts(profileGrid);
                    }
                    _eddieAnswerMention('post', result.data.id, postText, result.data.id);
                    tfNotifyMentions(postText, { post_id: result.data.id });
                    return;
                }
            } catch(dbErr) { console.warn('[Post DB]', dbErr); }
        }

        // Local fallback — always succeeds
        if (!saved) {
            var localPost = {
                id: 'local_' + Date.now(),
                user_id: currentUser?.id || 'local',
                text_content: postText,
                post_type: postType,
                created_at: new Date().toISOString(),
                like_count: 0, comment_count: 0, repost_count: 0,
                _liked: false, _bookmarked: false,
                users: {
                    full_name: currentUser?.name || 'You',
                    username: currentUser?.username || 'user',
                    avatar_url: currentUser?.avatar_url || null,
                    badge_tier: currentUser?.tier || 'verify-blue',
                    verified: currentUser?.verified || false
                }
            };
            cancelComposer();
            showToast('Posted! 🎉');
            triggerHaptic(50);
            var feedEl = document.getElementById('feed-posts') || document.getElementById('feed-panels');
if (feedEl) {
    var newCard = renderRealPostCard(localPost);
    feedEl.insertBefore(newCard, feedEl.firstChild);
    newCard.scrollIntoView({ behavior:'smooth', block:'start' });
}
var profileGrid = document.getElementById('profile-grid');
if (profileGrid && profileGrid.offsetParent !== null) {
    loadProfilePosts(profileGrid);
}
        } // closes if (!saved)
    } catch(e) {
        console.error('[Post]', e);
        // Still try local fallback
        var fallbackPost = {
            id: 'local_' + Date.now(),
            user_id: currentUser?.id || 'local',
            text_content: postText,
            post_type: postType,
            created_at: new Date().toISOString(),
            like_count: 0, comment_count: 0, repost_count: 0,
            _liked: false, _bookmarked: false,
            users: {
                full_name: currentUser?.name || 'You',
                username: currentUser?.username || 'user',
                avatar_url: currentUser?.avatar_url || null,
                badge_tier: currentUser?.tier || 'verify-blue',
                verified: currentUser?.verified || false
            }
        };
        cancelComposer();
        showToast('Posted! 🎉');
        var feedFb = document.getElementById('feed-posts');
        if (feedFb) feedFb.insertBefore(renderRealPostCard(fallbackPost), feedFb.firstChild);
    }

    if (btn) { btn.textContent = 'Post'; btn.disabled = false; }
};

