function tfSetLocationAudience(key) {
    localStorage.setItem('tf-location-audience', key);
    // Refresh radio buttons
    var sheet = document.getElementById('locationPrivacySheet');
    if (!sheet) return;
    sheet.querySelectorAll('[onclick^="tfSetLocationAudience"]').forEach(function(row) {
        var rowKey = row.getAttribute('onclick').replace("tfSetLocationAudience('","").replace("')","");
        var radio = row.querySelector('div[style*="border-radius:50%"]:last-child');
        if (!radio) return;
        if (rowKey === key) {
            radio.style.borderColor = '#007AFF';
            radio.innerHTML = '<div style="width:14px;height:14px;border-radius:50%;background:#007AFF;"></div>';
        } else {
            radio.style.borderColor = '#ccc';
            radio.innerHTML = '';
        }
    });
    triggerHaptic(10);
}

function tfConfirmLocationAudience() {
    var key = localStorage.getItem('tf-location-audience') || 'none';
    var sharingOn = key !== 'none';
    localStorage.setItem('tf-location-sharing', sharingOn);

    // Update the pill on the map if it's open
    var icon  = document.getElementById('mapLocIcon');
    var label = document.getElementById('mapPrivacyLabel');
    if (icon)  icon.style.color = sharingOn ? '#34C759' : '#FF3B30';
    if (label) label.textContent = sharingOn ? 'Sharing location' : 'Not sharing location';

    var sheet = document.getElementById('locationPrivacySheet');
    if (sheet) sheet.remove();
    triggerHaptic(20);
    showToast(sharingOn ? 'Location sharing on' : 'Location sharing off');
}
