function filterSettings(q) {
    var overlay = document.getElementById('settings-overlay');
    if (!overlay) return;
    var rows   = overlay.querySelectorAll('.settings-row');
    var titles = overlay.querySelectorAll('.settings-section-title');
    var cards  = overlay.querySelectorAll('.settings-card');
    if (!q || !q.trim()) {
        rows.forEach(function(r){r.style.display='';});
        titles.forEach(function(t){t.style.display='';});
        cards.forEach(function(c){c.style.display='';});
        return;
    }
    var lq = q.toLowerCase();
    rows.forEach(function(r){ r.style.display = r.textContent.toLowerCase().includes(lq)?'':'none'; });
    cards.forEach(function(card){
        var vis = Array.from(card.querySelectorAll('.settings-row')).some(function(r){return r.style.display!=='none';});
        card.style.display = vis?'':'none';
        var prev = card.previousElementSibling;
        if(prev&&prev.classList.contains('settings-section-title')) prev.style.display=vis?'':'none';
    });
}
