    ;(function installDropletNav() {
    function init() {
        var pill = document.getElementById('liquidPill');
        if (!pill) return;
        var old = document.getElementById('navDroplet');
        if (old) old.remove();
        var droplet = document.createElement('div');
        droplet.id = 'navDroplet';
        pill.appendChild(droplet);

        var currentX = null;
        var raf = null;

        function spring(t) {
            return 1 - Math.pow(2, -10 * t) * Math.cos(t * Math.PI * 2.4);
        }

        function center(icon) {
            var pr = pill.getBoundingClientRect();
            var ir = icon.getBoundingClientRect();
            return ir.left - pr.left + ir.width * 0.5;
        }

        function addHalo(icon) {
            document.querySelectorAll('.nav-halo').forEach(function(h){ h.remove(); });
            if (!icon) return;
            var h = document.createElement('div');
            h.className = 'nav-halo';
            icon.appendChild(h);
            setTimeout(function(){ if (h.parentNode) h.remove(); }, 500);
        }

        function fallIn(toCx) {
            if (raf) cancelAnimationFrame(raf);
            droplet.style.opacity = '1';
            var start = null;
            var dur = 420;
            function step(ts) {
                if (!start) start = ts;
                var p = Math.min((ts - start) / dur, 1);
                var s = spring(p);
                var cy = -14 + 14 * s;
                var impact = p > 0.75 ? (p - 0.75) / 0.25 : 0;
                var w = 4 + Math.sin(impact * Math.PI) * 2.5;
                var h = Math.max((p < 0.75 ? 9 - p * 4 : 5 - Math.sin(impact * Math.PI) * 1.5), 3.5);
                droplet.style.top    = (3 + cy) + 'px';
                droplet.style.left   = (toCx - w * 0.5) + 'px';
                droplet.style.width  = w + 'px';
                droplet.style.height = h + 'px';
                droplet.style.borderRadius = w <= 5.5 ? '50%' : (w/2) + 'px';
                if (p < 1) { raf = requestAnimationFrame(step); }
                else {
                    droplet.style.cssText += ';top:3px;width:5px;height:5px;border-radius:50%;left:'+(toCx-2.5)+'px;';
                    currentX = toCx;
                }
            }
            raf = requestAnimationFrame(step);
        }

        function slide(fromCx, toCx) {
            if (raf) cancelAnimationFrame(raf);
            var dist = Math.abs(toCx - fromCx);
            var dur  = Math.min(Math.max(dist * 1.2, 220), 480);
            var start = null;
            function step(ts) {
                if (!start) start = ts;
                var p  = Math.min((ts - start) / dur, 1);
                var s  = spring(p);
                var cx = fromCx + (toCx - fromCx) * s;
                var stretch = Math.sin(p * Math.PI);
                var w = p < 0.82
                    ? 5 + stretch * Math.min(dist * 0.55, 36)
                    : 5 + Math.sin(((p-0.82)/0.18)*Math.PI) * 2.5;
                var h = Math.max(p < 0.82
                    ? 5 - stretch * 1.5
                    : 5 - Math.sin(((p-0.82)/0.18)*Math.PI) * 1.5, 3);
                droplet.style.width        = w + 'px';
                droplet.style.height       = h + 'px';
                droplet.style.left         = (cx - w*0.5) + 'px';
                droplet.style.borderRadius = w <= 6 ? '50%' : (w/2) + 'px';
                droplet.style.opacity      = '1';
                currentX = cx;
                if (p < 1) { raf = requestAnimationFrame(step); }
                else {
                    droplet.style.width='5px'; droplet.style.height='5px';
                    droplet.style.left=(toCx-2.5)+'px'; droplet.style.borderRadius='50%';
                    currentX = toCx;
                }
            }
            raf = requestAnimationFrame(step);
        }

        var first = true;
        function refresh() {
            var active = document.querySelector('.liquid-pill .nav-icon.nav-active');
            if (!active) { droplet.style.opacity='0'; currentX=null; return; }
            var cx = center(active);
            if (currentX === null || first) {
                first = false; currentX = cx;
                fallIn(cx); addHalo(active);
            } else if (Math.abs(cx - currentX) > 3) {
                slide(currentX, cx); addHalo(active);
            }
        }

        var mo = new MutationObserver(function(){ setTimeout(refresh, 12); });
        document.querySelectorAll('.liquid-pill .nav-icon').forEach(function(ic){
            mo.observe(ic, { attributes: true, attributeFilter: ['class'] });
        });
        setTimeout(refresh, 250);

        new MutationObserver(function(){
            // colors now handled entirely by CSS — no inline override needed
        }).observe(document.documentElement, { attributes: true, attributeFilter:['data-theme'] });
    }

    // Old 5px droplet-morph disabled — replaced by the draggable droplet selector
    // (setupNavDroplet). init() is intentionally left uncalled.
    void init;
})();

