    overlay.innerHTML =
        '<div style="position:sticky;top:0;z-index:10;background:var(--bg-primary,#fff);backdrop-filter:blur(20px);padding:54px 20px 14px;border-bottom:0.5px solid var(--border-color,#f0f0f0);flex-shrink:0;">' +
            '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px;">' +
                '<button onclick="document.getElementById(\'addToCircleSheet\').remove()" style="background:none;border:none;cursor:pointer;color:#007AFF;font-size:15px;font-weight:600;">Cancel</button>' +
                '<b style="font-size:17px;color:var(--text-primary,#000);">Add to Circle</b>' +
                '<button id="circleDoneBtn" onclick="confirmCircleSelection()" style="background:none;border:none;cursor:pointer;color:#007AFF;font-size:15px;font-weight:600;opacity:0.35;pointer-events:none;">Done</button>' +
            '</div>' +
            '<div style="display:flex;align-items:center;gap:10px;background:var(--bg-secondary,#f2f2f7);border-radius:25px;padding:10px 16px;">' +
                '<i class="fa-solid fa-magnifying-glass" style="color:#aaa;font-size:14px;"></i>' +
                '<input type="text" placeholder="Search" style="flex:1;border:none;background:transparent;outline:none;font-size:15px;color:var(--text-primary,#000);" oninput="filterCircleMembers(this.value)">' +
            '</div>' +
        '</div>' +
        '<div style="flex:1;overflow-y:auto;padding:10px 20px 40px;">' +
            '<div style="font-size:12px;font-weight:800;color:#888;text-transform:uppercase;letter-spacing:0.06em;margin-bottom:6px;">Suggested</div>' +
            '<div id="circleMembers"><p style="text-align:center;color:#aaa;padding:30px 0;font-size:14px;">Loading your following list…</p></div>' +
        '</div>';

    (document.getElementById('app') || document.body).appendChild(overlay);

    // Load real follows from Supabase
    if (!window.sb || !window.currentUser) return;
