    var _cvrStream = null, _cvrRecorder = null, _cvrChunks = [], _cvrSecs = 0, _cvrInterval = null, _cvrFront = true;

function openCircularVideoRecorder() {
    document.getElementById('circularVideoRecorder').style.display = 'flex';
    _cvrFront = true;
    _cvrStartStream();
    triggerHaptic(30);
}

async function _cvrStartStream() {
    if (_cvrStream) _cvrStream.getTracks().forEach(function(t){ t.stop(); });
    _cvrStream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: _cvrFront ? 'user' : 'environment', width: 480, height: 480 },
        audio: true
    });
    var vid = document.getElementById('cvrVideo');
    if (vid) vid.srcObject = _cvrStream;
    // auto-start recording
    _cvrChunks = []; _cvrSecs = 0;
    _cvrRecorder = new MediaRecorder(_cvrStream, { mimeType: 'video/webm' });
    _cvrRecorder.ondataavailable = function(e){ if(e.data.size>0) _cvrChunks.push(e.data); };
    _cvrRecorder.start();
    var timerEl = document.getElementById('cvrTimer');
    if (timerEl) timerEl.style.display = 'block';
    _cvrInterval = setInterval(function(){
        _cvrSecs++;
        var m = String(Math.floor(_cvrSecs/60)).padStart(2,'0');
        var s = String(_cvrSecs%60).padStart(2,'0');
        if (timerEl) timerEl.textContent = m + ':' + s;
        if (_cvrSecs >= 60) stopCVR();
        var sendBtn = document.getElementById('cvrSendBtn');
        if (sendBtn && _cvrSecs >= 1) { sendBtn.style.opacity='1'; sendBtn.style.pointerEvents='all'; }
    }, 1000);
}

function cvrFlip() { _cvrFront = !_cvrFront; _cvrStartStream(); }

function stopCVR() {
    clearInterval(_cvrInterval);
    if (_cvrRecorder && _cvrRecorder.state !== 'inactive') _cvrRecorder.stop();
}

function discardCVR() { clearInterval(_cvrInterval); closeCVR(); }

function sendCVR() {
    stopCVR();
    closeCVR();
    var chatBody = document.getElementById('chat-body');
    if (!chatBody) return;
    var blob = new Blob(_cvrChunks, { type: 'video/webm' });
    var localUrl = URL.createObjectURL(blob);
    var msgId = 'cvr_' + Date.now();
    var bubble = document.createElement('div');
    bubble.setAttribute('data-msg-id', msgId);
    bubble.setAttribute('data-msg-bubble', 'true');
    bubble.style.cssText = 'display:flex;flex-direction:column;align-items:flex-end;margin-bottom:10px;animation:popIn 0.3s ease;';
    bubble.innerHTML =
        '<video src="' + localUrl + '" autoplay loop muted playsinline ' +
            'style="width:120px;height:120px;border-radius:50%;object-fit:cover;display:block;' +
                   'border:3px solid #007AFF;box-shadow:0 4px 16px rgba(0,122,255,0.35);"></video>' +
        '<small style="color:#aaa;font-size:10px;margin-top:3px;">' +
            new Date().toLocaleTimeString('en-ZA', { hour: '2-digit', minute: '2-digit' }) + '</small>';
    chatBody.appendChild(bubble);
    chatBody.scrollTop = chatBody.scrollHeight;
    showToast('Video note sent');
    triggerHaptic(25);
    // Upload and save to DB
    if (window.sb && currentUser && currentConversationId) {
        var path = currentUser.id + '/vn_' + Date.now() + '.webm';
        window.sb.storage.from('chat_media').upload(path, blob, { contentType: 'video/webm' })
            .then(function(r) {
                if (!r.error) {
                    var urlResult = window.sb.storage.from('chat_media').getPublicUrl(r.data.path);
                    var publicUrl = urlResult.data && urlResult.data.publicUrl;
                    if (publicUrl) {
                        window.sb.from('messages').insert({
                            conversation_id: currentConversationId,
                            sender_id: currentUser.id,
                            message_type: 'video',
                            media_url: publicUrl,
                            created_at: new Date().toISOString(),
                            inserted_at: new Date().toISOString()
                        }).catch(function(){});
                    }
                }
            }).catch(function(){});
    }
}

function closeCVR() {
    clearInterval(_cvrInterval);
    if (_cvrStream) _cvrStream.getTracks().forEach(function(t){ t.stop(); }); _cvrStream = null;
    document.getElementById('circularVideoRecorder').style.display = 'none';
    document.getElementById('cvrTimer').style.display = 'none';
}

function normalizeEmoji(text) {
    return text || '';
}

    async function sendEmailVerification() {
    if (!currentUser || !currentUser.email) { showToast('No email found'); return; }
    if (window.sb) {
        await sb.auth.resend({ type: 'signup', email: currentUser.email });
    }
    showToast('Verification email sent to ' + currentUser.email + ' 📧');
}

async function sendPhoneOTP() {
    var phone = currentUser && currentUser.phone;
    if (!phone) {
        phone = prompt('Enter your phone number (e.g. +27820000000):');
        if (!phone) return;
        currentUser.phone = phone;
        secureSave('current_user', currentUser);
        var pd = document.getElementById('settings-phone-display');
        if (pd) pd.textContent = phone;
        if (window.sb && currentUser) {
            await sb.from('users').update({ phone: phone }).eq('id', currentUser.id);
        }
    }
    if (window.sb) {
        try {
            await sb.auth.signInWithOtp({ phone: phone });
            showToast('OTP sent to ' + phone + ' 📱');
        } catch(e) {
            showToast('OTP: ' + (e.message || 'Check your number'));
        }
    } else {
        showToast('OTP sent to ' + phone + ' 📱');
    }
}

    function renderQRCode() {
    var el = document.getElementById('qr-canvas');
    if (!el) return;
    el.innerHTML = '';
    var handle = currentUser ? (currentUser.handle || currentUser.username || '@user') : '@user';
    if (handle && !handle.startsWith('@')) handle = '@' + handle;
    var url = 'https://trustfirst.app/u/' + handle.replace('@','');
    try {
        new QRCode(el, {
            text: url,
            width: 200, height: 200,
            colorDark: '#000000',
            colorLight: '#ffffff',
            correctLevel: QRCode.CorrectLevel.H
        });
    } catch(e) {
        el.innerHTML = '<div style="width:200px;height:200px;background:#f0f0f0;display:flex;align-items:center;justify-content:center;border-radius:10px;"><small style="color:#888;">' + handle + '</small></div>';
    }
    var label = document.getElementById('qr-username');
    if (label) label.textContent = handle;
}

function shareQRCode() {
    var handle = currentUser ? currentUser.handle : '@user';
    var url = 'https://trustfirst.app/u/' + handle.replace('@','');
    if (navigator.share) {
        navigator.share({ title: 'Connect with me on TrustFirst', url: url });
    } else {
        navigator.clipboard.writeText(url).then(function(){ showToast('Profile link copied!'); });
    }
}

