function editorTogglePlay() {
    var vid = document.getElementById('edVideo');
    if (!vid) return;
    // Drive the actual <video>; the play/pause EVENTS keep icon + state in sync
    // (toggling a separate flag desynced the icon from what the video was doing).
    // Also kick the audio here, inside the tap, so autoplay policy lets it start.
    if (vid.paused) { vid.play().catch(function(){}); if (typeof _edAudioSync === 'function') _edAudioSync(true); }
    else { vid.pause(); if (typeof _edAudioSync === 'function') _edAudioSync(false); }
}

// Keep the play/pause icon, playhead tick and timestamp locked to the video's
// real state — including the autoplay when the editor first opens.
function edWireVideo() {
    var vid = document.getElementById('edVideo');
    if (!vid || vid._edWired) return;
    vid._edWired = true;
    function icon() { var b = document.getElementById('edPlayBtn'); if (b) b.innerHTML = vid.paused ? '<i class="fa-solid fa-play"></i>' : '<i class="fa-solid fa-pause"></i>'; }
    vid.addEventListener('play', function(){ edState.isPlaying = true; icon(); if (_edTickRAF) cancelAnimationFrame(_edTickRAF); edTickPlayhead(); _edAudioSync(true); });
    vid.addEventListener('pause', function(){ edState.isPlaying = false; icon(); if (_edTickRAF) { cancelAnimationFrame(_edTickRAF); _edTickRAF = null; } edSyncTimelineScroll(); _edAudioSync(false); });
    // While playing, the requestAnimationFrame loop is the sole driver of the
    // playhead (smooth). timeupdate only fires ~4×/sec, so only use it to catch
    // up when paused (e.g. the user scrubbed the native control) — using it
    // during playback fought the RAF and made the scrubber jump.
    vid.addEventListener('timeupdate', function(){ if (!edState.isPlaying) { edState.playheadMs = Math.round(vid.currentTime * 1000); edUpdateTimestamp(); edSyncTimelineScroll(); _edAudioSync(false); } });
    vid.addEventListener('seeked', function(){ edState.playheadMs = Math.round(vid.currentTime * 1000); edUpdateTimestamp(); edSyncTimelineScroll(); _edAudioSync(false); });
    icon();
}

// Scroll the timeline so the playhead position stays in view (shared by the
// RAF play loop and paused seeks so both move the scrubber identically).
function edSyncTimelineScroll() {
    var totalMs = edState.clips.reduce(function(s,c){return s+c.durationMs;},0) || 1;
    var scroller = document.querySelector('#preview-edit-overlay .ed-timeline-scroll');
    if (!scroller) return;
    var maxScroll = scroller.scrollWidth - scroller.clientWidth;
    if (maxScroll > 0) scroller.scrollLeft = (edState.playheadMs / totalMs) * maxScroll;
}

var _edTickRAF = null;
function edTickPlayhead() {
    if (!edState.isPlaying) { _edTickRAF = null; return; }
    var vid = document.getElementById('edVideo');
    if (vid && !vid.paused) {
        edState.playheadMs = Math.round(vid.currentTime * 1000);
        edUpdateTimestamp();
        edSyncTimelineScroll();
        _edAudioSync(true);
    }
    _edTickRAF = requestAnimationFrame(edTickPlayhead);
}

// Play the editor's audio tracks (imported audio, music, voice-over) in time
// with the video. They used to be stored but never actually played, which is
// why imported audio "wasn't syncing" — there was no audio playback at all.
function _edEnsureAudioEl(track) {
    window._edAudioEls = window._edAudioEls || {};
    var el = window._edAudioEls[track.id];
    if (!el) { el = new Audio(); el.preload = 'auto'; el.src = track.url || ''; window._edAudioEls[track.id] = el; }
    return el;
}
function _edAudioSync(playing) {
    var pos = edState.playheadMs || 0;          // ms into the whole timeline
    var live = {};
    (edState.audioTracks || []).forEach(function (t) {
        if (!t || !t.url) return;               // music entries without a preview url can't play
        live[t.id] = true;
        var el = _edEnsureAudioEl(t);
        var start = t.startMs || 0;
        var end = start + (t.durationMs || 0);
        var inWindow = pos >= start && pos < end;
        var into = (pos - start) / 1000;        // seconds into this track
        el.volume = (typeof t.volume === 'number') ? t.volume : 1;
        el.muted = !!t.muted;
        if (inWindow) {
            // Only correct drift > 250ms; seeking every frame would stutter.
            if (Math.abs((el.currentTime || 0) - into) > 0.25) { try { el.currentTime = Math.max(0, into); } catch (e) {} }
            if (playing) { if (el.paused) el.play().catch(function () {}); }
            else if (!el.paused) el.pause();
        } else if (!el.paused) { el.pause(); }
    });
    // Silence any element whose track was removed.
    Object.keys(window._edAudioEls || {}).forEach(function (id) {
        if (!live[id]) { try { window._edAudioEls[id].pause(); } catch (e) {} }
    });
}
function _edAudioStop() {
    Object.keys(window._edAudioEls || {}).forEach(function (id) {
        try { window._edAudioEls[id].pause(); window._edAudioEls[id].currentTime = 0; } catch (e) {}
    });
}
// Drop cached audio elements when the track set is rebuilt (draft load, undo),
// so stale blob URLs don't linger.
function _edAudioReset() { _edAudioStop(); window._edAudioEls = {}; }

function edUpdateTimestamp() {
    var el = document.getElementById('edTimestamp');
    if (!el) return;
    var total = edState.clips.reduce(function(s,c){return s+c.durationMs;},0);
    el.textContent = edFmt(edState.playheadMs) + ' / ' + edFmt(total);
}
function edFmt(ms) { var s=Math.floor(ms/1000); return Math.floor(s/60)+':'+(s%60<10?'0':'')+(s%60); }

function editorUndo() {
    if (edState.historyIndex <= 0) { showToast('Nothing to undo'); return; }
    edState.historyIndex--;
    _edApplySnapshot(JSON.parse(edState.history[edState.historyIndex]));
    triggerHaptic(8);
}
function editorRedo() {
    if (edState.historyIndex >= edState.history.length - 1) { showToast('Nothing to redo'); return; }
    edState.historyIndex++;
    _edApplySnapshot(JSON.parse(edState.history[edState.historyIndex]));
    triggerHaptic(8);
}
// Restoring state is not enough on its own - the text layer and the video's
// effect are rendered separately, so they have to be re-applied too. Effect CSS
// is set directly (not via edApplyEffect) so this never pushes new history.
function _edApplySnapshot(snap) {
    edState.clips = snap.clips || [];
    edState.audioTracks = snap.audioTracks || [];
    edState.textOverlays = snap.textOverlays || [];
    if (typeof _edAudioReset === 'function') _edAudioReset();   // track set changed; drop stale audio els
    edRenderTimeline();
    if (typeof edRenderTextOverlays === 'function') edRenderTextOverlays();
    var vid = document.getElementById('edVideo');
    if (vid && typeof _edEffectCss !== 'undefined') {
        var css = _edEffectCss[snap.effect || 'none'] || { f: 'none' };
        vid.style.filter = css.f || 'none';
        vid.style.transform = css.t || '';
    }
    window._edCurrentEffect = snap.effect || 'none';
    edState.isDirty = true;
    editorSaveDraft(false);
}
function edSaveHistory() {
    var snap = JSON.stringify({
        clips: edState.clips,
        audioTracks: edState.audioTracks,
        textOverlays: edState.textOverlays,
        effect: window._edCurrentEffect || 'none'
    });
    if (edState.history[edState.historyIndex] === snap) return;   // no-op edits
    edState.history = edState.history.slice(0, edState.historyIndex + 1);
    edState.history.push(snap);
    if (edState.history.length > 50) edState.history.shift();
    edState.historyIndex = edState.history.length - 1;
}

function edOpenPanel(type) {
    if (type === 'text') { edOpenTextSheet(); return; }
    if (type === 'audio') { edOpenMusicModal(); return; }
    if (type === 'effects') { edOpenEffectsModal(); return; }
    if (type === 'voice') { edOpenVoicePanel(); return; }
    if (type === 'captions') { edOpenCaptionsPanel(); return; }
    // Plain overlay tool, not the Gallery sticker: make sure a stale sticker
    // flag from a cancelled pick does not turn this into a sticker.
    if (type === 'overlay') { window._edGalleryStickerMode = false; edOpenOverlayPicker(); return; }
    if (type === 'sticker') { edOpenStickerTray(); return; }
    if (type === 'filter') { edOpenFilterPanel(); return; }
    if (type === 'crop')   { edOpenCropPanel();   return; }
    if (type === 'volume') { edOpenVolumePanel(); return; }
    if (type === 'cutout') { edOpenCutoutPanel(); return; }

    var panel = document.getElementById('edPanel');
    var title = document.getElementById('edPanelTitle');
    var body = document.getElementById('edPanelBody');
    if (!panel) return;
    title.textContent = type.charAt(0).toUpperCase() + type.slice(1);
    if (type === 'trim') {
        var clip = edState.clips.find(function(c){return c.id===edState.selectedClipId;});
        body.innerHTML = clip
            ? '<p style="color:rgba(255,255,255,0.6);font-size:13px;margin-bottom:12px;">Selected: '+clip.id+', '+(clip.durationMs/1000).toFixed(1)+'s</p>'+
              '<p style="color:rgba(255,255,255,0.5);font-size:13px;">Drag the yellow handles on the timeline to trim.</p>'
            : '<p style="color:rgba(255,255,255,0.5);font-size:13px;">Tap a clip on the timeline first.</p>';
    }
    panel.classList.add('active');
    triggerHaptic(8);
}

/* ---- EFFECTS MODAL ---- */
function edOpenEffectsModal() {
    var existing = document.getElementById('edEffectsModal');
    if (existing) { existing.remove(); return; }
    var EFFECTS = [
        {id:'none', label:'No Effect', icon:'fa-ban', color:'#888'},
        {id:'blur', label:'Blur', icon:'fa-droplet', color:'#5AC8FA'},
        {id:'grayscale', label:'B&W', icon:'fa-circle-half-stroke', color:'#aaa'},
        {id:'sepia', label:'Sepia', icon:'fa-sun', color:'#C8A96E'},
        {id:'neon', label:'Neon', icon:'fa-bolt', color:'#BF5AF2'},
        {id:'vhs', label:'VHS', icon:'fa-film', color:'#FF2D55'},
        {id:'glow', label:'Glow', icon:'fa-star', color:'#FFD60A'},
        {id:'warm', label:'Warm', icon:'fa-fire', color:'#FF9500'},
        {id:'cool', label:'Cool', icon:'fa-snowflake', color:'#34C8FF'},
        {id:'mirror', label:'Mirror', icon:'fa-left-right', color:'#30D158'},
        {id:'zoom', label:'Zoom', icon:'fa-magnifying-glass-plus', color:'#007AFF'},
        {id:'glitch', label:'Glitch', icon:'fa-bolt-lightning', color:'#FF3B30'}
    ];
    var m = document.createElement('div');
    m.id = 'edEffectsModal';
    m.style.cssText = 'position:absolute;inset:0;z-index:500;background:rgba(0,0,0,0.88);backdrop-filter:blur(20px);display:flex;flex-direction:column;animation:slideUpOverlay 0.3s ease;';
    m.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 18px 10px;">'+
            '<span style="color:white;font-size:17px;font-weight:700;">Effects</span>'+
            '<button onclick="document.getElementById(\'edEffectsModal\').remove()" style="background:rgba(255,255,255,0.12);border:none;color:white;width:30px;height:30px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-xmark"></i></button>'+
        '</div>'+
        '<div style="padding:8px 14px 12px;">'+
            '<div style="display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.08);border-radius:14px;padding:8px 12px;">'+
                '<i class="fa-solid fa-magnifying-glass" style="color:rgba(255,255,255,0.4);font-size:14px;"></i>'+
                '<input id="edEffectSearch" placeholder="Search effects…" oninput="edFilterEffects(this.value)" style="flex:1;background:transparent;border:none;outline:none;color:white;font-size:14px;">'+
            '</div>'+
        '</div>'+
        '<div style="display:flex;gap:0;padding:0 14px 10px;border-bottom:0.5px solid rgba(255,255,255,0.1);">'+
            '<button onclick="edEffectsTab(\'all\',this)" id="edEffTabAll" style="flex:1;padding:7px;border:none;background:rgba(0,122,255,0.9);color:white;border-radius:20px 0 0 20px;font-size:13px;font-weight:700;cursor:pointer;">All</button>'+
            '<button onclick="edEffectsTab(\'fav\',this)" id="edEffTabFav" style="flex:1;padding:7px;border:none;background:rgba(255,255,255,0.1);color:rgba(255,255,255,0.6);border-radius:0;font-size:13px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:4px;"><i class="fa-solid fa-bookmark" style="font-size:12px;"></i> Favourites</button>'+
            '<button onclick="edEffectsTab(\'sug\',this)" id="edEffTabSug" style="flex:1;padding:7px;border:none;background:rgba(255,255,255,0.1);color:rgba(255,255,255,0.6);border-radius:0 20px 20px 0;font-size:13px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:4px;"><i class="fa-solid fa-star" style="font-size:12px;"></i><i class="fa-solid fa-star" style="font-size:8px;"></i><i class="fa-solid fa-star" style="font-size:5px;"></i> Suggestions</button>'+
        '</div>'+
        '<div id="edEffectsGrid" style="flex:1;overflow-y:auto;display:grid;grid-template-columns:repeat(3,1fr);gap:10px;padding:14px;">'+
        (function(){
            // Grab a real frame so every effect shows a true preview, the same way
            // the Filters panel does (this grid used to be flat icons).
            var frameUrl = _edCaptureEffectFrame();
            return EFFECTS.map(function(ef){
                var css = _edEffectCss[ef.id] || { f: 'none' };
                var thumb = frameUrl
                    ? '<img src="' + frameUrl + '" style="width:100%;height:100%;object-fit:cover;filter:' + css.f + ';transform:' + (css.t || 'none') + ';">'
                    : '<i class="fa-solid ' + ef.icon + '" style="color:' + ef.color + ';font-size:20px;"></i>';
                return '<div onclick="edApplyEffect(\''+ef.id+'\')" id="efItem_'+ef.id+'" style="display:flex;flex-direction:column;align-items:center;gap:6px;padding:8px;border-radius:16px;background:rgba(255,255,255,0.07);border:1.5px solid transparent;cursor:pointer;transition:all 0.2s;" data-label="'+ef.label.toLowerCase()+'">'+
                    '<div style="width:100%;aspect-ratio:3/4;border-radius:12px;overflow:hidden;background:#222;display:flex;align-items:center;justify-content:center;">'+
                        thumb +
                    '</div>'+
                    '<span style="color:rgba(255,255,255,0.85);font-size:12px;font-weight:600;text-align:center;">'+ef.label+'</span>'+
                '</div>';
            }).join('');
        })()+
        '</div>';
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) overlay.appendChild(m);
    window._edEffectFavs = window._edEffectFavs || [];
}
window._edCurrentEffect = 'none';

// One definition of each effect, used for BOTH the preview thumbnails and the
// applied result, so a tile always looks like what you get. `f` is a CSS filter,
// `t` a transform (mirror/zoom aren't filters). Neon was missing before, so it
// used to apply nothing.
var _edEffectCss = {
    none:      { f: 'none' },
    blur:      { f: 'blur(4px)' },
    grayscale: { f: 'grayscale(100%)' },
    sepia:     { f: 'sepia(80%)' },
    neon:      { f: 'saturate(220%) contrast(1.3) brightness(1.15)' },
    vhs:       { f: 'contrast(1.2) saturate(60%) hue-rotate(5deg)' },
    glow:      { f: 'brightness(1.3) contrast(1.1)' },
    warm:      { f: 'saturate(150%) hue-rotate(-20deg)' },
    cool:      { f: 'hue-rotate(180deg) saturate(120%)' },
    mirror:    { f: 'none', t: 'scaleX(-1)' },
    zoom:      { f: 'none', t: 'scale(1.15)' },
    glitch:    { f: 'hue-rotate(90deg) saturate(200%) contrast(1.3)' }
};

// Small still of the current frame, used for effect/filter tiles.
function _edCaptureEffectFrame() {
    try {
        var vid = document.getElementById('edVideo');
        if (!vid || !vid.videoWidth) return '';
        var cnv = document.createElement('canvas'); cnv.width = 90; cnv.height = 120;
        var cx = cnv.getContext('2d');
        var vw = vid.videoWidth, vh = vid.videoHeight, sc = Math.max(90 / vw, 120 / vh);
        var dw = vw * sc, dh = vh * sc;
        cx.drawImage(vid, (90 - dw) / 2, (120 - dh) / 2, dw, dh);
        return cnv.toDataURL('image/jpeg', 0.6);
    } catch (e) { return ''; }
}

function edApplyEffect(id) {
    window._edCurrentEffect = id;
    document.querySelectorAll('[id^="efItem_"]').forEach(function(el){ el.style.border='1.5px solid transparent'; el.style.background='rgba(255,255,255,0.07)'; });
    var sel = document.getElementById('efItem_'+id);
    if (sel) { sel.style.border='1.5px solid #007AFF'; sel.style.background='rgba(0,122,255,0.15)'; }
    var vid = document.getElementById('edVideo');
    if (vid) {
        var css = _edEffectCss[id] || { f: 'none' };
        vid.style.filter = css.f || 'none';
        vid.style.transform = css.t || '';
    }
    edState.isDirty = true;
    triggerHaptic(10);
}
function edFilterEffects(q) {
    document.querySelectorAll('[id^="efItem_"]').forEach(function(el){
        el.style.display = (!q || el.getAttribute('data-label').includes(q.toLowerCase())) ? '' : 'none';
    });
}
function edEffectsTab(tab) {
    ['all','fav','sug'].forEach(function(t){
        var btn = document.getElementById('edEffTab'+t.charAt(0).toUpperCase()+t.slice(1));
        if (btn) { btn.style.background = t===tab ? 'rgba(0,122,255,0.9)' : 'rgba(255,255,255,0.1)'; btn.style.color = t===tab ? 'white' : 'rgba(255,255,255,0.6)'; }
    });
    var grid = document.getElementById('edEffectsGrid');
    if (!grid) return;
    var items = grid.querySelectorAll('[id^="efItem_"]');
    items.forEach(function(el){
        var id = el.id.replace('efItem_','');
        if (tab === 'all') el.style.display = '';
        else if (tab === 'fav') el.style.display = (window._edEffectFavs||[]).includes(id) ? '' : 'none';
        else el.style.display = ['neon','vhs','glitch','glow','warm'].includes(id) ? '' : 'none';
    });
}

function edToggleEffectFav(id) {
    window._edEffectFavs = window._edEffectFavs || [];
    var idx = window._edEffectFavs.indexOf(id);
    if (idx === -1) { window._edEffectFavs.push(id); } else { window._edEffectFavs.splice(idx, 1); }
    var icon = document.getElementById('efFavIcon_' + id);
    if (icon) {
        var isFav = window._edEffectFavs.indexOf(id) !== -1;
        icon.className = isFav ? 'fa-solid fa-bookmark' : 'fa-regular fa-bookmark';
        icon.style.color = isFav ? '#FFD60A' : 'rgba(255,255,255,0.3)';
    }
    triggerHaptic(8);
}
/* ---- VOICE PANEL ---- */
function edOpenVoicePanel() {
    var existing = document.getElementById('edVoicePanel');
    if (existing) { existing.remove(); return; }
    var panel = document.createElement('div');
    panel.id = 'edVoicePanel';
    panel.style.cssText = 'position:absolute;left:0;right:0;bottom:0;z-index:500;background:rgba(10,10,10,0.96);backdrop-filter:blur(30px);border-radius:24px 24px 0 0;padding:20px;animation:slideUpOverlay 0.32s cubic-bezier(0.34,1.56,0.64,1);';
    panel.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:20px;">'+
            '<span style="color:white;font-size:17px;font-weight:700;">Voice Over</span>'+
            '<button onclick="edStopVoiceRecord();document.getElementById(\'edVoicePanel\').remove();" style="background:rgba(255,255,255,0.12);border:none;color:white;width:30px;height:30px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-xmark"></i></button>'+
        '</div>'+
        // Waveform line
        '<div style="height:40px;background:rgba(255,255,255,0.06);border-radius:12px;margin-bottom:18px;overflow:hidden;position:relative;">'+
            '<div id="edVoiceWave" style="position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:2px;padding:0 8px;"></div>'+
            '<span id="edVoiceDuration" style="position:absolute;right:10px;top:50%;transform:translateY(-50%);color:rgba(255,255,255,0.5);font-size:12px;font-weight:700;">0:00</span>'+
        '</div>'+
        // Record button
        '<div style="display:flex;justify-content:center;margin-bottom:18px;">'+
            '<button id="edVoiceRecBtn" onclick="edToggleVoiceRecord()" style="width:72px;height:72px;border-radius:50%;background:white;border:none;cursor:pointer;display:flex;align-items:center;justify-content:center;position:relative;box-shadow:0 4px 20px rgba(255,255,255,0.2);">'+
                '<div id="edVoiceCircle" style="position:absolute;inset:-4px;border-radius:50%;border:3px solid transparent;"></div>'+
                '<div id="edVoiceRecIcon" style="width:24px;height:24px;border-radius:50%;background:#FF3B30;"></div>'+
            '</button>'+
        '</div>'+
        '<p id="edVoiceStatus" style="color:rgba(255,255,255,0.4);font-size:13px;text-align:center;">Tap to start recording</p>';
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) overlay.appendChild(panel);
    window._edVoiceRecording = false;
    window._edVoiceRAF = null;
    window._edVoiceMediaRecorder = null;
    window._edVoiceStartTime = null;
}
function edToggleVoiceRecord() {
    if (!window._edVoiceRecording) {
        navigator.mediaDevices.getUserMedia({audio:true}).then(function(stream){
            window._edVoiceRecording = true;
            window._edVoiceStartTime = Date.now();
            var vid = document.getElementById('edVideo');
            if (vid) { vid.muted = false; vid.currentTime = 0; vid.play().catch(function(){}); }
            var recBtn = document.getElementById('edVoiceRecBtn');
            var recIcon = document.getElementById('edVoiceRecIcon');
            var circle = document.getElementById('edVoiceCircle');
            var status = document.getElementById('edVoiceStatus');
            if (recIcon) { recIcon.style.width='20px'; recIcon.style.height='20px'; recIcon.style.borderRadius='4px'; recIcon.style.background='#007AFF'; }
            if (status) status.textContent = 'Recording…';
            // Animate blue circle
            var vidDuration = (vid && vid.duration && isFinite(vid.duration)) ? vid.duration : 15;
            var circleAnim = null;
            if (circle) {
                circle.style.transition = 'none';
                circle.style.borderColor = 'transparent';
                var startT = performance.now();
                function animCircle(now) {
                    var elapsed = (now - startT) / 1000;
                    var pct = Math.min(elapsed / vidDuration, 1);
                    var deg = pct * 360;
                    circle.style.background = 'conic-gradient(#007AFF '+deg+'deg, transparent '+deg+'deg)';
                    circle.style.borderRadius = '50%';
                    circle.style.inset = '-6px';
                    circle.style.width = 'calc(100% + 12px)';
                    circle.style.height = 'calc(100% + 12px)';
                    if (window._edVoiceRecording) circleAnim = requestAnimationFrame(animCircle);
                }
                circleAnim = requestAnimationFrame(animCircle);
            }
            // Waveform animation
            var waveEl = document.getElementById('edVoiceWave');
            var waveAnim;
            function animWave() {
                if (!waveEl || !window._edVoiceRecording) return;
                waveEl.innerHTML = Array.from({length:28}, function(){
                    var h = Math.random()*28+4;
                    return '<div style="width:3px;height:'+h+'px;background:rgba(0,122,255,0.7);border-radius:2px;flex-shrink:0;transition:height 0.08s;"></div>';
                }).join('');
                waveAnim = setTimeout(animWave, 100);
            }
            animWave();
            // Duration counter
            var durEl = document.getElementById('edVoiceDuration');
            var durInt = setInterval(function(){
                if (!window._edVoiceRecording) { clearInterval(durInt); return; }
                var secs = Math.floor((Date.now() - window._edVoiceStartTime)/1000);
                var m = Math.floor(secs/60), s = secs%60;
                if (durEl) durEl.textContent = m+':'+(s<10?'0':'')+s;
            }, 500);
            window._edVoiceMediaRecorder = new MediaRecorder(stream);
            var chunks = [];
            window._edVoiceMediaRecorder.ondataavailable = function(e){ chunks.push(e.data); };
            window._edVoiceMediaRecorder.onstop = function(){
                stream.getTracks().forEach(function(t){t.stop();});
                clearTimeout(waveAnim); clearInterval(durInt);
                var blob = new Blob(chunks, {type:'audio/webm'});
                var url = URL.createObjectURL(blob);
                edState.audioTracks.push({id:'voice_'+Date.now(), label:'Voice Over', url:url, startMs:0, durationMs:(Date.now()-window._edVoiceStartTime)});
                edState.isDirty = true; edRenderTimeline();
                showToast('Voice over added ✅'); triggerHaptic(20);
                var panel = document.getElementById('edVoicePanel');
                if (panel) panel.remove();
            };
            window._edVoiceMediaRecorder.start();
        }).catch(function(){ showToast('Microphone access denied'); });
    } else {
        window._edVoiceRecording = false;
        if (window._edVoiceMediaRecorder) window._edVoiceMediaRecorder.stop();
        var vid = document.getElementById('edVideo');
        if (vid) vid.pause();
        cancelAnimationFrame(window._edVoiceRAF);
    }
}
function edStopVoiceRecord() {
    if (window._edVoiceRecording && window._edVoiceMediaRecorder) {
        window._edVoiceRecording = false;
        window._edVoiceMediaRecorder.stop();
    }
}

/* ---- CAPTIONS PANEL ---- */
var _edCaptionStyles = [
    {id:'classic', label:'Classic', style:'color:white;font-size:18px;font-weight:700;text-shadow:0 2px 6px rgba(0,0,0,0.9);background:rgba(0,0,0,0.45);padding:4px 12px;border-radius:6px;'},
    {id:'neon', label:'Neon', style:'color:#fff;font-size:18px;font-weight:900;text-shadow:0 0 8px #007AFF,0 0 20px #007AFF;letter-spacing:1px;'},
    {id:'bold', label:'Bold', style:'color:white;font-size:20px;font-weight:900;background:#000;padding:4px 14px;border-radius:4px;'},
    {id:'outline', label:'Outline', style:'color:white;font-size:18px;font-weight:700;-webkit-text-stroke:1.5px black;'},
    {id:'gradient', label:'Gradient', style:'background:linear-gradient(90deg,#FF2D55,#FF9500);-webkit-background-clip:text;-webkit-text-fill-color:transparent;font-size:18px;font-weight:900;'}
];
var _edActiveCaptionStyle = 'classic';
function edOpenCaptionsPanel() {
    var existing = document.getElementById('edCaptionsPanel');
    if (existing) { existing.remove(); return; }
    var panel = document.createElement('div');
    panel.id = 'edCaptionsPanel';
    panel.style.cssText = 'position:absolute;left:0;right:0;bottom:0;z-index:500;background:rgba(10,10,10,0.96);backdrop-filter:blur(30px);border-radius:24px 24px 0 0;padding:20px;animation:slideUpOverlay 0.32s ease;';
    panel.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;">'+
            '<span style="color:white;font-size:17px;font-weight:700;">Captions</span>'+
            '<button onclick="document.getElementById(\'edCaptionsPanel\').remove();" style="background:rgba(255,255,255,0.12);border:none;color:white;width:30px;height:30px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-xmark"></i></button>'+
        '</div>'+
        '<div style="margin-bottom:14px;">'+
            '<p style="color:rgba(255,255,255,0.5);font-size:13px;margin-bottom:10px;">Caption style:</p>'+
            '<div style="display:flex;gap:8px;overflow-x:auto;scrollbar-width:none;padding:4px 0;">'+
            _edCaptionStyles.map(function(s){
                return '<div onclick="edSelectCaptionStyle(\''+s.id+'\')" id="capStyle_'+s.id+'" style="flex-shrink:0;padding:8px 14px;border-radius:20px;border:1.5px solid '+(s.id==='classic'?'#007AFF':'rgba(255,255,255,0.2)')+';background:'+(s.id==='classic'?'rgba(0,122,255,0.15)':'rgba(255,255,255,0.06)')+';cursor:pointer;">'+
                    '<span style="'+s.style+';font-size:13px;">'+s.label+'</span>'+
                '</div>';
            }).join('')+
            '</div>'+
        '</div>'+
        '<button onclick="edGenerateCaptions()" style="width:100%;padding:14px;border-radius:14px;border:none;background:#007AFF;color:white;font-size:15px;font-weight:700;cursor:pointer;"><i class="fa-solid fa-closed-captioning" style="margin-right:8px;"></i>Auto-Generate Captions</button>';
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) overlay.appendChild(panel);
}
function edSelectCaptionStyle(id) {
    _edActiveCaptionStyle = id;
    _edCaptionStyles.forEach(function(s){
        var el = document.getElementById('capStyle_'+s.id);
        if (el) { el.style.border = s.id===id ? '1.5px solid #007AFF' : '1.5px solid rgba(255,255,255,0.2)'; el.style.background = s.id===id ? 'rgba(0,122,255,0.15)' : 'rgba(255,255,255,0.06)'; }
    });
}
async function edGenerateCaptions() {
    var btn = document.querySelector('#edCaptionsPanel button[onclick="edGenerateCaptions()"]');
    function reset() { if (btn) { btn.innerHTML = '<i class="fa-solid fa-closed-captioning" style="margin-right:8px;"></i>Auto-Generate Captions'; btn.disabled = false; } }
    if (btn) { btn.innerHTML = '<i class="fa-solid fa-spinner fa-spin" style="margin-right:8px;"></i>Transcribing speech…'; btn.disabled = true; }
    // Transcribe the clip's REAL audio via ElevenLabs (server-side), not the mic.
    var file = (window.edState && edState.clips && edState.clips[0] && edState.clips[0].file) || null;
    var vid = document.getElementById('edVideo');
    try {
        if (!file) {
            var src = (vid && vid.src) || window._lastPickedVideoSrc || '';
            if (!src) { reset(); edShowNoSpeechToast(); return; }
            var rb = await fetch(src); file = await rb.blob();
        }
        var fd = new FormData();
        fd.append('file', file, (file.name || 'clip.mp4'));
        var token = '';
        try { var s = await sb.auth.getSession(); token = (s && s.data && s.data.session && s.data.session.access_token) || ''; } catch (e) {}
        var resp = await fetch('/api/transcribe/', { method: 'POST', headers: token ? { 'Authorization': 'Bearer ' + token } : {}, body: fd });
        reset();
        if (!resp.ok) {
            // 5xx = service/config problem (not "no speech"); give an honest message.
            var emsg = '';
            try { emsg = ((await resp.json()) || {}).error || ''; } catch (e) {}
            if (resp.status >= 500) showToast('Auto-captions are unavailable right now');
            else if (resp.status === 401) showToast('Sign in to use auto-captions');
            else showToast(emsg || 'Could not caption this clip');
            return;
        }
        var data = await resp.json();
        var words = data.words || [];
        if (!words.length && !(data.text || '').trim()) { edShowNoSpeechToast(); return; }
        edApplyTimedCaptions(words, data.text || '');
    } catch (e) { reset(); edShowNoSpeechToast(); }
}

// Turn transcribed words into short caption lines and sync them to playback,
// styled with whatever caption style the user picked.
function edApplyTimedCaptions(words, fullText) {
    var style = _edCaptionStyles.find(function(s){ return s.id === _edActiveCaptionStyle; }) || _edCaptionStyles[0];
    var lines = [];
    if (words.length) {
        var cur = [];
        words.forEach(function(w, i) {
            cur.push(w);
            var span = (cur[cur.length-1].end || 0) - (cur[0].start || 0);
            if (cur.length >= 5 || span >= 2.4 || i === words.length - 1) {
                lines.push({ text: cur.map(function(x){ return x.text; }).join(' '), start: cur[0].start || 0, end: (cur[cur.length-1].end) || ((cur[0].start || 0) + 2) });
                cur = [];
            }
        });
    } else if (fullText) {
        var vd = (document.getElementById('edVideo') || {}).duration || 10;
        var ws = fullText.split(' ').filter(Boolean);
        for (var i = 0; i < ws.length; i += 5) { var t0 = (i / ws.length) * vd; lines.push({ text: ws.slice(i, i+5).join(' '), start: t0, end: t0 + (5 / Math.max(1, ws.length)) * vd }); }
    }
    edState.captions = lines;
    _edMountCaptionSync(style);
    edState.isDirty = true;
    triggerHaptic(15); showToast('Captions added ✅');
    var panel = document.getElementById('edCaptionsPanel'); if (panel) panel.remove();
}

function _edMountCaptionSync(style) {
    var vid = document.getElementById('edVideo');
    var layer = document.getElementById('edTextLayer');
    if (!vid || !layer) return;
    style = style || (_edCaptionStyles.find(function(s){ return s.id === _edActiveCaptionStyle; }) || _edCaptionStyles[0]);
    var cap = document.getElementById('edLiveCaption');
    if (!cap) { cap = document.createElement('div'); cap.id = 'edLiveCaption'; cap.style.cssText = 'position:absolute;left:8%;right:8%;bottom:14%;text-align:center;pointer-events:none;'; layer.appendChild(cap); }
    function sync() {
        var t = vid.currentTime;
        var line = (edState.captions || []).find(function(l){ return t >= l.start && t <= l.end; });
        cap.innerHTML = line ? '<span style="' + style.style + ';display:inline-block;">' + escapeHtml(line.text) + '</span>' : '';
    }
    if (vid._edCapSync) vid.removeEventListener('timeupdate', vid._edCapSync);
    vid._edCapSync = sync;
    vid.addEventListener('timeupdate', sync);
    sync();
}
function edShowNoSpeechToast() {
    var t = document.createElement('div');
    t.style.cssText = 'position:absolute;bottom:180px;left:50%;transform:translateX(-50%);background:rgba(30,30,30,0.95);color:white;padding:12px 18px;border-radius:14px;font-size:13px;font-weight:600;display:flex;align-items:center;gap:10px;z-index:600;white-space:nowrap;box-shadow:0 4px 20px rgba(0,0,0,0.4);';
    t.innerHTML = '<i class="fa-solid fa-microphone-slash" style="color:#FF3B30;"></i> No speech detected <button onclick="edGenerateCaptions();this.closest(\'div\').remove();" style="margin-left:6px;background:#007AFF;border:none;color:white;padding:5px 12px;border-radius:10px;font-size:12px;font-weight:700;cursor:pointer;">Retry</button>';
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) { overlay.appendChild(t); setTimeout(function(){ if(t.parentNode) t.remove(); }, 5000); }
}
function edRenderFakeCaptions() {
    var lines = ['This is an auto-generated caption', 'Add your own content here'];
    edRenderCaptionLines(lines.join(' '));
}
function edRenderCaptionLines(text) {
    var style = _edCaptionStyles.find(function(s){return s.id===_edActiveCaptionStyle;}) || _edCaptionStyles[0];
    var words = text.split(' ').filter(Boolean);
    var layer = document.getElementById('edTextLayer');
    if (!layer) return;
    words.reduce(function(groups, w, i) {
        var g = Math.floor(i/5); if (!groups[g]) groups[g]=[]; groups[g].push(w); return groups;
    }, []).forEach(function(group, i){
        var el = document.createElement('div');
        el.style.cssText = 'position:absolute;left:10%;right:10%;bottom:'+(15+i*10)+'%;text-align:center;'+style.style;
        el.textContent = group.join(' ');
        layer.appendChild(el);
    });
    edState.isDirty = true;
    showToast('Captions added ✅'); triggerHaptic(15);
    var panel = document.getElementById('edCaptionsPanel');
    if (panel) panel.remove();
}

/* ---- OVERLAY PICKER ---- */
function edOpenOverlayPicker() {
    var existing = document.getElementById('edGalleryPicker');
    if (existing) { existing.remove(); return; }
    var picker = document.createElement('div');
    picker.id = 'edGalleryPicker';
    picker.style.cssText = 'position:absolute;inset:0;z-index:600;background:rgba(0,0,0,0.85);display:flex;flex-direction:column;animation:slideUpOverlay 0.3s ease;';
    picker.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:calc(env(safe-area-inset-top,0px) + 16px) 20px 16px;flex-shrink:0;">' +
            '<button onclick="document.getElementById(\'edGalleryPicker\').remove()" style="background:rgba(255,255,255,0.12);border:none;color:white;width:34px;height:34px;border-radius:50%;cursor:pointer;font-size:15px;">✕</button>' +
            '<b style="color:white;font-size:16px;">Add as overlay</b>' +
            '<button onclick="document.getElementById(\'edOverlayFileInput\').click()" style="background:#007AFF;border:none;color:white;font-size:13px;font-weight:700;padding:8px 16px;border-radius:20px;cursor:pointer;">Browse Files</button>' +
        '</div>' +
        '<input id="edOverlayFileInput" type="file" accept="image/*,video/*,.mov" style="display:none" onchange="edPickerFileChosen(this)">' +
        '<div id="edPickerGrid" style="display:grid;grid-template-columns:repeat(3,1fr);gap:2px;overflow-y:auto;flex:1;padding:2px;"></div>';
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) overlay.appendChild(picker);
    // Load recent images/videos from _edState or show browse prompt
    var grid = document.getElementById('edPickerGrid');
    if (grid) {
        if (edState.clips && edState.clips.length) {
            edState.clips.forEach(function(c) {
                if (!c.objectUrl && !c.url) return;
                var src = c.objectUrl || c.url;
                var div = document.createElement('div');
                div.style.cssText = 'aspect-ratio:1;background:#222;overflow:hidden;cursor:pointer;position:relative;';
                div.innerHTML = '<video src="'+src+'" style="width:100%;height:100%;object-fit:cover;" muted preload="metadata"></video>' +
                    '<div style="position:absolute;bottom:4px;left:4px;background:rgba(0,0,0,0.6);border-radius:4px;padding:2px 6px;font-size:10px;color:white;font-weight:700;">Clip '+(edState.clips.indexOf(c)+1)+'</div>';
                div.onclick = function() {
                    document.getElementById('edGalleryPicker').remove();
                    // An existing clip is a local blob, so it stays an in-editor
                    // overlay rather than an uploaded sticker.
                    window._edGalleryStickerMode = false;
                    edAddOverlayItem(src, true, 'Clip '+(edState.clips.indexOf(c)+1));
                };
                grid.appendChild(div);
            });
        } else {
            grid.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:60px 20px;color:rgba(255,255,255,0.4);font-size:14px;">Tap "Browse Files" to choose a photo or video</div>';
        }
    }
}
function edPickerFileChosen(inp) {
    if (!inp.files || !inp.files.length) return;
    var file = inp.files[0];
    var url = URL.createObjectURL(file);
    var isVideo = file.type.startsWith('video');
    document.getElementById('edGalleryPicker')?.remove();

    // Opened from the Gallery sticker tile: place it as a real sticker so it
    // persists to the feed. Shows the local file immediately, then swaps in the
    // uploaded url once it lands.
    if (window._edGalleryStickerMode) {
        window._edGalleryStickerMode = false;
        var desc = { type: isVideo ? 'video' : 'image', wPct: 0.5, data: { url: url, uploading: true } };
        var wrap = _edPlaceOverlay(desc, { removeMsg: isVideo ? 'Video removed' : 'Image removed', fontK: 0.08 });
        _tfUploadStickerMedia(file).then(function (publicUrl) {
            desc.data.uploading = false;
            if (publicUrl) desc.data.url = publicUrl;
            else showToast('Could not upload, this overlay will not show after posting');
            if (wrap && wrap._ovBody) {
                var nb = TFStickers.render(desc, { mode: 'editor' });
                nb.style.pointerEvents = 'none';
                wrap.replaceChild(nb, wrap._ovBody);
                wrap._ovBody = nb;
            }
        });
        return;
    }
    edAddOverlayItem(url, isVideo, file.name);
}
// Keep a dragged overlay/sticker partly inside the frame. Without this a drag
// can push an item fully off the canvas, taking its ✕ with it, so it can be
// neither grabbed back nor removed.
function _edClampPos(wrap, nx, ny) {
    var area = wrap.offsetParent || wrap.parentElement;
    var grab = 44;   // always leave a finger-sized handle inside the frame
    if (area && area.clientWidth) {
        nx = Math.max(grab - wrap.offsetWidth, Math.min(nx, area.clientWidth - grab));
        ny = Math.max(12, Math.min(ny, area.clientHeight - grab));
    }
    return { x: nx, y: ny };
}

function _edClampWidth(wrap, w, min) {
    var area = wrap.offsetParent || wrap.parentElement;
    var max = (area && area.clientWidth) ? area.clientWidth : 4000;
    return Math.max(min || 60, Math.min(w, max));
}

function edAddOverlayItem(url, isVideo, name) {
    var previewArea = document.getElementById('edPreviewArea');
    if (!previewArea) return;
    var existing = document.getElementById('edOverlayItem');
    if (existing) existing.remove();
    // Add overlay label to timeline
    var ol = document.getElementById('edVideoTrack');
    if (ol) {
        var badge = document.createElement('div');
        badge.className = 'ed-clip';
        badge.id = 'overlayClipBadge';
        badge.style.cssText = 'background:rgba(88,86,214,0.55);border:1.5px solid rgba(88,86,214,0.8);cursor:pointer;';
        badge.innerHTML = '<i class="fa-solid fa-layer-group" style="margin-right:4px;font-size:10px;"></i>' + (name||'Overlay').substring(0,12);
        badge.setAttribute('data-overlay','true');
        badge.style.width = '120px';
        badge.onclick = function(){ edShowOverlayPanel(); };
        ol.appendChild(badge);
    }
    // Add to preview
    var wrap = document.createElement('div');
    wrap.id = 'edOverlayItem';
    wrap.style.cssText = 'position:absolute;top:20%;left:10%;width:60%;z-index:50;cursor:move;border:2px solid rgba(88,86,214,0.7);border-radius:8px;overflow:hidden;';
    if (isVideo) {
        wrap.innerHTML = '<video src="'+url+'" style="width:100%;display:block;" autoplay muted loop playsinline></video>';
    } else {
        wrap.innerHTML = '<img src="'+url+'" style="width:100%;display:block;">';
    }
    previewArea.appendChild(wrap);
    // Remove + resize controls. Previously the overlay only had touch drag, and
    // its click handler compared e.clientX against a startX that was set solely
    // in touchstart — so on desktop that was NaN, the action panel never opened
    // and the overlay could not be removed at all.
    var del = document.createElement('div');
    del.textContent = '✕';
    del.title = 'Remove overlay';
    del.style.cssText = 'position:absolute;top:-11px;right:-11px;width:24px;height:24px;border-radius:50%;background:rgba(0,0,0,0.8);color:#fff;font-size:12px;line-height:24px;text-align:center;cursor:pointer;z-index:2;font-weight:700;';
    del.addEventListener('click', function(ev) {
        ev.stopPropagation();
        wrap.remove();
        var badgeEl = document.getElementById('overlayClipBadge'); if (badgeEl) badgeEl.remove();
        var pnl = document.getElementById('edOverlayActionPanel'); if (pnl) pnl.remove();
        edState.isDirty = true;
        if (typeof edSaveHistory === 'function') edSaveHistory();
        showToast('Overlay removed');
    });
    wrap.appendChild(del);

    var grip = document.createElement('div');
    grip.title = 'Resize';
    grip.style.cssText = 'position:absolute;right:-9px;bottom:-9px;width:20px;height:20px;border-radius:50%;background:#5856D6;border:2px solid #fff;cursor:nwse-resize;z-index:2;';
    wrap.appendChild(grip);

    function pt(e) { var t = (e.touches && e.touches[0]) || e; return { x: t.clientX, y: t.clientY }; }

    function beginDrag(e) {
        if (e.target === del || e.target === grip) return;
        if (e.cancelable) e.preventDefault();
        var p0 = pt(e), ox = wrap.offsetLeft, oy = wrap.offsetTop, moved = false;
        function mv(ev) {
            var p = pt(ev);
            if (Math.abs(p.x - p0.x) > 3 || Math.abs(p.y - p0.y) > 3) moved = true;
            var c = _edClampPos(wrap, ox + p.x - p0.x, oy + p.y - p0.y);
            wrap.style.left = c.x + 'px';
            wrap.style.top = c.y + 'px';
        }
        function end() {
            document.removeEventListener('mousemove', mv); document.removeEventListener('mouseup', end);
            document.removeEventListener('touchmove', mv); document.removeEventListener('touchend', end);
            if (moved) { edState.isDirty = true; if (typeof edSaveHistory === 'function') edSaveHistory(); }
            else { edShowOverlayPanel(); }   // a tap (not a drag) opens the actions
        }
        document.addEventListener('mousemove', mv); document.addEventListener('mouseup', end);
        document.addEventListener('touchmove', mv, { passive: false }); document.addEventListener('touchend', end);
    }
    wrap.addEventListener('mousedown', beginDrag);
    wrap.addEventListener('touchstart', beginDrag, { passive: false });

    function beginResize(e) {
        e.stopPropagation();
        if (e.cancelable) e.preventDefault();
        var p0 = pt(e), w0 = wrap.offsetWidth;
        function mv(ev) {
            var p = pt(ev);
            wrap.style.width = _edClampWidth(wrap, w0 + (p.x - p0.x), 60) + 'px';
        }
        function end() {
            document.removeEventListener('mousemove', mv); document.removeEventListener('mouseup', end);
            document.removeEventListener('touchmove', mv); document.removeEventListener('touchend', end);
            edState.isDirty = true;
            if (typeof edSaveHistory === 'function') edSaveHistory();
        }
        document.addEventListener('mousemove', mv); document.addEventListener('mouseup', end);
        document.addEventListener('touchmove', mv, { passive: false }); document.addEventListener('touchend', end);
    }
    grip.addEventListener('mousedown', beginResize);
    grip.addEventListener('touchstart', beginResize, { passive: false });

    showToast('Overlay added'); triggerHaptic(15); edState.isDirty = true;
}
function edShowOverlayPanel() {
    var existing = document.getElementById('edOverlayActionPanel');
    if (existing) { existing.remove(); return; }
    var p = document.createElement('div');
    p.id = 'edOverlayActionPanel';
    p.style.cssText = 'position:absolute;bottom:90px;left:50%;transform:translateX(-50%);background:rgba(20,20,20,0.95);backdrop-filter:blur(20px);border-radius:16px;display:flex;gap:0;overflow:hidden;border:0.5px solid rgba(255,255,255,0.12);z-index:600;';
    var actions = [
        {icon:'fa-arrow-right-arrow-left',label:'Replace',fn:'edReplaceOverlay()'},
        {icon:'fa-pen',label:'Edit',fn:'edEditOverlay()'},
        {icon:'fa-scissors',label:'Split',fn:'edSplitOverlay()'},
        {icon:'fa-copy',label:'Duplicate',fn:'edDuplicateOverlay()'},
        {icon:'fa-trash',label:'Delete',fn:'edDeleteOverlay()',red:true}
    ];
    p.innerHTML = actions.map(function(a){
        return '<button onclick="'+a.fn+';document.getElementById(\'edOverlayActionPanel\').remove();" style="background:none;border:none;border-right:0.5px solid rgba(255,255,255,0.08);padding:12px 14px;color:'+(a.red?'#FF3B30':'white')+';cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:4px;font-size:10px;font-weight:600;min-width:52px;">'+
            '<i class="fa-solid '+a.icon+'" style="font-size:16px;"></i>'+a.label+
        '</button>';
    }).join('');
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) overlay.appendChild(p);
    // Close on outside tap
    setTimeout(function(){
        function outside(e){ if(!e.target.closest('#edOverlayActionPanel') && !e.target.closest('#edOverlayItem')){ p.remove(); document.removeEventListener('click',outside); } }
        document.addEventListener('click', outside);
    }, 100);
}
function edReplaceOverlay() { edOpenOverlayPicker(); }
function edEditOverlay() { showToast('Drag to reposition'); }
function edSplitOverlay() { showToast('Split overlay coming'); }
function edDuplicateOverlay() {
    var it = document.getElementById('edOverlayItem');
    if (!it) return;
    var clone = it.cloneNode(true);
    clone.id = 'edOverlayItem_dup_'+Date.now();
    clone.style.top = (parseInt(it.style.top)||0)+30+'px';
    clone.style.left = (parseInt(it.style.left)||0)+20+'px';
    it.parentNode.appendChild(clone);
    showToast('Overlay duplicated');
}
function edDeleteOverlay() {
    var it = document.getElementById('edOverlayItem');
    var badge = document.getElementById('overlayClipBadge');
    if (it) it.remove();
    if (badge) badge.remove();
    showToast('Overlay removed');
}

function edAddClipFromGallery() {
    var inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'video/*';
    inp.onchange = function() {
        if (!inp.files || !inp.files.length) return;
        var file = inp.files[0];
        var url = URL.createObjectURL(file);
        var vid = document.createElement('video');
        vid.src = url;
        vid.preload = 'metadata';
        vid.onloadedmetadata = function() {
            var dur = Math.round((vid.duration || 5) * 1000);
            var startMs = edState.clips.reduce(function(acc,c){return acc+c.durationMs;}, 0);
            var clipId = 'clip_'+Date.now();
            var canvas = document.createElement('canvas'); canvas.width=80; canvas.height=40;
            vid.currentTime = 0.1;
            vid.onseeked = function() {
                try { canvas.getContext('2d').drawImage(vid,0,0,80,40); } catch(e){}
                var thumb = canvas.toDataURL('image/jpeg',0.5);
                var clip = edState.clips.find(function(c){return c.id===clipId;});
                if (clip) { clip.thumbnail = thumb; edRenderTimeline(); }
            };
            edState.clips.push({id:clipId, label:file.name.split('.')[0].substring(0,10), url:url, startMs:startMs, durationMs:dur, color:'rgba(52,199,89,0.5)'});
            edMarkDirtyAndUnlockNext();
            edRenderTimeline(); edSaveHistory();
            showToast('Clip added'); triggerHaptic(15);
        };
    };
    inp.click();
}

/* ---- MUSIC MODAL ---- */
function edOpenMusicModal() {
    var existing = document.getElementById('edMusicModal');
    if (existing) { existing.remove(); return; }
    var m = document.createElement('div');
    m.id = 'edMusicModal';
    m.style.cssText = 'position:absolute;inset:0;z-index:500;background:rgba(0,0,0,0.92);backdrop-filter:blur(20px);display:flex;flex-direction:column;animation:slideUpOverlay 0.3s ease;';
    m.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 18px 10px;">'+
            '<span style="color:white;font-size:17px;font-weight:700;">Music</span>'+
            '<button onclick="document.getElementById(\'edMusicModal\').remove()" style="background:rgba(255,255,255,0.12);border:none;color:white;width:30px;height:30px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;"><i class="fa-solid fa-xmark"></i></button>'+
        '</div>'+
        '<div style="padding:8px 14px 10px;display:flex;gap:8px;">'+
            '<div style="flex:1;display:flex;align-items:center;gap:8px;background:rgba(255,255,255,0.08);border-radius:14px;padding:8px 12px;">'+
                '<i class="fa-solid fa-magnifying-glass" style="color:rgba(255,255,255,0.4);font-size:14px;"></i>'+
                '<input id="edMusicSearch" placeholder="Search songs…" oninput="edSearchMusic(this.value)" style="flex:1;background:transparent;border:none;outline:none;color:white;font-size:14px;">'+
            '</div>'+
            '<button onclick="edImportAudio()" style="flex-shrink:0;background:rgba(255,255,255,0.1);border:none;color:white;border-radius:14px;padding:8px 14px;font-size:13px;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px;"><i class="fa-solid fa-folder-open"></i> Import</button>'+
        '</div>'+
        '<div id="edMusicList" style="flex:1;overflow-y:auto;padding:0 14px 20px;">'+
            '<div style="text-align:center;padding:30px;"><i class="fa-solid fa-spinner fa-spin" style="color:#007AFF;font-size:24px;"></i><p style="color:rgba(255,255,255,0.4);margin-top:10px;font-size:13px;">Search for a song above</p></div>'+
        '</div>';
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) overlay.appendChild(m);
    // Show empty state — user must search
    var list = document.getElementById('edMusicList');
    if (list) list.innerHTML = '<div style="text-align:center;padding:40px 20px;"><i class="fa-solid fa-magnifying-glass" style="color:rgba(255,255,255,0.2);font-size:32px;margin-bottom:12px;display:block;"></i><p style="color:rgba(255,255,255,0.4);font-size:14px;margin:0 0 16px;">Search for any song above</p><div style="display:flex;flex-wrap:wrap;gap:8px;justify-content:center;">' + ['Amapiano','Afrobeats','Hip Hop','R&B','Pop','Gospel'].map(function(g){ return '<button onclick="document.getElementById(\'edMusicSearch\').value=\''+g+'\';edSearchMusic(\''+g+'\')" style="padding:7px 14px;border-radius:20px;border:0.5px solid rgba(255,255,255,0.2);background:rgba(255,255,255,0.06);color:rgba(255,255,255,0.7);font-size:13px;cursor:pointer;">'+g+'</button>'; }).join('') + '</div></div>';
}
function edSearchMusic(q) {
    edSearchMusicReal(q || 'trending');
}
async function edSearchMusicReal(query) {
    var list = document.getElementById('edMusicList');
    if (!list) return;
    // Skeleton rows matching the track layout (art + title + subtitle).
    list.innerHTML = [0,1,2,3,4,5].map(function(){ return '<div style="display:flex;align-items:center;gap:12px;padding:12px;border-radius:14px;background:rgba(255,255,255,0.05);margin-bottom:8px;animation:skeletonPulse 1.4s ease-in-out infinite;"><div style="width:42px;height:42px;border-radius:10px;background:rgba(255,255,255,0.12);flex-shrink:0;"></div><div style="flex:1;"><div style="height:13px;width:60%;border-radius:6px;background:rgba(255,255,255,0.12);margin-bottom:7px;"></div><div style="height:11px;width:38%;border-radius:6px;background:rgba(255,255,255,0.1);"></div></div></div>'; }).join('');
    try {
        // Proxied server-side; a direct iTunes fetch was CORS-blocked and
        // surfaced as the editor's "connection error".
        var res = await fetch('/api/music/search/?q='+encodeURIComponent(query)+'&country=ZA');
        var data = await res.json();
        var tracks = (data.results || []).filter(function(t){ return t.previewUrl; });
        if (!tracks.length) { list.innerHTML = '<p style="text-align:center;color:rgba(255,255,255,0.4);padding:30px;font-size:13px;">No songs found</p>'; return; }
        list.innerHTML = tracks.map(function(t){
            var art = (t.artworkUrl100||'').replace('100x100','300x300');
            var dur = t.trackTimeMillis ? Math.floor(t.trackTimeMillis/60000)+':'+String(Math.floor((t.trackTimeMillis%60000)/1000)).padStart(2,'0') : '';
            return '<div onclick="edAddMusicTrackReal(\''+escapeHtml(t.trackName)+'\',\''+escapeHtml(t.artistName)+'\',\''+escapeHtml(t.previewUrl||'')+'\',\''+escapeHtml(art)+'\')" style="display:flex;align-items:center;gap:12px;padding:12px;border-radius:14px;background:rgba(255,255,255,0.05);margin-bottom:8px;cursor:pointer;border:0.5px solid rgba(255,255,255,0.06);">'+
                '<img src="'+escapeHtml(art)+'" style="width:42px;height:42px;border-radius:10px;object-fit:cover;flex-shrink:0;" onerror="this.style.display=\'none\'">'+
                '<div style="flex:1;min-width:0;"><div style="color:white;font-size:14px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+escapeHtml(t.trackName)+'</div><div style="color:rgba(255,255,255,0.45);font-size:12px;margin-top:2px;">'+escapeHtml(t.artistName)+' · '+dur+'</div></div>'+
                '<i class="fa-solid fa-plus" style="color:#007AFF;flex-shrink:0;"></i></div>';
        }).join('');
    } catch(e) {
        list.innerHTML = '<p style="text-align:center;color:rgba(255,255,255,0.4);padding:30px;font-size:13px;">Connection error. Try again.</p>';
    }
}
function edAddMusicTrackReal(title, artist, previewUrl, artUrl) {
    // Opened from the Music sticker tile: drop a music sticker on the video
    // instead of adding the track to the audio timeline.
    if (window._edMusicStickerMode) {
        window._edMusicStickerMode = false;
        var mm = document.getElementById('edMusicModal'); if (mm) mm.remove();
        _edPlaceOverlay(
            { type: 'music', wPct: 0.66,
              data: { name: title, artist: artist, previewUrl: previewUrl, artUrl: artUrl, style: 1 } },
            { removeMsg: 'Music removed', fontK: 0.075 }
        );
        showToast('Tap the sticker to switch style');
        triggerHaptic(15);
        return;
    }
    // If called from story post context, play audio instead of adding to editor
    if (window._spMusicModalActive) {
        window._spMusicModalActive = false;
        window._spMusicOnly = false; // image/video + music -> no spinning disc
        var m = document.getElementById('edMusicModal'); if (m) m.remove();
        triggerHaptic && triggerHaptic(15);
        spApplyMusic({ name: title, artist: artist, previewUrl: previewUrl, artUrl: artUrl });
        return;
    }
    edState.audioTracks.push({id:'music_'+Date.now(), label:title+', '+artist, url:previewUrl, artUrl:artUrl, startMs:0, durationMs:180000});
    edState.isDirty = true; edRenderTimeline(); edSaveHistory(); editorSaveDraft(false);
    var m = document.getElementById('edMusicModal');
    if (m) m.remove();
    showToast(title + ' added'); triggerHaptic(15);
}
function edRenderMusicList(songs) {
    var list = document.getElementById('edMusicList');
    if (!list) return;
    if (!songs.length) { list.innerHTML = '<p style="text-align:center;color:rgba(255,255,255,0.4);padding:30px;font-size:13px;">No songs found</p>'; return; }
    list.innerHTML = songs.map(function(s, idx){
        return '<div onclick="edAddMusicTrack(\''+escapeHtml(s.title)+'\',\''+escapeHtml(s.artist)+'\')" style="display:flex;align-items:center;gap:12px;padding:12px;border-radius:14px;background:rgba(255,255,255,0.05);margin-bottom:8px;cursor:pointer;border:0.5px solid rgba(255,255,255,0.06);">'+
            '<div style="width:42px;height:42px;border-radius:10px;background:rgba(0,122,255,0.25);display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fa-solid fa-music" style="color:#007AFF;font-size:16px;"></i></div>'+
            '<div style="flex:1;min-width:0;"><div style="color:white;font-size:14px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+escapeHtml(s.title)+'</div><div style="color:rgba(255,255,255,0.45);font-size:12px;margin-top:2px;">'+escapeHtml(s.artist)+' · '+s.duration+'</div></div>'+
            '<i class="fa-solid fa-plus" style="color:#007AFF;flex-shrink:0;"></i>'+
        '</div>';
    }).join('');
}
function edAddMusicTrack(title, artist) {
    edState.audioTracks.push({id:'music_'+Date.now(), label:title+', '+artist, startMs:0, durationMs:180000});
    edState.isDirty = true; edRenderTimeline(); edSaveHistory(); editorSaveDraft(false);
    var m = document.getElementById('edMusicModal');
    if (m) m.remove();
    showToast(title + ' added'); triggerHaptic(15);
}
function edImportAudio() {
    var inp = document.createElement('input');
    inp.type = 'file'; inp.accept = 'audio/*,video/*';
    inp.onchange = function() {
        if (!inp.files || !inp.files.length) return;
        var file = inp.files[0];
        var url = URL.createObjectURL(file);
        edState.audioTracks.push({id:'import_'+Date.now(), label:file.name.split('.')[0], url:url, startMs:0, durationMs:180000});
        edState.isDirty = true; edRenderTimeline();
        var m = document.getElementById('edMusicModal');
        if (m) m.remove();
        showToast(file.name.split('.')[0]+' imported'); triggerHaptic(15);
    };
    inp.click();
}

/* ---- TEXT BOTTOM SHEET ---- */
var _edTextState = {text:'', font:'Classic', color:'#ffffff', effect:'none', animation:'none', align:'center'};
var _edFonts = ['Classic','Modern','Poster','Bubble','Typewriter','Serif','Mono','Rounded'];
var _edTextEffects = ['None','Neon','Hard Shadow','3D Offset','Pixel','Glow','Retro'];
var _edTextAnims = ['None','Typewriter','Pop','Fade','Slide Right','Reveal','Bounce','Spin'];
function edOpenTextSheet() {
    var existing = document.getElementById('edTextSheet');
    if (existing) { existing.remove(); return; }
    var sheet = document.createElement('div');
    sheet.id = 'edTextSheet';
    sheet.style.cssText = 'position:absolute;left:0;right:0;bottom:0;height:70%;z-index:500;background:#1a1a1a;border-radius:24px 24px 0 0;display:flex;flex-direction:column;animation:slideUpOverlay 0.35s cubic-bezier(0.34,1.56,0.64,1);';
    sheet.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:14px 16px 8px;">'+
            '<div style="width:32px;"></div>'+
            '<div style="width:36px;height:4px;background:rgba(255,255,255,0.2);border-radius:2px;margin:0 auto;"></div>'+
            '<button onclick="edApplyText()" style="background:none;border:none;color:#007AFF;font-size:15px;font-weight:700;cursor:pointer;">Done</button>'+
        '</div>'+
        // Tab icons
        '<div style="display:flex;overflow-x:auto;gap:0;border-bottom:0.5px solid rgba(255,255,255,0.1);scrollbar-width:none;">'+
            [
                {id:'kbd',icon:'fa-keyboard',tip:'Text'},
                {id:'font',icon:'fa-font',tip:'Fonts'},
                {id:'color',icon:'fa-palette',tip:'Color'},
                {id:'anim',icon:'fa-film',tip:'Animate'},
                {id:'effect',icon:'fa-star',tip:'Effect'},
                {id:'style',icon:'fa-text-height',tip:'Style'},
                {id:'format',icon:'fa-align-center',tip:'Format'}
            ].map(function(t,i){
                return '<button id="edTxtTab_'+t.id+'" onclick="edTextTab(\''+t.id+'\')" style="flex:1;min-width:48px;padding:10px 0;background:none;border:none;border-bottom:2px solid '+(i===0?'#007AFF':'transparent')+';color:'+(i===0?'#007AFF':'rgba(255,255,255,0.4)')+';cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:3px;font-size:10px;font-weight:600;">'+
                    '<i class="fa-solid '+t.icon+'" style="font-size:17px;"></i>'+t.tip+
                '</button>';
            }).join('')+
        '</div>'+
        '<div id="edTextTabBody" style="flex:1;overflow-y:auto;padding:16px;"></div>';
    var overlay = document.getElementById('preview-edit-overlay');
    if (overlay) overlay.appendChild(sheet);
    edTextTab('kbd');
}
function edTextTab(id) {
    ['kbd','font','color','anim','effect','style','format'].forEach(function(t){
        var btn = document.getElementById('edTxtTab_'+t);
        if (btn) { btn.style.borderBottom = t===id ? '2px solid #007AFF' : '2px solid transparent'; btn.style.color = t===id ? '#007AFF' : 'rgba(255,255,255,0.4)'; }
    });
    var body = document.getElementById('edTextTabBody');
    if (!body) return;
    if (id === 'kbd') {
        body.innerHTML = '<textarea id="edTxtInput" placeholder="Type something…" oninput="_edTextState.text=this.value" style="width:100%;min-height:100px;background:rgba(255,255,255,0.07);border:0.5px solid rgba(255,255,255,0.15);border-radius:14px;color:white;font-size:18px;padding:14px;outline:none;resize:none;font-family:inherit;">'+escapeHtml(_edTextState.text)+'</textarea>';
        setTimeout(function(){ var el=document.getElementById('edTxtInput'); if(el) el.focus(); }, 100);
    } else if (id === 'font') {
        body.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">'+
            _edFonts.map(function(f){
                var sel = f===_edTextState.font;
                return '<button onclick="edSetTextFont(\''+f+'\')" id="edFont_'+f+'" style="padding:14px;border-radius:14px;border:1.5px solid '+(sel?'#007AFF':'rgba(255,255,255,0.12)')+';background:'+(sel?'rgba(0,122,255,0.15)':'rgba(255,255,255,0.05)')+';color:white;font-size:15px;font-weight:700;cursor:pointer;">'+f+'</button>';
            }).join('')+
        '</div>';
    } else if (id === 'color') {
        var presets = ['#ffffff','#000000','#FF3B30','#FF9500','#FFD60A','#34C759','#007AFF','#5856D6','#FF2D55','#BF5AF2','#32D74B','#0A84FF'];
        body.innerHTML =
            '<div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;">'+
                '<div style="width:36px;height:36px;border-radius:50%;background:'+_edTextState.color+';border:2px solid rgba(255,255,255,0.3);flex-shrink:0;"></div>'+
                '<div style="flex:1;overflow-x:auto;display:flex;gap:8px;scrollbar-width:none;">'+
                presets.map(function(c){
                    return '<div onclick="edSetTextColor(\''+c+'\')" style="width:32px;height:32px;border-radius:50%;background:'+c+';flex-shrink:0;cursor:pointer;border:2px solid '+(c===_edTextState.color?'white':'transparent')+';"></div>';
                }).join('')+
                '</div>'+
            '</div>'+
            ['Hue','Saturation','Brightness'].map(function(label, i){
                var grad = i===0 ? 'linear-gradient(to right,red,yellow,lime,cyan,blue,magenta,red)' : i===1 ? 'linear-gradient(to right,#888,'+_edTextState.color+')' : 'linear-gradient(to right,#000,#fff)';
                return '<div style="margin-bottom:14px;"><p style="color:rgba(255,255,255,0.5);font-size:12px;margin-bottom:6px;">'+label+'</p>'+
                    '<div style="height:10px;border-radius:5px;background:'+grad+';position:relative;cursor:pointer;" onclick="edSliderClick(event,\''+label.toLowerCase()+'\')">'+
                        '<div style="position:absolute;top:-3px;left:50%;width:16px;height:16px;background:white;border-radius:50%;transform:translateX(-50%);box-shadow:0 2px 6px rgba(0,0,0,0.4);pointer-events:none;"></div>'+
                    '</div></div>';
            }).join('');
    } else if (id === 'anim') {
        body.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">'+
            _edTextAnims.map(function(a){
                var sel = a===_edTextState.animation || (a==='None' && _edTextState.animation==='none');
                return '<button onclick="edSetTextAnim(\''+a+'\')" style="padding:14px;border-radius:14px;border:1.5px solid '+(sel?'#007AFF':'rgba(255,255,255,0.12)')+';background:'+(sel?'rgba(0,122,255,0.15)':'rgba(255,255,255,0.05)')+';color:white;font-size:13px;font-weight:700;cursor:pointer;">'+a+'</button>';
            }).join('')+
        '</div>';
    } else if (id === 'effect') {
        body.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">'+
            _edTextEffects.map(function(ef){
                var sel = ef===_edTextState.effect || (ef==='None' && _edTextState.effect==='none');
                var style = ef==='Neon'?'text-shadow:0 0 10px #007AFF,0 0 20px #007AFF;' : ef==='Hard Shadow'?'text-shadow:3px 3px 0 #000;' : ef==='3D Offset'?'text-shadow:2px 2px 0 #555,4px 4px 0 #333;' : ef==='Pixel'?'font-family:monospace;letter-spacing:2px;' : ef==='Glow'?'text-shadow:0 0 14px white;' : ef==='Retro'?'letter-spacing:3px;text-transform:uppercase;' : '';
                return '<button onclick="edSetTextEffect(\''+ef+'\')" style="padding:14px;border-radius:14px;border:1.5px solid '+(sel?'#007AFF':'rgba(255,255,255,0.12)')+';background:'+(sel?'rgba(0,122,255,0.15)':'rgba(255,255,255,0.05)')+';color:white;font-size:13px;font-weight:700;cursor:pointer;'+style+'">'+ef+'</button>';
            }).join('')+
        '</div>';
    } else if (id === 'style') {
        var styleOpts = [
            {label:'Bold',prop:'fontWeight',val:'900',off:'400'},
            {label:'Italic',prop:'fontStyle',val:'italic',off:'normal'},
            {label:'Underline',prop:'textDecoration',val:'underline',off:'none'},
            {label:'Shadow',prop:'textShadow',val:'2px 2px 6px rgba(0,0,0,0.6)',off:'none'},
            {label:'Outline',prop:'webkitTextStroke',val:'1px rgba(0,0,0,0.5)',off:'0'},
            {label:'Uppercase',prop:'textTransform',val:'uppercase',off:'none'},
            {label:'Wide',prop:'letterSpacing',val:'4px',off:'normal'},
            {label:'Tight',prop:'letterSpacing',val:'-1px',off:'normal'}
        ];
        body.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">'+
            styleOpts.map(function(opt){
                var isOn = _edTextState['style_'+opt.label] === true;
                return '<button id="edStyleBtn_'+opt.label+'" onclick="edToggleStyle(\''+opt.label+'\',\''+opt.prop+'\',\''+escapeHtml(opt.val)+'\',\''+escapeHtml(opt.off)+'\')" style="padding:14px;border-radius:14px;border:1.5px solid '+(isOn?'#007AFF':'rgba(255,255,255,0.12)')+';background:'+(isOn?'rgba(0,122,255,0.15)':'rgba(255,255,255,0.05)')+';color:white;font-size:14px;font-weight:700;cursor:pointer;">'+opt.label+'</button>';
            }).join('')+
        '</div>';
    } else if (id === 'format') {
        body.innerHTML = '<div style="display:flex;gap:10px;justify-content:center;margin-bottom:16px;">'+
            [{a:'left',icon:'fa-align-left'},{a:'center',icon:'fa-align-center'},{a:'right',icon:'fa-align-right'}].map(function(x){
                return '<button onclick="edSetTextAlign(\''+x.a+'\')" style="width:50px;height:50px;border-radius:14px;border:1.5px solid rgba(255,255,255,0.15);background:rgba(255,255,255,0.06);color:white;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:18px;"><i class="fa-solid '+x.icon+'"></i></button>';
            }).join('')+
        '</div>'+
        '<div style="display:flex;gap:8px;flex-wrap:wrap;">'+
            [{label:'Bold',css:'font-weight:900'},{label:'Italic',css:'font-style:italic'},{label:'Underline',css:'text-decoration:underline'},{label:'Uppercase',css:'text-transform:uppercase'},{label:'Small',css:'font-size:12px'},{label:'Large',css:'font-size:28px'}]
            .map(function(opt){ return '<button style="padding:8px 14px;border-radius:20px;border:0.5px solid rgba(255,255,255,0.2);background:rgba(255,255,255,0.06);color:white;font-size:13px;cursor:pointer;'+opt.css+'">'+opt.label+'</button>'; }).join('')+
        '</div>';
    }
}
function edSetTextFont(f) { _edTextState.font = f; edTextTab('font'); }
function edSetTextColor(c) { _edTextState.color = c; edTextTab('color'); }
function edSetTextAnim(a) { _edTextState.animation = a; edTextTab('anim'); }
function edSetTextEffect(e) { _edTextState.effect = e; edTextTab('effect'); }
function edSetTextAlign(a) { _edTextState.align = a; }
function edToggleStyle(label, prop, val, off) {
    var key = 'style_' + label;
    _edTextState[key] = !_edTextState[key];
    edTextTab('style');
}
function edSliderClick(e, type) {
    var rect = e.currentTarget.getBoundingClientRect();
    var pct = (e.clientX - rect.left) / rect.width;
    if (type === 'hue') { var h = Math.round(pct*360); _edTextState.color = 'hsl('+h+',100%,50%)'; }
    edTextTab('color');
}
// Text overlays live in edState, so they survive undo/redo and draft restore.
// They used to be raw DOM nodes, which is why undo could never move them back.
var _edFontMap = {Classic:'sans-serif',Modern:'"SF Pro Display",sans-serif',Poster:'Georgia,serif',Bubble:'Arial Rounded MT Bold,sans-serif',Typewriter:'"Courier New",monospace',Serif:'Georgia,serif',Mono:'monospace',Rounded:'Arial,sans-serif'};
function _edTextEffectCss(effect, color) {
    var m = {
        'Neon':'text-shadow:0 0 10px '+color+',0 0 20px '+color+';',
        'Hard Shadow':'text-shadow:3px 3px 0 #000;',
        '3D Offset':'text-shadow:2px 2px 0 #555,4px 4px 0 #333;',
        'Pixel':'letter-spacing:3px;',
        'Glow':'text-shadow:0 0 14px '+color+',0 0 28px '+color+';',
        'Retro':'letter-spacing:3px;text-transform:uppercase;'
    };
    return m[effect] || '';
}

function edRenderTextOverlays() {
    var layer = document.getElementById('edTextLayer');
    if (!layer) return;
    Array.prototype.slice.call(layer.querySelectorAll('.ed-text-item')).forEach(function(n) { n.remove(); });
    (edState.textOverlays || []).forEach(function(t) {
        var el = document.createElement('div');
        el.className = 'ed-text-item';
        el.setAttribute('data-id', t.id);
        el.textContent = t.text;
        // The layer is pointer-events:none so taps reach the video; each item
        // turns them back on so it can be dragged and removed.
        el.style.cssText = 'position:absolute;left:' + t.left + ';top:' + t.top + ';' +
            (t.right ? 'right:' + t.right + ';' : '') +
            'text-align:' + t.align + ';color:' + t.color + ';font-size:22px;font-weight:800;font-family:' +
            (_edFontMap[t.font] || 'sans-serif') + ';cursor:move;padding:4px 8px;pointer-events:auto;' +
            'touch-action:none;-webkit-user-select:none;user-select:none;' + _edTextEffectCss(t.effect, t.color);

        var del = document.createElement('div');
        del.textContent = '✕';
        del.title = 'Remove text';
        del.style.cssText = 'position:absolute;top:-11px;right:-11px;width:23px;height:23px;border-radius:50%;background:rgba(0,0,0,0.75);color:#fff;font-size:11px;line-height:23px;text-align:center;cursor:pointer;pointer-events:auto;font-weight:700;';
        del.addEventListener('click', function(ev) {
            ev.stopPropagation();
            edState.textOverlays = edState.textOverlays.filter(function(x) { return x.id !== t.id; });
            edRenderTextOverlays();
            edState.isDirty = true; edRenderTimeline(); edSaveHistory(); editorSaveDraft(false);
            showToast('Text removed');
        });
        el.appendChild(del);

        function from(sx, sy) {
            var ox = el.offsetLeft, oy = el.offsetTop;
            return function(cx, cy) {
                t.left = (ox + cx - sx) + 'px';
                t.top  = (oy + cy - sy) + 'px';
                t.right = '';
                el.style.left = t.left; el.style.top = t.top; el.style.right = 'auto';
            };
        }
        function done() { edState.isDirty = true; edSaveHistory(); editorSaveDraft(false); }
        el.addEventListener('touchstart', function(e) {
            if (e.target === del) return;
            var pt = e.touches[0], move = from(pt.clientX, pt.clientY);
            function mv(ev) { move(ev.touches[0].clientX, ev.touches[0].clientY); }
            function en() { document.removeEventListener('touchmove', mv); document.removeEventListener('touchend', en); done(); }
            document.addEventListener('touchmove', mv, { passive: true });
            document.addEventListener('touchend', en);
        }, { passive: true });
        el.addEventListener('mousedown', function(e) {
            if (e.target === del) return;
            e.preventDefault();
            var move = from(e.clientX, e.clientY);
            function mv(ev) { move(ev.clientX, ev.clientY); }
            function up() { document.removeEventListener('mousemove', mv); document.removeEventListener('mouseup', up); done(); }
            document.addEventListener('mousemove', mv);
            document.addEventListener('mouseup', up);
        });
        layer.appendChild(el);
    });
}

function edApplyText() {
    var inp = document.getElementById('edTxtInput');
    if (inp) _edTextState.text = inp.value.trim();
    if (!_edTextState.text) { var s0 = document.getElementById('edTextSheet'); if (s0) s0.remove(); return; }
    edState.textOverlays = edState.textOverlays || [];
    edState.textOverlays.push({
        id: 't_' + Date.now() + '_' + Math.floor(Math.random() * 1000),
        text: _edTextState.text, font: _edTextState.font, color: _edTextState.color,
        align: _edTextState.align, effect: _edTextState.effect,
        left: '10%', right: '10%', top: '40%'
    });
    edRenderTextOverlays();
    edState.isDirty = true; edRenderTimeline(); edSaveHistory(); editorSaveDraft(false);
    var sheet = document.getElementById('edTextSheet');
    if (sheet) sheet.remove();
    showToast('Text added ✅'); triggerHaptic(15);
    _edTextState = {text:'', font:'Classic', color:'#ffffff', effect:'none', animation:'none', align:'center'};
}

