function openTrustclipDraftPreview(draftId) {
    var drafts = [];
    try { drafts = JSON.parse(localStorage.getItem('tf_tc_drafts') || '[]'); } catch(e) {}
    var draft = drafts.find(function(d){ return d.id === draftId; });
    if (!draft) return;
    var sheet = document.createElement('div');
    sheet.style.cssText = 'position:absolute;inset:0;z-index:9200;display:flex;align-items:flex-end;background:rgba(0,0,0,0.6);backdrop-filter:blur(10px);';
    sheet.innerHTML =
        '<div style="width:100%;background:var(--bg-primary,#fff);border-radius:22px 22px 0 0;padding:20px 20px 40px;animation:modalUp 0.3s cubic-bezier(0.32,0.72,0,1);">' +
            '<div style="width:36px;height:4px;background:#ccc;border-radius:2px;margin:0 auto 18px;"></div>' +
            '<div style="display:flex;gap:14px;align-items:center;margin-bottom:20px;">' +
                (draft.videoThumbnail
                    ? '<img src="' + escapeHtml(draft.videoThumbnail) + '" style="width:60px;height:90px;border-radius:10px;object-fit:cover;" onerror="this.style.display=\'none\';this.nextElementSibling.style.display=\'flex\';">' +
                      '<div style="display:none;width:60px;height:90px;border-radius:10px;background:#1a1a1a;align-items:center;justify-content:center;flex-shrink:0;"><i class="fa-solid fa-film" style="font-size:22px;color:#555;"></i></div>'
                    : '<div style="width:60px;height:90px;border-radius:10px;background:#1a1a1a;display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fa-solid fa-film" style="font-size:22px;color:#555;"></i></div>') +
                '<div>' +
                    '<p style="font-size:13px;font-weight:700;color:var(--text-primary,#000);">' + (draft.caption || 'No caption') + '</p>' +
                    '<p style="font-size:12px;color:#888;margin-top:4px;">' + draft.fileSize + ' · ' + new Date(draft.dateCreated).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'}) + '</p>' +
                '</div>' +
            '</div>' +
            '<button onclick="continueTrustclipDraft(\'' + draftId + '\')" style="width:100%;padding:15px;border-radius:14px;background:#007AFF;color:white;border:none;font-size:15px;font-weight:700;cursor:pointer;margin-bottom:10px;">Continue editing</button>' +
            '<button onclick="deleteTrustclipDraft(\'' + draftId + '\')" style="width:100%;padding:15px;border-radius:14px;background:transparent;color:#FF3B30;border:none;font-size:15px;font-weight:600;cursor:pointer;">Delete draft</button>' +
        '</div>';
    sheet.addEventListener('click', function(e){ if(e.target===sheet) sheet.remove(); });
    (document.getElementById('app') || document.body).appendChild(sheet);
}

function deleteTrustclipDraft(draftId) {
    if (!confirm('Delete this draft?')) return;
    try {
        var drafts = JSON.parse(localStorage.getItem('tf_tc_drafts') || '[]');
        drafts = drafts.filter(function(d){ return d.id !== draftId; });
        localStorage.setItem('tf_tc_drafts', JSON.stringify(drafts));
    } catch(e) {}
    if (typeof _tcDraftDelVideo === 'function') _tcDraftDelVideo(draftId); // free the stored blob
    // Close preview sheet
    var sheets = document.querySelectorAll('[style*="z-index:9200"]');
    sheets.forEach(function(s){ s.remove(); });
    // Refresh drafts screen
    openTrustclipDraftsScreen();
    showToast('Draft deleted');
    triggerHaptic(20);
}

async function continueTrustclipDraft(draftId) {
    var drafts = [];
    try { drafts = JSON.parse(localStorage.getItem('tf_tc_drafts') || '[]'); } catch(e) {}
    var draft = drafts.find(function(d){ return d.id === draftId; });
    if (!draft) return;
    // Close the preview sheet + drafts screen
    var _ps = document.querySelector('[style*="z-index:9200"]'); if (_ps) _ps.remove();
    var _ds = document.getElementById('tcDraftsScreen'); if (_ds) _ds.remove();
    // Restore the actual video from IndexedDB so it isn't "gone" on continue.
    var blob = null;
    if (draft.hasVideo) { try { blob = await _tcDraftGetVideo(draftId); } catch(e) {} }
    if (blob) {
        try { if (window._lastPickedVideoSrc && String(window._lastPickedVideoSrc).indexOf('blob:') === 0) URL.revokeObjectURL(window._lastPickedVideoSrc); } catch(e) {}
        window._lastRecordedBlob = null;
        window._lastPickedVideoSrc = URL.createObjectURL(blob);
    }
    // openNewTrustClipPost() wires the video into #tcThumbVid from the globals.
    if (typeof openNewTrustClipPost === 'function') openNewTrustClipPost();
    else openPage('new-trust-clip-overlay');
    hideNavBar();
    setTimeout(function(){
        var cap = document.getElementById('tcCaption');
        if (cap && draft.caption) cap.value = draft.caption;
    }, 200);
    if (draft.hasVideo && !blob) showToast('Draft video could not be restored, please re-add it');
}

function openTrustclipDraftSelect() {
    var screen = document.getElementById('tcDraftsScreen');
    if (!screen) return;
    var drafts = [];
    try { drafts = JSON.parse(localStorage.getItem('tf_tc_drafts') || '[]'); } catch(e) {}
    var selected = [];
    screen.querySelectorAll('[data-draft-id]').forEach(function(el) {
        el.style.position = 'relative';
        if (!el.querySelector('.tc-sel-circle')) {
            var circle = document.createElement('div');
            circle.className = 'tc-sel-circle';
            circle.style.cssText = 'position:absolute;top:6px;right:6px;width:22px;height:22px;border-radius:50%;border:2px solid white;background:rgba(0,0,0,0.3);display:flex;align-items:center;justify-content:center;z-index:10;';
            el.appendChild(circle);
            var origClick = el.getAttribute('onclick');
            el.removeAttribute('onclick');
            el.onclick = function() {
                var id = el.getAttribute('data-draft-id');
                var idx = selected.indexOf(id);
                if (idx === -1) { selected.push(id); circle.style.background='#007AFF'; circle.innerHTML='<i class="fa-solid fa-check" style="color:white;font-size:11px;"></i>'; }
                else { selected.splice(idx,1); circle.style.background='rgba(0,0,0,0.3)'; circle.innerHTML=''; }
                actionBar.querySelector('button:last-child').textContent = 'Delete (' + selected.length + ')';
                actionBar.querySelector('button:last-child').style.opacity = selected.length ? '1' : '0.4';
            };
        }
    });
    var actionBar = document.createElement('div');
    actionBar.style.cssText = 'position:absolute;bottom:0;left:0;right:0;padding:16px 20px max(32px,env(safe-area-inset-bottom,32px));background:var(--bg-primary,#fff);display:flex;gap:10px;border-top:0.5px solid var(--border-color,#eee);z-index:100;';
    actionBar.innerHTML = '<button onclick="document.getElementById(\'tcDraftsScreen\').remove();openTrustclipDraftsScreen();" style="flex:1;padding:14px;border-radius:14px;border:none;background:rgba(0,0,0,0.06);color:var(--text-primary,#000);font-size:15px;font-weight:600;cursor:pointer;">Cancel</button>' +
        '<button style="flex:1;padding:14px;border-radius:14px;border:none;background:#FF3B30;color:white;font-size:15px;font-weight:700;cursor:pointer;opacity:0.4;" onclick="if(!selected.length)return;if(confirm(\'Delete \'+selected.length+\' draft\'+(selected.length>1?\'s?\':\' ?\'))) { var drafts=JSON.parse(localStorage.getItem(\'tf_tc_drafts\')||\'[]\'); localStorage.setItem(\'tf_tc_drafts\',JSON.stringify(drafts.filter(function(d){return selected.indexOf(d.id)===-1;}))); document.getElementById(\'tcDraftsScreen\').remove(); openTrustclipDraftsScreen(); showToast(\'Deleted\'); }">Delete (0)</button>';
    screen.appendChild(actionBar);
    screen.style.paddingBottom = '80px';
}

