function _refreshTcAudienceRadios() {
    ['everyone','friends'].forEach(function(v) {
        var radio = document.getElementById('tcaud-radio-' + v);
        if (!radio) return;
        var active = window._tcAudience === v;
        radio.style.borderColor = active ? '#007AFF' : '#ccc';
        radio.style.background = active ? '#007AFF' : 'transparent';
        radio.innerHTML = active ? '<div style="width:8px;height:8px;border-radius:50%;background:white;"></div>' : '';
    });
}

