function _setTcProfileDisplay(val) {
    window._tcProfileDisplay = val;
    var labels = { main_grid:'Main grid', trustclip_grid:'Trustclip grid', both:'Both grids' };
    var lbl = document.getElementById('tcProfileDisplayLabel');
    if (lbl) lbl.innerHTML = labels[val] + ' <i class="fa-solid fa-chevron-right" style="color:#ccc;font-size:12px;"></i>';
    // Update check icons
    ['main_grid','trustclip_grid','both'].forEach(function(v){
        var el = document.getElementById('tcpd-check-' + v);
        if (el) el.style.color = v === val ? '#007AFF' : '#ccc';
    });
    // Close sheet
    setTimeout(function(){
        var sheets = document.querySelectorAll('[style*="z-index:9400"]');
        sheets.forEach(function(s){ s.remove(); });
    }, 200);
}

