function addChecklistItem() {
    var inp = document.getElementById('ckNewItem');
    if (!inp || !inp.value.trim()) return;
    var items = document.getElementById('ckItems');
    if (!items) return;
    var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    var tc = isDark ? '#fff' : '#000';

    var row = document.createElement('div');
    row.style.cssText = 'display:flex;align-items:center;gap:8px;padding:8px 0;border-bottom:0.5px solid rgba(128,128,128,0.1);';

    var checkbox = document.createElement('div');
    checkbox.style.cssText = 'width:20px;height:20px;border-radius:6px;border:1.5px solid rgba(0,122,255,0.4);flex-shrink:0;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:all 0.2s;';
    checkbox.addEventListener('click', function () {
        this.style.background = '#007AFF';
        this.style.border = 'none';
        var icon = document.createElement('i');
        icon.className = 'fa-solid fa-check';
        icon.style.cssText = 'color:white;font-size:10px;';
        this.innerHTML = '';
        this.appendChild(icon);
    });

    var label = document.createElement('span');
    label.style.cssText = 'flex:1;font-size:15px;color:' + tc + ';';
    label.textContent = inp.value.trim();
    label.setAttribute('data-ck-label', inp.value.trim());

    var delBtn = document.createElement('button');
    delBtn.style.cssText = 'background:none;border:none;color:#FF3B30;font-size:15px;cursor:pointer;padding:0 2px;';
    delBtn.textContent = '×';
    delBtn.addEventListener('click', function () { row.remove(); });

    row.appendChild(checkbox);
    row.appendChild(label);
    row.appendChild(delBtn);
    items.appendChild(row);
    inp.value = '';
    inp.focus();
    triggerHaptic(8);
}

