var _dsTab = 'topics';
var _dsActiveCat = null;

var _dsCategories = [
    { id:'News',          label:'News',          color:'#007AFF' },
    { id:'Sports',        label:'Sports',        color:'#34C759' },
    { id:'Business',      label:'Business',      color:'#FF9500' },
    { id:'Technology',    label:'Technology',    color:'#5856D6' },
    { id:'Entertainment', label:'Entertainment', color:'#FF2D55' },
    { id:'Gaming',        label:'Gaming',        color:'#AF52DE' },
    { id:'Arts',          label:'Arts & Culture',color:'#FF6B35' },
    { id:'Science',       label:'Science',       color:'#32ADE6' },
    { id:'Food',          label:'Food',          color:'#FF9500' },
    { id:'Travel',        label:'Travel',        color:'#34C759' },
    { id:'Fashion',       label:'Fashion',       color:'#FF2D55' },
    { id:'Fitness',       label:'Fitness',       color:'#34C759' },
    { id:'Music',         label:'Music',         color:'#FF375F' },
    { id:'Photography',   label:'Photography',   color:'#FFCC00' },
    { id:'Cars',          label:'Cars',          color:'#007AFF' }
];

var _dsFollowedTopics = {};
var _dsTopicPeopleCache = {};

function openDiscoverScreen() {
    var el = document.getElementById('discover-screen');
    if (!el) return;
    el.style.display = 'flex';
    el.style.animation = 'slideUpOverlay 0.35s cubic-bezier(0.34,1.56,0.64,1)';
    _dsCategories.forEach(function(c) {
        _dsFollowedTopics[c.id] = localStorage.getItem('tf-topic-' + c.id) === '1';
    });
    _dsActiveCat = _dsActiveCat || _dsCategories[0].id;
    _dsRenderPills();
    switchDsTab('topics');
}

function switchDsTab(tab) {
    _dsTab = tab;
    var isTopics = tab === 'topics';
    document.getElementById('ds-tab-topics').classList.toggle('active', isTopics);
    document.getElementById('ds-tab-suggested').classList.toggle('active', !isTopics);
    document.getElementById('ds-topics-content').style.display = isTopics ? 'flex' : 'none';
    document.getElementById('ds-suggested-content').style.display = isTopics ? 'none' : 'flex';
    var ind = document.getElementById('ds-tab-indicator');
    if (ind) ind.style.left = isTopics ? '0%' : '50%';
    if (!isTopics) _dsRenderSuggested();
}

function _dsRenderPills() {
    var row = document.getElementById('ds-pills-row');
    if (!row) return;
    row.innerHTML = _dsCategories.map(function(c) {
        var active = c.id === _dsActiveCat;
        return '<span class="ds-pill' + (active ? ' active' : '') + '" onclick="_dsSelectCat(\'' + c.id + '\')">' + c.label + '</span>';
    }).join('');
    _dsRenderTopicCard(_dsActiveCat);
}

function _dsSelectCat(catId) {
    _dsActiveCat = catId;
    document.querySelectorAll('.ds-pill').forEach(function(p, i) {
        p.classList.toggle('active', _dsCategories[i] && _dsCategories[i].id === catId);
    });
    _dsRenderTopicCard(catId);
    if (typeof triggerHaptic === 'function') triggerHaptic(8);
}

function _dsRenderTopicCard(catId) {
    var cat = _dsCategories.find(function(c) { return c.id === catId; }) || _dsCategories[0];
    var card = document.getElementById('ds-topic-card');
    if (!card) return;
    var followed = !!_dsFollowedTopics[catId];
    card.innerHTML =
        '<div style="background:linear-gradient(135deg,' + cat.color + '22,' + cat.color + '08);border:1px solid ' + cat.color + '33;border-radius:18px;padding:20px;display:flex;align-items:center;justify-content:space-between;gap:12px;">' +
            '<div>' +
                '<b style="font-size:18px;font-weight:800;color:var(--text-primary,#000);display:block;margin-bottom:4px;">' + cat.label + '</b>' +
                '<span id="ds-topic-count-' + catId + '" style="font-size:13px;color:var(--text-secondary,#888);display:none;"></span>' +
            '</div>' +
            '<button id="ds-topic-btn-' + catId + '" onclick="_dsToggleTopicFollow(\'' + catId + '\',this)" ' +
                'style="padding:10px 20px;border-radius:999px;border:1.5px solid ' + (followed ? 'transparent' : cat.color) + ';' +
                'background:' + (followed ? cat.color : 'transparent') + ';' +
                'color:' + (followed ? '#fff' : cat.color) + ';' +
                'font-size:14px;font-weight:700;cursor:pointer;white-space:nowrap;flex-shrink:0;">' +
                (followed ? 'Following' : 'Follow') +
            '</button>' +
        '</div>';
    if (window.sb) {
        sb.from('topic_follows').select('id', { count:'exact', head:true }).eq('topic', catId)
            .then(function(r) {
                var el = document.getElementById('ds-topic-count-' + catId);
                if (!el) return;
                var n = r.count || 0;
                el.textContent = (n >= 1000 ? (n/1000).toFixed(1) + 'K' : n) + ' followers';
            }).catch(function() {});
    } else {
        var countEl = document.getElementById('ds-topic-count-' + catId);
    if (countEl) countEl.style.display = 'none';
    }
    _dsRenderTopicPeople(catId);
}

function _dsToggleTopicFollow(catId, btn) {
    var wasFollowing = !!_dsFollowedTopics[catId];
    _dsFollowedTopics[catId] = !wasFollowing;
    var cat = _dsCategories.find(function(c) { return c.id === catId; }) || { color:'#007AFF' };
    if (_dsFollowedTopics[catId]) {
        localStorage.setItem('tf-topic-' + catId, '1');
        btn.textContent = 'Following';
        btn.style.background = cat.color;
        btn.style.color = '#fff';
        btn.style.borderColor = 'transparent';
        if (typeof triggerHaptic === 'function') triggerHaptic(12);
        showToast('Following ' + cat.label);
        if (window.sb && currentUser) {
            sb.from('topic_follows').insert({ user_id: currentUser.id, topic: catId }).catch(function(){});
        }
    } else {
        localStorage.removeItem('tf-topic-' + catId);
        btn.textContent = 'Follow';
        btn.style.background = 'transparent';
        btn.style.color = cat.color;
        btn.style.borderColor = cat.color;
        showToast('Unfollowed ' + cat.label);
        if (window.sb && currentUser) {
            sb.from('topic_follows').delete().eq('user_id', currentUser.id).eq('topic', catId).catch(function(){});
        }
    }
}

function _dsRenderTopicPeople(catId) {
    var ppl = document.getElementById('ds-topic-people');
    if (!ppl) return;
    if (_dsTopicPeopleCache[catId]) {
        _dsBuildPeopleRows(ppl, _dsTopicPeopleCache[catId]); return;
    }
    ppl.innerHTML = [0,1,2].map(function() {
        return '<div style="display:flex;align-items:center;gap:12px;padding:14px 16px;">' +
            '<div class="ds-skeleton" style="width:46px;height:46px;border-radius:50%;flex-shrink:0;"></div>' +
            '<div style="flex:1;">' +
                '<div class="ds-skeleton" style="height:13px;width:55%;margin-bottom:7px;"></div>' +
                '<div class="ds-skeleton" style="height:11px;width:35%;"></div>' +
            '</div>' +
            '<div class="ds-skeleton" style="width:70px;height:32px;border-radius:999px;"></div>' +
        '</div>';
    }).join('');
    if (!window.sb) { ppl.innerHTML = ''; return; }
    sb.from('topic_follows')
        .select('user_id, users:user_id(id,full_name,username,avatar_url,bio)')
        .eq('topic', catId)
        .limit(6)
        .then(function(r) {
            var people = (r.data || [])
                .map(function(row) { return row.users; })
                .filter(function(u) { return u && u.username; });
            _dsTopicPeopleCache[catId] = people;
            _dsBuildPeopleRows(ppl, people);
        }).catch(function() {
            ppl.innerHTML = '<div style="padding:20px 16px;color:var(--text-secondary,#888);font-size:14px;">Could not load people right now.</div>';
        });
}

function _dsBuildPeopleRows(container, people) {
    if (!people || !people.length) {
        container.innerHTML = '<div style="padding:20px 16px;text-align:center;color:var(--text-secondary,#888);font-size:14px;">No people in this topic yet.</div>';
        return;
    }
    container.innerHTML = people.map(function(u, i) {
        var name = escapeHtml(u.display_name || u.username || 'User');
        var handle = escapeHtml(u.username || 'user');
        var avatar = u.avatar_url || ('https://ui-avatars.com/api/?name=' + encodeURIComponent(name) + '&background=random&color=fff&size=80');
        var bio = u.bio ? '<div style="font-size:13px;color:var(--text-secondary,#888);margin-top:2px;line-height:1.4;">' + escapeHtml(u.bio.substring(0,80)) + '</div>' : '';
        return '<div class="ds-user-row" style="animation-delay:' + (i*0.06) + 's">' +
            '<img src="' + avatar + '" style="width:46px;height:46px;border-radius:50%;object-fit:cover;flex-shrink:0;" onerror="this.src=\'https://ui-avatars.com/api/?name=U&background=random&color=fff&size=80\'">' +
            '<div style="flex:1;min-width:0;">' +
                '<div style="font-size:15px;font-weight:700;color:var(--text-primary,#000);">@' + handle + '</div>' +
                '<div style="font-size:13px;color:var(--text-secondary,#888);">' + name + '</div>' +
                bio +
            '</div>' +
            '<button class="ds-follow-btn" data-uid="' + u.id + '" onclick="realDsFollow(\'' + u.id + '\',this)">Follow</button>' +
        '</div>';
    }).join('');
}

function _dsRenderSuggested() {
    var list = document.getElementById('ds-suggested-list');
    if (!list) return;
    list.innerHTML = [0,1,2,3].map(function() {
        return '<div style="display:flex;align-items:center;gap:12px;padding:14px 16px;">' +
            '<div class="ds-skeleton" style="width:48px;height:48px;border-radius:50%;flex-shrink:0;"></div>' +
            '<div style="flex:1;">' +
                '<div class="ds-skeleton" style="height:13px;width:50%;margin-bottom:7px;"></div>' +
                '<div class="ds-skeleton" style="height:11px;width:32%;margin-bottom:6px;"></div>' +
                '<div class="ds-skeleton" style="height:11px;width:70%;"></div>' +
            '</div>' +
            '<div class="ds-skeleton" style="width:70px;height:32px;border-radius:999px;"></div>' +
        '</div>';
    }).join('');
    if (!window.sb || !currentUser) {
        list.innerHTML = '<div style="padding:30px 16px;text-align:center;color:var(--text-secondary,#888);font-size:14px;">Sign in to see suggestions.</div>';
        return;
    }
    sb.from('follows')
        .select('following_id')
        .eq('follower_id', currentUser.id)
        .then(function(followRes) {
            var alreadyFollowing = (followRes.data || []).map(function(f){ return f.following_id; });
            alreadyFollowing.push(currentUser.id);
            var notIn = '(' + alreadyFollowing.map(function(id){ return '"' + id + '"'; }).join(',') + ')';
            return sb.from('users')
                .select('id,full_name,username,avatar_url,bio')
                .not('id','in', notIn)
                .limit(25);
        })
        .then(function(r) {
            var people = (r.data || []).filter(function(u){ return u.username; });
            if (!people.length) {
                list.innerHTML = '<div style="padding:40px 16px;text-align:center;color:var(--text-secondary,#888);">' +
                    '<i class="fa-solid fa-user-group" style="font-size:32px;color:var(--border-color,#ddd);display:block;margin-bottom:12px;"></i>' +
                    '<p style="font-size:14px;">No suggestions right now. Check back soon.</p></div>';
                return;
            }
            list.innerHTML = people.map(function(u, i) {
                var name = escapeHtml(u.full_name || u.username || 'User');
                var handle = escapeHtml(u.username || 'user');
                var avatar = u.avatar_url || ('https://ui-avatars.com/api/?name=' + encodeURIComponent(name) + '&background=random&color=fff&size=80');
                var bio = u.bio ? '<div style="font-size:13px;color:var(--text-secondary,#888);margin-top:3px;line-height:1.4;">' + escapeHtml(u.bio.substring(0,80)) + '</div>' : '';
                return '<div class="ds-user-row" style="animation-delay:' + (i*0.05) + 's">' +
                    '<img src="' + avatar + '" style="width:48px;height:48px;border-radius:50%;object-fit:cover;flex-shrink:0;" onerror="this.src=\'https://ui-avatars.com/api/?name=U&background=random&color=fff&size=80\'">' +
                    '<div style="flex:1;min-width:0;">' +
                        '<div style="font-size:15px;font-weight:700;color:var(--text-primary,#000);">@' + handle + '</div>' +
                        '<div style="font-size:13px;color:var(--text-secondary,#888);">' + name + '</div>' +
                        bio +
                    '</div>' +
                    '<button class="ds-follow-btn" data-uid="' + u.id + '" onclick="realDsFollow(\'' + u.id + '\',this)">Follow</button>' +
                '</div>';
            }).join('');
        })
        .catch(function() {
            list.innerHTML = '<div style="padding:20px 16px;text-align:center;color:var(--text-secondary,#888);font-size:14px;">Could not load suggestions. Try again.</div>';
        });
}

async function realDsFollow(userId, btn) {
    if (!window.sb || !currentUser) {
        btn.classList.toggle('followed');
        btn.textContent = btn.classList.contains('followed') ? 'Following' : 'Follow';
        return;
    }
    var isFollowing = btn.classList.contains('followed');
    btn.disabled = true;
    btn.classList.toggle('followed');
    btn.textContent = isFollowing ? 'Follow' : 'Following';
    try {
        if (isFollowing) {
            await sb.from('follows').delete().eq('follower_id', currentUser.id).eq('following_id', userId);
        } else {
            await sb.from('follows').insert({ follower_id: currentUser.id, following_id: userId });
            if (typeof triggerHaptic === 'function') triggerHaptic(12);
        }
    } catch(e) {
        btn.classList.toggle('followed');
        btn.textContent = isFollowing ? 'Following' : 'Follow';
        showToast('Could not update follow. Try again.');
    }
    btn.disabled = false;
}

function toggleDsFollow(id, btn) { realDsFollow(id, btn); }
function renderDsSuggested() { _dsRenderSuggested(); }
function tfToggleTopicFollow(cat, btn) { _dsToggleTopicFollow(cat, btn); }

