var _dataSaverOn = false;
try { _dataSaverOn = localStorage.getItem('tf_data_saver') === 'true'; } catch(e) {}

function openDataSaverScreen() {
    var existing = document.getElementById('dataSaverScreen');
    if (existing) existing.remove();
    var screen = document.createElement('div');
    screen.id = 'dataSaverScreen';
    screen.style.cssText = 'position:absolute;inset:0;z-index:9100;display:flex;flex-direction:column;background:var(--bg-secondary,#f2f2f7);animation:slideUpOverlay 0.3s cubic-bezier(0.32,0.72,0,1);';
    screen.innerHTML =
        '<div style="display:flex;align-items:center;justify-content:space-between;padding:16px 20px;background:var(--bg-primary,#fff);border-bottom:0.5px solid var(--border-color,#f0f0f0);">' +
            '<button onclick="document.getElementById(\'dataSaverScreen\').remove()" style="background:none;border:none;color:#007AFF;font-size:22px;cursor:pointer;"><i class="fa-solid fa-chevron-left"></i></button>' +
            '<b style="font-size:17px;color:var(--text-primary,#000);">Data Saver</b>' +
            '<div style="width:36px;"></div>' +
        '</div>' +
        '<div style="padding:20px;">' +
            '<div style="background:var(--card-bg,#fff);border-radius:18px;overflow:hidden;">' +
                '<div style="display:flex;align-items:center;justify-content:space-between;padding:18px 18px;">' +
                    '<div>' +
                        '<b style="font-size:16px;color:var(--text-primary,#000);">Data Saver</b>' +
                        '<p style="font-size:13px;color:#888;margin:4px 0 0;line-height:1.5;max-width:220px;">Reduces video quality and disables autoplay on mobile data. Wi-Fi is not affected.</p>' +
                    '</div>' +
                    '<div class="toggle' + (_dataSaverOn?' active':'') + '" id="dataSaverToggle" onclick="toggleDataSaver(this)" style="flex-shrink:0;"></div>' +
                '</div>' +
            '</div>' +
            '<p style="font-size:12px;color:#aaa;padding:14px 4px;line-height:1.65;">When on, videos load at lower resolution and will not play automatically when you are on a mobile data connection.</p>' +
        '</div>';
    (document.getElementById('app') || document.body).appendChild(screen);
    // Sync settings label
    var lbl = document.getElementById('dataSaverStatusLabel');
    if (lbl) lbl.textContent = _dataSaverOn ? 'On' : 'Off';
}

function toggleDataSaver(toggleEl) {
    toggleEl.classList.toggle('active');
    _dataSaverOn = toggleEl.classList.contains('active');
    try { localStorage.setItem('tf_data_saver', _dataSaverOn ? 'true' : 'false'); } catch(e) {}
    var lbl = document.getElementById('dataSaverStatusLabel');
    if (lbl) lbl.textContent = _dataSaverOn ? 'On' : 'Off';
    showToast('Data Saver ' + (_dataSaverOn ? 'on' : 'off'));
    triggerHaptic(15);
}

    async function saveTrustCircle() {
    if (!currentUser || !window.sb) { showToast('Not signed in'); return; }
    var selectedIds = Array.from(document.querySelectorAll('#trustCircleOverlay [data-selected="true"]')).map(function(el){ return el.getAttribute('data-uid'); });
    var { error } = await sb.from('trust_circles').upsert({ user_id: currentUser.id, members: selectedIds }, { onConflict: 'user_id' });
    if (error) { showToast('Failed to save. Try again.'); return; }
    closeSub('trustCircleOverlay');
    showToast('TrustCircle saved');
}

    async function realUnrestrict(btn) {
    var uid = btn.closest('[data-uid]')?.getAttribute('data-uid');
    if (!uid || !window.sb) return;
    btn.disabled = true;
    var { error } = await sb.from('restrictions').delete().eq('user_id', currentUser.id).eq('restricted_id', uid);
    if (error) { showToast('Failed. Try again.'); btn.disabled = false; return; }
    btn.closest('[data-uid]')?.remove();
}

    async function saveInteractionControl() {
    if (!window.sb || !currentUser) return;
    var { error } = await sb.from('user_settings').upsert({ user_id: currentUser.id, interaction_control: true }, { onConflict: 'user_id' });
    if (error) { showToast('Failed. Try again.'); return; }
    closeSub('interactionControlOverlay');
    showToast('Interaction Control enabled');
}

