    function openLinkManager() {
    var rawLinks = currentUser.profile_links || (currentUser.website_url ? [{ label: currentUser.website_url.replace(/^https?:\/\//,'').split('/')[0], url: currentUser.website_url }] : []);
    if (typeof rawLinks === 'string') { try { rawLinks = JSON.parse(rawLinks); } catch(e) { rawLinks = []; } }
    var links = rawLinks || [];
    var modal = document.createElement('div');
    modal.id = 'linkMgrModal';
    modal.style.cssText = 'position:fixed;inset:0;z-index:20000;background:rgba(0,0,0,0.5);backdrop-filter:blur(10px);display:flex;align-items:flex-end;justify-content:center;';
    function renderLinkMgrContent() {
        var listHtml = links.map(function(l, i) {
            return '<div style="display:flex;align-items:center;gap:10px;padding:12px 0;border-bottom:1px solid var(--border-color,#eee);">' +
                '<div style="flex:1;min-width:0;"><div style="font-size:14px;font-weight:700;color:var(--text-primary,#000);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(l.label || l.url) + '</div>' +
                '<div style="font-size:12px;color:#888;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escapeHtml(l.url) + '</div></div>' +
                '<button onclick="removeLinkMgrItem(' + i + ')" style="background:none;border:none;color:#FF3B30;font-size:18px;cursor:pointer;padding:4px;flex-shrink:0;"><i class="fa-solid fa-trash-can"></i></button></div>';
        }).join('');
        return '<div style="background:var(--card-bg,#fff);border-radius:24px 24px 0 0;width:100%;max-width:500px;padding:24px 20px 44px;">' +
            '<div style="width:40px;height:4px;background:#ccc;border-radius:2px;margin:0 auto 20px;"></div>' +
            '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px;">' +
            '<h3 style="font-size:18px;font-weight:800;color:var(--text-primary,#000);">Links in Bio</h3>' +
            '<span style="font-size:13px;color:#007AFF;font-weight:600;">' + links.length + '/5</span></div>' +
            '<p style="color:#888;font-size:13px;margin-bottom:16px;">Add links to your profile, people tap them to visit.</p>' +
            (listHtml ? '<div style="margin-bottom:16px;">' + listHtml + '</div>' : '') +
            (links.length < 5 ? '<div style="margin-bottom:12px;">' +
            '<input id="lmLabelInput" placeholder="Label (e.g. My YouTube)" style="width:100%;padding:14px;border-radius:14px;border:1.5px solid var(--border-color,#eee);font-size:15px;outline:none;box-sizing:border-box;color:var(--text-primary,#000);background:var(--card-bg,#fff);margin-bottom:8px;-webkit-user-select:text;user-select:text;" onfocus="this.style.borderColor=\'#007AFF\'" onblur="this.style.borderColor=\'var(--border-color,#eee)\'">' +
            '<input id="lmUrlInput" type="url" placeholder="https://..." style="width:100%;padding:14px;border-radius:14px;border:1.5px solid var(--border-color,#eee);font-size:15px;outline:none;box-sizing:border-box;color:var(--text-primary,#000);background:var(--card-bg,#fff);-webkit-user-select:text;user-select:text;" onfocus="this.style.borderColor=\'#007AFF\'" onblur="this.style.borderColor=\'var(--border-color,#eee)\'">' +
            '</div>' +
            '<button onclick="addLinkMgrItem()" style="width:100%;padding:15px;border-radius:14px;border:none;background:rgba(0,122,255,0.08);color:#007AFF;font-size:15px;font-weight:700;cursor:pointer;margin-bottom:8px;"><i class="fa-solid fa-plus" style="margin-right:6px;"></i>Add Link</button>' : '<p style="text-align:center;color:#888;font-size:13px;margin-bottom:12px;">Maximum 5 links reached</p>') +
            '<button onclick="saveLinkMgr()" style="width:100%;padding:16px;border-radius:14px;border:none;background:#007AFF;color:#fff;font-size:16px;font-weight:700;cursor:pointer;margin-bottom:8px;">Save</button>' +
            '<button onclick="document.getElementById(\'linkMgrModal\').remove()" style="width:100%;padding:14px;border-radius:14px;border:none;background:var(--bg-secondary,#f0f0f0);color:var(--text-primary,#000);font-size:15px;cursor:pointer;">Cancel</button>' +
            '</div>';
    }
    modal.innerHTML = renderLinkMgrContent();
    document.body.appendChild(modal);

    window.addLinkMgrItem = function() {
        var labelEl = document.getElementById('lmLabelInput');
        var urlEl   = document.getElementById('lmUrlInput');
        var url = (urlEl ? urlEl.value.trim() : '');
        var label = (labelEl ? labelEl.value.trim() : '');
        if (!url) { showToast('Enter a URL'); return; }
        if (!url.startsWith('http')) url = 'https://' + url;
        if (!label) label = url.replace(/^https?:\/\//, '').split('/')[0];
        links.push({ label: label, url: url });
        modal.innerHTML = renderLinkMgrContent();
    };
    window.removeLinkMgrItem = function(idx) {
        links.splice(idx, 1);
        modal.innerHTML = renderLinkMgrContent();
    };
    window.saveLinkMgr = async function() {
        if (window.sb && currentUser) {
            var res = await window.sb.from('users').update({ profile_links: JSON.stringify(links), website_url: links.length ? links[0].url : null }).eq('id', currentUser.id);
            if (res.error) { console.warn('[links]', res.error.message); showToast('Could not save links'); return; }
            currentUser.profile_links = JSON.stringify(links);
            currentUser.website_url = links.length ? links[0].url : null;
            try { secureSave('current_user', currentUser); } catch(e) {}
        }
        document.getElementById('linkMgrModal').remove();
        if (typeof loadMyProfile === 'function') loadMyProfile();
        showToast('Links saved');
    };
}

